local _, ns = ...

ns.QueueQuestData({
[9035] = { ["id"] = 9035, ["name"] = "Roadside Ambush", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9035 }, ["series"] = { 9062, 9064, 9066 }, ["description"] = "You, there! You must help me, please! A fellow apprentice and I were attacked by the Wretched! In their mad hunger for magic, they took everything they could get their hands on: mana crystals, wands, spellbooks... everything! Meledor gave chase after them; I had to stay behind and look after what they didn't take. Continue down the road and see if you can lend him a hand.", ["objectivesText"] = "Speak to Apprentice Meledor in Eversong Woods along the road heading south from Silvermoon City.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15941, ["x"] = 0.452, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15945, ["x"] = 0.448, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9062] = { ["id"] = 9062, ["name"] = "Soaked Pages", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["series"] = { 9035, 9064, 9066 }, ["description"] = "Those blasted Wretched sure can run fast at the sight of someone who'll stand up to them. But let's not worry about that now. I need to find my instructor's elemental grimoire. I'm certain I saw one of those cowards throw it into the river but I cannot seem to be able to locate it. I could use another set of eyes. I'll throw in a bit of coin if you spot it.", ["objectivesText"] = "Apprentice Meledor in Eversong Woods wants you to search the water beneath the bridge nearby and bring him Antheol's Elemental Grimoire . Progress: No luck? Well, keep looking. The book is of utmost importance, <class>.", ["rewardGold"] = 573000, ["rewardXP"] = 100, ["rewardItems"] = { 22414 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15945, ["x"] = 0.448, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15945, ["x"] = 0.448, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 31, ["flags"] = 0 } } },
[9064] = { ["id"] = 9064, ["name"] = "Taking the Fall", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["series"] = { 9035, 9062, 9066 }, ["description"] = "Antheol is going to fly off his rocker when he finds out his book is ruined. I've got a little proposal for you; don't worry, I'll make it worth your while. Take this book to him and tell him nothing of this incident. If he asks, just tell him you dropped the book into a puddle. He has no direct authority over you, so there's not much he can do. Antheol delivers his lectures at Stillwhisper Pond, southeast of Silvermoon. You'll do this for us, right? I'll reward you handsomely for this favor!", ["objectivesText"] = "Bring Antheol's Elemental Grimoire to Instructor Antheol at Stillwhisper Pond in Eversong Woods. Progress: What calls for this interruption to my lecture, <class>?", ["rewardGold"] = 286500, ["rewardXP"] = 50, ["rewardItems"] = { 22414 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15945, ["x"] = 0.448, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15970, ["x"] = 0.555333, ["y"] = 0.544667 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 32, ["flags"] = 0 } } },
[9066] = { ["id"] = 9066, ["name"] = "Swift Discipline", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["series"] = { 9035, 9062, 9064 }, ["description"] = "I hope you learn a valuable lesson today, <name>. Never trust someone else to lie for you. Now I want you to go back to my two dimwitted students and discipline them using this wand. My magic tells me that you'll find them along the road to the west on the other side of the Dead Scar. Come back to me after you've done this. I'll give you a small reward for your troubles.", ["objectivesText"] = "Use Antheol's Disciplinary Rod on his two students: Apprentice Ralen and Apprentice Meledor . Return to Antheol at Stillwhisper Pond in Eversong Woods with the rod after this. Progress: Did you do what I asked of you, <name>?", ["rewardGold"] = 286500, ["rewardXP"] = 200, ["rewardItems"] = { 22473, 22976 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15970, ["x"] = 0.555333, ["y"] = 0.544667 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15970, ["x"] = 0.555333, ["y"] = 0.544667 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.555333, ["y"] = 0.544667 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 33, ["flags"] = 0 } } },
[9067] = { ["id"] = 9067, ["name"] = "The Party Never Ends", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["series"] = { 9395 }, ["description"] = "I like to throw parties... just a little something to celebrate the magnificence that is Quel'Thalas! But, I'm in a bit of a bind. I need you to gather up more party supplies. From Vinemaster Suntouched at the Silvermoon City inn, bring me a bottle of Suntouched Special Reserve . From Zalene Firstlight at Farstrider Retreat acquire more of those delicious Springpaw Appetizers . And you can pick up my delivery of fireworks from Halis Dawnstrider at Fairbreeze Village. Be quick about it!", ["objectivesText"] = "Acquire a bottle of Suntouched Special Reserve , Springpaw Appetizers and a Bundle of Fireworks , and return them to Lord Saltheril at Saltheril's Haven in Eversong Woods. Progress: Didn't I just send you out to gather up more party supplies? Was that you? Oh, I can't be expected to remember everyone's face, now can I? I meet so many... interesting people. What is it that you want?", ["rewardGold"] = 859500, ["rewardXP"] = 200, ["rewardItems"] = { 22775, 22776, 22777, 23500 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 16144, ["x"] = 0.381, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 16144, ["x"] = 0.381, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.381, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 9, 