[9076] = { ["id"] = 9076, ["name"] = "Wretched Ringleader", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["series"] = { 8480 }, ["description"] = "The Wretched are so oblivious, gorging on foul magic, that they haven't realized we've recovered most of our weapons. We can't expect them to remain in their stupor, though. Now is the time for a decisive attack. Let us make an example of their leader, Aldaron. He was spotted on the top floor of the building by the anchorage. Bring me his head; I'll reward you suitably.", ["objectivesText"] = "Bring Aldaron's Head to Velendris Whitemorn near Sunsail Anchorage in Eversong Woods. Progress: Well, do you have his head or not? I've no time to waste, <name>.", ["rewardGold"] = 286500, ["rewardXP"] = 200, ["rewardItems"] = { 22487, 22964, 22965, 22966, 131240 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15404, ["x"] = 0.362, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15404, ["x"] = 0.362, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 20, ["flags"] = 0 } } },
[9119] = { ["id"] = 9119, ["name"] = "Malfunction at the West Sanctum", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9119 }, ["series"] = { 8472, 8486, 8895 }, ["description"] = "Since you're here, <name>, I've a favor to ask you. Ley-Keeper Velania 's apprentice dropped by earlier to ask for assistance. Apparently there's some malfunction happening at the West Sanctum. I've been a bit busy entertaining our... most pleasant... dwarven guest. See if you can give her a hand. You'll find the West Sanctum southwest of here.", ["objectivesText"] = "Speak to Ley-Keeper Velania at the West Sanctum in Eversong Woods.", ["rewardGold"] = 99850, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15405, ["x"] = 0.446, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15401, ["x"] = 0.366, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9133] = { ["id"] = 9133, ["name"] = "Fly to Silvermoon City", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9133 }, ["series"] = { 9130, 9134, 9135 }, ["description"] = "<class>, for a very modest amount of coin, I can send you swiftly flying through the air on one of these magnificent beasts. And, it's safer than walking there, I can assure you! When you arrive in Silvermoon City, seek out Sathren Azuredawn in the Bazaar. Speak with me once more when you've decided you're ready to brave the skies.", ["objectivesText"] = "Purchase a flight to Silvermoon City and deliver Sathiel's Request to Sathren Azuredawn in Silvermoon City. Progress: That's quite a list you have there, friend. Let me take a look at it.", ["rewardGold"] = 49925, ["rewardXP"] = 100, ["rewardItems"] = { 22549 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 44036, ["x"] = 0.44, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 16191, ["x"] = 0.540286, ["y"] = 0.672 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 94, 110 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9135] = { ["id"] = 9135, ["name"] = "Return to Sathiel", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9135 }, ["series"] = { 9130, 9133, 9134 }, ["description"] = "It all checks out as far as I can tell. So, the question is, have you already spoken to Skymaster Brightdawn in Fairbreeze Village? If so, then this can be as simple as you paying the small fare and quickly flying back. Let me know when you're ready.", ["objectivesText"] = "Purchase a flight back to Fairbreeze Village in Eversong Woods and deliver Sathiel's Goods to Sathiel . Progress: <class>, back so soon? That doesn't look like everything I requested...", ["rewardGold"] = 58650, ["rewardXP"] = 200, ["rewardItems"] = { 22550 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 16192, ["x"] = 0.544, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 16261, ["x"] = 0.436, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9138] = { ["id"] = 9138, ["name"] = "Suncrown Village", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9139, 9140, 9327, 9329, 9758, 28560 }, ["description"] = "We're surrounded here, <class>. The outlying villages have all been overrun by the Scourge! You must head northeast to Suncrown Village immediately and deal with the Nerubian Scourge menace. You can't miss them - they're spider-like creatures. There's no time to waste.... Quel'Thalas must be reclaimed!", ["objectivesText"] = "Slay 10 Nerubis Guards and then return to Arcanist Vandril at Tranquillien in the Ghostlands .", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.2855 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 3, ["flags"] = 0 } } },
[9139] = { ["id"] = 9139, ["name"] = "Goldenmist Village", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9138, 9140, 9327, 9329, 9758, 28560 }, ["description"] = "We've had one success, but there are two more villages that must be reclaimed! Goldenmist Village is our next target. It lies to the northwest, and has been taken by the ghosts of the high elves that used to live there. Gruesome, I know, but these are apparently the sorts of tactics that the Scourge like to employ. Go and defeat these ghosts and wraiths, <class>. Take the west road out of Tranquillien to get there.", ["objectivesText"] = "Defeat 6 Quel'dorei Ghosts and 4 Quel'dorei Wraiths at Goldenmist Village, and then return to Arcanist Vandril at Tranquillien in the Ghostlands .", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23444, 28152 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.2855 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 30, ["flags"] = 0 } } },
[9140] = { ["id"] = 9140, ["name"] = "Windrunner Village", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9138, 9139, 9327, 9329, 9758, 28560 }, ["description"] = "<name>, the final battle against the Ghostlands villages is upon you. Windrunner Village to the southwest has been overrun by a large force of the more powerful Scourge shocktroopers; shades and gargoyles. You will be the spearpoint of our offensive by thinning out their numbers. The magisters at the nearby Sanctum of the Sun have made a special request this time; they want the remains from these Scourge to study in hopes of finding creative ways of fighting them. Good hunting!", ["objectivesText"] = "Gather 6 Phantasmal Substance and 4 Gargoyle Fragments . Return them to Arcanist Vandril at Tranquillien in the Ghostlands . Progress: <class>, has Windrunner Village been liberated? Those damned magisters at the Sanctum of the Sun have been berating me to get their hands on those Scourge remnants I asked you to gather. Don't worry about that, though. You take your time and get the job done right. I'll deal with the magisters.", ["rewardGold"] = 210000, ["rewardXP"] = 250, ["rewardItems"] = { 22566, 22567, 23402, 23403, 23404, 28151, 131241 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.2855 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 31, ["flags"] = 0 } } },
[9143] = { ["id"] = 9143, ["name"] = "Dealing with Zeb'Sora", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9145, 9146 }, ["description"] = "The lieutenant here rushed us into battle with the trolls across the lake instead of scouting the situation first. We were decimated by his stupidity! You hear me Tomathren? You're an idiot! Will you help us, <class>? Those trolls still need to be dealt with. I need to stay here and nursemaid him -- I think he's lost his mind. Just head east to the other side of the lake into Zeb'Sora. I want revenge... bring me their ears so that I can fashion a nice necklace!", ["objectivesText"] = "Collect 6 Zeb'Sora Troll Ears and return them to Ranger Valanna in the Ghostlands . Progress: You get those troll ears yet? You know, if we could get some help from Tranquillien every once in a while this wouldn't be such a problem. I'm just glad that you're here.", ["rewardXP"] = 200, ["rewardItems"] = { 22639 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16219, ["x"] = 0.66, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16219, ["x"] = 0.66, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 5, ["flags"] = 0 } } },
[9144] = { ["id"] = 9144, ["name"] = "Missing in the Ghostlands", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9144 }, ["series"] = { 9147, 9148 }, ["description"] = "My nephew was sent into the Ghostlands a few days ago. He never mentioned anything about his task, except that it was of an extremely secret nature. He never returned and I fear for the worst, <class>. A missing messenger might not mean much to the callous magisters of Silvermoon, but he's like a son to me. Please, <name>, will you look for him?", ["objectivesText"] = "Follow the road out of Fairbreeze Village towards the south and look for Courier Dawnstrider as you approach the Ghostlands .", ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 16210, ["x"] = 0.44, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 16183, ["x"] = 0.49, ["y"] = 0.89 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9145] = { ["id"] = 9145, ["name"] = "Help Ranger Valanna!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9143, 9146 }, ["description"] = "<class>, I can't just sit here waiting for an audience with the high executor or Dame Auriferous! This cannot wait! We were dealing with the Shadowpine trolls of Zeb'Sora to the northeast across Lake Elrendar. But the lieutenant mishandled the attack and we lost a lot of Farstriders. Then he just fell to pieces afterward. Ranger Valanna sent me here, and Ranger Salissa to the Farstrider Enclave for help. Please find them, <class>. Valanna was badly injured and the lieutenant's useless.", ["objectivesText"] = "Find Ranger Valanna and Lieutenant Tomathren on the shore of Lake Elrendar in the Ghostlands near Suncrown Village.", ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16213, ["x"] = 0.455, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16219, ["x"] = 0.66, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 4, ["flags"] = 0 } } },
[9146] = { ["id"] = 9146, ["name"] = "Report to Captain Helios", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9143, 9145 }, ["description"] = "I need one last favor of you, <class>. Just in case Ranger Salissa didn't make it back to Farstrider Enclave on the south edge of the lake, I need you to go there and get help. Just check in with Captain Helios and let him know what's happened here. I'm sure he'll send help back as soon as he can.", ["objectivesText"] = "Speak with Captain Helios at the Farstrider Enclave on the southern shore of Lake Elrendar in the Ghostlands .", ["rewardGold"] = 99850, ["rewardXP"] = 50, ["rewardItems"] = { 23405, 28144, 28153, 131242 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16219, ["x"] = 0.66, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16220, ["x"] = 0.722, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 6, ["flags"] = 0 } } },
[9147] = { ["id"] = 9147, ["name"] = "The Fallen Courier", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9147 }, ["series"] = { 9144, 9148 }, ["description"] = "What are you standing around for? Can't you see this boy needs immediate attention? By the looks of it, the plague is beginning to take over his body. Within minutes not even a master apothecary like me will be able to save him. The animals south of the river all carry the plague in their blood. Go across the bridge and hunt the plagued beasts there. Bring me enough plagued blood samples and I'll distill a serum capable of saving this blood elf. Hurry!", ["objectivesText"] = "Apothecary Thedra in Eversong Woods wants you to bring her 4 Plagued Blood Samples from beasts in the Ghostlands . Progress: Well? Did you bring me what I need? Hurry, or the pretty <race> boy is a goner!", ["rewardXP"] = 200, ["rewardItems"] = { 22570 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 16196, ["x"] = 0.49, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 16196, ["x"] = 0.49, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9148] = { ["id"] = 9148, ["name"] = "Delivery to Tranquillien", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9148 }, ["series"] = { 9144, 9147 }, ["description"] = "I... I'm too weak to continue. I carry a dire warning from Regent Lord Theron, in the form of a letter. You'll have to deliver it for me. Take it to Arcanist Vandril in Tranquillien. You'll find the town further to the south along this road. Go there and... find Vandril...", ["objectivesText"] = "Bring the Letter from Silvermoon to Arcanist Vandril at Tranquillien in the Ghostlands . Progress: You have the letter?", ["rewardGold"] = 49925, ["rewardXP"] = 100, ["rewardItems"] = { 22571, 22717, 28146, 28147, 28148, 131243 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 16183, ["x"] = 0.49, ["y"] = 0.89 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.89 }, ["mapCandidates"] = { ["npc"] = { 94, 95 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9149] = { ["id"] = 9149, ["name"] = "The Plagued Coast", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "To find a cure for the plague we need to understand how it affects different creatures, from the most complex life forms to the lowliest subspecies. I've come here to study the murlocs since, like us, they've retained free will in undeath. What makes these lowly mongrels so special? I need to find out, <name>! Travel northwest and bring me their spines so that I may study the accumulation of plague in their marrow. Who knows what secrets their little bones hold?", ["objectivesText"] = "Bring 6 Plagued Murloc Spines to Apothecary Renzithen in Tranquillien in the Ghostlands . Progress: Have you obtained the specimens I asked of you, <name>?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 6372, 22579, 28150 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16198, ["x"] = 0.475333, ["y"] = 0.346667 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16198, ["x"] = 0.475333, ["y"] = 0.346667 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.346667 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 22, ["flags"] = 0 } } },
[9150] = { ["id"] = 9150, ["name"] = "Salvaging the Past", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "Can you believe it? We have an actual functioning arcane sanctum up and running southeast of here: the Sanctum of the Sun. All manner of important magisters have come to take part in running it. Of course they've all forgotten about the Sanctum of the Moon. Not much remains of it and its energies have given rise to bizarre creatures. I'm not one to let good resources go to waste, however. Go to the Sanctum of the Moon and see if you can recover the crystallized essences from the creatures there.", ["objectivesText"] = "Magister Darenis wants you to travel to the Sanctum of the Moon to the west of Tranquillien and recover 8 Crystallized Mana Essences from the Arcane Devourers and Mana Shifters that inhabit the structure. Progress: Did you obtain the essences, <name>?", ["rewardGold"] = 99850, ["rewardXP"] = 200, ["rewardItems"] = { 22580 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16199, ["x"] = 0.46, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16199, ["x"] = 0.46, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 21, ["flags"] = 0 } } },
[9151] = { ["id"] = 9151, ["name"] = "The Sanctum of the Sun", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9161, 9162, 9167, 9172, 9176, 9282 }, ["description"] = "You've proven your loyalty to Tranquillien and have helped us defend it against the threat of the Scourge. Some of our most powerful magisters have come from Silvermoon to help us take the fight to the enemy's doorstep. They've rebuilt the arcane sanctum to the south and have driven the Scourge away from the surrounding area. They plan to launch an offensive into Deatholme, Dar'Khan's stronghold. You would do well to join them, <name>. I'm sure they can make use of a seasoned <class> like yourself.", ["objectivesText"] = "Speak to Magister Idonis in the Sanctum of the Sun in the Ghostlands .", ["rewardGold"] = 29325, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16199, ["x"] = 0.46, ["y"] = 0.316 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16204, ["x"] = 0.548, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 32, ["flags"] = 0 } } },
[9152] = { ["id"] = 9152, ["name"] = "Tomber's Supplies", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "How am I supposed to supply the war effort when I cannot even safely get my supplies here? I was promised an escort that never came. And then, I had to leave one of my carts behind to the west when I was attacked by a band of ghouls! Want to help out, and get me open for business in the process? Go down the western road out of town and past the graveyard. On the other side of the Dead Scar is a fork in the road. The hill that my cart had to be left on lies just beyond.", ["objectivesText"] = "Retrieve Rathis Tomber's Supplies and return it to him at Tranquillien in the Ghostlands . Progress: Just as soon as I get the rest of my supplies, I'll be open for business. The forces here aren't going to get very far if they can't purchase what they need to ply their trades. War zones can be such profitable places, wouldn't you agree, <class>? Now, did you manage to fight your way to my cart through all of those ghouls?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 954, 955, 2770, 2771, 2775, 3012, 22583 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16224, ["x"] = 0.471, ["y"] = 0.284 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16224, ["x"] = 0.471, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 20, ["flags"] = 0 } } },
[9155] = { ["id"] = 9155, ["name"] = "Down the Dead Scar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "If you've made it this far then you probably know about the Dead Scar and how to this day mindless Scourge follow the path of destruction that Arthas created on his way to Silvermoon City. Make yourself useful and thin down the Scourge's numbers in the Scar. If you prove to be worth your salt I'll put in a good word for you.", ["objectivesText"] = "Slay 10 Risen Hungerers and 10 Gangled Cannibals on the Dead Scar. Return to Deathstalker Rathiel in Tranquillien for a reward.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 1179, 4605 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16200, ["x"] = 0.46, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16200, ["x"] = 0.46, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 23, ["flags"] = 0 } } },
[9156] = { ["id"] = 9156, ["name"] = "WANTED: Knucklerot and Luzran", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "A bounty is hereby declared for the abominations known as Knucklerot and Luzran. These dreadful creations of Dar'Khan are extremely dangerous and have been sighted patrolling near the Howling and Bleeding Ziggurats. Individuals seeking to claim the reward must present the abominations' heads to Deathstalker Rathiel as proof of the deed.", ["objectivesText"] = "Search the Ghostlands for Knucklerot and Luzran. Bring their heads to Deathstalker Rathiel in Tranquillien for a reward. Progress: You have something to show me, <name>?", ["rewardGold"] = 315000, ["rewardXP"] = 300, ["rewardItems"] = { 22893, 22894, 22979, 28303 }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16200, ["x"] = 0.46, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "group", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 17, ["flags"] = 0 } } },
[9157] = { ["id"] = 9157, ["name"] = "Forgotten Rituals", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9174 }, ["description"] = "Every year we, the denizens of Suncrown Village, would take part in a ritual to keep the different aspects of nature under our control. Dominion over the element of water was symbolized by the summoning and enslavement of an elemental named Aquantion. Through a wicked perversion of our magic, the scoundrel broke his bonds and enslaved us instead! We wore medallions shaped like waves during the ritual. Seek them at the bottom of the lake; we'll need them to free my compatriots' spirits!", ["objectivesText"] = "Bring 8 Wavefront Medallions to Geranis Whitemorn in the Ghostlands . Progress: Have you obtained the medallions, <name>? The drowned still haunt this lake!", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 22674 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16201, ["x"] = 0.722, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16201, ["x"] = 0.722, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 11, ["flags"] = 0 } } },
[9158] = { ["id"] = 9158, ["name"] = "Bearers of the Plague", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9158 }, ["description"] = "You show courage coming to the Ghostlands , <name>. There is much work to be done here and not enough brave souls to do it. I've a thankless task to offer you, should you have the inclination to aid our cause. The very wildlife in this land has been tainted by the plague and we must stop it from spreading. Hunt the ghostclaw lynxes to the east and south of here and return when you've slain enough of them.", ["objectivesText"] = "Farstrider Sedina at the Farstrider Enclave in the Ghostlands wants you to slay 10 Ghostclaw Lynxes .", ["rewardGold"] = 99850, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16202, ["x"] = 0.725, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16202, ["x"] = 0.725, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9159] = { ["id"] = 9159, ["name"] = "Curbing the Plague", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9159 }, ["description"] = "You've proven your worth as an ally, <name>. I need you to continue your task and track down more plagued wildlife. This time seek out some of the more dangerous beasts. Hunt the spindleweb lurkers west of the Dead Scar and the vampiric mistbats just south of here. Return to me when you're done.", ["objectivesText"] = "Farstrider Sedina at the Farstrider Enclave in the Ghostlands wants you to slay 8 Spindleweb Lurkers and 10 Vampiric Mistbats . Progress: Have you completed the task I asked of you, <name>?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23415, 28141, 28142, 28143, 131244 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16202, ["x"] = 0.725, ["y"] = 0.321 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16202, ["x"] = 0.725, ["y"] = 0.321 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.725, ["y"] = 0.321 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9160] = { ["id"] = 9160, ["name"] = "Investigate An'daroth", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9163, 9166 }, ["description"] = "<class>, we are having difficulty with a group of night elves that have recently taken over a nearby island. They've set up a small camp at the old high elf ley-line nexus, An'daroth, to the northwest. There is a dirt path that leads up to it just past the Dead Scar. I suggest that you lend us your aid by going there, investigating what they are up to, and slaying as many of the conceited night elves as you can.", ["objectivesText"] = "Investigate the area at An'daroth, kill 12 Sentinel Spies and then return to Dame Auriferous at Tranquillien in the Ghostlands .", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 858 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16231, ["x"] = 0.448, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16231, ["x"] = 0.448, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 26, ["flags"] = 0 } } },
[9161] = { ["id"] = 9161, ["name"] = "The Traitor's Shadow", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9161 }, ["series"] = { 9151, 9162, 9167, 9172, 9176, 9282 }, ["description"] = "Dar'Khan Drathir is believed to have returned from the dead to rule over the armies of the Scourge in the Ghostlands . Dar'Khan aligned himself with the Scourge long ago... yet he was once a living, breathing elf. Much of his time was spent inside Dawnstar Spire, northeast of here. He hid there for many nights, scheming against his own. Search the tower for more information, <name>. Perhaps he had a journal or kept notes. One never knows where useful information might present itself.", ["objectivesText"] = "Travel to Dawnstar Spire in the Ghostlands and search for any clues involving Dar'Khan's past.", ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16203, ["x"] = 0.718, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9162] = { ["id"] = 9162, ["name"] = "Hints of the Past", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9151, 9161, 9167, 9172, 9176, 9282 }, ["description"] = "As you skim through the pages in the journal you're overcome by an unnerving sense of being watched. The contents are unsettling. Dar'Khan's soul was one filled with hatred and contempt for his own people. The extent of his machinations and plots are all documented in great detail. Perhaps there is something here that Vynna will find useful.", ["objectivesText"] = "Return to Ranger Vynna at the Farstrider Enclave with Dar'Khan's Journal . Progress: Tell me, <name>, what did you find out?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 22706, 103977, 211279 }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16203, ["x"] = 0.718, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 34, ["flags"] = 0 } } },
[9163] = { ["id"] = 9163, ["name"] = "Into Occupied Territory", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9160, 9166 }, ["description"] = "Now, the more direct course of action that we are going to take, to figure out what these night elves are really up to, is to have you go to their island and steal any information that you can come by. I want you to head west down the road out of town to Shalandis Isle, just off the coast. Go there and recover any plans they might have on the island or on their ship.", ["objectivesText"] = "Steal the Night Elf Plans: An'daroth , Night Elf Plans: An'owyn and Night Elf Plans: Scrying on the Sin'dorei , and return them to Dame Auriferous at Tranquillien in the Ghostlands . Progress: How fare our efforts to uncover the night elf plot on Shalandis Isle, <class>?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 18230, 22590, 22591, 22592, 113364 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16231, ["x"] = 0.448, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16231, ["x"] = 0.448, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 27, ["flags"] = 0 } } },
[9164] = { ["id"] = 9164, ["name"] = "Captives at Deatholme", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "Ah, yes. I possess a draught that will break most forms of alchemically induced stupor. Side effects include confusion, nausea and - in rare cases - temporary blindness. All much preferable to whatever the Scourge plans to do to those prisoners in Deatholme, if you ask me. Best of luck, brave <class>. You are going to need it.", ["objectivesText"] = "Take Janeda's Restorative Draught to Deatholme and rescue Apprentice Varnis , Apothecary Enith and Ranger Vedoran . Return to Arcanist Janeda at the Sanctum of the Sun for a reward.", ["rewardGold"] = 210000, ["rewardXP"] = 250, ["rewardItems"] = { 22628 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16198, ["x"] = 0.475333, ["y"] = 0.346667 }, { ["mapID"] = 95, ["npcID"] = 16240, ["x"] = 0.548, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16240, ["x"] = 0.548, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.346667 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 37, ["flags"] = 0 } } },
[9166] = { ["id"] = 9166, ["name"] = "Deliver the Plans to An'telas", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9160, 9163 }, ["description"] = "You must deliver the recovered night elf plans to An'telas for me. It is to the east, on the southern slopes of Sungraze Peak, just to the northeast of the Sanctum of the Sun. Magister Sylastor is there conducting ongoing studies into the ley-line nexus energy for potential use in our fight against the Scourge. Have him look at these plans to shed some light on what it is that these night elves are up to.", ["objectivesText"] = "Deliver the Night Elf Plans to Magister Sylastor at An'telas in the Ghostlands . Progress: Oh, thank goodness for you!", ["rewardXP"] = 50, ["rewardItems"] = { 22594 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16231, ["x"] = 0.448, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16237, ["x"] = 0.602, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 28, ["flags"] = 0 } } },
[9167] = { ["id"] = 9167, ["name"] = "The Traitor's Destruction", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9151, 9161, 9162, 9172, 9176, 9282 }, ["description"] = "Everything we've done in the Ghostlands has been done with the goal of taking back what is rightfully ours. The Scourge have maintained their chokehold on the region for far too long. The time has come for payback, <name>. Thanks to your help and the help of our new allies, the Forsaken, vengeance will soon be ours. He who sought to steal the power of the Sunwell must die. Go to Deatholme, the Scourge stronghold south of the Dead Scar. Bring me Dar'Khan's head and your deeds will go down in history!", ["objectivesText"] = "Slay Dar'Khan Drathir inside Deatholme and bring his head to Magister Kaendris at the Sanctum of the Sun in the Ghostlands . Progress: Is it done, then? Has Dar'Khan been destroyed?", ["rewardGold"] = 315000, ["rewardXP"] = 300, ["rewardItems"] = { 16889, 22653, 22783, 22980, 22982, 22984, 22995, 156941 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16239, ["x"] = 0.55, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16239, ["x"] = 0.55, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "group", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 40, ["flags"] = 0 } } },
[9169] = { ["id"] = 9169, ["name"] = "Deactivate An'owyn", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "Their moon crystals are scrying devices -- they're going to spy on us! I know that An'daroth can't provide enough power for that, but An'owyn, directly to the south, most definitely can! From the plans I now have a basic knowledge of how these moon crystals work; enough to shut them down. They're keyed so that they can be turned off. You must go to An'owyn, retrieve the controlling orb from one of the night elves and then use it on the moon crystal to stop them from enacting their plan! Hurry, <class>!", ["objectivesText"] = "Retrieve the Crystal Controlling Orb and then use it to deactivate the Night Elf Moon Crystal at An'owyn. Then return to Magister Sylastor at An'telas in the Ghostlands . Progress: Is it over then, <class>? Did you deactivate the night elf moon crystal at An'owyn?", ["rewardGold"] = 683200, ["rewardXP"] = 250, ["rewardItems"] = { 23191, 23400, 23401, 28160 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16237, ["x"] = 0.602, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16237, ["x"] = 0.602, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 29, ["flags"] = 0 } } },
[9170] = { ["id"] = 9170, ["name"] = "Dar'Khan's Lieutenants", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "The odious traitor, Dar'Khan, has risen to great power among the ranks of the Scourge. His lieutenants command vast armies of undead against our dwindling numbers. Masophet the Black , Jurion the Deceiver , Borgoth the Bloodletter , Mirdoran the Fallen . Learn these names well for in the Ghostlands these Scourge leaders are second only to Dar'Khan himself. Slay them and their mindless armies will be thrown into disarray.", ["objectivesText"] = "Magister Idonis wants you to venture into Deatholme to slay Masophet the Black , Jurion the Deceiver , Borgoth the Bloodletter and Mirdoran the Fallen . Report back to him in the Sanctum of the Sun in the Ghostlands after you've completed this task.", ["rewardGold"] = 210000, ["rewardXP"] = 250, ["rewardItems"] = { 22996, 22997, 22998, 131245, 156942 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16204, ["x"] = 0.548, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16204, ["x"] = 0.548, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 39, ["flags"] = 0 } } },
[9171] = { ["id"] = 9171, ["name"] = "Culinary Crunch", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "This is intolerable! I have nothing to work with here! Milady asks me to come from Silvermoon City; she deserves cuisine as befits her station. No? But I get here and there is no food. You must go out, <class>, and bring back fresh kills so that I have something to prepare. Dame Auriferous prefers a crunchy texture to her food. There are plenty of spindleweb lurkers to the southwest on the other side of the Dead Scar. Disgusting, I know, but that's what we have to work with.", ["objectivesText"] = "Collect 5 Crunchy Spider Legs and return them to Master Chef Mouldier at Tranquillien in the Ghostlands . Progress: I believe I can hear the dame's belly rumbling even from here! I take it that you are here talking to me because you have what I asked you to obtain?", ["rewardXP"] = 200, ["rewardItems"] = { 22644, 22645, 22647 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16253, ["x"] = 0.485, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16253, ["x"] = 0.485, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 18, ["flags"] = 0 } } },
[9172] = { ["id"] = 9172, ["name"] = "Report to Magister Kaendris", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9151, 9161, 9162, 9167, 9176, 9282 }, ["description"] = "The magisters at the Sanctum of the Sun have made great progress in analyzing the Scourge's weaknesses with the aid of the Forsaken. Magister Kaendris will know what to do with this information. You'll find the Sanctum of the Sun southwest of here. You must hurry, <name>. Dar'Khan is a cunning enemy and watches our every move!", ["objectivesText"] = "Bring Dar'Khan's Journal to Magister Kaendris at the Sanctum of the Sun in the Ghostlands . Progress: You wish to speak to me?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 22706, 28154, 28157, 28161, 131246 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16203, ["x"] = 0.718, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16239, ["x"] = 0.55, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 35, ["flags"] = 0 } } },
[9173] = { ["id"] = 9173, ["name"] = "Retaking Windrunner Spire", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9173 }, ["description"] = "<class>, I want you to reclaim Windrunner Spire! It's an honor, really. Windrunner Spire is the original home of Lady Sylvanas Windrunner, queen of the Forsaken and former ranger-general of the elves. But now it's been overrun by the mindless Scourge. To get there take the road south until it branches. Take the right fork and after crossing the Dead Scar continue southwest. You can't miss it.", ["objectivesText"] = "Slay 8 Deatholme Acolytes and 10 Fallen Rangers , and return to High Executor Mavren at Tranquillien in the Ghostlands .", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16252, ["x"] = 0.448, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16252, ["x"] = 0.448, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9174] = { ["id"] = 9174, ["name"] = "Vanquishing Aquantion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9157 }, ["description"] = "That willful elemental ended many lives that fateful day when he revolted against us. By calling to the lowly murloc to sabotage our rites he subverted our magic and turned it against us. Show him our thirst for vengeance has not waned! Take these medallions and lay them at the Altar of Tidal Mastery at the bottom of the lake. Aquantion shall immediately answer your summons! Beware, <race>! Without our magic controlling him, his wrath will be unrestrained. Destroy Aquantion so we may rest!", ["objectivesText"] = "Geranis Whitemorn wants you to swim to the bottom of the lake east of Suncrown Village and use the Bundle of Medallions on the Altar of Tidal Mastery. Summon and slay the elemental known as Aquantion and return to Geranis. Progress: Has Aquantion been destroyed yet?", ["rewardGold"] = 210000, ["rewardXP"] = 250, ["rewardItems"] = { 22675 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16201, ["x"] = 0.722, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16201, ["x"] = 0.722, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 12, ["flags"] = 0 } } },
[9175] = { ["id"] = 9175, ["name"] = "The Lady's Necklace", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9175 }, ["series"] = { 9180 }, ["description"] = "The necklace shimmers, a remarkable piece of jewelry that doesn't seem to succumb to the gloom that permeates the Ghostlands . Given the inscription, and where you found it, it must be the lost property of Lady Sylvanas Windrunner herself! Perhaps it would be best to first take it to High Executor Mavren at Tranquillien? He seems to be the highest ranking Forsaken in the area and is sure to know what to do with it.", ["objectivesText"] = "Take The Lady's Necklace to High Executor Mavren at Tranquillien in the Ghostlands . Progress: What's that you have there, <name>?", ["rewardGold"] = 199700, ["rewardXP"] = 200, ["rewardItems"] = { 22597 }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16252, ["x"] = 0.448, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["startItems"] = { 22597 } },
[9176] = { ["id"] = 9176, ["name"] = "The Twin Ziggurats", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9151, 9161, 9162, 9167, 9172, 9282 }, ["description"] = "According to this journal, Dar'Khan promised the Scourge two powerful elven artifacts: the stone of light and the stone of flame . These were imbued with the magical energies of the Sunwell and attuned to have warding powers against the Scourge. The crystals were to be transported to where the Howling Ziggurat and the Bleeding Ziggurat now stand, in the middle of the Dead Scar. If they're still held there, we need to recover them. Their power will be greatly useful in our struggle against the enemy.", ["objectivesText"] = "Travel to the Bleeding Ziggurat and the Howling Ziggurat and recover the Stone of Light and the Stone of Flame . Return to Magister Kaendris at the Sanctum of the Sun after recovering the items. Progress: Have you recovered the crystals yet?", ["rewardGold"] = 105000, ["rewardXP"] = 300, ["rewardItems"] = { 22598, 22599, 22783, 22784 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16239, ["x"] = 0.55, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16239, ["x"] = 0.55, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 36, ["flags"] = 0 } } },
[9192] = { ["id"] = 9192, ["name"] = "Trouble at the Underlight Mines", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "The Underlight Mines to the southwest have been overrun by a clan of gnolls calling themselves the Blackpaw. I don't need to remind you how important those mines are to us as a strategic asset in our ongoing campaign here in the Ghostlands ! Take the south road out of town and follow the fork to the right. Just past the ziggurat on the right there will be a short dirt path to the west. Follow it. The ore must flow!", ["objectivesText"] = "Slay 8 Blackpaw Gnolls , 6 Blackpaw Scavengers and 4 Blackpaw Shaman , and return to Deathstalker Maltendis at Tranquillien in the Ghostlands .", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16251, ["x"] = 0.448, ["y"] = 0.324 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16251, ["x"] = 0.448, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 19, ["flags"] = 0 } } },
[9193] = { ["id"] = 9193, ["name"] = "Investigate the Amani Catacombs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "<class>, our sources tell us that the trolls buried in the Amani Catacombs inside Sungraze Peak have been rising from the dead. I need you to investigate these catacombs and put to the torch any of the unanimated remains you come across so as to prevent any more of these creatures from rising. The fastest way there is to head northwest out of the enclave. This will put you near the western entrance to the catacombs.", ["objectivesText"] = "Investigate the Amani Catacombs and burn 10 Mummified Troll Remains , then return to Ranger Vynna at Farstrider Enclave in the Ghostlands . Progress: This is a most grim and undignified business, <class>. I trust that you will complete this task to milady's complete satisfaction?", ["rewardGold"] = 286500, ["rewardXP"] = 200, ["rewardItems"] = { 22755 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16203, ["x"] = 0.718, ["y"] = 0.326 }, { ["mapID"] = 95, ["npcID"] = 16289, ["x"] = 0.448, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16203, ["x"] = 0.718, ["y"] = 0.326 }, { ["mapID"] = 95, ["npcID"] = 16289, ["x"] = 0.448, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 7, ["flags"] = 0 } } },
[9199] = { ["id"] = 9199, ["name"] = "Troll Juju", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "The corpses of trolls buried inside the Amani Catacombs have been rising from the dead! I want you to go there and bring back proof of their final demise. Some of these mummy trolls, and their living counterparts, carry juju; glowing objects that house an unknown power source. It's probably what is animating them! The catacombs lie within Sungraze Peak, directly to the east. I am told that the easiest way in lies on the north face of the mountain. See to it, <class>!", ["objectivesText"] = "Collect 8 Troll Juju and return them to Apothecary Venustus at Farstrider Enclave in the Ghostlands . Progress: I don't have to remind you that we can ill afford this trouble with the troll dead rising in our very backyard! We have enough trouble with Deatholme to the south!", ["rewardGold"] = 99850, ["rewardXP"] = 200, ["rewardItems"] = { 22633, 28156, 28159, 28163, 131247 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16251, ["x"] = 0.448, ["y"] = 0.324 }, { ["mapID"] = 95, ["npcID"] = 16464, ["x"] = 0.726, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16251, ["x"] = 0.448, ["y"] = 0.324 }, { ["mapID"] = 95, ["npcID"] = 16464, ["x"] = 0.726, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.324 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 8, ["flags"] = 0 } } },
[9207] = { ["id"] = 9207, ["name"] = "Underlight Ore Samples", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9207 }, ["description"] = "I was sent here from the Sanctum of the Sun to collect some ore samples, but the gnolls have overrun the place! It's going to be my head on a platter if I don't get those samples to the magister soon. Maybe you could help, <class>? You can find the ore in the tin and copper veins here, and the gnolls are carrying it around, too. When you have enough, take it to Magister Quallestis at the Sanctum of the Sun directly to the east. Go across the Dead Scar and you'll find the sanctum just south of Sungraze Peak.", ["objectivesText"] = "Collect 6 Underlight Ore and deliver them to Magister Quallestis at the Sanctum of the Sun in the Ghostlands . Progress: How may I help you, <class>?", ["rewardGold"] = 99850, ["rewardXP"] = 200, ["rewardItems"] = { 22634 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16293, ["x"] = 0.314667, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16291, ["x"] = 0.55, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.314667, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9212] = { ["id"] = 9212, ["name"] = "Escape from the Catacombs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9212 }, ["description"] = "These trolls ambushed me and have been keeping me in this cage. I think they're planning to sacrifice me! Help me get out of here! The lock on the cage isn't that complex... I just can't get to it from this side. Please escort me back to the Farstrider Enclave. I'm sure Captain Helios will reward you, and you'll have my undying gratitude!", ["objectivesText"] = "Escort Ranger Lilatha to Captain Helios at Farstrider Enclave in the Ghostlands . Progress: You're the one that rescued my ranger?", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 23412, 23413, 23414, 131248 }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16220, ["x"] = 0.722, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9214] = { ["id"] = 9214, ["name"] = "Shadowpine Weaponry", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "<class>, I want you to kill as many Shadowpine trolls as you can. We need their numbers greatly reduced before we can shift our attention toward Deatholme. And while you're at it, we might as well kill two birds with one stone, so bring me back a load of their weapons. Better that they not go to waste, and we can use them in the fight against the Scourge. Hit their camps hard to the east and the south at Zeb'Tela and Zeb'Nowa.", ["objectivesText"] = "Collect 3 Headhunter Axes , 3 Shadowcaster Maces , 3 Catlord Claws and 3 Hexxer Staves . Return them to Captain Helios at Farstrider Enclave in the Ghostlands . Progress: Have those weapons yet? With the Shadowpine numbers decimated we'll finally be able to turn our attention to the fight against the Scourge.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 22677, 23165, 23166, 23167 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16220, ["x"] = 0.722, ["y"] = 0.296 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16220, ["x"] = 0.722, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 9, ["flags"] = 0 } } },
[9215] = { ["id"] = 9215, ["name"] = "Bring Me Kel'gash's Head!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "WANTED: Bring the head of Kel'gash the Wicked , chieftain of the Shadowpine trolls, to Captain Helios . No questions asked. Kel'gash is known to dwell somewhere to the south in Zeb'Nowa. REWARD: Yes, but no advances!", ["objectivesText"] = "Return the Head of Kel'gash the Wicked to Captain Helios at the Farstrider Enclave in the Ghostlands . Progress: What is that awful smell?", ["rewardGold"] = 683200, ["rewardXP"] = 250, ["rewardItems"] = { 22640, 23409, 23410, 23411 }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16220, ["x"] = 0.722, ["y"] = 0.296 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.296 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "group", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 16, ["flags"] = 0 } } },
[9216] = { ["id"] = 9216, ["name"] = "Rotting Hearts", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "I hear the Amani trolls eat their enemies' hearts to steal their strength. They might just be on to something, <name>. With the proper treatment, the hearts of the unliving can produce potent elixirs. Hunt down the zombies that roam the Dead Scar and bring me their hearts. I'll show you the kind of enhancement we can perform to your physical prowess against the undead.", ["objectivesText"] = "Bring back 10 Rotting Hearts to Magistrix Aminel in Tranquillien. Progress: Do you have the zombie hearts I requested, <name>?", ["rewardXP"] = 200, ["rewardItems"] = { 22641, 22779 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16205, ["x"] = 0.489, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16205, ["x"] = 0.489, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 24, ["flags"] = 0 } } },
[9217] = { ["id"] = 9217, ["name"] = "More Rotting Hearts", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9217 }, ["objectivesText"] = "Progress: You've brought more ghoul hearts? I can use as many as you can collect, <name>.", ["rewardItems"] = { 22641, 22779 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16205, ["x"] = 0.489, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16205, ["x"] = 0.489, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9218] = { ["id"] = 9218, ["name"] = "Spinal Dust", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "The dark energy that flows through the bodies of reanimated skeletons tends to accumulate primarily in their spine. I've discovered a method of instilling this energy into a potion that boosts our magical abilities against the undead. Bring me some spinal dust and I'll be glad to provide you with a sample. You'll find an ample number of skeletons wandering the Dead Scar, west of here.", ["objectivesText"] = "Bring back 10 Spinal Dusts to Magistrix Aminel in Tranquillien. Progress: Do you have the samples I requested, <name>?", ["rewardXP"] = 200, ["rewardItems"] = { 22642, 22778 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16205, ["x"] = 0.489, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16205, ["x"] = 0.489, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 25, ["flags"] = 0 } } },
[9219] = { ["id"] = 9219, ["name"] = "More Spinal Dust", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9219 }, ["objectivesText"] = "Progress: You've procured more spinal dust ? I can use as much of it as you bring me.", ["rewardItems"] = { 22642, 22778 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16205, ["x"] = 0.489, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16205, ["x"] = 0.489, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9220] = { ["id"] = 9220, ["name"] = "War on Deatholme", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "If you seek to aid our cause there is no better place to start than here and no better time to do it than now. By rebuilding the Sanctum of the Sun we've raised a banner of defiance in front of our enemy's seat of power: Deatholme. Go forth and fight the hordes of undead that inhabit the vile Scourge fortress.", ["objectivesText"] = "Slay 5 Eyes of Dar'khan, 6 Nerubis Centurions and 6 Wailers in Deatholme and return to Magister Idonis at the Sanctum of the Sun in the Ghostlands .", ["rewardGold"] = 210000, ["rewardXP"] = 250, ["rewardItems"] = { 44836 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16204, ["x"] = 0.548, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16204, ["x"] = 0.548, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 38, ["flags"] = 0 } } },
[9252] = { ["id"] = 9252, ["name"] = "Defending Fairbreeze Village", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["description"] = "We've experienced a marked increase in Scourge attacks, <name>. Our defenses are barely holding and there's no sign of reinforcements from Silvermoon City. Lend us a hand in defending the village by thinning the numbers of the undead roaming the Dead Scar nearby.", ["objectivesText"] = "Slay 4 Rotlimb Marauders and 4 Darkwraiths and return to Ranger Sareyn at Fairbreeze Village in Eversong Woods. Progress: We will prevail, <name>.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15942, ["x"] = 0.468, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15942, ["x"] = 0.468, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 13, ["flags"] = 0 } } },
[9253] = { ["id"] = 9253, ["name"] = "Runewarden Deryan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9253 }, ["series"] = { 8490 }, ["description"] = "This increase in Scourge attacks leads me to believe there might be a malfunction at one of the protective runestones at the border with the Ghostlands. We used these ancient stones to protect us against the undead. Most of them were destroyed or lost after the attack on the Sunwell. Follow the road south, towards the Ghostlands, and look to the west for a small path. You will find Runewarden Deryan by the runestone nearby; he will know whether anything's wrong.", ["objectivesText"] = "Speak to Runewarden Deryan in Eversong Woods, near the border with the Ghostlands.", ["rewardGold"] = 85400, ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15942, ["x"] = 0.468, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 16362, ["x"] = 0.442, ["y"] = 0.855 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9254] = { ["id"] = 9254, ["name"] = "The Wayward Apprentice", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9254 }, ["series"] = { 8487 }, ["description"] = "Thank you for your help, <name>. While I get things back in order here, I'd like to ask you for a favor. One of my former apprentices embarked in a very dangerous line of research. She journeyed to the East Sanctum, in the middle of the Dead Scar. I worry for her well-being. See if you can find her and convince her to return to her senses.", ["objectivesText"] = "Speak to Apprentice Mirveda at the East Sanctum in Eversong Woods.", ["rewardGold"] = 14665, ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 16210, ["x"] = 0.44, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15402, ["x"] = 0.542, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9255] = { ["id"] = 9255, ["name"] = "Research Notes", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["series"] = { 8488 }, ["description"] = "As discouraging as my research results are, they still contain valuable data. I must have a Magister review my work before it is taken seriously. Please, take these notes to Magistrix Landra Dawnstrider at Fairbreeze Village, west of here.", ["objectivesText"] = "Deliver the Research Notes to Magistrix Landra Dawnstrider at Fairbreeze Village in Eversong Woods. Progress: You've something for me?", ["rewardGold"] = 26250, ["rewardXP"] = 100, ["rewardItems"] = { 22735, 210951, 211395 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15402, ["x"] = 0.542, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 16210, ["x"] = 0.44, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 12, ["flags"] = 0 } } },
[9256] = { ["id"] = 9256, ["name"] = "Fairbreeze Village", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9256 }, ["series"] = { 8892 }, ["description"] = "I have another task for you, <name>. Ranger Degolien was sent to Fairbreeze Village to find out more about a Wretched attack on a nearby shipyard. He has requested reinforcements which we cannot yet provide. Seek him out and grant him whatever aid you can. Fairbreeze Village can be reached by following the road out of Falconwing Square all the way towards the south. Good luck, <name>.", ["objectivesText"] = "Speak to Ranger Degolien at Fairbreeze Village in Eversong Woods.", ["rewardGold"] = 170800, ["rewardXP"] = 100, ["rewardItems"] = { 23265, 23266, 23267, 131252 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15403, ["x"] = 0.48, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15939, ["x"] = 0.434, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9257] = { ["id"] = 9257, ["name"] = "Atiesh, Greatstaff of the Guardian", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 440, ["storyline"] = { 9257 }, ["description"] = "This final task will be the most difficult of all, <name>. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras. Take the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", ["objectivesText"] = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", ["rewardXP"] = 6175, ["rewardItems"] = { 22589, 22630, 22631, 22632, 22737 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Nightborne" },
[9258] = { ["id"] = 9258, ["name"] = "The Scorched Grove", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9258 }, ["series"] = { 8473 }, ["description"] = "A foul taint in the soil precedes the expansion of the Scourge into a new area. The protective runestones along the border with the Ghostlands have warded the land against this taint in the past. The westernmost runestone was destroyed during a Scourge attack, which forced us to burn the ground around it to prevent the taint from spreading. My sister, Larianna Riverwind , watches over the Scorched Grove. Go find her; she might have some work for you.", ["objectivesText"] = "Find Larianna Riverwind near the Scorched Grove in the southwest of Eversong Woods.", ["rewardGold"] = 85400, ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 16397, ["x"] = 0.435, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15398, ["x"] = 0.34, ["y"] = 0.8 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9266] = { ["id"] = 9266, ["name"] = "Making Amends", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 618, ["mapID"] = 83, ["storyline"] = { 9266 }, ["objectivesText"] = "Progress: You must've done something really bad to us or our friends, <name>. At any rate, I'm here to offer you a way to get our good graces back. As you know, Winterspring is quite cold. With so many of us goblins coming from other cities, we could use a hand keeping warm. Bring me some runecloth and coal and I'll put in the good word for ya. Be warned though, our enemies are not going to take kindly to your helping us.", ["rewardItems"] = { 3857, 14047 }, ["starts"] = { { ["mapID"] = 83, ["npcID"] = 16416, ["x"] = 0.58, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 83, ["npcID"] = 16416, ["x"] = 0.58, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 83, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 83 }, ["zone"] = { 618 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Suffusion Camps" },
[9269] = { ["id"] = 9269, ["name"] = "Atiesh, Greatstaff of the Guardian", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 440, ["storyline"] = { 9269 }, ["description"] = "This final task will be the most difficult of all, <name>. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras. Take the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", ["objectivesText"] = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", ["rewardXP"] = 6175, ["rewardItems"] = { 22589, 22630, 22631, 22632, 22737 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Nightborne" },
[9270] = { ["id"] = 9270, ["name"] = "Atiesh, Greatstaff of the Guardian", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 440, ["storyline"] = { 9270 }, ["description"] = "This final task will be the most difficult of all, <name>. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras. Take the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", ["objectivesText"] = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", ["rewardXP"] = 6175, ["rewardItems"] = { 22589, 22630, 22631, 22632, 22737 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Nightborne" },
[9271] = { ["id"] = 9271, ["name"] = "Atiesh, Greatstaff of the Guardian", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 440, ["storyline"] = { 9271 }, ["description"] = "This final task will be the most difficult of all, <name>. You have faced and defeated both an Old God and the Lich King's General, but now you must face the hand of Sargeras. Take the staff to Stratholme. It is there that you will find a piece of consecrated earth: ground where the greatest knights of Lordaeron were murdered. Place the befouled staff upon the holy ground and prepare for an entity of immense power to break from within... Defeat the demonic being that controls the staff and return to me.", ["objectivesText"] = "Anachronos at the Caverns of Time in Tanaris wants you to take Atiesh, Greatstaff of the Guardian to Stratholme and use it on Consecrated Earth. Defeat the entity that is exorcised from the staff and return to him.", ["rewardXP"] = 6175, ["rewardItems"] = { 22589, 22630, 22631, 22632, 22737 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Nightborne" },
[9274] = { ["id"] = 9274, ["name"] = "Spirits of the Drowned", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "The lake to the north has been haunted by the ghosts of my ancestors for as long as I can remember, <name>. The poor souls were victims of a tragic incident in which scores of them drowned at the bottom of the lake. The details of the event are mostly forgotten, but their haunting cries serve as a constant reminder of their curse. If you're up to the task, I want you to go to the lake and put an end to their suffering, <name>. You will have my gratitude as well as theirs... I'm sure.", ["objectivesText"] = "Ranger Krenn'an , at the Farstrider Enclave in the Ghostlands , wants you to kill 8 Vengeful Apparitions and 8 Ravening Apparitions in the nearby lake.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16462, ["x"] = 0.722, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16462, ["x"] = 0.722, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 10, ["flags"] = 0 } } },
[9275] = { ["id"] = 9275, ["name"] = "A Little Dash of Seasoning", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["description"] = "I'm on loan to the Farstriders in an attempt to help with their troll difficulties. I believe that I have a solution to their problem. At my disposal are a number of potent poisons. The trolls, as you know, are living creatures and therefore must eat. If we combine my poison with their food... well, I'm sure that the results will be entertaining! Care to help rid us of the Shadowpine trolls at Zeb'Nowa to the south? The camp straddles both the north and south sides of the road to Zul'Aman.", ["objectivesText"] = "Poison the Troll foodstuff at the camps in Zeb'Nowa and then return to Apothecary Venustus at the Farstrider Enclave in the Ghostlands . Progress: Isn't this exciting? I really do take great pride in my work; I hope you appreciate it, <class>. So, I trust that you have 'seasoned' the food at the troll camps in Zeb'Nowa?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 22796 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16464, ["x"] = 0.726, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16464, ["x"] = 0.726, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 15, ["flags"] = 0 } } },
[9276] = { ["id"] = 9276, ["name"] = "Attack on Zeb'Tela", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9277 }, ["description"] = "Our resources are spread pretty thin here, <class>, so your help is going to be invaluable. The captain has tasked me with overseeing the harassment of the local Shadowpine troll camps. We have a policy of keeping them off balance until the day when we can launch a brutal offensive to wipe them out. Until then, we need all of the volunteers that we can get so that those Shadowpine troll numbers are decreased. Think you could head east to Zeb'Tela and hurt them a little?", ["objectivesText"] = "Kill 8 Shadowpine Shadowcasters and 8 Shadowpine Headhunters , and return to Farstrider Solanna at Farstrider Enclave in the Ghostlands .", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16463, ["x"] = 0.723, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16463, ["x"] = 0.723, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.723, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 13, ["flags"] = 0 } } },
[9277] = { ["id"] = 9277, ["name"] = "Assault on Zeb'Nowa", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9276 }, ["description"] = "Time for something a little more challenging. Zeb'Nowa, to the south, is where the more powerful Shadowpine trolls make their home. In our continuing effort to keep the troll numbers to a minimum I'm dispatching you to go down there and assail them by whatever means you have at your disposal. What do you say, <name>? Ready to deal with some more trolls?", ["objectivesText"] = "Kill 10 Shadowpine Catlords and 10 Shadowpine Hexxers , and return to Farstrider Solanna at the Farstrider Enclave in the Ghostlands .", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23406, 23407, 23408, 131249 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16463, ["x"] = 0.723, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16463, ["x"] = 0.723, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.723, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 14, ["flags"] = 0 } } },
[9279] = { ["id"] = 9279, ["name"] = "You Survived!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9280, 9369, 9409 }, ["description"] = "Nevermind my injuries, <brother/sister>. It's a miracle that any of us are alive! It didn't look like you'd pull through; you've been in suspension for weeks. Something happened and the Exodar crashed. Many have died. But I'm relieved that you are alive, <name>. With you leading our efforts, I'm sure we'll get to safety soon! Proenitus asked me to send you to him when you awoke. He's waiting for you at the bottom of the hill. Just follow the path southwest.", ["objectivesText"] = "Speak with Proenitus at the Crash Site in Ammen Vale .", ["rewardGold"] = 28600, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16475, ["x"] = 0.842, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16477, ["x"] = 0.804, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.842, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 0, ["flags"] = 0 } } },
[9281] = { ["id"] = 9281, ["name"] = "Clearing the Way", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9281 }, ["description"] = "Magister Kaendris sent me down here to clear the area of any hostile wildlife. Once this area is secured, the magisters plan to turn it into some sort of advance outpost against the Scourge. Now if there's one thing I've learned as an apprentice it's to delegate responsibility - especially in matters that endanger one's life! If you're interested, I'll pay you well to kill the greater spindlewebs and ghostclaw ravagers to the west and south of here.", ["objectivesText"] = "Apprentice Vor'el at Andilien Estate in the Ghostlands wants you to slay 10 Greater Spindlewebs and 10 Ghostclaw Ravagers .", ["rewardGold"] = 210000, ["rewardXP"] = 200, ["rewardItems"] = { 26009, 26023, 26035, 112595, 112596, 112597, 112598, 131273 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16480, ["x"] = 0.465, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16480, ["x"] = 0.465, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9282] = { ["id"] = 9282, ["name"] = "The Farstrider Enclave", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9151, 9161, 9162, 9167, 9172, 9176 }, ["description"] = "Magisters and Farstriders may not see eye to eye all the time, <name>. When it comes to Dar'Khan, however, we're all in agreement that a way must be found to defeat him and his legions. Ranger Vynna , at the Farstrider Enclave northeast of here, has come across important information regarding our enemy. Speak to her and see if you can be of assistance.", ["objectivesText"] = "Magister Kaendris , at the Sanctum of the Sun, wants you to talk to Ranger Vynna at the Farstrider Enclave in the Ghostlands .", ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16239, ["x"] = 0.55, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16203, ["x"] = 0.718, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 33, ["flags"] = 0 } } },
[9283] = { ["id"] = 9283, ["name"] = "Rescue the Survivors!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "The healing crystals are replenished, but that is not the only way we can help the injured. All draenei can tap the gift of the Naaru to heal. You must use this ability to heal one of the crash survivors. You'll find most of the survivors in the areas to the west and northwest, but the crash scattered us all over the vale. The survivors have suffered from exposure to the irradiated power crystals, so you should be able to find them by the red glow that surround them. You must save them, <name>.", ["objectivesText"] = "Use your Gift of the Naaru ability on one of the Draenei Survivors spread throughout Ammen Vale , then return to Zalduun at the Crash Site in Ammen Vale . Progress: We'll survive this yet with your help.", ["rewardGold"] = 107000, ["rewardXP"] = 250, ["rewardItems"] = { 23389 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16502, ["x"] = 0.8, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16502, ["x"] = 0.8, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.8, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 4, ["flags"] = 0 } } },
