[9293] = { ["id"] = 9293, ["name"] = "What Must Be Done...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9371, 10302 }, ["description"] = "The nearby lake has been contaminated by one of the ship's power crystals. Many of the plants and animals of Ammen Vale have been mutated because of this. I have a theory on how to heal the lake, but I must have samples from the mutated lashers for analysis. They can be found to the west in the Ammen Fields. Will you help me, <class>?", ["objectivesText"] = "Gather 10 Lasher Samples and return them to Botanist Taerix at the Crash Site in Ammen Vale . Progress: I'll need all of the samples in good condition if we're to have a chance of cleansing the lake. We don't have much time, <class>!", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 22934 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16514, ["x"] = 0.792, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16514, ["x"] = 0.792, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 7, ["flags"] = 0 } } },
[9294] = { ["id"] = 9294, ["name"] = "Healing the Lake", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "Thank goodness, I think it'll work! I have an agent for you to spread at Silverline Lake to the south. It will neutralize the effects of the irradiated ship's power crystal that fell there. Swim out and scatter the neutralizing agent near it. Don't worry, you won't be exposed long enough to become irradiated.", ["objectivesText"] = "Disperse the Neutralizing Agent at the Irradiated Power Crystal, then return to Botanist Taerix at the Crash Site in Ammen Vale . Progress: The sooner you disperse the agent at the lake, the fewer native creatures that will be mutated by drinking the water, including ourselves! I'm sorry that we can't do anything to help the poor creatures that have already been infected. If only my lab equipment were intact.", ["rewardXP"] = 200, ["rewardItems"] = { 22955 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16514, ["x"] = 0.792, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16514, ["x"] = 0.792, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 9, ["flags"] = 0 } } },
[9303] = { ["id"] = 9303, ["name"] = "Inoculation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 10304 }, ["description"] = "Zhanaa needs our help to salvage parts from the Exodar. Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage. Just get close to the unaffected ones and use the crystal on them. Unfortunately, you'll have to kill the others. You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.", ["objectivesText"] = "Use the Inoculating Crystal on 6 Nestlewood Owlkin. Then return to Vindicator Aldar at the Crash Site in Ammen Vale . Progress: The more we can do to clear up Nestlewood, the faster Zhanaa can get back to work.", ["rewardGold"] = 107000, ["rewardXP"] = 250, ["rewardItems"] = { 118, 2454, 5997, 22962, 152096, 237812 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16535, ["x"] = 0.794, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16535, ["x"] = 0.794, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.794, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 11, ["flags"] = 0 } } },
[9305] = { ["id"] = 9305, ["name"] = "Spare Parts", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale . There were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. <name>, you must go south to Nestlewood Thicket and Hills to find the spare parts.", ["objectivesText"] = "Collect 4 Emitter Spare Parts and then return to Technician Zhanaa at the Crash Site in Ammen Vale . Progress: When we have those spare parts, I know that we'll get this emitter repaired. With any luck there will be someone else out there left to talk to.", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 22978, 24423, 24424, 24425, 57489, 57490, 57491, 131250, 131472 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17071, ["x"] = 0.794, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17071, ["x"] = 0.794, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.794, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 17, ["flags"] = 0 } } },
[9309] = { ["id"] = 9309, ["name"] = "The Missing Scout", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9311, 10303 }, ["description"] = "We now have several separate confirmations of unusual activity up on the Shadow Ridge. This is disturbing; we thought that the scouting missions already undertaken had been thorough. One of my scouts hasn't reported back yet. <class>, I need you to head southwest to the other side of Silverline Lake and find Tolaan , and see what has delayed him.", ["objectivesText"] = "Find and speak with Tolaan at Shadow Ridge in Ammen Vale .", ["rewardGold"] = 58650, ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16535, ["x"] = 0.794, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16546, ["x"] = 0.72, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.794, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 13, ["flags"] = 0 } } },
[9311] = { ["id"] = 9311, ["name"] = "Blood Elf Spy", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9309, 10303 }, ["description"] = "I have a plan. We must kill their leader. Without their master, perhaps they will retreat to regroup. We just need to buy time until the repairs are completed. Then Vindicator Aldar must know of this. Kill the surveyor, then return and tell him what we've found.", ["objectivesText"] = "Slay Surveyor Candress and then inform Vindicator Aldar at the Crash Site in Ammen Vale .", ["rewardGold"] = 160500, ["rewardXP"] = 300, ["rewardItems"] = { 23390, 23391, 23392, 23393, 24441, 25553 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16546, ["x"] = 0.72, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16535, ["x"] = 0.794, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 15, ["flags"] = 0 } } },
[9312] = { ["id"] = 9312, ["name"] = "The Emitter", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "<name>, while you were out investigating the Shadow Ridge, Zhanaa here has been going on about the holographic emitter. You might want to speak with her.", ["objectivesText"] = "Speak with Technician Zhanaa at the Crash Site in Ammen Vale .", ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16535, ["x"] = 0.794, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17071, ["x"] = 0.794, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.794, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 19, ["flags"] = 0 } } },
[9313] = { ["id"] = 9313, ["name"] = "Travel to Azure Watch", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "By all that is good, <name>, you must go at once to this Azure Watch and speak with Dyvuun! There is a path that leads west off of this tiny isle. Follow it and cross the Crystalbrook River to arrive on the larger part of the isle. Continue to follow the path and you should find Azure Watch. See if you can convince them to send us some aid and supplies. The rest of us will follow when we can. Thank you, we wouldn't have made it without you!", ["objectivesText"] = "Speak with Technician Dyvuun at Azure Watch on Azuremyst Isle .", ["rewardXP"] = 250, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17071, ["x"] = 0.794, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16551, ["x"] = 0.486, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.794, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 20, ["flags"] = 0 } } },
[9314] = { ["id"] = 9314, ["name"] = "Word from Azure Watch", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "<class>! A couple mutated beasts jumped me and my leg is injured. I was sent on a scouting mission from Azure Watch after we received word from Zhanaa. Please, could you go speak with Caregiver Chellan in my stead? She needs to know how many people to expect in Azure Watch. Just cross the Crystalbrook River here and continue following the road until you get to Azure Watch. Be sure to ask her for a place for yourself to stay in.", ["objectivesText"] = "Speak with Caregiver Chellan at Azure Watch on Azuremyst Isle .", ["rewardXP"] = 50, ["rewardItems"] = { 159, 6290 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16554, ["x"] = 0.645, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16553, ["x"] = 0.484, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 21, ["flags"] = 0 } } },
[9315] = { ["id"] = 9315, ["name"] = "Anok'suten", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9315 }, ["description"] = "Come closer, I am ... dying. I was sent here ... to slay these Nerubians, but Vandril didn't ... know that they have a leader. <The dying blood elf coughs up a good amount of blood.> You must find and ... slay Anok'suten . Get help. She wanders around ... Suncrown Village.", ["objectivesText"] = "Slay Anok'suten and return to Arcanist Vandril at Tranquillien in the Ghostlands .", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 24339, 24340, 24341, 28149, 131251 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16601, ["x"] = 0.575, ["y"] = 0.15 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.15 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "group" },
[9327] = { ["id"] = 9327, ["name"] = "The Forsaken", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9138, 9139, 9140, 9329, 9758, 28560 }, ["description"] = "I know it seems strange, but these Forsaken are here to help. You should speak with their leader, High Executor Mavren . He's in the tower on the west side of town. And, <class>, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", ["objectivesText"] = "Speak with High Executor Mavren at Tranquillien in the Ghostlands .", ["rewardGold"] = 26750, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16252, ["x"] = 0.448, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.2855 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 0, ["flags"] = 0 } } },
[9328] = { ["id"] = 9328, ["name"] = "Hero of the Sin'dorei", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9328 }, ["series"] = { 9621, 9626, 9627 }, ["description"] = "This is the beginning of a new chapter in the history of our race, <name>. Our lands will be reclaimed and we shall cement our bond with Sylvanas and her allies. Take the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City. He'll be eager to hear the news.", ["objectivesText"] = "Take Dar'Khan's Head to Lor'themar Theron in Silvermoon City. Progress: You seek audience with me, <class>? I do not recall hearing of an appointment.", ["rewardXP"] = 100, ["rewardItems"] = { 22653, 22982 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16239, ["x"] = 0.55, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 16802, ["x"] = 0.618667, ["y"] = 0.301 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 95, 110 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9329] = { ["id"] = 9329, ["name"] = "The Forsaken", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9138, 9139, 9140, 9327, 9758, 28560 }, ["description"] = "I know it seems strange, but the Forsaken are here to help. You should speak with their leader, High Executor Mavren . He's in the tower on the west side of town. And, <class>, when you're done talking with him return to me; I have something dire that needs to be dealt with immediately!", ["objectivesText"] = "Speak with High Executor Mavren at Tranquillien in the Ghostlands .", ["rewardGold"] = 26750, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16252, ["x"] = 0.448, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.2855 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 1, ["flags"] = 0 } } },
[9352] = { ["id"] = 9352, ["name"] = "Darnassian Intrusions", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["series"] = { 8463 }, ["description"] = "Besides the constant threat that the Wretched represent, I also have to deal with all kind of fictitious reports of night elf sightings. Though most reports are unfounded, one recent incident demands further investigation. The West Sanctum, one of our primary energy sources, has suffered a terrible malfunction and rumors of Darnassian sabotage are rampant. Travel there and deal with anyone that looks suspicious. Report back to Ley-Keeper Velania , who watches over the sanctum.", ["objectivesText"] = "Travel to the West Sanctum, southwest of Falconwing Square and defeat any intruders present there. Report your findings to Ley-Keeper Velania .", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 20765 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15403, ["x"] = 0.48, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15401, ["x"] = 0.366, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 2, ["flags"] = 0 } } },
[9358] = { ["id"] = 9358, ["name"] = "Ranger Sareyn", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9358 }, ["description"] = "Don't take the safety of this village for granted. We're under siege by the Scourge on the east and the Wretched to the west. Ranger Sareyn keeps our borders safe from the undead that pour in from the Dead Scar. Follow the road eastwards out of town and see if you can lend her a hand.", ["objectivesText"] = "Report to Ranger Sareyn outside Fairbreeze Village in Eversong Woods.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15397, ["x"] = 0.436, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15942, ["x"] = 0.468, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9359] = { ["id"] = 9359, ["name"] = "Farstrider Retreat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9359 }, ["series"] = { 8476 }, ["description"] = "Your help in subduing the Wretched has been invaluable. The Farstriders would surely have use for someone like you in their fight against the Amani trolls. Look for the Farstrider Retreat to the northeast of here, speak to Lieutenant Dawnrunner and see what assistance she might need.", ["objectivesText"] = "Report to Lieutenant Dawnrunner at the Farstrider Retreat in Eversong Woods.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15939, ["x"] = 0.434, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15399, ["x"] = 0.602, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9360] = { ["id"] = 9360, ["name"] = "Amani Invasion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["series"] = { 9363 }, ["description"] = "Though you don't understand the language in these battle plans, you clearly make out a map marking the positions of the Farstrider Retreat and Fairbreeze Village. You'd best let Lieutenant Dawnrunner at the Farstrider Retreat know about this.", ["objectivesText"] = "Deliver the Amani Invasion Plans to Lieutenant Dawnrunner at Farstrider Retreat. Progress: What do you want to show me?", ["rewardGold"] = 58650, ["rewardXP"] = 200, ["rewardItems"] = { 23249 }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15399, ["x"] = 0.602, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 28, ["flags"] = 0 } }, ["startItems"] = { 23249 } },
[9363] = { ["id"] = 9363, ["name"] = "Warning Fairbreeze Village", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8463, 8468, 8472, 8473, 8475, 8476, 8477, 8479, 8480, 8482, 8483, 8486, 8487, 8488, 8490, 8491, 8884, 8885, 8886, 8887, 8889, 8890, 8891, 8892, 8894, 9062, 9064, 9066, 9067, 9076, 9252, 9255, 9352, 9360, 9363 }, ["series"] = { 9360 }, ["description"] = "Go to Fairbreeze Village and notify Ranger Degolien of the Amani plans. Even with Zul'Marosh dead, Fairbreeze must prepare for a troll attack. Tell Degolien I will send him reinforcements as soon as possible.", ["objectivesText"] = "Travel to Fairbreeze Village in Eversong Woods and speak to Ranger Degolien .", ["rewardGold"] = 49925, ["rewardXP"] = 100, ["rewardItems"] = { 23265, 23266, 23267, 131252 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15399, ["x"] = 0.602, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15939, ["x"] = 0.434, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 569, ["name"] = "Eversong Woods", ["orderIndex"] = 29, ["flags"] = 0 } } },
[9369] = { ["id"] = 9369, ["name"] = "Replenishing the Healing Crystals", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9279, 9280, 9409 }, ["description"] = "We are the draenei. Our ship crashed and, since we have many wounded, our immediate concern is the depleted state of our healing crystals. We must replenish them quickly! Unfortunately, the only way to do this at this point is to extract the blood from the local vale moths. Their blood will make for a suitable substitute. The moths can be found in many places around the vale, but mostly in the northwest.", ["objectivesText"] = "Acquire 6 Vials of Moth Blood from the nearby Vale Moths and bring them to Proenitus at the Crash Site in Ammen Vale . Progress: Have you harvested the necessary moth blood for the healing crystals yet? With survivors scattered all over the vale, time is of the essence!", ["rewardGold"] = 53500, ["rewardXP"] = 250, ["rewardItems"] = { 22889, 24129, 24130, 24131, 131819 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16477, ["x"] = 0.804, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16477, ["x"] = 0.804, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.804, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 2, ["flags"] = 0 } } },
[9371] = { ["id"] = 9371, ["name"] = "Botanist Taerix", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9293, 10302 }, ["description"] = "<name>, Botanist Taerix is in need of your assistance. You'll find her with her apprentices to the west, outside the ship.", ["objectivesText"] = "Speak with Botanist Taerix at the Crash Site in Ammen Vale .", ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16477, ["x"] = 0.804, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16514, ["x"] = 0.792, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.804, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 5, ["flags"] = 0 } } },
[9394] = { ["id"] = 9394, ["name"] = "Where's Wyllithen?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9394 }, ["series"] = { 8894 }, ["description"] = "The Duskwither groundskeeper has gone missing! Someone must have forgotten to tell him to leave when the magister and everyone else did. I know that he's still somewhere around here on the grounds, but I dare not go looking for him myself with all of these magical creatures roaming about. Will you find him for me, <class>, and make sure that he's alright?", ["objectivesText"] = "Find Groundskeeper Wyllithen on the Duskwither Grounds in Eversong Woods.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15924, ["x"] = 0.678, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15969, ["x"] = 0.686, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9395] = { ["id"] = 9395, ["name"] = "Saltheril's Haven", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9395 }, ["series"] = { 9067 }, ["description"] = "I swear that I'm going to fireball someone if I get one more request from Lord Saltheril concerning supplies for his party! Do I look like a party planner?! Between you and me, that fool and his sycophants are living in denial that we're under attack here! Some of us are actually busy with, oh, I don't know, defending what's left of Quel'Thalas! <class>, would you please head over to Saltheril's Haven and see if you can shut him up? It's just down the road to the west.", ["objectivesText"] = "Speak with Lord Saltheril at Saltheril's Haven in Eversong Woods.", ["rewardGold"] = 33800, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 16210, ["x"] = 0.44, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 16144, ["x"] = 0.381, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9402] = { ["id"] = 9402, ["name"] = "Fetch!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9402 }, ["series"] = { 9403, 9404 }, ["description"] = "So... <name> is it? Don't be flattered I know your name, one of my students has been fawning over you and won't shut up. Hmm... if you'd like to impress <her/him>, why don't you do something for me? There's an azure phial at the bottom of the pond behind me. Dive in, retrieve it, and bring it here.", ["objectivesText"] = "Dive to the bottom of Stillwhisper Pond and retrieve the Azure Phial for Instructor Antheol . Progress: How's the water?", ["rewardGold"] = 679200, ["rewardXP"] = 50, ["rewardItems"] = { 23551, 119042 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15970, ["x"] = 0.555333, ["y"] = 0.544667 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15970, ["x"] = 0.555333, ["y"] = 0.544667 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.555333, ["y"] = 0.544667 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9403] = { ["id"] = 9403, ["name"] = "The Purest Water", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9403 }, ["series"] = { 9402, 9404 }, ["description"] = "Now that you've learned a little lesson, I'll offer you something more substantial. It concerns your ability to defend yourself in close combat. Of course, you should only resort to melee in the most dire of circumstances, but that is no excuse to be unprepared. I can assist you in creating a staff befitting a mage of your learning. Simply take the phial you retrieved for me and fill it at the base of Elrendar Falls. Just follow the river southeast from here.", ["objectivesText"] = "Instructor Antheol wants you to fill the Azure Phial at Elrendar Falls. Progress: Only water from the Elrendar Falls has the purity required for use with magic. Do you have it?", ["rewardXP"] = 200, ["rewardItems"] = { 23552, 23566 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15970, ["x"] = 0.555333, ["y"] = 0.544667 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15970, ["x"] = 0.555333, ["y"] = 0.544667 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.555333, ["y"] = 0.544667 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9404] = { ["id"] = 9404, ["name"] = "Recently Living", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["requiredRaces"] = { 5, 8, 10 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9404 }, ["series"] = { 9402, 9403 }, ["description"] = "You may have noticed the walking trees near Elrendar Falls. As the keepers of nature, they are infused with a primal magic we can reform to our own purposes using the pure water you have already brought to me. Unfortunately, the green keepers are gnarled and twisted creatures, so you may need to kill a few before you find a useable branch.", ["objectivesText"] = "Slay the Eversong Green Keepers until they yield a Living Branch for Instructor Antheol . Progress: Do you have the living branch ? Hand it over quickly!", ["rewardXP"] = 200, ["rewardItems"] = { 7508, 9513, 23553 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15970, ["x"] = 0.555333, ["y"] = 0.544667 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15970, ["x"] = 0.555333, ["y"] = 0.544667 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.555333, ["y"] = 0.544667 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9409] = { ["id"] = 9409, ["name"] = "Urgent Delivery!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9279, 9280, 9369 }, ["description"] = "Now that you've gathered all that we need to replenish our healing crystals, I need you to deliver the vials to Zalduun , our priest. You'll find him tending to our wounded inside the central chamber of the ship.", ["objectivesText"] = "Deliver the Bundle of Vials to Zalduun at the Crash Site in Ammen Vale . Progress: Hello, <class>. What have you there? Is it for me?", ["rewardXP"] = 50, ["rewardItems"] = { 23568 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16477, ["x"] = 0.804, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16502, ["x"] = 0.8, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.804, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 3, ["flags"] = 0 } } },
[9421] = { ["id"] = 9421, ["name"] = "Shaman Training", ["level"] = 5, ["requiredLevel"] = 5, ["faction"] = "alliance", ["requiredClasses"] = { 7 }, ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9421 }, ["rewardXP"] = 370, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17089, ["x"] = 0.792, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17089, ["x"] = 0.792, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard" },
[9452] = { ["id"] = 9452, ["name"] = "Red Snapper - Very Tasty!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9453 }, ["description"] = "I've found that these waters are bustling with red snapper , a very tasty fish. With a fishing net, I can catch enough to feed dozens of draenei! Unfortunately, I was recently attacked by a creature known as a murloc while netting in the river and have suffered some injuries that prevent me from doing my job. I need help! Use this fishing net near schools of red snapper , found in the Crystalbrook river to the east, to catch the fish. What do you say? Remember to return the net when you are finished.", ["objectivesText"] = "Use the Draenei Fishing Net to catch 10 Red Snappers . Return both the fish and the net to Diktynna on Azuremyst Isle when the task is complete. Progress: Watch out for murlocs: Strange and extremely annoying little creatures.", ["rewardXP"] = 200, ["rewardItems"] = { 6256, 6529, 23614, 23654 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17101, ["x"] = 0.61, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17101, ["x"] = 0.61, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 1, ["flags"] = 0 } } },
[9453] = { ["id"] = 9453, ["name"] = "Find Acteon!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9452 }, ["description"] = "You did a wonderful job, <name>. Our people will be thankful for this bounty. With that said, would you mind taking this haul of red snapper to Acteon at Azure Watch? He shouldn't be hard to find as he is awaiting this catch.", ["objectivesText"] = "Deliver the Crate of Red Snapper to Acteon at Azure Watch. Progress: What do you think of my armor? Crafted it myself! It's a little different than what we'd traditionally wear but extremely comfortable.", ["rewardXP"] = 25, ["rewardItems"] = { 23672 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17101, ["x"] = 0.61, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17110, ["x"] = 0.498, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 2, ["flags"] = 0 } } },
[9454] = { ["id"] = 9454, ["name"] = "The Great Moongraze Hunt", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 10324 }, ["description"] = "You're starting to make a name for yourself, <name>. How about trying your hand at hunting? Back on Draenor, our greatest hunters would hunt a beast that resembled the moongraze stag of this region known as a talbuk. If you think yourself draenei enough, go out into the wilds and kill enough stags to fill your pack with meat. You will find them grazing south of Azure Watch. Watch out for their horns!", ["objectivesText"] = "Bring 6 Moongraze Stag Tenderloins to Acteon at Azure Watch. Progress: The stag hides are frail which tend to make for tender, succulent flesh.", ["rewardGold"] = 78750, ["rewardXP"] = 150, ["rewardItems"] = { 23676, 24103, 24104, 24105, 27686, 131274 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17110, ["x"] = 0.498, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17110, ["x"] = 0.498, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 3, ["flags"] = 0 } } },
[9455] = { ["id"] = 9455, ["name"] = "Strange Findings", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9455 }, ["series"] = { 9456 }, ["description"] = "The crystal you found on the nightstalker runt's body appears to be a piece of the Exodar. This may help explain the unusual appearance and demeanor of some of the animals in this region. Take the crystal back to Azure Watch. The exarch will surely want to know about this discovery.", ["objectivesText"] = "Deliver the Faintly Glowing Crystal to Exarch Menelaous at Azure Watch. Progress: You found what? Where?", ["rewardXP"] = 150, ["rewardItems"] = { 23678 }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17116, ["x"] = 0.472, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["startItems"] = { 23678 } },
[9456] = { ["id"] = 9456, ["name"] = "Nightstalker Clean Up, Isle 2...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9456 }, ["series"] = { 9455 }, ["description"] = "I'm not going to make any excuses for what you've found. This is clearly our fault. We had gotten reports of crushed crystal fragments showing up in the river to the east but chose to ignore the implications. Now we can either sit around on this island and cry about the tragedy that has befallen this land or we can do something about it and prevent it from spreading. If you've got the stomach for it, I want you to go back into the wilds and kill as many of the infected nightstalkers as you can find.", ["objectivesText"] = "Exarch Menelaous at Azure Watch has asked that you slay 8 Infected Nightstalker Runts . Progress: We can't risk this contamination spreading. The reports I've heard come from Blood Watch are bad enough. This has to be stopped now!", ["rewardGold"] = 99850, ["rewardXP"] = 200, ["rewardItems"] = { 24435, 24436, 24437, 131254 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17116, ["x"] = 0.472, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17116, ["x"] = 0.472, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[9473] = { ["id"] = 9473, ["name"] = "An Alternative Alternative", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "The girl is too far gone for mere ointments to be effective. There may be another way... The forest of Azuremyst holds many secrets, one of those being a rare plant known as the azure snapdragon that some claim to be a panacea - a cure all. You can identify the plant by its stark contrast to the other plants of Azuremyst and its need to grow at the base of the azure pine trees. Make haste! And <name>, be wary of the root threshers of the region as they consume snapdragon for sustenance.", ["objectivesText"] = "Daedal at Azure Watch wants you to bring him 5 Azure Snapdragon Bulbs . Progress: Do not waste time, boy.", ["rewardGold"] = 234000, ["rewardXP"] = 200, ["rewardItems"] = { 23692 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17215, ["x"] = 0.484, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17215, ["x"] = 0.484, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 21, ["flags"] = 0 } } },
[9483] = { ["id"] = 9483, ["name"] = "Life's Finer Pleasures", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 9483 }, ["objectivesText"] = "Progress: Just because we're on this pilgrimage doesn't mean we have to give up all of life's pleasures. It's been ages since I had a good wine. I'd literally kill for a bottle of cenarion spirits ! I know, I know, how unfashionable of me to enjoy a drink brewed by night elves.", ["rewardItems"] = { 29112 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 17226, ["x"] = 0.2664, ["y"] = 0.6304 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 17226, ["x"] = 0.2664, ["y"] = 0.6304 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.2664, ["y"] = 0.6304 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "standard" },
[9488] = { ["id"] = 9488, ["name"] = "A Simple Robe", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9488 }, ["series"] = { 9487 }, ["description"] = "The arcane fragments you collected will do nicely. Nicely for what, you ask? For making a splendid robe fit for a <class> like yourself! All we need now is some linen cloth and a spindleweb silk gland . You can find the silk gland from any spindleweb spider, preferably after killing them.", ["objectivesText"] = "Arcanist Vandril wants you to bring him 15 Linen Cloth and a Spindleweb Silk Gland . Progress: The robe cannot be completed without the necessary supplies. But you knew that, didn't you?", ["rewardXP"] = 200, ["rewardItems"] = { 2589, 7509, 23707 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.2855 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9505] = { ["id"] = 9505, ["name"] = "The Prophecy of Velen", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11, 30 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9506, 9530, 9531, 9537, 9602 }, ["description"] = "The Prophet spoke of this day: That on this island, in this new world, our allies would find us. \"We will be tested. They will ask that we pay for the sins of our fathers...\" At the time, I did not understand the meaning behind his words, but seeing this creature and her reaction to us, it is now coming into focus. The corruption of our people has been felt even here. Venture south. It is there that we found this being. Find its kin and tell them of our people.", ["objectivesText"] = "Daedal wants you to travel south and seek out the people that the injured creature mentioned.", ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17215, ["x"] = 0.484, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 22, ["flags"] = 0 } } },
[9506] = { ["id"] = 9506, ["name"] = "A Small Start", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9505, 9530, 9531, 9537, 9602 }, ["description"] = "I am Admiral Odesyus of Alliance Naval Command. Our ship was forced to port on your island due to an infestation of sorts. It's embarrassing to even talk about, but goblins somehow managed to stow away in the holds of both of my ships. Last night, while most of the ship's crew was asleep below deck, they struck! Stranger still, they took our navigation gear and jumped ship! They disappeared into the thicket, east of here. Will you go in search of our gear? It will make for a strong gesture.", ["objectivesText"] = "Admiral Odesyus at Odesyus' Landing wants you to recover the Nautical Compass and Nautical Map stolen by the Venture Co. Progress: Any luck, stranger?", ["rewardXP"] = 200, ["rewardItems"] = { 23738, 23739 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 23, ["flags"] = 0 } } },
[9512] = { ["id"] = 9512, ["name"] = "Cookie's Jumbo Gumbo", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "The Admiral be right, ye are a resourceful one. Mayhap ye could help Cookie out? If I serve the crew chicken for dinner again, I'll be sent to the brig fer sure. I noticed that thar be crawlers all along the coastline - lots o' crawlers! Bring me crawler meats and I'll be forever indebted to ya. Help a reformed pirate out?", ["objectivesText"] = "\"Cookie\" McWeaksauce at the Odesyus' Landing wants you to bring him 6 Skittering Crawler Meat . Progress: Arrr... Yarr... Shiver me timbers... Er, sorry lad, I gotta practice me pirate lest I forget it...", ["rewardXP"] = 150, ["rewardItems"] = { 23756, 23757 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17246, ["x"] = 0.465, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17246, ["x"] = 0.465, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 24, ["flags"] = 0 } } },
[9513] = { ["id"] = 9513, ["name"] = "Reclaiming the Ruins", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "While some may look at our current predicament as an unfortunate turn of events, I sense that we are here for a reason. The invisible hand of fate has pushed us in this direction. The reason why will become evident in time. To the west lies an ancient night elf city, now in ruin and overrun with naga. It would be remiss of me to sit idly by as the naga tainted my ancestral lands. You have shown yourself a capable <class>. Honor my people and cleanse the ruins of their unwelcome inhabitants.", ["objectivesText"] = "Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill 5 Wrathscale Myrmidons , 5 Wrathscale Naga and 5 Wrathscale Sirens .", ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17241, ["x"] = 0.47, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17241, ["x"] = 0.47, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 25, ["flags"] = 0 } } },
[9514] = { ["id"] = 9514, ["name"] = "Rune Covered Tablet", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9514 }, ["description"] = "You cannot make out any of the symbols on the tablet. Perhaps the priestess would be able to decipher the mysterious runes.", ["objectivesText"] = "Take the Rune Covered Tablet to Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle . Progress: You've found something?", ["rewardXP"] = 25, ["rewardItems"] = { 23759 }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17241, ["x"] = 0.47, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["startItems"] = { 23759 } },
[9515] = { ["id"] = 9515, ["name"] = "Warlord Sriss'tiz", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9515 }, ["description"] = "A naga invasion would be disastrous, <name>. I've seen what naga can do and I would not want to see such a catastrophe befall any being. If I were to guess, this Warlord Sriss'tiz will be hidden in a cave - probably along the coast to the west. Find Warlord Sriss'tiz and put an end to his reign.", ["objectivesText"] = "Priestess Kyleen Il'dinare at Odesyus' Landing on Azuremyst Isle wants you to kill Warlord Sriss'tiz .", ["rewardGold"] = 1024800, ["rewardXP"] = 200, ["rewardItems"] = { 23759, 24447, 24448, 133691 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17241, ["x"] = 0.47, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17241, ["x"] = 0.47, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[9523] = { ["id"] = 9523, ["name"] = "Precious and Fragile Things Need Special Handling", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "The priestess tells me that the ruins to the west are what's left of a night elf civilization. That got me thinking about what my pappy used to always say about night elf ruins, \"Sonny, whenever you see night elf ruins, night elf relics are sure to be close by.\" Now what kind of a dwarf would I be if I didn't hire the first person I saw to go digging up night elf relics for me? Now get going!", ["objectivesText"] = "Archaeologist Adamant Ironheart at Odesyus' Landing on Azuremyst Isle wants you to bring him 8 Ancient Relics . Progress: Don't come back without some ancient relics .", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 23779 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17242, ["x"] = 0.472, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17242, ["x"] = 0.472, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 26, ["flags"] = 0 } } },
[9527] = { ["id"] = 9527, ["name"] = "All That Remains", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 10428 }, ["description"] = "We had lived peacefully among the Owlbeasts of this island for many years. You can imagine my surprise when they stormed the beach and attacked us. I fought tooth and nail but was easily overpowered. As I blacked out from the vicious blows that I had been dealt, I prayed that my family not suffer. When I awoke, all was quiet. The sand was soaked red with blood - their blood. They were devoured whole. I care not for vengeance, <name>. I only ask that their remains be returned to me for proper burial.", ["objectivesText"] = "Cowlen on Azuremyst Isle wants you to recover the Remains of Cowlen's Family . Progress: My wife was named Thalrisa and my daughter, Magwin.", ["rewardGold"] = 11795, ["rewardXP"] = 200, ["rewardItems"] = { 23789 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17311, ["x"] = 0.165, ["y"] = 0.944 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17311, ["x"] = 0.165, ["y"] = 0.944 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.165, ["y"] = 0.944 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 29, ["flags"] = 0 } } },
[9528] = { ["id"] = 9528, ["name"] = "A Cry For Help", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9528 }, ["description"] = "My family was attacked by the murlocs and owlkin of this island several weeks ago. I managed to escape but I think that both my mother and father have been slain. I don't know what I'm going to do now, but I must try and get back to my home - or what's left of it... Will you help me get through the forest?", ["objectivesText"] = "Escort Magwin through the island to her home.", ["rewardXP"] = 200, ["rewardItems"] = { 24113 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17312, ["x"] = 0.1344, ["y"] = 0.7672 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17311, ["x"] = 0.165, ["y"] = 0.944 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.1344, ["y"] = 0.7672 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[9530] = { ["id"] = 9530, ["name"] = "I've Got a Plant", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9505, 9506, 9531, 9537, 9602 }, ["description"] = "I've wondered about this for some time now, but this proves it to be true. There is a traitor among us. The plans left behind by the goblins document the conspiracy. Since I don't know who it could be, I'm going to need your help in finding the traitor. None of my crew can be trusted. If this is going to work, I'm going to need a hollowed out tree and leaves. Search near the loggers north of us for the tree. You'll need to find the leaves by yourself. Check the forest.", ["objectivesText"] = "Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to bring him a Hollowed Out Tree and 5 Piles of Leaves. Progress: I love it when a plan comes together...", ["rewardXP"] = 50, ["rewardItems"] = { 23790, 23791 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 27, ["flags"] = 0 } } },
[9531] = { ["id"] = 9531, ["name"] = "Tree's Company", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9505, 9506, 9530, 9537, 9602 }, ["description"] = "According to the plans, the traitor and the leader of the goblins, Geezle, are to meet at a cove on the western island. I need you to be at that meeting, <name>. Remember the tree and leaves? You're going to wear them! It's a perfect disguise. Go to the cove and look for a naga flag. If the flag is there, it means a meeting is planned. Use the disguise kit when you see the flag and wait. Eventually the traitor will show up. Let the meeting finish then return to me with the identity of the scoundrel.", ["objectivesText"] = "Admiral Odesyus at Odesyus' Landing on Azuremyst Isle wants you to observe the meeting that is to take place between Geezle and the traitor. Return to him when you know the identity of the traitor. Progress: That traitor is going to wish he never messed with Alliance Naval Command!", ["rewardGold"] = 315000, ["rewardXP"] = 150, ["rewardItems"] = { 23792, 124669, 138201, 138777, 138811, 140261, 142398 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 28, ["flags"] = 0 } } },
[9537] = { ["id"] = 9537, ["name"] = "Show Gnomercy", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9505, 9506, 9530, 9531, 9602 }, ["description"] = "Spark must be brought to justice! I need you to go down to the beach and find that deceitful gnome. Once you find him, get whatever information you can out of him! If a high ranking official of the Alliance has committed treasonous acts, who knows how many others are corrupt? And <name>, use force if you have to...", ["objectivesText"] = "Admiral Odesyus at Odesyus' Landing wants you to recover the Traitor's Communication from Engineer \"Spark\" Overgrind. Progress: Did you find the lying dog?", ["rewardXP"] = 200, ["rewardItems"] = { 23899, 24430, 24431, 24432, 24433, 24434 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 30, ["flags"] = 0 } } },
[9538] = { ["id"] = 9538, ["name"] = "Learning the Language", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9539, 9540, 9541, 9542, 9544 }, ["description"] = "I think I've cracked it, <name>! <Aurren points to the totem.> All that we need to know about the Stillpine furbolg language is imprinted on their totems. With just a rudimentary understanding of how their symbols work, we can study the totems and learn to communicate with the furbolgs. I've written down the basics of the symbol matrix on this parchment. Study it and then examine the totem. It should lead you to the next language totem. Speak to Arugoo when you return an educated <race>!", ["objectivesText"] = "Read the Stillpine Furbolg Language Primer that Aurren gave you and interact with the Totem of Akida at Azure Watch. Progress: You can hear a low-pitched hum emanating from the totem.", ["rewardXP"] = 25, ["rewardItems"] = { 23818, 24112 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17232, ["x"] = 0.494, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17360, ["x"] = 0.494, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 5, ["flags"] = 0 } } },
[9539] = { ["id"] = 9539, ["name"] = "Totem of Coo", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9538, 9540, 9541, 9542, 9544 }, ["description"] = "You begin to read the totem, barely able to pronounce the awkward words and phrases. Slowly, words start to form in your head. You think that the totem is telling you to go up the nearby hill, to the northeast.", ["objectivesText"] = "Find the Totem of Coo using the clues provided to you.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17360, ["x"] = 0.494, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17361, ["x"] = 0.552, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 6, ["flags"] = 0 } } },
[9540] = { ["id"] = 9540, ["name"] = "Totem of Tikti", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9538, 9539, 9541, 9542, 9544 }, ["description"] = "You begin to read the totem, better able to pronounce the words and phrases. Words start to form in your head. You think that the totem is telling you to go across the Crystalbrook river to the east. Perhaps your destination is on the other side of the river.", ["objectivesText"] = "Find the Totem of Tikti using the clues provided to you.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17361, ["x"] = 0.552, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17362, ["x"] = 0.644, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 7, ["flags"] = 0 } } },
[9541] = { ["id"] = 9541, ["name"] = "Totem of Yor", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9538, 9539, 9540, 9542, 9544 }, ["description"] = "The symbols on this totem seem to translate much faster. The patterns and imagery all seem to blend into familiar words. You are fairly certain the totem is pointing you south, down the river. Something is at the bottom of the river itself.", ["objectivesText"] = "Find the Totem of Yor using the clues provided to you.", ["rewardXP"] = 25, ["rewardItems"] = { 122703 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17362, ["x"] = 0.644, ["y"] = 0.398 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17363, ["x"] = 0.63, ["y"] = 0.676 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.644, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 8, ["flags"] = 0 } } },
[9542] = { ["id"] = 9542, ["name"] = "Totem of Vark", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9538, 9539, 9540, 9541, 9544 }, ["description"] = "You no longer see unrecognizable symbology in the totems. The totem of Yor reads to you just as easily as your native tongue. The markings identify another furbolg den, due west of here. You are able to expertly decipher the language on the totem and know that your destination is Bristlelimb Village. Yor will guide you but if you get lost, you know that you are able to take the ancient elven road in the forest leading west to reach your destination.", ["objectivesText"] = "Find the Totem of Vark using the clues provided to you.", ["rewardXP"] = 25, ["rewardItems"] = { 30632 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17363, ["x"] = 0.63, ["y"] = 0.676 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17364, ["x"] = 0.282, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.676 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 9, ["flags"] = 0 } } },
[9544] = { ["id"] = 9544, ["name"] = "The Prophecy of Akida", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9538, 9539, 9540, 9541, 9542 }, ["description"] = "The images on this totem depict a war between the Stillpine and the Bristlelimb furbolg tribes. The etchings show that the Bristlelimb have done unconscionable things to the furbolgs of Stillpine. Amidst the chaos, a prophecy has begun to unfold: A hero will rise - not of furbolg blood - and save the Stillpine tribe. Slay Bristlelimb furbolgs at Bristlelimb Village for their keys. Use the keys to free the Stillpine captives . Return to Arugoo of the Stillpine when you have freed them all!", ["objectivesText"] = "Free 8 Stillpine Captives from cages found in Bristlelimb Village. Return to Arugoo of the Stillpine at Azure Watch when you have completed this task.", ["rewardXP"] = 300, ["rewardItems"] = { 23801, 27399, 27401, 27403, 30632 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17364, ["x"] = 0.282, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17114, ["x"] = 0.494, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 10, ["flags"] = 0 } } },
[9548] = { ["id"] = 9548, ["name"] = "Pilfered Equipment", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9548 }, ["description"] = "Shh! Keep your voice down and don't call attention to me. If the murlocs detect my presence, the experiment will be ruined! I've already come perilously close to contaminating my data. While I was foraging yesterday, one of them must've wandered too close and discovered my camp. I returned just in time to see two of them carrying off a crate with most of my equipment! It's bound to be in one of their settlements around here, but I can't risk revealing my presence. Are you willing to help?", ["objectivesText"] = "Bring Clopper's Equipment back to Clopper Wizbang , who is hiding in a beached turtle shell. Progress: Did you manage to find my equipment?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23830 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17421, ["x"] = 0.42, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17421, ["x"] = 0.42, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9549] = { ["id"] = 9549, ["name"] = "Artifacts of the Blacksilt", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9549 }, ["description"] = "My observations and writings about the Blacksilt murlocs are quite illuminating, <name>, but they are just the beginning. I plan to return to Ironforge with items produced by the Blacksilts' rudimentary crafting skills. The problem is that the Blacksilt carry these items with them at all times, and I can't have their blood on my conscience. If you're willing to help me gather the idols carried by Blacksilt seers and crude knives of the Blacksilt warriors and shorestrikers, I won't ask how you came by them.", ["objectivesText"] = "Bring 3 Crude Murloc Idols and 6 Crude Murloc Knives to Clopper Wizbang , who is hiding in a beached turtle shell. Progress: Do you have those samples for me to send back to Ironforge?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23833, 23834, 23837 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17421, ["x"] = 0.42, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17421, ["x"] = 0.42, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9550] = { ["id"] = 9550, ["name"] = "A Map to Where?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["storyline"] = { 9550 }, ["series"] = { 9557 }, ["description"] = "The crudely-drawn map reveals nothing of its maker, but it appears to have been drawn with an unsteady hand. Wavering lines and symbols depict a small pavilion with broken columns located to the west of a partially submerged tower. If the map is to be believed, this cluster of ruins appears to be located on the eastern coast of the island. You have no idea what you'll find, but it was important enough for the map's creator to record.", ["objectivesText"] = "Locate the pavilion described by the map and search for what the map's maker was trying to record. Progress: Perhaps this old journal is what the map is referencing.", ["rewardXP"] = 200, ["rewardItems"] = { 23837 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3525 } }, ["questType"] = "standard", ["startItems"] = { 23837 } },
[9557] = { ["id"] = 9557, ["name"] = "Deciphering the Book", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9557 }, ["series"] = { 9550 }, ["description"] = "Lacking the means to read the book's contents, you think about who might be able to help you separate the author's words from the mapmaker's scrawl. Remembering Anchorite Paetheus 's collection of artifacts from countless cultures, you wonder if his experienced eye might be able to help you decipher the book's contents.", ["objectivesText"] = "Take the Ancient Journal to Anchorite Paetheus in Blood Watch. Progress: The Light shine upon you in all your endeavors, <class>. What is it you have there?", ["rewardXP"] = 200, ["rewardItems"] = { 23851 }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17424, ["x"] = 0.546, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9559] = { ["id"] = 9559, ["name"] = "Stillpine Hold", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "Promised one, you must travel north to the home of my people - Stillpine Hold. It is there that you will face your most daunting challenge. Go now, High Chief Stillpine awaits your arrival.", ["objectivesText"] = "Speak with High Chief Stillpine at Stillpine Hold.", ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17114, ["x"] = 0.494, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17440, ["x"] = 0.465, ["y"] = 0.207 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 11, ["flags"] = 0 } } },
[9560] = { ["id"] = 9560, ["name"] = "Beasts of the Apocalypse!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "My brother and I were hunting in the woods to the east when we were ambushed by strange, insect-like beasts. Such aberrations have never before been seen in Azuremyst! Could they be a sign of the coming apocalypse? The apocalypse that YOU are destined to prevent? If you truly are the Promised One, you will strike the creatures of the apocalypse down... and bring me their hides. From their hides, I can fashion armor of great power! Find them to the east, beyond the road.", ["objectivesText"] = "Moordo at Stillpine Hold on Azuremyst Isle wants you to bring him 8 Ravager Hides . Progress: They are ugly little creatures. Even the Blind Watcher could see them... and he's blind.", ["rewardXP"] = 200, ["rewardItems"] = { 23845, 24107, 24108, 24109, 131257 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17442, ["x"] = 0.448, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17442, ["x"] = 0.448, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 13, ["flags"] = 0 } } },
[9561] = { ["id"] = 9561, ["name"] = "Nolkai's Words", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9561 }, ["description"] = "The translation is ready now, <name>. < Anchorite Paetheus points out a block of text at the end of his translation.> 'The enemy is nearly upon us. We've gathered up all the survivors and retreated to the temple to the east. It's the last ground we truly hold on the island, and there is a sense among the survivors that we will make our last stand here. I've taken care to bury my last few possessions on the grounds of the temple, with the hope that someone will find them and know what happened here.'", ["objectivesText"] = "Find the location described in Nolkai's journal and discover his long-buried possessions.", ["rewardXP"] = 200, ["rewardItems"] = { 23837, 23846 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17424, ["x"] = 0.546, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9562] = { ["id"] = 9562, ["name"] = "Murlocs... Why Here? Why Now?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "These are dark days, Promised One. Even the murlocs are kicking our tails - literally. Unfortunately, more than just my ego has been bruised. While our relationship with the Siltfin murlocs had always been tenuous, never could we have imagined that they would have the gall to attack us and steal from our food stores! Travel west to the Silting Shore and recover our stolen food-stuffs! And if you see a dark-skinned murloc with a patch of white fur stuck in between his webbed toes...", ["objectivesText"] = "Gurf at Stillpine Hold on Azuremyst Isle wants you to recover 5 sacks of Stillpine Grain . Progress: A murloc kicked me in the behind and spit on me... in broad daylight!", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23849, 23850 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17441, ["x"] = 0.446, ["y"] = 0.235 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17441, ["x"] = 0.446, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 12, ["flags"] = 0 } } },
[9564] = { ["id"] = 9564, ["name"] = "Gurf's Dignity", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9564 }, ["description"] = "You recover the piece of fur that Gurf had \"lost\" in his struggle with the murlocs. Return the fur to Gurf and let him know that the fearsome Murgurgula has been slain.", ["objectivesText"] = "Return Gurf's Dignity to Gurf at Stillpine Hold on Azuremyst Isle . Progress: Is that what I think it is?", ["rewardXP"] = 200, ["rewardItems"] = { 23850, 24438, 24439, 24440, 131258 }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17441, ["x"] = 0.446, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["startItems"] = { 23850 } },
[9565] = { ["id"] = 9565, ["name"] = "Search Stillpine Hold", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9566 }, ["description"] = "As High Chief, my immediate concern is the root of the corruption in Stillpine Hold. Why did the wildkin - once our allies - attack us? Why have they taken residence in Stillpine Hold? Perhaps something inside will hold the answer. Search Stillpine Hold for clues as to the source of corruption.", ["objectivesText"] = "Search Stillpine Hold for clues.", ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17440, ["x"] = 0.465, ["y"] = 0.207 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.207 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 16, ["flags"] = 0 } } },
[9566] = { ["id"] = 9566, ["name"] = "Blood Crystals", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9565 }, ["description"] = "On the surface, the crystal appears to be a piece of the Exodar. Something has gone terribly wrong with this crystal, however, as it is blood red and rapidly dissolving into the water supply of the cave. This may explain the unusually aggressive behavior of the creatures in Azuremyst. Return to High Chief Stillpine with this information.", ["objectivesText"] = "Speak with High Chief Stillpine at Stillpine Hold.", ["rewardGold"] = 58650, ["rewardXP"] = 150, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17440, ["x"] = 0.465, ["y"] = 0.207 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.207 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 18, ["flags"] = 0 } } },
[9567] = { ["id"] = 9567, ["name"] = "Know Thine Enemy", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9567 }, ["description"] = "It's good to see another new face here in Blood Watch, <class>. Although the blood elves are the most immediate threat, there are other sinister creatures that call Bloodmyst Isle home. The Nazzivus satyr are of particular concern. They are foul, demonic creatures, commanding dark magics and feeding on the corruption created by the Exodar's crash. We must hold them in check, but first we must learn more about them. Go southwest to Nazzivian and learn what you can from their grotesque monument.", ["objectivesText"] = "Find the Nazzivus Monument in Nazzivian and retrieve a Nazzivus Monument Glyph . Return to Vindicator Aalesia in Blood Watch when you have one of the glyphs. Progress: Were you successful in obtaining knowledge of the Nazzivus satyr?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23859 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17433, ["x"] = 0.55, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17433, ["x"] = 0.55, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9569] = { ["id"] = 9569, ["name"] = "Containing the Threat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9569 }, ["description"] = "Now that we have made our presence known to the satyr, we must send a message that we will not tolerate the Burning Legion's hounds in these lands. Too long have the draenei fled in the wake of the Legion and its minions, <name>. Wherever they have found us, they have shown no mercy. We must not permit the satyr to exploit the Exodar's crash and use the corrupted crystals as weapons. Go north to where their leader resides in Axxarien, destroy him, and recover the corrupted crystals he has been gathering!", ["objectivesText"] = "Kill 5 Axxarien Shadowstalkers , 5 Axxarien Hellcallers , and Zevrax , then gather 5 Corrupted Crystals and return to Vindicator Aalesia in Blood Watch. Progress: < Vindicator Aalesia seems to look through you rather than at you, her mind fixed on dealing with the satyr.> Have you moved against the satyr leader as I have asked?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23863, 27402, 27404 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17433, ["x"] = 0.55, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17433, ["x"] = 0.55, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9570] = { ["id"] = 9570, ["name"] = "The Kurken is Lurkin'", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9571 }, ["description"] = "After the crystal storm had subsided, a beast of myth appeared in our village. Brought here by the invading wildkin, this beast, the Kurken, laid waste to our village. Many Stillpine were slain in defense of our lands by this fiend and many have since lost their lives attempting to subdue the beast. In my visions, I have seen one defeat the Kurken. The one must be you, <name>. You are our only hope. Enter Stillpine Hold and slay the Kurken. Bring me his hide as proof of deed.", ["objectivesText"] = "Kurz the Revelator at Stillpine Hold on Azuremyst Isle wants you to kill the Kurken and bring back the Kurken's Hide . Progress: <Kurz grunts at you.>", ["rewardXP"] = 250, ["rewardItems"] = { 23860, 30632 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17443, ["x"] = 0.468, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17443, ["x"] = 0.468, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 15, ["flags"] = 0 } } },
[9571] = { ["id"] = 9571, ["name"] = "The Kurken's Hide", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9570 }, ["description"] = "Take the Kurken's hide to Moordo , on the other side of the village. He will fashion the hide into an item of your choice.", ["objectivesText"] = "Deliver the Kurken's Hide to Moordo at Stillpine Hold. Progress: Hello, hero!", ["rewardXP"] = 25, ["rewardItems"] = { 23860, 24111, 24112, 131259 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17443, ["x"] = 0.468, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17442, ["x"] = 0.448, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 17, ["flags"] = 0 } } },
[9573] = { ["id"] = 9573, ["name"] = "Chieftain Oomooroo", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "I am Stillpine the Younger , heir to the Stillpine legacy. As you can see, my defenders have set up a death trap for the raving wildkin that attack from inside Stillpine Hold. While we are able to hold them off out here, none of my defenders have been able to infiltrate the hold. If you could get inside and slay their leader, it might give us an opportunity to strike! Find Chieftain Oomooroo and destroy him. Slay any crazed wildkin that you encounter inside as well.", ["objectivesText"] = "Stillpine the Younger at Stillpine Hold on Azuremyst Isle wants you to slay Chieftain Oomooroo and 9 Crazed Wildkin .", ["rewardXP"] = 200, ["rewardItems"] = { 24445, 24446, 131260 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17445, ["x"] = 0.468, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17445, ["x"] = 0.468, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 14, ["flags"] = 0 } } },
[9574] = { ["id"] = 9574, ["name"] = "Victims of Corruption", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9574 }, ["series"] = { 9629 }, ["description"] = "Bloodmyst Isle was forever changed by our arrival. The Exodar's crash scattered debris all over the islands and I think it's beginning to have an adverse effect on the wildlife. Before I can be certain of my conclusion, I'll need to get a closer look. The crystals seem to have affected the trees the fastest, so it seems that the treants would be the most likely to show symptoms. If you bring me samples of bark from corrupted treants, I can begin my in-depth studies.", ["objectivesText"] = "Bring 6 pieces of Crystallized Bark to Morae in Blood Watch. Progress: Were you able to get the samples I need?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23869 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17434, ["x"] = 0.532, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17434, ["x"] = 0.532, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9576] = { ["id"] = 9576, ["name"] = "Cruelfin's Necklace", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9576 }, ["description"] = "Examining the crudely constructed pendant, you notice the crystal pulsating softly. Though it emits little light, you can almost feel the crystal radiating a sense of wrongness. You're not quite sure what might have possessed Cruelfin to create this pendant, but the find is too important to ignore. You should probably show it to someone at Blood Watch.", ["objectivesText"] = "Bring the Red Crystal Pendant to Morae at Blood Watch. Progress: What is it you have there?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23870 }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17434, ["x"] = 0.532, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["startItems"] = { 23870 } },
[9578] = { ["id"] = 9578, ["name"] = "Searching for Galaen", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9579 }, ["description"] = "Do you think often of your family, <name>? There were a number of families aboard the Exodar, but I've heard of very few being reunited. I, myself, am looking for traces of my husband Galaen, who was a technician in the Cryo-Core. The wreckage of it is located to the west, and it's swarming with blood elves! I must find out what became of Galaen! Even news of his death is better than never knowing. My husband will be wearing a pendant identical to my own; they were a gift from my sister.", ["objectivesText"] = "Search for Morae 's husband Galaen.", ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17434, ["x"] = 0.532, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17508, ["x"] = 0.375, ["y"] = 0.613 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 12, ["flags"] = 0 } } },
[9579] = { ["id"] = 9579, ["name"] = "Galaen's Fate", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9578 }, ["description"] = "You have no means of identifying the corpse as Galaen with the information Morae gave you, but the clothing appears to have been torn in search of valuables. The blood elves in the area would've claimed anything of value from the wreckage, including Galaen's jeweled amulet. Although her husband did not survive the crash, you believe that Morae would be grateful if you recovered her husband's amulet from the blood elves.", ["objectivesText"] = "Bring Galaen's Amulet to Morae at Blood Watch. Progress: < Morae looks at you hopefully.> Did your search turn up any trace of Galaen?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23873, 26011, 26025, 26037, 131261 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17508, ["x"] = 0.375, ["y"] = 0.613 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17434, ["x"] = 0.532, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.613 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 13, ["flags"] = 0 } } },
[9580] = { ["id"] = 9580, ["name"] = "The Bear Necessities", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9580 }, ["description"] = "As I'm sure you've seen in your time on Bloodmyst Isle , very little remains unchanged by our arrival. My training and experience has taught me that even the products of an environment like this one can be put to use. With so few resources, we must rely on our ingenuity to provide for us. I've been supplementing our stores with meat from the bears that wander this island. With the proper preparation, it can safely be eaten. If you're going to be out in the field, why not help replenish our stocks?", ["objectivesText"] = "Bring 8 Elder Brown Bear Flanks to Tracker Lyceon in Blood Watch. Progress: How goes the hunt, <name>?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 24026 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17642, ["x"] = 0.558, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17642, ["x"] = 0.558, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9581] = { ["id"] = 9581, ["name"] = "Learning from the Crystals", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9581 }, ["series"] = { 9584, 9585, 9620, 9628 }, ["description"] = "Welcome to Blood Watch, <class>. Seeing to the defenses of the outpost is my primary concern, but I've also been tasked with a variety of other duties by our leaders at the Exodar. The problem is that it's hardly safe to send out large amounts of researchers when the island is this dangerous. I need someone to gather a series of crystal samples from various sites on the island. The first sample I need must come from the ravager infested ship debris south of the town and across the bridge.", ["objectivesText"] = "Get an Impact Site Crystal Sample using the Crystal Mining Pick on the Impact Site Crystal and bring it to Harbinger Mikolaas in Blood Watch. Progress: Were you able to gather the first crystal sample?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23875, 23878, 26006, 26020, 26032, 131262 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9582] = { ["id"] = 9582, ["name"] = "Strength of One", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9582 }, ["series"] = { 10350 }, ["description"] = "When the ship crashed, our menagerie was scattered on the northeast beaches of this isle. I have been handed a key that unlocks the cage holding one of the deadlier specimens, a death ravager . The creature is little armored but resistant to most magic. It must be killed by a simple blade. Take this key and release the creature from both its prison and its pain. We cannot afford to have it escape and cause even more damage to the ecology than we already have.", ["objectivesText"] = "Unlock the Ravager Cage and kill the Death Ravager , then return to Ruada at Azure Watch in Azuremyst. Progress: Have you put down the beast?", ["rewardXP"] = 1415, ["rewardItems"] = { 23925 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17480, ["x"] = 0.499, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17480, ["x"] = 0.499, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.499, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[9584] = { ["id"] = 9584, ["name"] = "The Second Sample", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9584 }, ["series"] = { 9581, 9585, 9620, 9628 }, ["description"] = "Now that we have the baseline crystal, we're going to need samples from more dangerous areas of the island to complete the set I'll be sending to the Exodar. The next sample must come from the crystals controlled by the blood elves in the Bladewood area to the northwest of Blood Watch. I have heard reports that they alter and harvest the crystals for use in some magical apparatus. See if you can find one that has not yet been incorporated into one of their devices, and mine a sample from it.", ["objectivesText"] = "Get an Altered Crystal Sample using the Crystal Mining Pick on the Altered Bloodmyst Crystal and bring it to Harbinger Mikolaas in Blood Watch. Progress: Do you have the second crystal sample?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23876, 23879 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9585] = { ["id"] = 9585, ["name"] = "The Final Sample", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9585 }, ["series"] = { 9581, 9584, 9620, 9628 }, ["description"] = "There's just one sample remaining before I can send this set of crystals to the Exodar, <name>. The final sample must come from the satyr stronghold of Axxarien to the northwest. I'm not certain what to expect from this crystal sample, but I'm sure there will be some signs of corruption. Take care to mine your shard from the crystal that looks like the ones you took your previous samples from, or else our researchers cannot make a valid comparison.", ["objectivesText"] = "Get an Axxarien Crystal Sample using the Crystal Mining Pick on the Axxarien Crystal and bring it to Harbinger Mikolaas in Blood Watch. Progress: Have you returned with the last sample for my set?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23877, 23880 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9594] = { ["id"] = 9594, ["name"] = "Signs of the Legion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9594 }, ["description"] = "The armor scrap is forged from a deep black metal that seems to absorb light. Although it doesn't appear to be enchanted, there is an unmistakable sense of wrongness about it. Such armor is only used by one force - the Burning Legion. The Legion's presence here can only mean that they're intending to mobilize the island's satyr against the draenei. Take action against the local satyr, then return to Blood Watch and show this armor scrap to Vindicator Aalesia .", ["objectivesText"] = "Kill 8 Nazzivus Satyr and 8 Nazzivus Felsworn , then bring Tzerak's Armor Plate to Vindicator Aalesia in Blood Watch. Progress: Yes, <class>? What is it you have there?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23900 }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17433, ["x"] = 0.55, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["startItems"] = { 23900 } },
[9595] = { ["id"] = 9595, ["name"] = "Control", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["storyline"] = { 9595 }, ["description"] = "You have chosen the path of the <class>, and so you must learn control. Magic, when unchecked, can corrupt souls and destroy worlds. To fully understand, you must face one who has been consumed by magic. Travel to the beaches on the northwest coast of Azuremyst Isle and use your spells to decimate the murlocs. The display of power will attract the attention of the evil force lurking there, a Quel'dorei magewraith . Defeat it. When you have finished, seek out Bati at the Vault of Lights in the Exodar.", ["objectivesText"] = "Kill Murlocs of the Silting Shore to summon a Quel'dorei Magewraith , then destroy it. Afterwards, speak with Bati at the Vault of Lights in the Exodar.", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 7508, 9513, 129032, 198048, 198059, 200454, 204075, 204673, 204732, 204733, 204735, 204736, 204745, 204746, 204747, 204748, 204749, 204750, 204751, 204752, 204754, 204755, 204756, 204757, 204758, 204759, 204760, 204761, 204762, 204763, 204764, 204765, 204767, 204769, 204770, 204771, 204772, 204773, 204775, 204777, 204778, 204779, 204781, 204783, 204784, 204785, 204786, 204788, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[9602] = { ["id"] = 9602, ["name"] = "Deliver Them From Evil...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9505, 9506, 9530, 9531, 9537 }, ["description"] = "You must get this information to your people, <name>. While your brave acts have certainly slowed down the plans of Kael'thas and his dark master, the attacks will undoubtedly continue. Take the traitor's communication to your leaders. They must see this for themselves. Perhaps they will be able to better understand some of what was written.", ["objectivesText"] = "Deliver the Traitor's Communication to Exarch Menelaous at Azure Watch. Progress: You have returned!", ["rewardXP"] = 50, ["rewardItems"] = { 23899 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17240, ["x"] = 0.47, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17116, ["x"] = 0.472, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 31, ["flags"] = 0 } } },
[9604] = { ["id"] = 9604, ["name"] = "On the Wings of a Hippogryph", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11, 30 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 106, ["storyline"] = { 9604 }, ["series"] = { 9603, 9605, 9606 }, ["description"] = "For a small fee, you can rent one of my hippogryphs to fly you to the Exodar. Taking the hippogryph is a faster, not to mention safer, alternative for someone carrying an important message. If you'd like to take a ride, speak to me again and I'll make the arrangements.", ["objectivesText"] = "Purchase a hippogryph ride to the Exodar from Zaldaan . When you land, take Chellan's List to Nurguni in the Seat of the Naaru at the Exodar. Progress: Greetings, friend. You look like you've come a long way. How can I help you?", ["rewardXP"] = 100, ["rewardItems"] = { 23902 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17554, ["x"] = 0.575, ["y"] = 0.54 }, { ["mapID"] = 97, ["npcID"] = 43991, ["x"] = 0.496, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 16768, ["x"] = 0.537111, ["y"] = 0.492667 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 97, 103, 106 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[9605] = { ["id"] = 9605, ["name"] = "Hippogryph Master Stephanos", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 9605 }, ["series"] = { 9603, 9604, 9606 }, ["description"] = "Here's the box, <name>. That should be enough for Chellan to get the inn up and running. Let her know that she can keep sending in orders as the need arises. Azure Watch urgently needs a place to care for the wounded and put up any travelers they receive. When you're ready to return to Azure Watch, seek out Stephanos near the Seat of the Naaru in the Exodar.", ["objectivesText"] = "Find Stephanos at the Seat of the Naaru inside the Exodar and purchase a hippogryph ride back to Azure Watch. Progress: Where are you headed, <class>?", ["rewardXP"] = 100, ["rewardItems"] = { 23903 }, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 16768, ["x"] = 0.537111, ["y"] = 0.492667 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 17555, ["x"] = 0.546, ["y"] = 0.3616 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.537111, ["y"] = 0.492667 }, ["mapCandidates"] = { ["npc"] = { 103 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[9606] = { ["id"] = 9606, ["name"] = "Return to Caregiver Chellan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 9606 }, ["series"] = { 9603, 9604, 9605 }, ["description"] = "If I remember correctly, Azure Watch's hippogryph master is Zaldaan. If you've spoken to him before, then you can take one of my hippogryphs to him. That's a good lesson to know: hippogryphs are always trained to fly to their capital city, but they'll only take you to a remote hippogryph master after you've already been there. Since you arrived on one of Zaldaan's hippogryphs, you can also use that route to return to Azure Watch with the caregiver's supplies.", ["objectivesText"] = "Speak with Stephanos to purchase a hippogryph ride back to Azure Watch. Once you have arrived, deliver Nurguni's Supplies to Caregiver Chellan . Progress: Welcome back, <name>. Was Nurguni able to gather everything on the list?", ["rewardGold"] = 619600, ["rewardXP"] = 200, ["rewardItems"] = { 23903 }, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 17555, ["x"] = 0.546, ["y"] = 0.3616 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16553, ["x"] = 0.484, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.3616 }, ["mapCandidates"] = { ["npc"] = { 97, 103 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[9612] = { ["id"] = 9612, ["name"] = "A Hearty Thanks!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9612 }, ["description"] = "You saved my life, <name>! Thank you so much! That beast would have torn me to shreds if it weren't for you. If you see the exarch at Azure Watch, tell him of what you did. I'm sure he'll be pleased to hear such news!", ["objectivesText"] = "Speak with Exarch Menelaous at Azure Watch.", ["rewardGold"] = 199700, ["rewardXP"] = 150, ["rewardItems"] = { 86570 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17587, ["x"] = 0.487741, ["y"] = 0.449296 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17116, ["x"] = 0.472, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.487741, ["y"] = 0.449296 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[9616] = { ["id"] = 9616, ["name"] = "Bandits!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9616 }, ["description"] = "This appears to be a bounty ledger. You cannot understand the blood elf language but you note that there is a picture depicting a dead draenei, a smiling blood elf standing over the corpse, and a symbol of what you think is some sort of blood elf currency. They've put a hit out on draenei! You must inform the exarch.", ["objectivesText"] = "Take the Blood Elf Communication to Exarch Menelaous at Azure Watch. Progress: Yes? I'm very busy, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 200, ["rewardItems"] = { 23909, 23910, 24141, 24142, 24144, 34863, 131263, 198612 }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17116, ["x"] = 0.472, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["startItems"] = { 23910 } },
[9620] = { ["id"] = 9620, ["name"] = "The Missing Survey Team", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9620 }, ["series"] = { 9581, 9584, 9585, 9628 }, ["description"] = "As we've gotten ourselves established here at Blood Watch, I've been sending out survey teams to create more reliable maps of the island. In most cases, they returned unharmed with the data we need, but the team I sent east to the ruins hasn't reported back. I worry about what might have happened to them, but I can't spare the men to send another mission after them. Find them, <name>, and lend them any assistance they require to return with their survey data.", ["objectivesText"] = "Harbinger Mikolaas wants you to find the Survey Team he sent to the Ruins of Loreth'Aran and assist them in any way you can.", ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17600, ["x"] = 0.612, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9622] = { ["id"] = 9622, ["name"] = "Warn Your People", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["description"] = "The Hold is saved and soon my people will make their way back to the ancestral home. The prophecy has come to pass and a new age of prosperity begins for the Stillpine. But I fear that darkness looms ahead for your own people. There are questions left unanswered - visions of prophecy unseen. Return to your leaders and tell them of what you have seen here. And Promised One, should you ever require the aid of Stillpine, you have merely to ask.", ["objectivesText"] = "Speak with Exarch Menelaous at Azure Watch.", ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17440, ["x"] = 0.465, ["y"] = 0.207 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17116, ["x"] = 0.472, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.207 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 19, ["flags"] = 0 } } },
[9623] = { ["id"] = 9623, ["name"] = "Coming of Age", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9623 }, ["series"] = { 9625 }, ["description"] = "You have survived the wilds of our new home and shown yourself a cut above the others. I believe that you have come of age to assist those battling on the front lines of Bloodmyst. The Hand of Argus could use a <race> like you. Report to Torallius the Pack Handler . You will find him outside the Exodar, tending to the elekk. Give him these orders so that he may direct you towards your new duties on Bloodmyst.", ["objectivesText"] = "Exarch Menelaous at Azure Watch has asked that you deliver the Exarch's Orders to Torallius the Pack Handler , standing outside of the Exodar. Progress: <Torallius adjusts his eyepatch to look at you.> This is the best we can offer the Hand of Argus?", ["rewardXP"] = 25, ["rewardItems"] = { 23928, 199680, 199681, 199682, 199683, 199684 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17116, ["x"] = 0.472, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 17584, ["x"] = 0.69375, ["y"] = 0.4775 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 97, 103 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[9624] = { ["id"] = 9624, ["name"] = "A Favorite Treat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9624 }, ["description"] = "I've made a wonderful discovery, <class>. On the uncorrupted part of the island grows a remarkable fruit called the sand pear . They're found near the bottoms of the trees. I've been preparing pies from them, but if I'm not careful, the elekk will start to wander over and steal my fruit. I've taken to gathering enough to share with the animals, but my stores are gone and the craving for pie has returned. Would you be willing to help gather the fruit I need for another batch of pies? I promise I'll share!", ["objectivesText"] = "Aonar at Kessel's Crossing wants you to bring him 10 Sand Pears . Progress: The sand pears are getting harder to find and, of course, that means less pie and fewer treats for the elekk here. Were you able to gather all the fruit I'll need?", ["rewardGold"] = 58650, ["rewardXP"] = 200, ["rewardItems"] = { 23927, 24072, 26004, 26018, 26031, 26032, 26040, 120951, 131264 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17599, ["x"] = 0.634667, ["y"] = 0.886 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17599, ["x"] = 0.634667, ["y"] = 0.886 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.634667, ["y"] = 0.886 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9625] = { ["id"] = 9625, ["name"] = "Elekks Are Serious Business", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 9625 }, ["series"] = { 9623 }, ["description"] = "Is he crazy? Entrusting something like this to some no-named <race> youngling! Just remember this kid: You'll never make it as a Hand of Argus! You don't have the guts! I guess I'll have to humor him this time. Speak with Vorkhan at Kessel's Crossing on Bloodmyst Isle . Just follow the road north from here, and when it forks, just keep on going north.", ["objectivesText"] = "Speak with Vorkhan the Elekk Herder on Bloodmyst Isle .", ["rewardGold"] = 85400, ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 17584, ["x"] = 0.69375, ["y"] = 0.4775 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17586, ["x"] = 0.63, ["y"] = 0.878 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.69375, ["y"] = 0.4775 }, ["mapCandidates"] = { ["npc"] = { 103, 106 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[9626] = { ["id"] = 9626, ["name"] = "Meeting the Orcs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 1637, ["mapID"] = 90, ["storyline"] = { 9626 }, ["series"] = { 9328, 9621, 9627 }, ["description"] = "I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table. This should silence any opposition. Take this letter to Saurfang in Orgrimmar . As leader of the orcs, he must have a say in accepting the sin'dorei's pledge. I've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.", ["objectivesText"] = "Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to High Overlord Saurfang in Orgrimmar , capital of Durotar. Progress: You've come to see me, <race>? Speak and be quick, young lady. I've no time for the formalities of your race.", ["rewardXP"] = 200, ["rewardItems"] = { 23930 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 10181, ["x"] = 0.599429, ["y"] = 0.807143 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 14720, ["x"] = 0.485, ["y"] = 0.71 }, { ["mapID"] = 85, ["npcID"] = 39605, ["x"] = 0.4745, ["y"] = 0.5395 }, { ["mapID"] = 85, ["npcID"] = 86832, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.599429, ["y"] = 0.807143 }, ["mapCandidates"] = { ["npc"] = { 85, 90 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[9627] = { ["id"] = 9627, ["name"] = "Allegiance to the Horde", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 9627 }, ["series"] = { 9328, 9621, 9626 }, ["description"] = "Your people suffered a great betrayal by the Alliance. You succeeded in fighting off the Darnassian attacks and the spies from Ironforge. Now you defeated a powerful Scourge leader at the footsteps of your home. Your worthiness is no longer in question. It is clear now that we need each other. Return to Lor'themar. Tell him I have heard your message and accept. <Saurfang crushes the letter inside his palm.> Welcome to the Horde, elf.", ["objectivesText"] = "Return to Silvermoon City and report back to Lor'themar Theron .", ["rewardXP"] = 300, ["rewardItems"] = { 2314, 4253, 13032 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 14720, ["x"] = 0.485, ["y"] = 0.71 }, { ["mapID"] = 85, ["npcID"] = 39605, ["x"] = 0.4745, ["y"] = 0.5395 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 16802, ["x"] = 0.618667, ["y"] = 0.301 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 85, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[9628] = { ["id"] = 9628, ["name"] = "Salvaging the Data", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9628 }, ["series"] = { 9581, 9584, 9585, 9620 }, ["description"] = "It's too late to assist the cartographers in completing their mission, but it appears they collected the data Harbinger Mikolaas was expecting. The crystal storing their survey information was not among their ransacked packs, so it must be in the hands of the Wrathscale naga. You know that Harbinger Mikolaas will be saddened by the loss of the survey crew, but would want to salvage the survey data.", ["objectivesText"] = "Obtain the Survey Data Crystal from the Wrathscale near the dead cartographers and return it to Harbinger Mikolaas at Blood Watch. Progress: Were you able to find out what was keeping the survey team from returning?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 23932, 26016 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17600, ["x"] = 0.612, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9629] = { ["id"] = 9629, ["name"] = "Catch and Release", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9629 }, ["series"] = { 9574 }, ["description"] = "The Blacksilt murlocs on the southwestern coast are curious creatures. In some ways, they act barely sentient, yet in others, they show a remarkable degree of organization. I have a few theories about that, but no real way to test them until recently. I've devised a method that will allow me to track the murlocs I'm interested in without doing any lasting harm or interfering with their natural behavior. If you're willing to help with the marking, I'll gladly pay you for your assistance.", ["objectivesText"] = "Morae at Blood Watch wants you to 'mark' 6 Blacksilt Scouts using the Murloc Tagger . Progress: Did the device work? Have you marked the murlocs for my research?", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 23995, 26008, 26022, 120951, 131265 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17434, ["x"] = 0.532, ["y"] = 0.575 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17434, ["x"] = 0.532, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9634] = { ["id"] = 9634, ["name"] = "Alien Predators", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9634 }, ["series"] = { 28559 }, ["description"] = "One thing we've learned in our travels is that extreme care must be taken when introducing wildlife from one world to another. When the Exodar crashed, it was carrying specimens of various Outland species, including an insectoid predator called the ravager. Some of the specimens were lost, but many others survived and took to the wild. If we don't keep them in check, they will upset the natural balance here on the islands. You'll find these ravagers to the west of Kessel's Crossing, near the coast.", ["objectivesText"] = "Kill 10 Bloodmyst Hatchlings then return to Vorkhan the Elekk Herder at Kessel's Crossing on Bloodmyst Isle .", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 26049, 26051, 26053, 27389, 156993 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17586, ["x"] = 0.63, ["y"] = 0.878 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17586, ["x"] = 0.63, ["y"] = 0.878 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9635] = { ["id"] = 9635, ["name"] = "The Zapthrottle Mote Extractor!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 9635 }, ["description"] = "The swamp gas is truly amazing, and can be very useful, mon! But first, you gotta be able to suck it up, and that, my friend, requires a Zapthrottle Mote Extractor. Now, I could just give you the schematics, but I'll need something in return first. How about some spare parts? Last time I checked, there were plenty lying around near the broken steam pump at the Dead Mire, far to the northeast. I heard that the withered giants spread the pieces all over that dried-out lake bed.", ["objectivesText"] = "Bring 15 Steam Pump Parts to Mack Diver at Zabra'jin in Zangarmarsh. Progress: You got those parts yet? I've got some diving to do.", ["rewardXP"] = 1415, ["rewardItems"] = { 23888, 23981 }, ["starts"] = { { ["mapID"] = 102, ["npcID"] = 17637, ["x"] = 0.34, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 102, ["npcID"] = 17637, ["x"] = 0.34, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "standard" },
[9636] = { ["id"] = 9636, ["name"] = "The Zapthrottle Mote Extractor!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 9636 }, ["description"] = "Have you seen the swamp gas? Isn't it just shiny? It takes a Zapthrottle Mote Extractor to suck 'em dry though. I could give you the plans to make one, but I really need some spare parts to fix stuff 'round here. Last time I checked, there were plenty of parts lying around near the steam pump at the Dead Mire to the northeast. I think the withered giants broke the pump out there. Shall we help each other out?", ["objectivesText"] = "Bring 15 Steam Pump Parts to K. Lee Smallfry at Telredor in Zangarmarsh. Progress: You got those parts yet? I've got a compression coil to fix before Anchorite Ahuurn starts breathing down my neck!", ["rewardXP"] = 1415, ["rewardItems"] = { 23888, 23981, 37589 }, ["starts"] = { { ["mapID"] = 102, ["npcID"] = 17634, ["x"] = 0.685, ["y"] = 0.501 } }, ["ends"] = { { ["mapID"] = 102, ["npcID"] = 17634, ["x"] = 0.685, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "standard" },
[9641] = { ["id"] = 9641, ["name"] = "Irradiated Crystal Shards", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9641 }, ["description"] = "The Exodar's crash scattered pieces of fouled crystals all over Bloodmyst Isle , corrupting the water and the landscape. We've even begun finding pieces of the crystals inside the flesh of animals taken for meat. I've uncovered a way to purify the shard and turn them into functional crystals, so if you bring me enough shards, I'll trade one of my completed crystals for them. So far I've found the shards in the bodies of bears, ravagers, flutterers, and treants inhabiting the corrupted part of the island.", ["objectivesText"] = "Vindicator Boros at Blood Watch wants you to bring him 10 Irradiated Crystal Shards . Progress: Have you gathered crystal shards from the creatures of Bloodmyst?", ["rewardXP"] = 200, ["rewardItems"] = { 23984, 23985, 23986, 23989 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9642] = { ["id"] = 9642, ["name"] = "More Irradiated Crystal Shards", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9642 }, ["objectivesText"] = "Progress: If you have more of the irradiated crystal shards , I'd be happy to exchange them for another of my crystals.", ["rewardItems"] = { 23984, 23985, 23986, 23989 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9643] = { ["id"] = 9643, ["name"] = "Constrictor Vines", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9643 }, ["description"] = "A good woodsman makes use of every available resource, <class>. Even the most bizarre creatures possess attributes we can use to our advantage. With Blood Watch under constant assault from the Sunhawks, we're looking to a variety of natural defenses including traps. The lasher's thorny vines are perfectly suited to the construction of the traps I have in mind. The combination of sharp spines and deadly toxin will fell unwary attackers. Bring me the vines of mutated constrictors so that I can begin my work.", ["objectivesText"] = "Tracker Lyceon at Blood Watch wants you to bring him 6 Thorny Constrictor Vines . Progress: Did you manage to get the constrictor vines?", ["rewardGold"] = 58650, ["rewardXP"] = 200, ["rewardItems"] = { 23994 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17642, ["x"] = 0.558, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17642, ["x"] = 0.558, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9646] = { ["id"] = 9646, ["name"] = "WANTED: Deathclaw", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9646 }, ["description"] = "By order of Harbinger Mikolaas : A bounty to be paid to the brave soul who returns with proof of the marauding bear Deathclaw's demise. Deathclaw should be considered extremely dangerous and is responsible for the killing of a survey team on the coast to the northwest of Blood Watch. Travelers are advised to avoid the area.", ["objectivesText"] = "Bring Deathclaw's Paw to Harbinger Mikolaas in Blood Watch. Progress: How can I help you, <class>?", ["rewardGold"] = 117300, ["rewardXP"] = 200, ["rewardItems"] = { 24025, 27398, 27400 }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9647] = { ["id"] = 9647, ["name"] = "Culling the Flutterers", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9647 }, ["description"] = "When we first encountered flutterers, they showed few signs of mutation. As the corruption got progressively worse, the moths and other species began to show signs of contamination. It has progressed to the point where they damage nearly everything they come in contact with. They're amplifying the damage being done by the crystal shards scattered by the Exodar's crash. We have no choice but to begin culling their population in the lands north of Blood Watch.", ["objectivesText"] = "Tracker Lyceon at Blood Watch wants you to kill 10 Royal Blue Flutterers .", ["rewardGold"] = 58650, ["rewardXP"] = 200, ["rewardItems"] = { 26013, 26026, 26038, 131266 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17642, ["x"] = 0.558, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17642, ["x"] = 0.558, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9648] = { ["id"] = 9648, ["name"] = "Maatparm Mushroom Menagerie", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "Did you know mushroom hunting is far more dangerous than mushroom consumption? Mushroom hunters expose themselves to many unknowns - not including potential wildlife dangers! What would life be without a little danger? I am in need of mushrooms for my collection. Scattered throughout these unexplored wilds you will find four different types: An aquatic stinkhorn , a blood mushroom , a ruinous polyspore , and a fel cone fungus . They are each unique to various regions in Bloodmyst. Bring them to me.", ["objectivesText"] = "Maatparm at Blood Watch wants 1 Aquatic Stinkhorn , 1 Blood Mushroom , 1 Ruinous Polyspore , and 1 Fel Cone Fungus . Progress: Remember, the mushrooms I requested are each unique to the different environments of Bloodmyst.", ["rewardGold"] = 210000, ["rewardXP"] = 200, ["rewardItems"] = { 24040, 24041, 24042, 24043, 26014, 26028, 26040, 131267 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17663, ["x"] = 0.5645, ["y"] = 0.5655 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17663, ["x"] = 0.5645, ["y"] = 0.5655 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.5645, ["y"] = 0.5655 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 26, ["flags"] = 0 } } },
[9649] = { ["id"] = 9649, ["name"] = "Ysera's Tears", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "Good to see you again, <name>! You were exceptionally efficient in completing the last task that I offered you. Perhaps you would be interested in another? To the northeast lies Wyrmscar Island, home to a rare species of mushroom known as Ysera's tear - named after the green dragonlings that inhabit the island. I only require a small sampling of the mushroom, but I must warn you that the denizens of the island do not welcome visitors. Tread carefully.", ["objectivesText"] = "Maatparm at Blood Watch wants 2 Ysera's Tears . Progress: Back so soon?", ["rewardGold"] = 929400, ["rewardXP"] = 200, ["rewardItems"] = { 24049, 26005, 26019, 26030, 131268 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17663, ["x"] = 0.5645, ["y"] = 0.5655 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17663, ["x"] = 0.5645, ["y"] = 0.5655 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.5645, ["y"] = 0.5655 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 27, ["flags"] = 0 } } },
[9663] = { ["id"] = 9663, ["name"] = "The Kessel Run", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster", "timed" }, ["timerSeconds"] = 900, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9666, 9668 }, ["description"] = "You're just in time, <name>. Blood elf activity in this area has doubled in the past week. Our agents have informed us that the blood elves that call themselves Sunhawks plan to launch an offensive upon Azuremyst soon. I need you to get a warning out to our allies and compatriots. Warn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing. Time is of the essence so I am lending you my elekk. Be sure to keep it out of water.", ["objectivesText"] = "Kessel at Kessel 's Crossing wants you to warn High Chief Stillpine at Stillpine Hold, Exarch Menelaous at Azure Watch and Admiral Odesyus at Odesyus' Landing of the imminent blood elf invasion. Return to Kessel when you complete this task. You have 15 minutes. (Be sure to keep it out of water.) Progress: This is no time to relax!", ["rewardXP"] = 200, ["rewardItems"] = { 122703 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17649, ["x"] = 0.63, ["y"] = 0.875 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17649, ["x"] = 0.63, ["y"] = 0.875 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.875 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 0, ["flags"] = 0 } } },
[9666] = { ["id"] = 9666, ["name"] = "Declaration of Power", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9663, 9668 }, ["description"] = "Have you seen the serpent men? The ones that call themselves naga? < Kessel spits.> They dared make an advance upon this camp under cover of darkness only three nights ago. Can you believe the audacity of those primitive beasts? I need you to deliver a message to their leadership, <name>. To the northeast is Wrathscale Lair, home to Lord Xiz . Find him, slay him where he stands and drive this banner through his corpse. Let them know fear whenever they should see our standard!", ["objectivesText"] = "Kessel at Kessel 's Crossing on Bloodmyst Isle wants you to kill Lord Xiz at Wrathscale Lair and drive the Draenei Banner through his dead body. Progress: Is it done?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 24084, 26012, 26027, 26039, 131269 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17649, ["x"] = 0.63, ["y"] = 0.875 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17649, ["x"] = 0.63, ["y"] = 0.875 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.875 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 1, ["flags"] = 0 } } },
[9667] = { ["id"] = 9667, ["name"] = "Saving Princess Stillpine", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9667 }, ["description"] = "Help me, <name>! The Bristlelimb captured me and are planning to sacrifice me to their foul gods! High Chief Bristlelimb holds the key that opens the cage. To force him to appear, you must slaughter the evil Bristlelimb furbolgs that inhabit the enclave, just two camps to the west of this camp. If you kill enough of them, he will surely come for vengeance! When he shows up, kill him and get the key! My father will richly reward you if you can save me!", ["objectivesText"] = "Release Princess Stillpine from her cage and then speak with Stillpine Ambassador Frasaboo at Blood Watch. You must kill High Chief Bristlelimb for the key that opens the cage.", ["rewardXP"] = 250, ["rewardItems"] = { 24099, 24342, 24343, 156994 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17682, ["x"] = 0.645, ["y"] = 0.7465 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 18803, ["x"] = 0.552, ["y"] = 0.557 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.7465 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9668] = { ["id"] = 9668, ["name"] = "Report to Exarch Admetius", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9668 }, ["series"] = { 9663, 9666 }, ["description"] = "A Hand of Argus soldier is many things: Obedient, brave, intelligent, and above all, honorable. You may yet exhibit some of these traits, <class>. Report to Exarch Admetius at Blood Watch if you are still interested in joining the Hand. He and his subordinates will further train you in the ways of the draenei soldier. And remember this, <name>: Honorable people do not always perform honorably. Sometimes they cannot. You will find Blood Watch just up this road, to the north.", ["objectivesText"] = "Speak with Exarch Admetius at Blood Watch.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17649, ["x"] = 0.63, ["y"] = 0.875 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17658, ["x"] = 0.526, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.875 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9669] = { ["id"] = 9669, ["name"] = "The Missing Expedition", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9669 }, ["description"] = "About a week ago, my research team and I were out exploring the western wilds of Bloodmyst when we were attacked by bloodthirsty spiders. The effect of the crystal contamination was clearly evident as these spiders were massive and extremely aggressive. I managed to escape but my team wasn't so lucky. We must not let the same fate befall others. Go west to the Amberweb Pass and destroy the spiders and their matriarch, Zarakh .", ["objectivesText"] = "Kill 8 Myst Spinners , 8 Myst Leechers and their leader, Zarakh . Return to Achelus at Blood Watch when the task is complete.", ["rewardGold"] = 315000, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17676, ["x"] = 0.532, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17676, ["x"] = 0.532, ["y"] = 0.57 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9670] = { ["id"] = 9670, ["name"] = "They're Alive! Maybe...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9670 }, ["description"] = "It was a bloody mess, <name>. We were ambushed by a large pack of these spiders. Their progenitor descended upon us with incredible speed and wrapped us up in cocoons. After we were webbed, she began to lay eggs near us. We were to be food for her young! FOOD! I managed to cut my way out and escape but I will not leave the others behind. So far I've been unsuccessful in nearing the pass. Would you lend a hand? Destroy those cocoons! Hopefully some of our team is still alive!", ["objectivesText"] = "Researcher Cornelius has asked that you free 5 Expedition Researchers . Progress: Any luck?", ["rewardXP"] = 200, ["rewardItems"] = { 26017 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17686, ["x"] = 0.248, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17686, ["x"] = 0.248, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.248, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[9671] = { ["id"] = 9671, ["name"] = "Urgent Delivery", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9672, 9674, 9682, 9683 }, ["rewardXP"] = 50, ["rewardItems"] = { 24132 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17703, ["x"] = 0.546118, ["y"] = 0.568353 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17703, ["x"] = 0.546118, ["y"] = 0.568353 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.546118, ["y"] = 0.568353 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 28, ["flags"] = 0 } } },
[9672] = { ["id"] = 9672, ["name"] = "The Bloodcurse Legacy", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9671, 9674, 9682, 9683 }, ["description"] = "Dear friend, My hand trembles as I ink this letter. I pray that it reaches you in time. Last night, Edward Hanes, captain of the ship 'Lost Hope', appeared before me in my tent. The same Edward Hanes that died of scurvy 20 years ago. This apparition told me a tale that made my heart tremble. A tale that I need you to hear and a mission that I need you to accomplish. Will you do it? Will you seek out Edward on Wyrmscar Island, northeast of your base? Regards, Admiral Odesyus", ["objectivesText"] = "Admiral Odesyus has asked that you find and speak with Captain Edward Hanes .", ["rewardXP"] = 50, ["rewardItems"] = { 24132, 24344 }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17712, ["x"] = 0.79, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 32, ["flags"] = 0 } }, ["startItems"] = { 24132 } },
[9674] = { ["id"] = 9674, ["name"] = "The Bloodcursed Naga", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9671, 9672, 9682, 9683 }, ["description"] = "They say when the world was sundered, this land cried the loudest. It was here that thousands of night elves faded into oblivion and in their place rose terrible creatures of hate - the naga. Obedient to their twisted queen, Azshara, they would destroy all that would dare pass through their sea. It would remain this way for thousands of years - until now. The first order of business is to remove the bloodcursed naga from the reef.", ["objectivesText"] = "Captain Edward Hanes on Wyrmscar Island wants you to kill 10 Bloodcursed Naga . Progress: They're nasty creatures...", ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17712, ["x"] = 0.79, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17712, ["x"] = 0.79, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 34, ["flags"] = 0 } } },
[9682] = { ["id"] = 9682, ["name"] = "The Hopeless Ones...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9671, 9672, 9674, 9683 }, ["description"] = "On a ledge of the reef, deeper than where you found the bloodcursed naga, you will find the hopeless ones: The bloodcursed voyagers, ghosts of those taken by the bloodcurse. It is regrettable, what I ask of you now... but they must be destroyed and their cursed shells brought back to me. Their souls must be put to rest. Return to me when you have done as asked and I shall give you one final task.", ["objectivesText"] = "Captain Edward Hanes on Wyrmscar Island wants you to recover 4 Bloodcursed Souls . Progress: Do not mourn their demise, <name>.", ["rewardXP"] = 200, ["rewardItems"] = { 24153 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17712, ["x"] = 0.79, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17712, ["x"] = 0.79, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 35, ["flags"] = 0 } } },
[9683] = { ["id"] = 9683, ["name"] = "Ending the Bloodcurse", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9671, 9672, 9674, 9682 }, ["description"] = "To the south you will find Bloodcurse Isle. Atop the island you will find a shrine dedicated to the beloved queen of the naga, Azshara. Destroy the statue - burn it in effigy! This will surely draw the ire of Atoph, the Bloodcursed leader. Slay Atoph and return to me!", ["objectivesText"] = "Captain Edward Hanes on Wyrmscar Island wants you to destroy the Statue of Queen Azshara and kill Atoph the Bloodcursed . Progress: Atoph must be lured out!", ["rewardXP"] = 200, ["rewardItems"] = { 24132, 24334 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17712, ["x"] = 0.79, ["y"] = 0.225 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17712, ["x"] = 0.79, ["y"] = 0.225 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.225 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 36, ["flags"] = 0 } } },
[9687] = { ["id"] = 9687, ["name"] = "Restoring Sanctity", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "Not long ago, the once tranquil owlkin of the region appeared on the shores of this island. One by one they would come to steal the bones of the fallen dragons. I do not know what would cause these creatures such distress or why they would want the bones of the deceased, but the spirits of the brood have grown restless due to this sacrilege. To the west, across the Crimson Reach, you will find Ragefeather Ridge. Venture to the owlkin encampments and recover the pilfered dragon bones .", ["objectivesText"] = "Prince Toreth on Wyrmscar Island wants you to recover 8 Dragon Bones . Progress: The dragon wars have long since passed. All that remains are bones and the agitated remnants of Ysera's brood.", ["rewardXP"] = 200, ["rewardItems"] = { 24185 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17674, ["x"] = 0.741, ["y"] = 0.341 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17674, ["x"] = 0.741, ["y"] = 0.341 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.341 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 29, ["flags"] = 0 } } },
[9688] = { ["id"] = 9688, ["name"] = "Into the Dream", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "The whelps that you see on this island are the agitated spirits of the green dragonflight. Like me, they are bound to the land, unable to ascend to their final resting place in the Dream. Recovering the bones of the fallen has settled them somewhat but you must take further action. Destroy their ethereal manifestations. I cannot leave this place until it is done. They must be released!", ["objectivesText"] = "Prince Toreth at Wyrmscar Island has asked that you slay 5 Veridian Whelps and 5 Veridian Broodlings .", ["rewardGold"] = 23400, ["rewardXP"] = 200, ["rewardItems"] = { 173363 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17674, ["x"] = 0.741, ["y"] = 0.341 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17674, ["x"] = 0.741, ["y"] = 0.341 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.341 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 30, ["flags"] = 0 } } },
[9689] = { ["id"] = 9689, ["name"] = "Razormaw", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "Many of the black dragonflight were slain during the attacks. One of them, a lieutenant of Deathwing himself, still haunts this place. If you look to the heavens, you can see his spectral countenance circling the skies. His hatred is so great that he remains even in death. Take the bones that you gathered for me earlier to the top of the mountain on this island and place them in the ever-burning pyre. This act should signal Razormaw to descend. When he does, slay his undead form.", ["objectivesText"] = "Prince Toreth at Wyrmscar Island has asked that you slay Razormaw . Progress: I recommend that you bring allies, <name>.", ["rewardXP"] = 200, ["rewardItems"] = { 24221, 24346, 24347, 24348, 131270 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17674, ["x"] = 0.741, ["y"] = 0.341 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17674, ["x"] = 0.741, ["y"] = 0.341 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.341 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 31, ["flags"] = 0 } } },
[9693] = { ["id"] = 9693, ["name"] = "What Argus Means to Me", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9694 }, ["description"] = "What does Argus mean to you, <name>? Many draenei probably do not know or remember our home planet. It is there that we split from the man'ari: the twisted demonic reflections of ourselves that were 'gifted' by Sargeras. Or as they call themselves, eredar. Eredar... this word once held meaning. <Admetius smacks his lips as if to taste the word.> Disgusting. Let us not waste anymore time. Find Vindicator Boros to begin your training.", ["objectivesText"] = "Exarch Admetius at Blood Watch has told you to speak with Vindicator Boros .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17658, ["x"] = 0.526, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 2, ["flags"] = 0 } } },
[9694] = { ["id"] = 9694, ["name"] = "Blood Watch", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9693 }, ["description"] = "Blood Watch is one of two forward bases operated by the Hand of Argus. You have already been to the other base, Azure Watch; things are completely different in Bloodmyst. When we first got here, the land was as beautiful as Azuremyst. We even called it Silvergale but now sickness is spreading across the land, worse yet, the blood elves that we were battling on the Exodar survived the crash. This brings me to your assignment: Venture northwest into Bladewood and terminate any blood elves that you find.", ["objectivesText"] = "Vindicator Boros at Blood Watch wants you to slay 10 Sunhawk Spies .", ["rewardXP"] = 200, ["rewardItems"] = { 26050, 26054, 27640 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 3, ["flags"] = 0 } } },
[9696] = { ["id"] = 9696, ["name"] = "Translations...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9698, 9699, 9700, 9779 }, ["description"] = "Our chief interrogator, Elysia, is fluent in Thalassian. Take the document to her and see what she has to say.", ["objectivesText"] = "Take the Sunhawk Missive to Interrogator Elysia at Blood Watch. Progress: I'm a bit busy here, agent <name>. This better be important.", ["rewardXP"] = 25, ["rewardItems"] = { 24399 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17825, ["x"] = 0.545, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 7, ["flags"] = 0 } } },
[9698] = { ["id"] = 9698, ["name"] = "Audience with the Prophet", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9696, 9699, 9700, 9779 }, ["description"] = "I need you to deliver the translated documents to Velen personally, <name>. I don't trust that deranged messenger. Explain to the Prophet that the blood elves are receiving reinforcements from the Outland and that they have a spy amongst the draenei at the Exodar. Velen resides in the Vault of Lights inside the Exodar. Make haste!", ["objectivesText"] = "Take the Translated Sunhawk Missive to Prophet Velen at the Exodar. Progress: <Velen smiles.> Greetings, <name>. I have been expecting you.", ["rewardXP"] = 200, ["rewardItems"] = { 24323 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17825, ["x"] = 0.545, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 17468, ["x"] = 0.3252, ["y"] = 0.5468 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 103, 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 8, ["flags"] = 0 } } },
[9699] = { ["id"] = 9699, ["name"] = "Truth or Fiction", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 103, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9696, 9698, 9700, 9779 }, ["description"] = "I thank you for the timely delivery, <name>. You are turning out to be one of the Hand's better agents. If only we knew who they reported to in Bloodmyst and more importantly, where this sun portal was... They seem to have it tightly guarded - wherever it may be. Would you be interested in some reconnaissance work? If so, take these orders back to Vindicator Boros . He will give you your next mission.", ["objectivesText"] = "Take Velen's Orders to Vindicator Boros at Blood Watch. Progress: Well?", ["rewardXP"] = 50, ["rewardItems"] = { 24230 }, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 17468, ["x"] = 0.3252, ["y"] = 0.5468 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.3252, ["y"] = 0.5468 }, ["mapCandidates"] = { ["npc"] = { 103, 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 9, ["flags"] = 0 } } },
[9700] = { ["id"] = 9700, ["name"] = "I Shoot Magic Into the Darkness", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9696, 9698, 9699, 9779 }, ["description"] = "Velen states that if the blood elves have been opening rifts between this island and the Outland, there will be residue or anomalies left in the areas where the portals have been opened. You must search the island for locations that exhibit or display these anomalies. Be warned, <name>; some of these anomalies will be creatures from the void itself. Should you find void anomalies, slay them! Report back to me with any new information that you may find. Begin your search to the north, near the Warp Piston.", ["objectivesText"] = "Vindicator Boros at Blood Watch wants you to locate the Sun Portal Site and slay 5 Void Anomalies .", ["rewardXP"] = 200, ["rewardItems"] = { 26010, 26024, 26036, 131271 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 10, ["flags"] = 0 } } },
[9703] = { ["id"] = 9703, ["name"] = "The Cryo-Core", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "We have others pursuing leads on the sun portals, <name>. I need you to focus on the task at hand. Boros has received new reports of another crash site. What we've since discovered is that the crash site is actually the Exodar's cryo-core. This is a pod holding area that houses pods exactly like the ones we draenei crawled out of in Ammen Vale. This area also holds medical supplies . Head to the Cryo-Core, directly west of Blood Watch. Search for supplies and search for survivors.", ["objectivesText"] = "Vindicator Kuros at Blood Watch wants you to recover 12 boxes of Medical Supplies . Progress: Was the information accurate?", ["rewardXP"] = 200, ["rewardItems"] = { 24236, 26052, 27390, 27641 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17843, ["x"] = 0.555333, ["y"] = 0.553333 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17843, ["x"] = 0.555333, ["y"] = 0.553333 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555333, ["y"] = 0.553333 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 11, ["flags"] = 0 } } },
[9704] = { ["id"] = 9704, ["name"] = "Slain by the Wretched", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8325, 8326, 8334, 8335, 8347, 8350, 9704, 9705 }, ["series"] = { 8347, 9705 }, ["description"] = "It's hard work being an outrunner between Sunstrider Isle and Falconwing Square. Tight deadlines, long hours and worst of all... the Wretched! The road south goes through the ruins of Silvermoon... the place is crawling with Wretched ready to kill you for a few mana crystals. Unfortunately, I think that's what happened to the last outrunner we sent with one of Erona's packages. I see you're eager to prove yourself. Venture into Dawning Lane and see if you can find any traces of our outrunner.", ["objectivesText"] = "Go south into the ruins of Silvermoon and look for the Slain Outrunner in Dawning Lane.", ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 15301, ["x"] = 0.404, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 17849, ["x"] = 0.42, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 1199, ["name"] = "Sunstrider Isle", ["orderIndex"] = 5, ["flags"] = 0 } } },
[9705] = { ["id"] = 9705, ["name"] = "Package Recovery", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 8325, 8326, 8334, 8335, 8347, 8350, 9704, 9705 }, ["series"] = { 8347, 9704 }, ["description"] = "You take the package and confirm that indeed it comes from Magistrix Erona. Alarion would probably want you to bring it to her.", ["objectivesText"] = "Return to Outrunner Alarion with Erona's Package . Progress: What did you find, <name>?", ["rewardGold"] = 26750, ["rewardXP"] = 100, ["rewardItems"] = { 20804 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 17849, ["x"] = 0.42, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 15301, ["x"] = 0.404, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 94, ["questLines"] = { { ["id"] = 1199, ["name"] = "Sunstrider Isle", ["orderIndex"] = 6, ["flags"] = 0 } } },
[9706] = { ["id"] = 9706, ["name"] = "Galaen's Journal - The Fate of Vindicator Saruan", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "Your hands tremble as you pick up the book. Kuros must be told about this tragedy. Return the book to him.", ["objectivesText"] = "Take Galaen's Journal to Vindicator Kuros at Blood Watch. Progress: What have you got there, <name>? Is that a journal?", ["rewardXP"] = 150, ["rewardItems"] = { 24237, 144275 }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17843, ["x"] = 0.555333, ["y"] = 0.553333 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555333, ["y"] = 0.553333 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 14, ["flags"] = 0 } } },
[9711] = { ["id"] = 9711, ["name"] = "Matis the Cruel", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "Matis will be brought to justice, <name>; and I want you to be the one to find him and bring him back to the Triumvirate. Scour the island for this killer. Should you find him, use this flare gun . When my trackers see the flare, they'll come and assist in capturing Matis. Return to me after he's been captured.", ["objectivesText"] = "Vindicator Kuros at Blood Watch wants you to capture Matis the Cruel.", ["rewardXP"] = 200, ["rewardItems"] = { 24278, 26007, 26021, 26033, 131272, 137663 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17843, ["x"] = 0.555333, ["y"] = 0.553333 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17843, ["x"] = 0.555333, ["y"] = 0.553333 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555333, ["y"] = 0.553333 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 15, ["flags"] = 0 } } },
[9740] = { ["id"] = 9740, ["name"] = "The Sun Gate", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9746, 9748 }, ["description"] = "Thanks to you and the work you did, my scouts were able to find the sun gate . The elves keep the portal location mobile so that they can move it at a moment's notice. That's why the site you investigated was empty. The strength of such a system is also its greatest weakness. The sun gate is stabilized by portal controllers. If we can take down the controllers, the portal will be ours to destroy. The current sun gate location can be found west of here, south of the Vector Coil. Find it and destroy it!", ["objectivesText"] = "Vindicator Aesom at Blood Watch wants you to destroy the Sun Gate .", ["rewardGold"] = 137400, ["rewardXP"] = 200, ["rewardItems"] = { 6662, 85500 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17844, ["x"] = 0.555, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17844, ["x"] = 0.555, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 25, ["flags"] = 0 } } },
[9741] = { ["id"] = 9741, ["name"] = "Critters of the Void", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "Aesom sent my squad out on a reconnaissance mission to search for the sun gate a few days ago. Needless to say, we found it... <Loryi points at Jorli.> Whatever those fool elves are transporting through that portal is causing void energy to be released. The area is teaming with void critters . We must destroy them before they have a chance to grow into void anomalies. You'll find the source of the creatures southwest of here, near the sun gate. Kill them and report back to Aesom when you're done.", ["objectivesText"] = "Kill 12 Void Critters and report to Vindicator Aesom at Blood Watch.", ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17926, ["x"] = 0.302, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17844, ["x"] = 0.555, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 23, ["flags"] = 0 } } },
[9746] = { ["id"] = 9746, ["name"] = "Limits of Physical Exhaustion", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9740, 9748 }, ["description"] = "Victory is close at hand, <name>. With the discovery of the sun gate, it won't be long until their supply lines are completely closed off. Now is the time to strike at their numbers. To the west you will find numerous Sunhawk camps. The Sunhawk pyromancers and defenders occupy the vast majority of the area. Find them, kill them and return to me.", ["objectivesText"] = "Vindicator Aesom at Blood Watch wants you to slay 10 Sunhawk Pyromancers and 10 Sunhawk Defenders . Progress: Their leader can't hide from us forever. We will systematically eliminate every possible hiding place until Sironas is found.", ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17844, ["x"] = 0.555, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17844, ["x"] = 0.555, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 17, ["flags"] = 0 } } },
[9748] = { ["id"] = 9748, ["name"] = "Don't Drink the Water", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9740, 9746 }, ["description"] = "Our shaman claim that the elements of water have become greatly agitated by the pollution of the water source. We know that the Exodar's power core is lodged into the mountain to the west. It must be leaking volatile fluids into the water supply! I need you to get me more information. <Aesom points to a flask and nods.> You are to take this flask and follow the beach north until you reach the area where the rivers of Bloodmyst drain into the ocean. Take a sample from that location and return to me.", ["objectivesText"] = "Vindicator Aesom at Blood Watch wants you to use the Water Sample Flask to get a Bloodmyst Water Sample . Progress: Don't drink the water, <name>!", ["rewardXP"] = 200, ["rewardItems"] = { 24317, 24318 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17844, ["x"] = 0.555, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17844, ["x"] = 0.555, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 16, ["flags"] = 0 } } },
[9753] = { ["id"] = 9753, ["name"] = "What We Know...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9756, 9760, 9761 }, ["description"] = "We've learned much of our enemies in recent days. The blood elves are led by a being known as Sironas and plot to destroy us. Ultimately, they seek to enslave O'ros and regain control of the Exodar. Light be praised, we have stopped their supply line by destroying the sun gate. Unfortunately, they continue to use the contaminant of the Vector Coil to poison the land, using the mutagenic properties of the fallout to their advantage. With this knowledge, Admetius has devised a plan. Seek him out.", ["objectivesText"] = "Speak to Exarch Admetius at Blood Watch.", ["rewardGold"] = 341600, ["rewardXP"] = 25, ["rewardItems"] = { 24344, 169477, 169478, 169481, 237812 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17844, ["x"] = 0.555, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17658, ["x"] = 0.526, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 4, ["flags"] = 0 } } },
[9756] = { ["id"] = 9756, ["name"] = "What We Don't Know...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9753, 9760, 9761 }, ["description"] = "Our attempts at interrogation have failed miserably, <name>. Torture is - of course - out of the question. What we need is a <race> on the inside. I can cast a spell upon you that would make you appear blood elf and adjust your language. Through subterfuge, we may be able to get the information we need out of the captured agent. Under this guise, I want you to get whatever information you can out of the prisoner. And <name>, do not leave Blood Watch while disguised as the spell will fail.", ["objectivesText"] = "Speak to a Captured Sunhawk Agent at Blood Watch and recover Sunhawk Information. Return to Exarch Admetius when the task is complete. Progress: Do not return until you have succeeded!", ["rewardGold"] = 341600, ["rewardXP"] = 150, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17658, ["x"] = 0.526, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17658, ["x"] = 0.526, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 5, ["flags"] = 0 } } },
[9758] = { ["id"] = 9758, ["name"] = "Return to Arcanist Vandril", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9138, 9139, 9140, 9143, 9145, 9146, 9149, 9150, 9151, 9152, 9155, 9156, 9157, 9160, 9162, 9163, 9164, 9166, 9167, 9169, 9170, 9171, 9172, 9174, 9176, 9192, 9193, 9199, 9214, 9215, 9216, 9218, 9220, 9274, 9275, 9276, 9277, 9282, 9327, 9329, 9758 }, ["series"] = { 9138, 9139, 9140, 9327, 9329, 28560 }, ["description"] = "Now my friend, if you would be so kind as to return to Arcanist Vandril , I know that he is very anxious to send you out on your first mission here in the Ghostlands . We're counting on you, <name>. Don't let us down.", ["objectivesText"] = "Return to Arcanist Vandril at Tranquillien in the Ghostlands .", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16252, ["x"] = 0.448, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 16197, ["x"] = 0.465, ["y"] = 0.2855 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 444, ["name"] = "Ghostlands", ["orderIndex"] = 2, ["flags"] = 0 } } },
[9759] = { ["id"] = 9759, ["name"] = "Ending Their World", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9762 }, ["description"] = "Don't accept this assignment if you value your life. You see that gigantic power core jutting out of the mountain side over yonder? Whoever takes on this burden will need to fight their way through that mountain, battling an army of Sunhawks while protecting me as I rig the core up for demolition. Sironas the eredar is somewhere up there as well. I won't think less of you if you just walk away, <name>. But maybe you're the one - the one to destroy the Vector Coil and take down Sironas. Well, are you?", ["objectivesText"] = "Follow and protect Demolitionist Legoso as he attempts to destroy the Vector Coil and slay Sironas. Return to Exarch Admetius at Blood Watch should you complete the mission.", ["rewardGold"] = 1024800, ["rewardXP"] = 300, ["rewardItems"] = { 24351, 24352, 24353, 24354 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17982, ["x"] = 0.2438, ["y"] = 0.5056 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17658, ["x"] = 0.526, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.2438, ["y"] = 0.5056 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 24, ["flags"] = 0 } } },
[9760] = { ["id"] = 9760, ["name"] = "Vindicator's Rest", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9753, 9756, 9761 }, ["description"] = "I would not ask you to single-handedly bear the burden of destroying the Vector Coil and slaying Sironas, <name>; however, I believe that you can be of some help in clearing the way for others that might take on such a dangerous assignment. Take the road going north out of Blood Watch and follow it until you get to the fork. Once there, take the left road and follow it until you see Vindicator's Rest - it will be slightly west of the road itself. Corin will be waiting for you.", ["objectivesText"] = "Speak with Vindicator Corin at Vindicator's Rest on Bloodmyst Isle .", ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17658, ["x"] = 0.526, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17986, ["x"] = 0.306, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 18, ["flags"] = 0 } } },
[9761] = { ["id"] = 9761, ["name"] = "Clearing the Way", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9753, 9756, 9760 }, ["description"] = "Only the most battle hardened, noble and positively fearless will submit to Legoso's mission. The exarch will not order any agent of the Hand to take on the task of destroying the Vector Coil and dispatching Sironas. He refuses to send any draenei to their death - which is what the mission is: suicide... <Corin sighs.> My job is to soften up the Sunhawk defenses. You are to slay Sunhawks near the Vector Coil and keep the path clear for our champion - whoever that may be.", ["objectivesText"] = "Vindicator Corin at Vindicator's Rest wants you to slay 8 Sunhawk Saboteurs and 8 Sunhawk Agents .", ["rewardGold"] = 210000, ["rewardXP"] = 250, ["rewardItems"] = { 26009, 26023, 26035, 112595, 112596, 112597, 112598, 131273 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17986, ["x"] = 0.306, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17986, ["x"] = 0.306, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 19, ["flags"] = 0 } } },
[9762] = { ["id"] = 9762, ["name"] = "The Unwritten Prophecy", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9759 }, ["rewardItems"] = { 24344, 24349, 24350 }, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 17468, ["x"] = 0.3252, ["y"] = 0.5468 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 17468, ["x"] = 0.3252, ["y"] = 0.5468 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.3252, ["y"] = 0.5468 }, ["mapCandidates"] = { ["npc"] = { 103 }, ["zone"] = { 3557 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 37, ["flags"] = 0 } } },
[9779] = { ["id"] = 9779, ["name"] = "Intercepting the Message", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["series"] = { 9696, 9698, 9699, 9700 }, ["description"] = "It is good to see you again, <name>. I have a quandary that you might be able to solve. Our agents situated behind Sunhawk lines have reported seeing Sunhawk soldiers parsing an unusual document. Unfortunately, we have been unsuccessful in acquiring a copy of the document for ourselves. I need you to go out in the field and try to recover the document. I am certain that if you apply enough pressure, a Sunhawk agent will turn over the information we seek. I leave the use of force to your discretion.", ["objectivesText"] = "Kill Sunhawk elves until you find the Sunhawk Missive , then return it to Vindicator Boros at Blood Watch. Progress: Back so soon? Have you found the missive?", ["rewardXP"] = 200, ["rewardItems"] = { 24399 }, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17684, ["x"] = 0.555, ["y"] = 0.5545 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 6, ["flags"] = 0 } } },
[9798] = { ["id"] = 9798, ["name"] = "Blood Elf Plans", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "These plans seem important. You should take them to Vindicator Aldar at the crash site.", ["objectivesText"] = "Take the Blood Elf Plans to Vindicator Aldar at the Crash Site in Ammen Vale . Progress: What have you got there?", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 24414 }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16535, ["x"] = 0.794, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.794, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 16, ["flags"] = 0 } }, ["startItems"] = { 24414 } },
[9799] = { ["id"] = 9799, ["name"] = "Botanical Legwork", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["description"] = "The Ammen Fields to the west are the primary breeding ground of the local lasher population. With the corruption of the water table from the nearby lake, Botanist Taerix is worried that the lashers will not be able to repopulate themselves once we've cleansed the lake. Go to the Ammen Fields and pick some of the corrupted flowers for me so that I might take a look at them and see what can be done. You should be able to identify them by their uncharacteristic red petals.", ["objectivesText"] = "Gather 3 Corrupted Flowers and return them to Apprentice Vishael at the Crash Site in Ammen Vale . Progress: Hello, <class>. Do you have those flowers yet?", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["rewardItems"] = { 24416 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 20233, ["x"] = 0.79, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 20233, ["x"] = 0.79, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.79, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 8, ["flags"] = 0 } } },
[9811] = { ["id"] = 9811, ["name"] = "Friend of the Sin'dorei", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 9811 }, ["series"] = { 9812, 9813 }, ["description"] = "This is the beginning of a new chapter in blood elf history, <name>. You've helped cement the bond between my race and yours, <race>. Take the traitor's head to Regent Lord Lor'themar Theron in Silvermoon City. He'll be eager to hear the news.", ["objectivesText"] = "Take Dar'Khan's Head to Lor'themar Theron in Silvermoon City. Progress: You seek audience with me, <class>? I do not recall hearing of an appointment.", ["rewardXP"] = 100, ["rewardItems"] = { 22653 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 16239, ["x"] = 0.55, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 16802, ["x"] = 0.618667, ["y"] = 0.301 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 95, 110 }, ["zone"] = { 3433 } }, ["questType"] = "standard" },
[9812] = { ["id"] = 9812, ["name"] = "Envoy to the Horde", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 9812 }, ["series"] = { 9811, 9813 }, ["description"] = "There were doubts about our capabilities among our potential new allies. Of what use could we be to them when perceived as unable to deal with our problems at home? This changes everything. No longer will our power be questioned. We'll be able to join the Horde as equals. Take this letter to Sylvanas, ruler of the Forsaken. She's already on our side but the news of Dar'Khan's death will be music to her ears. Prepare for a long trip, <name>. If all goes well she will send you to Orgrimmar.", ["objectivesText"] = "Bring the Letter from Lor'themar Theron to Lady Sylvanas Windrunner in Undercity , the Forsaken capital in Tirisfal Glades. Progress: I was told a visitor from Quel'Thalas was coming. I was expecting a blood elf, to tell you the truth. What news do you bring?", ["rewardXP"] = 100, ["rewardItems"] = { 23929 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 16802, ["x"] = 0.618667, ["y"] = 0.301 } }, ["ends"] = { { ["mapID"] = 90, ["npcID"] = 10181, ["x"] = 0.599429, ["y"] = 0.807143 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.618667, ["y"] = 0.301 }, ["mapCandidates"] = { ["npc"] = { 90, 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard" },
[9813] = { ["id"] = 9813, ["name"] = "Meeting the Orcs", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 1637, ["mapID"] = 90, ["storyline"] = { 9813 }, ["series"] = { 9811, 9812 }, ["description"] = "I haven't lost any love for my homeland or its people, as you know. I've fought tooth and nail for Silvermoon to be allowed a place beside Undercity and Orgrimmar at the negotiating table. This should silence any opposition. Take this letter to Saurfang in Orgrimmar . As leader of the orcs, he must have a say in accepting the sin'dorei's pledge. I've added my own seal to the letter as a personal endorsement. Go northwest of the city and board the zeppelin bound for Durotar at the tower.", ["objectivesText"] = "Lady Sylvanas Windrunner wants you to take the Letter Sealed by Sylvanas to High Overlord Saurfang in Orgrimmar , capital of Durotar. Progress: Yes, <class>?", ["rewardXP"] = 200, ["rewardItems"] = { 23930 }, ["starts"] = { { ["mapID"] = 90, ["npcID"] = 10181, ["x"] = 0.599429, ["y"] = 0.807143 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 14720, ["x"] = 0.485, ["y"] = 0.71 }, { ["mapID"] = 85, ["npcID"] = 39605, ["x"] = 0.4745, ["y"] = 0.5395 }, { ["mapID"] = 85, ["npcID"] = 86832, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 90, ["source"] = "quest_giver", ["x"] = 0.599429, ["y"] = 0.807143 }, ["mapCandidates"] = { ["npc"] = { 85, 90 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[10017] = { ["id"] = 10017, ["name"] = "Strained Supplies", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10017 }, ["description"] = "More and more refugees come through the gates of Shattrath City each day. Some have sustained such injuries, it's a real wonder they made it here. I can deal with most of the conventional injuries; my training as an Aldor healer has prepared me for that. Poison wounds are more problematic as my anti-venom supplies have begun to run low. Bring me venom sacs from the local dreadfang spiders so I can produce more antidotes. You'll find a pocket of the spiders in the southeastern region of Terokkar.", ["objectivesText"] = "Bring 8 Dreadfang Venom Sacs to Sha'nir in Shattrath City . Completing quests for the Aldor will cause your Scryers reputation level to decrease. Progress: Have you obtained the venom sacs, <name>? These refugees can't wait much longer.", ["rewardXP"] = 2090, ["rewardItems"] = { 25802 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18597, ["x"] = 0.564, ["y"] = 0.1565 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18597, ["x"] = 0.564, ["y"] = 0.1565 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.1565 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10019] = { ["id"] = 10019, ["name"] = "More Venom Sacs", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10019 }, ["objectivesText"] = "Progress: Many refugees still need treatment for their poisonous wounds. Have you brought more venom sacs for me to use, <name>?", ["rewardItems"] = { 25802 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18597, ["x"] = 0.564, ["y"] = 0.1565 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18597, ["x"] = 0.564, ["y"] = 0.1565 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.1565 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10020] = { ["id"] = 10020, ["name"] = "A Cure for Zahlia", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3519, ["mapID"] = 111, ["storyline"] = { 10020 }, ["description"] = "The woman to my right suffered a severe injury to the head. She survived, but lost her eyesight. A traditional cure used among my people requires the blood of a very old basilisk. Unfortunately, due to poaching from various groups, Terokkar basilisks don't tend to live very long. There is one basilisk whose name I've known since I was a youngling. It is known only as \"Stonegazer\" and it's rumored to live east of here, near the land's edge. Bring me its blood so that Zahlia may see once again.", ["objectivesText"] = "Bring Stonegazer's Blood to Sha'nir in Shattrath City . Completing quests for the Aldor will cause your Scryers reputation level to decrease. Progress: Have you obtained the blood, <name>? Without it, Zahlia may never see her son again.", ["rewardGold"] = 619600, ["rewardXP"] = 2615, ["rewardItems"] = { 25815 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18597, ["x"] = 0.564, ["y"] = 0.1565 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18597, ["x"] = 0.564, ["y"] = 0.1565 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.1565 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3519 } }, ["questType"] = "standard" },
[10021] = { ["id"] = 10021, ["name"] = "Restoring the Light", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3519, ["mapID"] = 111, ["storyline"] = { 10021 }, ["description"] = "Much of this region was inhabited by draenei long ago. We Aldor were charged with the safeguarding of our holy sites and altars. Many of them have since been destroyed or taken over by our enemies. To the east of here there is an arakkoa outpost. It was purposefully built on the location of three of our sacred altars. The arakkoa use their foul magic to warp and defile the innate power of our shrines. Take this to the arakkoa outpost and use it to cleanse the three altars.", ["objectivesText"] = "Ishanah wants you to go to the Arakkoa outpost east of Shattrath City and use the Blessed Vial to cleanse the Eastern Altar , the Western Altar and the Northern Altar . Completing quests for the Aldor will cause your Scryers reputation level to decrease. Progress: Have you completed your task, <name>?", ["rewardXP"] = 2090, ["rewardItems"] = { 25817 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18538, ["x"] = 0.335333, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18538, ["x"] = 0.335333, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.335333, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3519 } }, ["questType"] = "standard" },
[10024] = { ["id"] = 10024, ["name"] = "Voren'thal's Visions", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10024 }, ["description"] = "Our leader, Voren'thal the Seer, was once a close advisor to Kael'thas. His prophetic visions warned him that Kael's path would lead to the destruction of our race. The visions are usually vague and unfocused, but our alchemists have devised an elixir to help him focus his clairvoyance. Unfortunately, this elixir calls for a rare ingredient: basilisk eyes. My usual source, this pathetic ethereal, has failed me. Seek the dampscale basilisks in the rocky regions of Terokkar and bring me their eyes.", ["objectivesText"] = "Bring 8 Dampscale Basilisk Eyes to Arcanist Adyria in Shattrath City . Completing quests for the Scryers will cause your Aldor reputation level to decrease. Progress: Have you obtained the basilisk eyes for Voren'thal's elixir?", ["rewardXP"] = 2090, ["rewardItems"] = { 25744, 29739, 30810 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18596, ["x"] = 0.514, ["y"] = 0.217143 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18596, ["x"] = 0.514, ["y"] = 0.217143 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.217143 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10025] = { ["id"] = 10025, ["name"] = "More Basilisk Eyes", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10025 }, ["objectivesText"] = "Progress: It takes many basilisk eyes to make even a small dose of Voren'thal's elixir. Bringing me more would certainly incur the Scryers' favor.", ["rewardItems"] = { 25744 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18596, ["x"] = 0.514, ["y"] = 0.217143 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18596, ["x"] = 0.514, ["y"] = 0.217143 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.217143 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10063] = { ["id"] = 10063, ["name"] = "Explorers' League, Is That Something for Gnomes?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 10063 }, ["description"] = "Babysitting! Would you believe it? They pulled me out of a promising dig and sent me along with Captain Odesyus' expedition to babysit that little gnome! I'd never heard o' a gnome wanting to become a prospector before, so I asked. Seems we are takin' gnomes now, and this particular one has a fascination with murlocs! Well, he's gone off and set up shop in an old turtle shell on the northern shore of the island. Go and have a look if you don't believe me!", ["objectivesText"] = "Find Clopper Wizbang camped in an old turtle shell on the shore north of Blood Watch.", ["rewardXP"] = 50, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 18804, ["x"] = 0.562, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17421, ["x"] = 0.42, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[10064] = { ["id"] = 10064, ["name"] = "Talk to the Hand", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 10064 }, ["description"] = "The Hand of Argus has established a forward base at Vindicator's Rest, but they are sorely outnumbered by both the blood elves and mutated wildlife. Without backup, their outpost is in danger of falling, and we'd have no way to keep an eye on events near the Vector Coil. Report to Scout Jorli at Vindicator's Rest to the northwest and offer her your assistance, <name>.", ["objectivesText"] = "Report to Scout Jorli at Vindicator's Rest.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17423, ["x"] = 0.526, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17927, ["x"] = 0.302, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard" },
[10065] = { ["id"] = 10065, ["name"] = "Cutting a Path", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "During our mission to reconnoiter the Sunhawks and their portal, I sustained a serious wound. Scout Loryi has managed to staunch the bleeding and she's trying to figure out a way to evacuate me to Blood Watch. The problem is that we'd have to abandon our position here in order to guarantee a safe return. As soon as we leave this consecrated ground, we'll be set upon by ravagers. If you can clear some of the enraged ravagers , it might allow us to make the trip back safely.", ["objectivesText"] = "Kill 10 Enraged Ravagers and return to Scout Jorli at Vindicator's Rest.", ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17927, ["x"] = 0.302, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17927, ["x"] = 0.302, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 22, ["flags"] = 0 } } },
[10066] = { ["id"] = 10066, ["name"] = "Oh, the Tangled Webs They Weave", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "We don't dare abandon our post, or wander too far from Vindicator's Rest, <race>. The mutated creatures closest to the Vector Coil have been changed profoundly by energy leaking from the crystals. The mutated tanglers appear to have gained a certain degree of sentience. They've learned to create, set, and conceal vicious traps that can ensnare even the most careful warrior. We'll never be able to move against the Sunhawks if we're constantly forced to look underfoot. Attack the problem at its source, <name>.", ["objectivesText"] = "Kill 8 Mutated Tanglers and report to Vindicator Corin at Vindicator's Rest.", ["rewardGold"] = 280900, ["rewardXP"] = 250, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17986, ["x"] = 0.306, ["y"] = 0.465 }, { ["mapID"] = 106, ["npcID"] = 18020, ["x"] = 0.518, ["y"] = 0.518 }, { ["mapID"] = 106, ["npcID"] = 18024, ["x"] = 0.555, ["y"] = 0.523 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17986, ["x"] = 0.306, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 20, ["flags"] = 0 } } },
[10067] = { ["id"] = 10067, ["name"] = "Fouled Water Spirits", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3525, ["mapID"] = 106, ["storyline"] = { 9578, 9579, 9648, 9649, 9663, 9666, 9671, 9672, 9674, 9682, 9683, 9687, 9688, 9689, 9693, 9694, 9696, 9698, 9699, 9700, 9703, 9706, 9711, 9740, 9741, 9746, 9748, 9751, 9753, 9756, 9759, 9760, 9761, 9762, 9779, 10065, 10066, 10067 }, ["description"] = "Most of the creatures touched by the crystals' energy have been corrupted in the same ways: strange marks on their flesh, increased aggression, and small crystal shards in their bodies. However, the fouled water spirits north of here appear to be turning entirely to crystal. I've never seen anything react to the crystals this way before, when we explored the foul pool, they were particularly dangerous. We must get rid of them before the Sunhawks can exploit them as a new source of energy.", ["objectivesText"] = "Kill 6 Fouled Water Spirits and return to Vindicator Corin at Vindicator's Rest.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 106, ["npcID"] = 17986, ["x"] = 0.306, ["y"] = 0.465 }, { ["mapID"] = 106, ["npcID"] = 18020, ["x"] = 0.518, ["y"] = 0.518 }, { ["mapID"] = 106, ["npcID"] = 18024, ["x"] = 0.555, ["y"] = 0.523 } }, ["ends"] = { { ["mapID"] = 106, ["npcID"] = 17986, ["x"] = 0.306, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 106, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 106 }, ["zone"] = { 3525 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 106, ["questLines"] = { { ["id"] = 504, ["name"] = "Bloodmyst Isle", ["orderIndex"] = 21, ["flags"] = 0 } } },
[10106] = { ["id"] = 10106, ["name"] = "Hellfire Fortifications", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 10106 }, ["description"] = "The Hellfire Citadel wages constant battles with our forces. We are holding our own so far, but we can't yet launch a real offensive against them. To do that, we need forward staging areas. Our scouts identified three fortifications near Hellfire Citadel. We want you to help secure these forts. Capture each fort, and then report back to me. May fortune shine upon you in the conflicts ahead, <name>, for you will no doubt clash with Horde forces eager to gain these same fortifications.", ["objectivesText"] = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula .", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 24579, 24581 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 18266, ["x"] = 0.564, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 18266, ["x"] = 0.564, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "pvp" },
[10110] = { ["id"] = 10110, ["name"] = "Hellfire Fortifications", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 10110 }, ["description"] = "The fel orcs of Hellfire Citadel must be scoured from our birthland! To attack them, we must first secure forward staging points near the Citadel. Our outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them! We want you to stop the Alliance and capture these forts. Aid in the capture of each fort and then return to me. For the Horde!", ["objectivesText"] = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 24579, 24581 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 18267, ["x"] = 0.558, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 18267, ["x"] = 0.558, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "pvp" },
[10180] = { ["id"] = 10180, ["name"] = "Can't Stay Away", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10180 }, ["description"] = "I tried to persuade Isfar to remain here, in the safety of Shattrath, but he would have none of it. Instead, he's decided to venture out to Auchindoun again on his own. He was lucky enough to escape the Sethekk Halls once, but if they discover him, there won't be a second time. I admire his desire to free his sister, but he's not going to be able to do it without help. Find Isfar and have a word with him, <name>. If you can't persuade him to come back, perhaps you could help him rescue Lakka?", ["objectivesText"] = "Speak with Isfar , who can be found just inside the Sethekk Halls in Auchindoun.", ["rewardXP"] = 525, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 19045, ["x"] = 0.522571, ["y"] = 0.226286 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.522571, ["y"] = 0.226286 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10227] = { ["id"] = 10227, ["name"] = "I See Dead Draenei", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 10227 }, ["series"] = { 10228, 10231, 10251, 10252, 10253 }, ["description"] = "I see dead draenei. They're all around us. Bah, nobody believes me because I'm a child. Not even my own mommy believes me. < Ha'lei points to Ramdor.> He believes me, though... He sees them too. Boy does he get angry about it! It's kind of funny. I see ghosts and people just smile and pat me on the head, trying to placate me. Ramdor sees ghosts and people label him as crazy. I sure hope I never grow up! You should probably talk to Ramdor before you go inside. He was once a death priest.", ["objectivesText"] = "Speak to Ramdor the Mad , standing on the bone pile outside of the Auchenai Crypts.", ["rewardXP"] = 260, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 19697, ["x"] = 0.35, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 19417, ["x"] = 0.352, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "dungeon" },
[10228] = { ["id"] = 10228, ["name"] = "Ezekiel", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 10228 }, ["series"] = { 10227, 10231, 10251, 10252, 10253 }, ["description"] = "I believe that the dead, which we have been caring for these last 500 odd years, should be left alone. Maladaar has other plans. He has retreated to the Crypt of Remembrance to start his experiments... Necromancy. I hope you weren't thinking about going in there... Not before helping me out so that these damned spirits will finally leave me alone. I know where they keep their treasures, <race>. Got your attention, eh? Bring me the book of the dead, held by the Aldor, Ezekiel of Shattrath.", ["objectivesText"] = "Find and speak with Ezekiel of Shattrath in Shattrath City.", ["rewardXP"] = 525, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 19417, ["x"] = 0.352, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 19715, ["x"] = 0.555099, ["y"] = 0.427408 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.352, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 108, 111 }, ["zone"] = { 3519 } }, ["questType"] = "dungeon" },
[10231] = { ["id"] = 10231, ["name"] = "What Book? I Don't See Any Book.", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10231 }, ["series"] = { 10227, 10228, 10251, 10252, 10253 }, ["description"] = "Ramdor? Hrm, let me think... Ramdor... Oh yes, the death priest. What does he want with the book? Well it doesn't matter. Yes I lied to you and no I don't have the book. Not anymore, anyway. It was stolen. Probably by one of those filthy refugees. Besides, Auchindoun is now defunct. We have no use for the book. If you find it, you can keep it. Like I said, I saw some of those ruffians snooping around the terrace last week. Start your search with them. They're probably playing dice in the slums.", ["objectivesText"] = "Ezekiel said the book has been stolen. Your best bet is to find the Ruffians and see if they have any information. Progress: Whaddya want?", ["rewardXP"] = 2090, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 19715, ["x"] = 0.555099, ["y"] = 0.427408 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 19720, ["x"] = 0.46575, ["y"] = 0.39475 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.555099, ["y"] = 0.427408 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon" },
[10251] = { ["id"] = 10251, ["name"] = "The Master's Grand Design?", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10251 }, ["series"] = { 10227, 10228, 10231, 10252, 10253 }, ["description"] = "A couple of draenei paid us a visit last night. They'd somehow learned that we had the book in our possession and made a very generous offer to \"take it off our hands.\" We didn't ask them what they wanted with the book but the young one kept talking about \"the master's grand design,\" whatever that means. Look, I don't ask questions when money is in play. They gave us a lot of gold and we gave them the book. He said that they lived in Nagrand - in the old Abandoned Armory, north of Telaar.", ["objectivesText"] = "Find Nitrin the Learned at the Abandoned Armory in Nagrand.", ["rewardXP"] = 1045, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 19720, ["x"] = 0.46575, ["y"] = 0.39475 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 19844, ["x"] = 0.518, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.46575, ["y"] = 0.39475 }, ["mapCandidates"] = { ["npc"] = { 107, 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon" },
[10252] = { ["id"] = 10252, ["name"] = "Vision of the Dead", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 10252 }, ["series"] = { 10227, 10228, 10231, 10251, 10253 }, ["description"] = "It has already begun. Levixus stands atop the ruins of Auchindoun and reads from the book of the dead. He calls the dead out by name and, through demonic ritual, binds the tortured souls to his will. He will raise all of Auchindoun if given the chance! But... you must first prepare. You cannot do battle with that which you cannot see. <Nitrin hands you a parchment.> Bring me the items I require to brew the tincture. It will open your mind and allow you to see into the spirit world.", ["objectivesText"] = "Nitrin at the Abandoned Armory in Nagrand wants you to bring him 1 Mountain Gronn Eyeball , 1 Flawless Greater Windroc Beak , and 1 Aged Clefthoof Blubber . Progress: Levixus's army grows in size and power with each second that passes. You must hurry.", ["rewardXP"] = 2090, ["rewardItems"] = { 28664, 28665, 28667, 28668 }, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 19844, ["x"] = 0.518, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 19844, ["x"] = 0.518, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "dungeon" },
[10253] = { ["id"] = 10253, ["name"] = "Levixus the Soul Caller", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3519, ["mapID"] = 107, ["storyline"] = { 10253 }, ["series"] = { 10227, 10228, 10231, 10251, 10252 }, ["description"] = "Go now, <name>. You will find Levixus on the uppermost ruins of Auchindoun. Enter there from the southern reaches of the Bone Wastes. He stands amidst a storm of souls... Destroy him and take the book of the dead . Once you have the cursed book in your possession, destroy it! Destroy it so that such an atrocity can never again be made possible.", ["objectivesText"] = "Destroy Levixus and take the Book of the Dead from his possession. Deliver the Book of the Dead to Ramdor the Mad standing outside the Auchenai Crypt entrance of Auchindoun. You had a deal, remember? Progress: Who are you and what do you want? Oh... It's YOU.", ["rewardXP"] = 3135, ["rewardItems"] = { 3775, 18859, 21991, 22829, 28041, 28677, 29312, 29313, 29314, 29315, 37865 }, ["starts"] = { { ["mapID"] = 107, ["npcID"] = 19844, ["x"] = 0.518, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 19417, ["x"] = 0.352, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 107, 108 }, ["zone"] = { 3519 } }, ["questType"] = "dungeon" },
[10302] = { ["id"] = 10302, ["name"] = "Volatile Mutations", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9293, 9371 }, ["description"] = "The irradiated power cores from the Exodar have been wreaking havoc on the environment here. The most obvious effect has been the appearance of the strange creatures that seem to have sprung up near them. There may be something we can do to help them, but now, their sheer numbers are becoming too much for us to handle. I'd like you to go out and cull their numbers somewhat, and perhaps I'll have another idea after giving it some thought.", ["objectivesText"] = "Kill 8 Volatile Mutations , then return to Botanist Taerix at the Crash Site in Ammen Vale . Progress: I am working on a solution I think may be effective with the strange creatures. I just need more time.", ["rewardGold"] = 53500, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16514, ["x"] = 0.792, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16514, ["x"] = 0.792, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 6, ["flags"] = 0 } } },
[10303] = { ["id"] = 10303, ["name"] = "The Blood Elves", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9309, 9311 }, ["description"] = "You must eliminate... the blood elf... threat. Find out... what they're... up to! They're on the... ridge behind me.", ["objectivesText"] = "Kill 10 Blood Elf Scouts then return to Tolaan in the Shadow Ridge of Ammen Vale . Progress: There are too many of them... We must whittle them down or else the survivors will have no chance against them.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 24133, 24134, 24135, 67161, 67178, 67195, 67211, 131820, 157021 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16546, ["x"] = 0.72, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16546, ["x"] = 0.72, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 14, ["flags"] = 0 } } },
[10304] = { ["id"] = 10304, ["name"] = "Vindicator Aldar", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9303 }, ["description"] = "With your help, we were able to find a solution to our problems faster than I could have hoped. I don't have any other work for you to do. My apprentices and I can handle the rest. You should go speak with Vindicator Aldar on the other side of the ship.", ["objectivesText"] = "Speak with Vindicator Aldar at the Crash Site in Ammen Vale .", ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16514, ["x"] = 0.792, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16535, ["x"] = 0.794, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 10, ["flags"] = 0 } } },
[10324] = { ["id"] = 10324, ["name"] = "The Great Moongraze Hunt", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 9314, 9452, 9453, 9454, 9463, 9473, 9505, 9506, 9512, 9513, 9523, 9527, 9530, 9531, 9537, 9538, 9539, 9540, 9541, 9542, 9544, 9559, 9560, 9562, 9565, 9566, 9570, 9571, 9573, 9602, 9622, 10324 }, ["series"] = { 9454 }, ["description"] = "Well done, <name>! Well done! Now that you've cut your teeth with the moongraze stag, it's time you graduated to more formidable prey. Do not allow the casual disinterest of the moongraze bucks to fool you: when provoked, they are a fearsome foe. You'll find the bucks north of here. Good hunting.", ["objectivesText"] = "Bring 6 Moongraze Buck Hides to Acteon at Azure Watch. Progress: The buck hides are rugged and strong, making for very tough flesh - almost inedible, but we can use them for other purposes.", ["rewardGold"] = 210675, ["rewardXP"] = 150, ["rewardItems"] = { 23677, 24103, 24104, 24105, 27686, 131274 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17110, ["x"] = 0.498, ["y"] = 0.518 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17110, ["x"] = 0.498, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 97, ["questLines"] = { { ["id"] = 570, ["name"] = "Azuremyst Isle", ["orderIndex"] = 4, ["flags"] = 0 } } },
[10325] = { ["id"] = 10325, ["name"] = "Marks of Kil'jaeden", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3523, ["mapID"] = 109, ["storyline"] = { 10325 }, ["series"] = { 10326, 10327 }, ["description"] = "As you probably know, <name>, the Aldor are keepers of the Light and servants of the naaru. Diametrically opposed to us are the agents of the Burning Legion - demons bent on the destruction of worlds and the corruption of the innocent. If you wish to prove yourself to the Aldor, bring me the insignias of low-ranking Legion and their Shadow Council followers. We know of a Shadow Council hideout in the Bone Wastes and there are many Legion outposts in Nagrand and the Blade's Edge Mountains.", ["objectivesText"] = "Bring 10 Marks of Kil'jaeden to Adyen the Lightwarden in Shattrath City . Completing quests for the Aldor will cause your Scryers reputation level to decrease. Progress: Do you bear any of our enemies' insignias, <name>?", ["rewardXP"] = 2090, ["rewardItems"] = { 29425 }, ["starts"] = { { ["mapID"] = 109, ["npcID"] = 18537, ["x"] = 0.338667, ["y"] = 0.146333 } }, ["ends"] = { { ["mapID"] = 109, ["npcID"] = 18537, ["x"] = 0.338667, ["y"] = 0.146333 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.338667, ["y"] = 0.146333 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 3523 } }, ["questType"] = "standard" },
[10326] = { ["id"] = 10326, ["name"] = "More Marks of Kil'jaeden", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3523, ["mapID"] = 109, ["storyline"] = { 10326 }, ["series"] = { 10325, 10327 }, ["objectivesText"] = "Progress: Do you bear more of our enemies' insignias, <class>? The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", ["rewardItems"] = { 29425 }, ["starts"] = { { ["mapID"] = 109, ["npcID"] = 18537, ["x"] = 0.338667, ["y"] = 0.146333 } }, ["ends"] = { { ["mapID"] = 109, ["npcID"] = 18537, ["x"] = 0.338667, ["y"] = 0.146333 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.338667, ["y"] = 0.146333 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 3523 } }, ["questType"] = "standard" },
[10327] = { ["id"] = 10327, ["name"] = "Single Mark of Kil'jaeden", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3523, ["mapID"] = 109, ["storyline"] = { 10327 }, ["series"] = { 10325, 10326 }, ["objectivesText"] = "Progress: I'll take any leftover marks you might have. Do not worry; your actions will be duly noted.", ["rewardItems"] = { 29425 }, ["starts"] = { { ["mapID"] = 109, ["npcID"] = 18537, ["x"] = 0.338667, ["y"] = 0.146333 } }, ["ends"] = { { ["mapID"] = 109, ["npcID"] = 18537, ["x"] = 0.338667, ["y"] = 0.146333 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.338667, ["y"] = 0.146333 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 3523 } }, ["questType"] = "standard" },
[10346] = { ["id"] = 10346, ["name"] = "Return to the Abyssal Shelf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 10346 }, ["description"] = "<name>, you've proven yourself as a capable gryphon rider, and we could use you on more sorties over the Abyssal Shelf. What say you, <class>? Do you want some more flight time?", ["objectivesText"] = "Gryphoneer Windbellow at Shatter Point in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons , 5 Mo'arg Overseers and 5 Fel Cannons . Progress: There are still plenty of targets on the Abyssal Shelf, <name>. Grab a gryphon when you're ready for another run.", ["rewardItems"] = { 28132 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 20235, ["x"] = 0.782, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 20235, ["x"] = 0.782, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "standard" },
[10347] = { ["id"] = 10347, ["name"] = "Return to the Abyssal Shelf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 10347 }, ["description"] = "<name>, are you ready for another sortie over the Abyssal Shelf? I fear that, if we do not maintain pressure on the Legion forces there and allow them to strengthen their hold, then we may suffer a large demon attack from the north. What say you, <class>? Do you want to take another windrider and hammer the Abyssal Shelf one more time?", ["objectivesText"] = "Wing Commander Brack at Reaver's Fall in Hellfire Peninsula has asked that you destroy 20 Gan'arg Peons , 5 Mo'arg Overseers and 5 Fel Cannons . Progress: The Legion must not think they are safe high atop the Abyssal Shelf. We must hit them repeatably!", ["rewardItems"] = { 28132 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 19401, ["x"] = 0.66, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 19401, ["x"] = 0.66, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "standard" },
[10350] = { ["id"] = 10350, ["name"] = "Behomat", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredClasses"] = { 1 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 10350 }, ["series"] = { 9582 }, ["description"] = "While you have learned many hard lessons from me during our time together, it is time that I entrusted you to wiser hands. Behomat , who trained me when I was as green as grass, will be your new teacher. I have told him that you will be seeking him out, and he is expecting you. You will find him at the center of the Warriors' Terrace, at the highest point of the Traders Tier of the Exodar.", ["objectivesText"] = "Speak with Behomat at the Traders Tier of the Exodar.", ["rewardXP"] = 100, ["rewardItems"] = { 23423, 23429, 23430, 23431 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17480, ["x"] = 0.499, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 17120, ["x"] = 0.555, ["y"] = 0.819667 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.499, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 97, 103 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[10412] = { ["id"] = 10412, ["name"] = "Firewing Signets", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10412 }, ["series"] = { 10414, 10415 }, ["description"] = "It is no secret that Kael'thas Sunstrider perceives us as a great threat. Let's face it - not many sin'dorei, fresh from Silvermoon, are willing to join the sort of company that Kael keeps. It's also no secret that this is not just a war of words. Scryers and the armies that serve Kael'thas attack each other on sight. The only way to prove you're with us, <name>, is to do your share of fighting. Kael's lower ranking followers wear Firewing signets to indicate their rank. Bring them to me.", ["objectivesText"] = "Magistrix Fyalenn in Shattrath City wants you to bring her 10 Firewing Signets . Performing quests for the Scryers will cause your Aldor reputation level to decrease. Progress: Go on, <name>. Speak.", ["rewardXP"] = 2090, ["rewardItems"] = { 29426 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18531, ["x"] = 0.429714, ["y"] = 0.745429 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18531, ["x"] = 0.429714, ["y"] = 0.745429 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.429714, ["y"] = 0.745429 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10414] = { ["id"] = 10414, ["name"] = "Single Firewing Signet", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10414 }, ["series"] = { 10412, 10415 }, ["objectivesText"] = "Progress: Even the smallest contribution to our cause is noted, <name>. Our enemies are many, but we shall prevail!", ["rewardItems"] = { 29426 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18531, ["x"] = 0.429714, ["y"] = 0.745429 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18531, ["x"] = 0.429714, ["y"] = 0.745429 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.429714, ["y"] = 0.745429 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10415] = { ["id"] = 10415, ["name"] = "More Firewing Signets", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10415 }, ["series"] = { 10412, 10414 }, ["objectivesText"] = "Progress: What have you done for us lately, <name>? The war against Kael'thas is not going to fight itself, you know?", ["rewardItems"] = { 29426 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18531, ["x"] = 0.429714, ["y"] = 0.745429 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18531, ["x"] = 0.429714, ["y"] = 0.745429 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.429714, ["y"] = 0.745429 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10416] = { ["id"] = 10416, ["name"] = "Synthesis of Power", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10416 }, ["series"] = { 10419 }, ["description"] = "Arcane tomes are not ordinary books that happen to deal with arcane matters. There is intrinsic power in them - a power I've learned to synthesize into a single arcane rune . Should you find an arcane tome in your travels I will give you one such rune. Only the most powerful wielders of magic carry the books I need. In Outland this usually means Kael's blood elves - but you'd be surprised by where such tomes often turn up.", ["objectivesText"] = "Voren'thal the Seer in Shattrath City wants you to obtain an Arcane Tome . Performing quests for the Scryers will cause your Aldor reputation to decrease. Progress: Have you obtained an arcane tome yet, <name>?", ["rewardXP"] = 2615, ["rewardItems"] = { 29736, 29739 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18530, ["x"] = 0.3885, ["y"] = 0.7725 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18530, ["x"] = 0.3885, ["y"] = 0.7725 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.3885, ["y"] = 0.7725 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10419] = { ["id"] = 10419, ["name"] = "Arcane Tomes", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10419 }, ["series"] = { 10416 }, ["objectivesText"] = "Progress: Have you obtained any more arcane tomes , <name>?", ["rewardItems"] = { 29736, 29739 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18530, ["x"] = 0.3885, ["y"] = 0.7725 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18530, ["x"] = 0.3885, ["y"] = 0.7725 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.3885, ["y"] = 0.7725 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10420] = { ["id"] = 10420, ["name"] = "A Cleansing Light", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10420 }, ["series"] = { 10421 }, ["description"] = "This temple is one of the holiest places in all of Outland. The power of the Light here is so strong, that even items with the strongest fel taint can be cleansed of a worldly item. Should you run into any fel armaments in your confrontations with demonic enemies, bring them to me and I will demonstrate the cleansing power of the Light.", ["objectivesText"] = "Bring a Fel Armament to Ishanah in Shattrath City . Completing quests for the Aldor will cause your Scryers reputation to decrease. Progress: Have you obtained any fel armaments yet, <name>?", ["rewardXP"] = 2615, ["rewardItems"] = { 29735, 29740 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18538, ["x"] = 0.335333, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18538, ["x"] = 0.335333, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.335333, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10421] = { ["id"] = 10421, ["name"] = "Fel Armaments", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10421 }, ["series"] = { 10420 }, ["objectivesText"] = "Progress: Have you run into any fel armaments lately? Let the Light do its work, <name>. Do not allow these foul objects to remain in this world.", ["rewardItems"] = { 29735, 29740 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18538, ["x"] = 0.335333, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18538, ["x"] = 0.335333, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.335333, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10428] = { ["id"] = 10428, ["name"] = "The Missing Fisherman", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3524, ["mapID"] = 97, ["storyline"] = { 10428 }, ["series"] = { 9527 }, ["description"] = "In the fevered dreams of our injured guest, she spoke of a fisherman, Cowlen , who was in some distress at Silvermyst Isle, to the southwest, off the coast of Azuremyst. With all that has been happening, no one has had the opportunity to look into it, but I do feel a bit of worry. Perhaps there's something you can do, <name>?", ["objectivesText"] = "Find Cowlen at the southeast docks of Silvermyst Isle off the coast of Azuremyst.", ["rewardXP"] = 100, ["rewardItems"] = { 124669, 138201, 138777, 138811, 140261, 142398 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 17488, ["x"] = 0.488, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 17311, ["x"] = 0.165, ["y"] = 0.944 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
