[10653] = { ["id"] = 10653, ["name"] = "Marks of Sargeras", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3523, ["mapID"] = 109, ["storyline"] = { 10653 }, ["series"] = { 10654, 10655 }, ["description"] = "By now it should be clear to you why we oppose the Burning Legion and those who serve them. If you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers. The highest-ranking Legion can be found in Netherstorm and Shadowmoon Valley.", ["objectivesText"] = "Bring 10 Marks of Sargeras to Adyen the Lightwarden in Shattrath City . Completing quests for the Aldor will cause your Scryers reputation level to decrease. Progress: Do you bear any of our enemies' insignias, <name>?", ["rewardXP"] = 2090, ["rewardItems"] = { 30809 }, ["starts"] = { { ["mapID"] = 109, ["npcID"] = 18537, ["x"] = 0.338667, ["y"] = 0.146333 } }, ["ends"] = { { ["mapID"] = 109, ["npcID"] = 18537, ["x"] = 0.338667, ["y"] = 0.146333 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.338667, ["y"] = 0.146333 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 3523 } }, ["questType"] = "standard" },
