[10656] = { ["id"] = 10656, ["name"] = "Sunfury Signets", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10656 }, ["series"] = { 10658, 10659 }, ["description"] = "As you might know, the Scryers and the armies of Kael'thas are at war. Kael sees us as a threat to his influence over other blood elves and has tried to crush us time and again. If you wish to aid us in our battle against Kael'thas, there are plenty of targets for you to go after. Kael's highest ranking soldiers wear Sunfury signets to mark their ranks. You will find them all over Netherstorm and Shadowmoon Valley.", ["objectivesText"] = "Magistrix Fyalenn in Shattrath City wants you to bring her 10 Sunfury Signets . Performing quests for the Scryers will cause you Aldor reputation level to decrease. Progress: Go on, <name>. Speak.", ["rewardXP"] = 2090, ["rewardItems"] = { 30810 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18531, ["x"] = 0.429714, ["y"] = 0.745429 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18531, ["x"] = 0.429714, ["y"] = 0.745429 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.429714, ["y"] = 0.745429 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
