[10939] = { ["id"] = 10939, ["name"] = "Darkmoon Storms Deck", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 2, ["zoneID"] = 5861, ["storyline"] = { 10939 }, ["description"] = "Now that you have gathered all of the Storms cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Storms Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a deck of Storms! Congratulations!", ["rewardItems"] = { 31857, 31891 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["startItems"] = { 31891 } },
