[10941] = { ["id"] = 10941, ["name"] = "Darkmoon Lunacy Deck", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 2, ["zoneID"] = 5861, ["storyline"] = { 10941 }, ["description"] = "Now that you have gathered all of the Lunacy cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Lunacy Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a deck of Lunacy! Congratulations!", ["rewardItems"] = { 31859, 31914 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["startItems"] = { 31914 } },
[10942] = { ["id"] = 10942, ["name"] = "Children's Week", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10942 }, ["description"] = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while. Take this whistle. With it, you will be able to call for the child that you have agreed to sponsor. It will only last for a limited time - not much longer than Children's Week itself, in fact. Please, <name>, call upon your orphan. I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", ["objectivesText"] = "Use the Blood Elf Orphan Whistle to call for the ward that you will be looking after during Children's Week. Provided item:", ["rewardItems"] = { 31880, 31951, 32616, 32617, 32622, 69648, 116202 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 22819, ["x"] = 0.747, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.747, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10943] = { ["id"] = 10943, ["name"] = "Children's Week", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10943 }, ["description"] = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while. Take this whistle. With it, you will be able to call for the child that you have agreed to sponsor. It will only last for a limited time - not much longer than Children's Week itself, in fact. Please, <name>, call upon your orphan. I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", ["objectivesText"] = "Use the Draenei Orphan Whistle to call for the ward that you will be looking after during Children's Week. Provided item:", ["rewardItems"] = { 31881 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 22819, ["x"] = 0.747, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.747, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10945] = { ["id"] = 10945, ["name"] = "Hch'uu and the Mushroom People", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 10945 }, ["description"] = "I had a friend named Hch'uu . She told me that she ended up in the orphanage because she had to run away from an evil fungal giant and got lost. We had great fun until her people came and took her away last year. I think she said she was going to live at a place called Sporeggar. I'd like to go to see her and have a look at her mushroom village. The orphan matron told me that it is on the west side of Zangarmarsh, between the Sporewind and Marshlight lakes. Can we go? Can we go? Please?!", ["objectivesText"] = "Take your orphan, Salandria, to Sporeggar in Zangarmarsh. Make sure to call for her if she is not present when you arrive. Then, speak with Hch'uu . Progress: You're the adventurer that brought her here?", ["rewardXP"] = 1415, ["rewardItems"] = { 31880, 31951, 32616, 32617, 32622, 69648, 116202 }, ["ends"] = { { ["mapID"] = 102, ["npcID"] = 22823, ["x"] = 0.192, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.192, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "standard" },
[10946] = { ["id"] = 10946, ["name"] = "Ruse of the Ashtongue", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3520, ["mapID"] = 104, ["storyline"] = { 10946 }, ["series"] = { 10944, 10947, 10948, 10949, 10957, 10958, 10959, 10985, 13429 }, ["description"] = "Olum's sacrifice was tremendous. I would never have asked him to give up his life myself. But it is done. If we're to lure Illidan back into a false sense of security, we need to do his bidding - at least for now. I command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted. You are to perform the deed that Illidan demands. Take this cowl; it is magical in nature. You will appear to be one of my men to any who see you slaying Kael's phoenix, Al'ar.", ["objectivesText"] = "Travel into Tempest Keep and slay Al'ar while wearing the Ashtongue Cowl . Return to Akama in Shadowmoon Valley once you've completed this task. Progress: Is the deed done, <name>? Illidan is not a patient master!", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["rewardItems"] = { 6948, 31946, 32757 }, ["starts"] = { { ["mapID"] = 104, ["npcID"] = 21700, ["x"] = 0.58, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 104, ["npcID"] = 21700, ["x"] = 0.58, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 104, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 104 }, ["zone"] = { 3520 } }, ["questType"] = "raid" },
[10947] = { ["id"] = 10947, ["name"] = "An Artifact From the Past", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3520, ["mapID"] = 104, ["storyline"] = { 10947 }, ["series"] = { 10944, 10946, 10948, 10949, 10957, 10958, 10959, 10985, 13429 }, ["description"] = "Illidan's attention is now on Kael'thas, thanks to you. The time has come to make our move. I've had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill. Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal. There might be a way to retrieve this artifact, however. Legend speaks of a place in Azeroth guarded by bronze dragons... a place where past and present meet. It is there you will find what we seek.", ["objectivesText"] = "Go to the Caverns of Time in Tanaris and gain access to the Battle of Mount Hyjal. Once inside, defeat Rage Winterchill and bring the Time-Phased Phylactery to Akama in Shadowmoon Valley. Progress: Have you retrieved the phylactery yet, <name>?", ["rewardXP"] = 6175, ["rewardItems"] = { 6948, 32459, 32757, 69777 }, ["starts"] = { { ["mapID"] = 104, ["npcID"] = 21700, ["x"] = 0.58, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 104, ["npcID"] = 21700, ["x"] = 0.58, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 104, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 104 }, ["zone"] = { 3520 } }, ["questType"] = "raid" },
[10948] = { ["id"] = 10948, ["name"] = "The Hostage Soul", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3520, ["mapID"] = 104, ["storyline"] = { 10948 }, ["series"] = { 10944, 10946, 10947, 10949, 10957, 10958, 10959, 10985, 13429 }, ["description"] = "You might wonder why I go to such lengths to hide my intentions. Why not throw my lot in openly with the naaru? My very essence - my soul - is held prisoner inside the Black Temple. Illidan could destroy me any moment... until now! This phylactery will allow me to regain control of my soul. The time has come, <name>. I'll lead Maiev and my Deathsworn to Illidan's doorstep. Speak to A'dal and and tell him of our plan. If we strike together we'll break through Illidan's defenses.", ["objectivesText"] = "Travel to Shattrath City to tell A'dal about Akama 's request.", ["rewardXP"] = 2060, ["rewardItems"] = { 32757 }, ["starts"] = { { ["mapID"] = 104, ["npcID"] = 21700, ["x"] = 0.58, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 104, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 104, 111 }, ["zone"] = { 3520 } }, ["questType"] = "standard" },
[10950] = { ["id"] = 10950, ["name"] = "Auchindoun and the Ring of Observance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3519, ["storyline"] = { 10950 }, ["description"] = "One of the priests that comes to visit told a story about a place nearby. It's called Auchindoun, and it's supposed to be very important to the draenei. He said it used to be the place where the bodies of the draenei were taken when they died. But some time ago, something bad blew it up. I'd like to see its Ring of Observance. The orphan matron told me that it is in the middle of the Bone Wastes, on the south side of the Terokkar Forest. Please, <Mr./Miss> <name>, can we go?", ["objectivesText"] = "Take your orphan, Dornaa, to the Meeting Stone at the Ring of Observance in the middle of Auchindoun. Auchindoun, in turn, is in the middle of Terokkar Forest's Bone Wastes. Make sure to call for her if she is not present when you arrive. Progress: Are we there yet? Just protect me from all the spooky ghosts, okay?", ["rewardXP"] = 1415, ["rewardItems"] = { 17020, 17029, 17033, 31881 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3519 } }, ["questType"] = "standard" },
[10951] = { ["id"] = 10951, ["name"] = "A Trip to the Dark Portal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 4, ["storyline"] = { 10951 }, ["description"] = "How can we look at all of these interesting places and not see the Dark Portal?! The grown-ups are always trying to tell us scary stories about it and how it's so dangerous, with lots of demons, and stuff. <Salandria rolls her eyes.> But you're here, so it can't be too bad, right? I want to see for myself. You remember where it is on the east edge of Hellfire Peninsula?", ["objectivesText"] = "Take your orphan, Salandria, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive. Progress: This is soooo exciting!", ["rewardXP"] = 1415, ["rewardItems"] = { 31880, 31951, 32616, 32617, 32622, 69648, 116202 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4 } }, ["questType"] = "standard" },
[10952] = { ["id"] = 10952, ["name"] = "A Trip to the Dark Portal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 4, ["storyline"] = { 10952 }, ["description"] = "There's one place that if we don't go anywhere else, we have to go to: the Dark Portal! The orphan matrons are always trying to scare us with stories about how dangerous it is, with lots of demons, and people like you coming through it. <Dornaa rolls her eyes.> But you're here, and nice, so it can't be too bad, right? I want to see it for myself. You remember where it is on the eastern edge of Hellfire Peninsula?", ["objectivesText"] = "Take your orphan, Dornaa, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive. Progress: What do you know about the Dark Portal?", ["rewardXP"] = 1415, ["rewardItems"] = { 31881 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4 } }, ["questType"] = "standard" },
[10953] = { ["id"] = 10953, ["name"] = "Visit the Throne of the Elements", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 10953 }, ["description"] = "Have you heard of the Throne of the Elements? It's supposed to be this place in Nagrand where there are these powerful elementals. One day soon, I'm going to be a powerful mage, or maybe a warlock. I'm gonna have to learn about some of the elemental forces! Do you think maybe that we could go there? <Salandria looks at you slyly.> Ya know, it would be educational to go there. It's supposedly just north of Garadar, on the other side of Skysong Lake.", ["objectivesText"] = "Take your orphan, Salandria, to the Throne of the Elements in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Elementalist Sharvak . Progress: The Earthen Ring sees you, <class>.", ["rewardXP"] = 1415, ["rewardItems"] = { 31880, 31951, 32616, 32617, 32622, 69648, 116202 }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 18072, ["x"] = 0.606, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "standard" },
[10954] = { ["id"] = 10954, ["name"] = "Jheel is at Aeris Landing!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3518, ["mapID"] = 107, ["storyline"] = { 10954 }, ["description"] = "I miss my brother, Jheel . He's a couple of years older than me, so they let him start an apprenticeship with the ethereal in Nagrand. It sure would be nice to go visit him. He loves geology and stuff, so I bet he's having a great time. The orphan matron told me that he's training at a place called Aeris Landing in Nagrand. It's supposed to be along the road, far to the west of Telaar, and northwest of the great mountain, Oshu'gun.", ["objectivesText"] = "Take your orphan, Dornaa, to Aeris Landing in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Jheel . Progress: Did you bring her here?", ["rewardXP"] = 1415, ["rewardItems"] = { 31881 }, ["ends"] = { { ["mapID"] = 107, ["npcID"] = 22836, ["x"] = 0.314, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 107, ["source"] = "quest_giver", ["x"] = 0.314, ["y"] = 0.575 }, ["mapCandidates"] = { ["npc"] = { 107 }, ["zone"] = { 3518 } }, ["questType"] = "standard" },
[10956] = { ["id"] = 10956, ["name"] = "The Seat of the Naaru", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 10956 }, ["series"] = { 10968 }, ["description"] = "Do you know anything about the naaru? They're these angelic beings that have been helping the draenei for a really long time. I've seen a bunch around Shattrath. They say that one naaru, O'ros , was with the Exodar when it traveled to your homeworld. I should like to see for myself. Can you take me there? I bet we could get there fast by using one of the portals inside the Temple of the Moon in Darnassus! When we get there, if you get lost, we could always just look at your map.", ["objectivesText"] = "Take your orphan, Dornaa, to stand before O'ros at the bottom of the Seat of the Naaru inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive. Remember that you can use your map inside the city. Progress: I have been expecting you.", ["rewardXP"] = 710, ["rewardItems"] = { 31881 }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 17538, ["x"] = 0.5745, ["y"] = 0.4135 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.5745, ["y"] = 0.4135 }, ["mapCandidates"] = { ["npc"] = { 103 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[10957] = { ["id"] = 10957, ["name"] = "Redemption of the Ashtongue", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 3959, ["storyline"] = { 10957 }, ["series"] = { 10944, 10946, 10947, 10948, 10949, 10958, 10959, 10985, 13429 }, ["description"] = "When Illidan obtained the Broken's allegiance, Akama was our wisest. He knew that openly opposing the Betrayer would lead to the extinction of our race. Instead he has plotted and schemed for this very moment under utmost secrecy. Failure would be catastrophic... not just for Akama, not just for the Broken, but for all of Outland. No one this close to Illidan has ever been able to deliver such a terrible blow to him. Help Akama free his soul and he will grant you access to Illidan's sanctum.", ["objectivesText"] = "Help Akama wrest control back of his soul by defeating the Shade of Akama inside the Black Temple . Return to Seer Kanai when you've completed this task. Progress: Yes, <name>?", ["rewardXP"] = 6175, ["rewardItems"] = { 32757 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3959 } }, ["questType"] = "raid" },
[10959] = { ["id"] = 10959, ["name"] = "The Fall of the Betrayer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 3959, ["storyline"] = { 10959 }, ["series"] = { 10944, 10946, 10947, 10948, 10949, 10957, 10958, 10985, 13429 }, ["description"] = "With Illidan's lieutenants defeated, Akama will be able to force open the doors to Illidan's sanctum. Be ready to bring your force inside as soon as Akama does. We still do not know what has become of Maiev, but we must make our move without her. I hope your force is up to the task. Illidan will not be pleased to see Akama.", ["objectivesText"] = "Seer Kanai wants you to defeat Illidan inside the Black Temple . Progress: Yes, <name>?", ["rewardGold"] = 315000, ["rewardXP"] = 6175, ["rewardItems"] = { 32649, 32757 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3959 } }, ["questType"] = "raid" },
[10962] = { ["id"] = 10962, ["name"] = "Time to Visit the Caverns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 440, ["storyline"] = { 10962 }, ["description"] = "In the orphanage, the old priest that comes by told us stories about the Caverns of Time. He said that it sits in the middle of time, and is really important for keeping things straight. I don't know what that means, but he said that there were dragons there that were helping to save the world! I want to see a dragon! Do you think that we could go there? He said that the entrance was on the eastern edge of a great desert named Tanaris. Maybe you could buy me a souvenir while we're there?", ["objectivesText"] = "Take your orphan, Dornaa, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive. Then, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel. Progress: You think it's true what they say about the Caverns of Time?", ["rewardXP"] = 1415, ["rewardItems"] = { 31881, 31951 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[10963] = { ["id"] = 10963, ["name"] = "Time to Visit the Caverns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 440, ["storyline"] = { 10963 }, ["description"] = "In the orphanage, the old stinky priest that comes by told us stories about the Caverns of Time. He said that it sits in the middle of time, and is really important for keeping things straight. I don't know what that means, but he said that there were dragons there that were helping to save the world! I want to see a dragon! I think we should go there. He said that the entrance was on the eastern edge of a great desert named Tanaris. You could buy me a souvenir while we're there!", ["objectivesText"] = "Take your orphan, Salandria, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive. Then, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel. Progress: If what they say about the Caverns of Time is true, then it must be a place of great power.", ["rewardXP"] = 1415, ["rewardItems"] = { 31880, 31951, 32616, 32617, 32622, 69648, 116202 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[10966] = { ["id"] = 10966, ["name"] = "Back to the Orphanage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10966 }, ["description"] = "Darn it all! I guess it's time to go back to the orphanage at Shattrath City. I've had such a great time. You're the best person in all of the worlds, <name>! You're my big <brother/sister> now! <Dornaa's eyes begin to well up with tears.> I'm going to miss you so much! When I grow up, I'm going to be just like you!!!", ["objectivesText"] = "Return your ward to the Shattrath City orphanage by handing in the Draenei Orphan Whistle to Orphan Matron Mercy in the Lower City.", ["rewardXP"] = 1415, ["rewardItems"] = { 23022, 32616, 32617, 32622, 38626, 69648, 116202, 241215 }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 22819, ["x"] = 0.747, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.747, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10967] = { ["id"] = 10967, ["name"] = "Back to the Orphanage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 10967 }, ["description"] = "Darn it all! I guess it's time to go back to the orphanage at Shattrath City. I've had such a great time. You're the best person in all of the worlds, <name>! You're my big <brother/sister> now! <Salandria's eyes begin to well up with tears.> I'm going to miss you so much!!!", ["objectivesText"] = "Return your ward to the Shattrath City orphanage by handing in the Blood Elf Orphan Whistle to Orphan Matron Mercy in the Lower City.", ["rewardXP"] = 1415, ["rewardItems"] = { 23022, 31880, 31951, 32616, 32617, 32622, 69648, 116202, 241215 }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 22819, ["x"] = 0.747, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.747, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[10968] = { ["id"] = 10968, ["name"] = "Call on the Farseer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 1, ["zoneID"] = 3557, ["mapID"] = 103, ["storyline"] = { 10968 }, ["series"] = { 10956 }, ["description"] = "I am sensing something very special about this child indeed. You should take her to visit Farseer Nobundo , here in the Exodar. I believe that he has been expecting the two of you. Look for Nobundo upon the highest terrace in the Crystal Hall.", ["objectivesText"] = "Take your orphan, Dornaa, to visit Farseer Nobundo at the Crystal Hall inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive. Remember that you can use your map inside the city. Progress: Remarkable.", ["rewardXP"] = 710, ["rewardItems"] = { 31881 }, ["starts"] = { { ["mapID"] = 103, ["npcID"] = 17538, ["x"] = 0.5745, ["y"] = 0.4135 } }, ["ends"] = { { ["mapID"] = 103, ["npcID"] = 17204, ["x"] = 0.305778, ["y"] = 0.307556 } }, ["coords"] = { ["mapID"] = 103, ["source"] = "quest_giver", ["x"] = 0.5745, ["y"] = 0.4135 }, ["mapCandidates"] = { ["npc"] = { 103 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[10981] = { ["id"] = 10981, ["name"] = "Nexus-Prince Shaffar's Personal Chamber", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3522, ["mapID"] = 105, ["storyline"] = { 10981 }, ["objectivesText"] = "Progress: Only the most steadfast and battle-hardened of adventurers will take me up on this offer, <name>. Should you wish to face the horrors of the second stasis chamber in the Mana-Tombs , I am able to synthesize a key. Bring me a mark of the Nexus-King and I will make it so.", ["rewardItems"] = { 29460, 31941, 32079, 32092, 64399 }, ["starts"] = { { ["mapID"] = 105, ["npcID"] = 22919, ["x"] = 0.528, ["y"] = 0.15 } }, ["ends"] = { { ["mapID"] = 105, ["npcID"] = 22919, ["x"] = 0.528, ["y"] = 0.15 } }, ["coords"] = { ["mapID"] = 105, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.15 }, ["mapCandidates"] = { ["npc"] = { 105 }, ["zone"] = { 3522 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5927 } },
[11002] = { ["id"] = 11002, ["name"] = "The Fall of Magtheridon", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3836, ["mapID"] = 100, ["storyline"] = { 11002 }, ["description"] = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Alliance. Return Magtheridon's head to Danath Trollbane at Honor Hold.", ["objectivesText"] = "Return Magtheridon's Head to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula. Progress: For the first time - in as long as I can remember - there is silence.", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["rewardItems"] = { 28790, 28791, 28792, 28793, 32385 }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 16819, ["x"] = 0.566, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3836 } }, ["questType"] = "standard", ["startItems"] = { 32385 } },
[11003] = { ["id"] = 11003, ["name"] = "The Fall of Magtheridon", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3836, ["mapID"] = 100, ["storyline"] = { 11003 }, ["description"] = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Horde. Return Magtheridon's head to Nazgrel at Thrallmar.", ["objectivesText"] = "Return Magtheridon's Head to Nazgrel at Thrallmar in Hellfire Peninsula. Progress: For the first time - in as long as I can remember - there is silence.", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["rewardItems"] = { 28790, 28791, 28792, 28793, 32386 }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 3230, ["x"] = 0.55, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3836 } }, ["questType"] = "standard", ["startItems"] = { 32386 } },
[11007] = { ["id"] = 11007, ["name"] = "Kael'thas and the Verdant Sphere", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3845, ["mapID"] = 111, ["storyline"] = { 11007 }, ["description"] = "The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael'thas Sunstrider. What secrets could it hold? Perhaps A'dal in Shattrath City could make sense of the item.", ["objectivesText"] = "Take the Verdant Sphere to A'dal in Shattrath City. Progress: You heard my call? Yes...", ["rewardXP"] = 6175, ["rewardItems"] = { 30007, 30015, 30017, 30018, 32405 }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3845 } }, ["questType"] = "standard", ["startItems"] = { 32405 } },
[11031] = { ["id"] = 11031, ["name"] = "Archmage No More", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 11031 }, ["objectivesText"] = "Progress: You've decided against your previous choice? I suppose I can help you reverse it. In the end Dalaran cares more about your loyalty than how you choose to show it. It won't be cheap. And of course, I will need your old ring back.", ["rewardItems"] = { 29279, 29283, 29287, 29290 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18253, ["x"] = 0.472, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18253, ["x"] = 0.472, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Day of the Dead" },
