[11117] = { ["id"] = 11117, ["name"] = "Catch the Wild Wolpertinger!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 11117 }, ["description"] = "Here now. Ye hear that? There be sounds in them hills. Those're the wolpertingers! Wily beasts, they are, attracted by the smells o' Brewfest. I've a mind to catch me some, but I knocked me shin and can't outrun the buggers. Ye can help me, though! Take this net and cast it over the little blighters. Bring me a good five of 'em and I'll make it worth yer while! One more thing - ye gotta use Synthebrew Goggles to spot 'em! Let me know if ya need a pair.", ["objectivesText"] = "Goldark Snipehunter has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net . He mentioned that you must be wearing Synthebrew Goggles to see them. Progress: Did ya see the little buggers?", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["rewardItems"] = { 32233, 32906, 32907, 37829 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 23486, ["x"] = 0.506, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 23486, ["x"] = 0.506, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[11118] = { ["id"] = 11118, ["name"] = "Pink Elekks On Parade", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 11118 }, ["description"] = "Getting drunk is a time-honored tradition at Brewfest -- it's damn near required! Thing is, I'm getting reports across Azeroth saying the celebration's plagued by hallucinations! We can't have that! These elekks can't be harmed by normal weapons -- they pass right through 'em -- so take this fabulous piece of gnomish machinery, visit one of the other beer gardens, and zap 'em to oblivion. Remember, you have to be wearing Synthebrew Goggles to see 'em! Talk to me if you need a pair.", ["objectivesText"] = "Visit the beer gardens outside Stormwind, Darnassus, or the Exodar, zap three elekks at any location, and return to Goldark Snipehunter . You must be wearing Synthebrew Goggles to see the pink elekks. Progress: Are those pesky pink elekks gone yet?", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["rewardItems"] = { 32960, 34334, 37829, 46735, 81415, 84101, 138730 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 23486, ["x"] = 0.506, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 23486, ["x"] = 0.506, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[11120] = { ["id"] = 11120, ["name"] = "Pink Elekks On Parade", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 11120 }, ["description"] = "Brewfest is a time-honored celebration of food and drink. But sometimes drink gets the better of you! Excessive brew drinking can lead to many side effects... and we're getting many reports on hallucinations! Folks have been talking about seeing pink elekks, and I need you to take care of them. Take this goblin-engineered ray gun to one of the beer gardens and zap the elekks away. To keep yourself safe, I recommend wearing Synthebrew Goggles to see your targets while still keeping your wits about you.", ["objectivesText"] = "Visit the beer gardens outside of Silvermoon, Thunder Bluff, or the Undercity, zap 3 Pink Elekks at any location, and return to Snipehunter Goro. You must be wearing Synthebrew Goggles to see them. Progress: Ya clear up that little problem we talked about?", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["rewardItems"] = { 32960, 37829, 46735 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 24657, ["x"] = 0.526667, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 24657, ["x"] = 0.526667, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[11122] = { ["id"] = 11122, ["name"] = "There and Back Again", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 11122 }, ["description"] = "So you want to help out at Brewfest? I've got the perfect task for ya. I'll put you on one of my racing rams and you head down to Kharanos. I've got some kegs I need to pick up. Flynn Firebrew is waiting on a hill near a stack of kegs. He'll toss you a keg when you get near, then you run the keg back here and toss the keg to Pol Amberstill. You can only carry one at a time. Ready?", ["objectivesText"] = "Get a keg from Flynn Firebrew in Kharanos and return it to Pol Amberstill. If you lose your ram, ask Neill Ramstein for another. Progress: I need those kegs! So, what are yeh waitin' for!?!", ["rewardGold"] = 208560, ["rewardXP"] = 200, ["rewardItems"] = { 33306, 37829 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 23558, ["x"] = 0.5196, ["y"] = 0.4284 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 23558, ["x"] = 0.5196, ["y"] = 0.4284 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.5196, ["y"] = 0.4284 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[11129] = { ["id"] = 11129, ["name"] = "Kyle's Gone Missing!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["description"] = "Help, <name>! My prized puppy, Kyle, has run away! I just know he's running around Bloodhoof Village, lost and hungry. Will you find him and feed him? Once he eats he will settle down and come home. To feed him you will need to find food. His favorite meal is tender strider meat . Just venture east and you should find plenty of striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, put the meat down and he is sure to come to you.", ["objectivesText"] = "Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied . Feed Kyle Tender Strider Meat and return to Ahab Wheathoof . Progress: Did you find Kyle?", ["rewardGold"] = 266800, ["rewardXP"] = 200, ["rewardItems"] = { 33009 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 23618, ["x"] = 0.482, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 23618, ["x"] = 0.482, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 5, ["flags"] = 0 } } },
[11131] = { ["id"] = 11131, ["name"] = "Stop the Fires!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3524, ["mapID"] = 27, ["storyline"] = { 11131 }, ["description"] = "You must help us! The Headless Horseman is attacking the village. Fires are everywhere! The children aren't safe! Please, <name>, join the fire brigade. Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze. Put out all the fires and we may yet be saved!", ["objectivesText"] = "The Costumed Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Costumed Orphan Matron . Progress: <name>, you promised to save the children!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 20557, 33226, 34068 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[11135] = { ["id"] = 11135, ["name"] = "The Headless Horseman", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["storyline"] = { 11135 }, ["description"] = "The Headless Horseman is driven away, but he will return as long as Hallow's End looms. <name>, end our misery, and the insane lament of the Horseman. Face him when he is joined with his head, and destroy it! He rests in the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades. Find his pumpkin shrine and say this: Horseman, rise Your time is nigh You felt death once Now, know demise! Go, <name>. And may the Light go with you.", ["objectivesText"] = "Find the Headless Horseman's pumpkin Shrine.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 33226 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[11196] = { ["id"] = 11196, ["name"] = "Warlord of the Amani", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 3805, ["storyline"] = { 11196 }, ["description"] = "Da Amani been rebuildin' their forces and dey raised up a new warlord to lead dem, <name>. He be called Daakara da Invincible, but we be seein' whether he lives up to the name or not. Ya must first defeat all his lieutenants to clear da way before ya can face this Daakara . Defeat him and put an end to da ambitions of da Zandalari and da Amani!", ["objectivesText"] = "Defeat the new Amani warlord, Daakara . Progress: Dis new warlord must fall before da Zandalari foothold here becomes permanent.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 69598, 69599 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3805 } }, ["questType"] = "dungeon", ["startItems"] = { 33102 } },
[11219] = { ["id"] = 11219, ["name"] = "Stop the Fires!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3430, ["mapID"] = 1, ["storyline"] = { 11219 }, ["description"] = "The Horde's children need you, <name>. The Headless Horseman, once a human paladin and now an insane fiend, has set fire to our village! You must put out those fires! Grab a bucket and throw it onto the blaze, or toss it to an ally who is closer to the flames. Extinguish all the fires and thwart the Headless Horseman!", ["objectivesText"] = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town. Progress: The Horde's children need you! Do not abandon them!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 20557, 33226, 34068, 37011 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.636667, ["y"] = 0.401333 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 3430 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[11220] = { ["id"] = 11220, ["name"] = "The Headless Horseman", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["storyline"] = { 11220 }, ["description"] = "Until the head of the Headless Horseman is destroyed, his rampage will not end. The Horseman rests within the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades. Go to his pumpkin shrine and speak these words: Horseman, rise Your time is nigh You felt death once Now, know demise! This will rouse the fiend. Destroy the head of the Horseman and he will plague us no longer.", ["objectivesText"] = "Find the Headless Horseman's Pumpkin Shrine.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["rewardItems"] = { 33226 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[11242] = { ["id"] = 11242, ["name"] = "Free at Last!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 11242 }, ["description"] = "Rage was my prison, <name>, and you have freed me. Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth. Thank you for leading me back to the Light. May I never again lose my way. Take this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.", ["objectivesText"] = "Take the Tome of Thomas Thomson to the Costumed Orphan Matron in Goldshire, Kharanos or Azure Watch. Progress: You have something for me, good <name>?", ["rewardGold"] = 619600, ["rewardXP"] = 4300, ["rewardItems"] = { 20557, 33277, 36796, 39109, 39112, 39117, 39119, 39120 }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[11251] = { ["id"] = 11251, ["name"] = "Fresh Legs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 495, ["mapID"] = 117, ["storyline"] = { 11251 }, ["description"] = "It's come at great cost, but we've completed our inspection of the site. The news isn't good. Nearly everyone has been slain or captured. Only a few veteran guards remain unaccounted for. The scouts have done all we can here. You must pick up where we've left off. Sounds of a skirmish are coming from up the hill to the northeast. Have a look, <class>. We can only hope there are some who have survived, and that they may have some intel we can use against this enemy.", ["objectivesText"] = "Scout Valory wants you to investigate the sounds of battle coming from the northeast of Wyrmskull Village.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 24106, ["x"] = 0.56, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 495 } }, ["questType"] = "dungeon" },
[11262] = { ["id"] = 11262, ["name"] = "Ingvar Must Die!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 206, ["mapID"] = 117, ["storyline"] = { 11262 }, ["description"] = "Of our entire recon party, only I remain. These vrykul are relentless fighters. Given their numbers and their savage tactics, our only hope is to bring down their leader and pray it brings chaos to their ranks. Ingvar is his name. Bring me his head!", ["objectivesText"] = "Dark Ranger Marrah has asked you to kill Ingvar the Plunderer inside Utgarde Keep . Progress: Gird up, <race>. There's much work to be done. This is just the tip of the iceberg, so to speak.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 33330, 38218, 38219, 38220 }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 23780, ["x"] = 0.785, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.785, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 206 } }, ["questType"] = "dungeon" },
[11272] = { ["id"] = 11272, ["name"] = "A Score to Settle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 206, ["mapID"] = 117, ["storyline"] = { 11272 }, ["description"] = "This elf prince thinks he can come to my town, insult my queen, kill my men and get away with it? He thinks we're going to stand by while the hordes of Utgarde build up to launch an attack? Not in a million years. You're going to walk right into Utgarde and kill him. I want Arthas to know that we've arrived and we're playing for keeps. Report to Dark Ranger Marrah inside Utgarde Keep when the deed is done and she'll tie up any... loose ends.", ["objectivesText"] = "High Executor Anselm wants you to slay Prince Keleseth inside Utgarde Keep .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 39676, 39678, 39679, 39680 }, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 23780, ["x"] = 0.785, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 23780, ["x"] = 0.785, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.785, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 206 } }, ["questType"] = "dungeon" },
[11293] = { ["id"] = 11293, ["name"] = "Bark for the Barleybrews!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily", "timed" }, ["timerSeconds"] = 240, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 11293 }, ["description"] = "We need to get the word out about the Barleybrews at Brewfest. You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward. I'll make things easy though, I'll lend you a racing ram for 4 minutes. Use the reins to let him go, but try not to tire him out.", ["objectivesText"] = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward. Progress: Have you finished spreading the word about Brewfest? But more importantly, did you let people know about the Barleybrews?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 33306, 37829 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 23627, ["x"] = 0.51, ["y"] = 0.491 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 23627, ["x"] = 0.51, ["y"] = 0.491 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.491 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[11294] = { ["id"] = 11294, ["name"] = "Bark for the Thunderbrews!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily", "timed" }, ["timerSeconds"] = 240, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 11294 }, ["description"] = "It's time to let people know that the Thunderbrew have heard their cries for good brew. You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward. We'll make it easy though. We'll lend you a ram for 4 minutes. Be careful with going too fast though since you won't find any apple crates in Ironforge... We can't take the chance of helping out the Barleybrew messengers.", ["objectivesText"] = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward. Progress: Did you let everyone know that the Thunderbrews are here at Brewfest?", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 33306, 37829 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 23628, ["x"] = 0.565, ["y"] = 0.369 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 23628, ["x"] = 0.565, ["y"] = 0.369 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.369 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[11318] = { ["id"] = 11318, ["name"] = "Now This is Ram Racing... Almost.", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 11318 }, ["description"] = "So you want to check out the racing rams? Well I hope you're ready for speed. BUT before I let you loose in the world, you'll need to show me that you can handle these fine creatures. So here's the deal: I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams. Keep the ram at a trot, canter and gallop for 8 seconds each. If you need instructions how to handle the ram, talk to my apprentice, Pol Amberstill.", ["objectivesText"] = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds. Progress: Were you able to handle the speed?", ["rewardGold"] = 262100, ["rewardXP"] = 200, ["rewardItems"] = { 33306 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 23558, ["x"] = 0.5196, ["y"] = 0.4284 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 23558, ["x"] = 0.5196, ["y"] = 0.4284 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.5196, ["y"] = 0.4284 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[11356] = { ["id"] = 11356, ["name"] = "Costumed Orphan Matron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 1537, ["mapID"] = 84, ["storyline"] = { 11356 }, ["description"] = "During Hallow's End, human orphanages have organized trips for their orphans to visit Alliance countryside villages. Those poor children would love to see a real <class> like yourself! Why don't you visit them? You'll find orphans at Goldshire in Elwynn Forest, Kharanos in Dun Morogh and Azure Watch in Azuremyst. Speak to the children's ward, a costumed orphan matron , and she'll introduce you to the children.", ["objectivesText"] = "Speak with a Costumed Orphan Matron in either Goldshire, Kharanos or Azure Watch.", ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 18927, ["x"] = 0.628143, ["y"] = 0.557571 }, { ["mapID"] = 87, ["npcID"] = 19148, ["x"] = 0.3115, ["y"] = 0.665625 }, { ["mapID"] = 87, ["npcID"] = 19172, ["x"] = 0.575333, ["y"] = 0.489333 }, { ["mapID"] = 89, ["npcID"] = 19173, ["x"] = 0.445, ["y"] = 0.529 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 }, { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.628143, ["y"] = 0.557571 }, ["mapCandidates"] = { ["npc"] = { 10, 27, 84, 87, 89, 2112, 2339 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[11357] = { ["id"] = 11357, ["name"] = "Masked Orphan Matron", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 1, ["zoneID"] = 1637, ["mapID"] = 94, ["storyline"] = { 11357 }, ["description"] = "For Hallow's End, several orphans were taken on a trip to different Horde villages. The orphan matrons thought it would be good for them to see real heroes adventuring in the field. Why don't you visit them? A brave <class> like yourself could strengthen their spirits with tales of your valor! Go to Razor Hill in Durotar, Brill in Tirisfal Glades, or Falconwing Square in Eversong Woods. Speak with the masked orphan matron and she'll introduce you to the children.", ["objectivesText"] = "Speak with a Masked Orphan Matron in Razor Hill, Brill, or Falconwing Square.", ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 19169, ["x"] = 0.542, ["y"] = 0.508 }, { ["mapID"] = 85, ["npcID"] = 19175, ["x"] = 0.545667, ["y"] = 0.709667 }, { ["mapID"] = 85, ["npcID"] = 19176, ["x"] = 0.402, ["y"] = 0.5615 }, { ["mapID"] = 85, ["npcID"] = 19177, ["x"] = 0.440857, ["y"] = 0.667714 }, { ["mapID"] = 90, ["npcID"] = 19178, ["x"] = 0.648923, ["y"] = 0.442154 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 1, 10, 85, 90, 94, 2339 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[11360] = { ["id"] = 11360, ["name"] = "Fire Brigade Practice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3524, ["mapID"] = 27, ["storyline"] = { 11360 }, ["description"] = "With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade. Do you want to help? North of here, guards set up a small area to practice fighting fires. Go there and throw buckets onto the blazes. You can fill a bucket from the water barrel here, or the one near the fires. Good bye, <name>. When you're done with fire brigade practice, please visit us again!", ["objectivesText"] = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron . Progress: Hello, <name>. Have you been perfecting your fire fighting techniques? Don't forget about the practice area to the north!", ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[11361] = { ["id"] = 11361, ["name"] = "Fire Training", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3430, ["mapID"] = 1, ["storyline"] = { 11361 }, ["description"] = "The grunts set up a fire training area outside the village. These days, Razor Hill's buildings often catch fire -- you should lend a hand and train as a fire fighter! Head west out of Razor Hill, then turn right as you pass the village's wall. Find the training area, then grab buckets and toss them on the practice fires.", ["objectivesText"] = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Razor Hill.", ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.636667, ["y"] = 0.401333 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[11364] = { ["id"] = 11364, ["name"] = "WANTED: Shattered Hand Centurions", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11364 }, ["description"] = "Do you question your master? Neither does Mah'duun. The blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel. If you want the bounty, you will not return until you have slain them all.", ["objectivesText"] = "Nether-Stalker Mah'duun has tasked you with the deaths of 4 Shattered Hand Centurions . Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", ["rewardGold"] = 561800, ["rewardXP"] = 2765, ["rewardItems"] = { 29460 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 5922 } },
[11369] = { ["id"] = 11369, ["name"] = "WANTED: A Black Stalker Egg", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11369 }, ["description"] = "There is only ever one great mother of the marsh walkers in Zangarmarsh. She is always known as the Black Stalker, and she hatches from one of the eggs left behind when her mother dies. I have a buyer who is interested in one of those eggs. He mentioned something about adding her as a zoo attraction. If you are interested in the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.", ["objectivesText"] = "Wind Trader Zhareem wants you to obtain a Black Stalker Egg . Deliver it to him in Shattrath's Lower City to collect the reward. This quest may only be completed on Heroic difficulty. Progress: We're speaking again because you have the egg? Outstanding, let me see it!", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["rewardItems"] = { 33826 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24369, ["x"] = 0.648857, ["y"] = 0.387714 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24369, ["x"] = 0.648857, ["y"] = 0.387714 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.648857, ["y"] = 0.387714 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5922 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 111, ["db2QuestInfoID"] = 85, ["db2QuestInfoName"] = "Heroic" },
[11371] = { ["id"] = 11371, ["name"] = "WANTED: Coilfang Myrmidons", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11371 }, ["description"] = "Mah'duun hears and obeys, and I now ask you to be my instrument. It has been related to me that the myrmidons of the coilfang tribe must be destroyed. Seek them out within the humid confines of the Steamvault underneath Coilfang Reservoir. I will accept nothing less than their utter annihilation.", ["objectivesText"] = "Nether-Stalker Mah'duun has asked you to slay 14 Coilfang Myrmidons . Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", ["rewardGold"] = 561800, ["rewardXP"] = 2765, ["rewardItems"] = { 29460 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 5922 }, ["db2PoiMapID"] = 545, ["db2PoiUiMapID"] = 263, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[11376] = { ["id"] = 11376, ["name"] = "WANTED: Malicious Instructors", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11376 }, ["description"] = "Mah'duun has heard it said that none are as cruel as the six-armed demonesses inside the Shadow Labyrinth . Go to Auchindoun, seek them out, kill them all. If you cannot accomplish so simple a task, we do not have anything further to say to one another.", ["objectivesText"] = "Nether-Stalker Mah'duun wants you to kill 3 Malicious Instructors . Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", ["rewardGold"] = 619600, ["rewardXP"] = 2765, ["rewardItems"] = { 29460 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 5922 }, ["db2PoiMapID"] = 555, ["db2PoiUiMapID"] = 260, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[11377] = { ["id"] = 11377, ["name"] = "Revenge is Tasty", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11377 }, ["description"] = "I'm providing the catering for some unusual party guests tonight. One of these fellows was flying around in Skettis and got knocked to the ground by a monstrous kaliri--his leg was broken badly. They've requested something special for his get well party: Kaliri Stew . I can loan you my cooking pot so you can whip up a batch of stew for me. The recipe itself is simple, but you'll need to get a giant kaliri wing and some cooked warp burgers.", ["objectivesText"] = "The Rokk in Lower City has asked you to cook up some Kaliri Stew using his cooking pot . Return to him when it's done. Progress: Do I smell something tasty?", ["rewardXP"] = 4115, ["rewardItems"] = { 27442, 27659, 27681, 33837, 33838, 33839, 33844, 33857 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24393, ["x"] = 0.594444, ["y"] = 0.245778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24393, ["x"] = 0.594444, ["y"] = 0.245778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.594444, ["y"] = 0.245778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11379] = { ["id"] = 11379, ["name"] = "Super Hot Stew", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11379 }, ["description"] = "I'm trying to invent something with some real zing. But to be honest, I'm more of an idea goblin these days. I've lost my sense of adventure. But you... remind me of my younger days; ready to take on the world with a sword in one hand and a skillet in the other. I want you to take my beloved cooking pot and head out to Blade's Edge. Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil it over an abyssal's corpse, the only thing hot enough to do the trick.", ["objectivesText"] = "The Rokk in Lower City has asked you to cook up some Demon Broiled Surprise using his cooking pot , two Mok'Nathal Shortribs and a Crunchy Serpent. Return to him when it's done. Progress: Any luck with my little experiment?", ["rewardXP"] = 4115, ["rewardItems"] = { 27442, 31670, 31671, 31672, 31673, 31674, 31675, 33844, 33848, 33852, 33857 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24393, ["x"] = 0.594444, ["y"] = 0.245778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24393, ["x"] = 0.594444, ["y"] = 0.245778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.594444, ["y"] = 0.245778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11380] = { ["id"] = 11380, ["name"] = "Manalicious", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11380 }, ["description"] = "Wouldn't you know it, I think my foodstuffs are up to date and someone comes along and requests the unusual: Mana Berry Delight. Unfortunately, mana berries are only found in the eco-domes of Netherstorm. Just don't bother looking around Stormspire--it's picked clean. I could only trust someone trained in the culinary arts to pick the best berries, so don't let me down!", ["objectivesText"] = "The Rokk in Lower City has asked you collect 15 Mana Berries from the Eco-Domes in Netherstorm. Progress: Any luck, friend?", ["rewardXP"] = 4115, ["rewardItems"] = { 27442, 33844, 33849, 33857 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24393, ["x"] = 0.594444, ["y"] = 0.245778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24393, ["x"] = 0.594444, ["y"] = 0.245778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.594444, ["y"] = 0.245778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11381] = { ["id"] = 11381, ["name"] = "Soup for the Soul", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11381 }, ["description"] = "Death is in the air. I've never had so many orders for my famous soup--it lifts your spirits and soothes the soul. And I know a fellow cook when I see one! Would you like to help me out and get a cut of the profits? Here, take my cooking pot , gather some clefthoof meat and I'll let you in on a little secret. What makes my soup so good for the soul? It's not chicken--I cook it at the Ancestral Grounds in Nagrand to soak up all that spiritual stuff there.", ["objectivesText"] = "The Rokk in Lower City has asked you to cook up some Spiritual Soup using his cooking pot . Return to him when it's done. Progress: What smells so good?", ["rewardXP"] = 4115, ["rewardItems"] = { 27442, 27658, 33844, 33850, 33851, 33857 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24393, ["x"] = 0.594444, ["y"] = 0.245778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24393, ["x"] = 0.594444, ["y"] = 0.245778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.594444, ["y"] = 0.245778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11383] = { ["id"] = 11383, ["name"] = "WANTED: Rift Lords", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11383 }, ["description"] = "Mah'duun knows where you must go. Mah'duun knows that you must kill rift lords . But, Mah'duun does not know exactly when. I know that does not make sense, but the voice on the winds was not more specific. Travel to the Black Morass through the Caverns of Time and the way shall be made clear.", ["objectivesText"] = "Nether-Stalker Mah'duun wants you to kill 4 Rift Lords . Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", ["rewardGold"] = 561800, ["rewardXP"] = 3440, ["rewardItems"] = { 29460 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 5922 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 111, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[11385] = { ["id"] = 11385, ["name"] = "WANTED: Sunseeker Channelers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11385 }, ["description"] = "It has been whispered to Mah'duun that the channelers of the military unit known as the Sunseekers must be killed today. They are to be found within the Botanica at Tempest Keep. You want the bounty, you kill the channelers.", ["objectivesText"] = "Nether-Stalker Mah'duun wants you to kill 6 Sunseeker Channelers . Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", ["rewardGold"] = 561800, ["rewardXP"] = 2765, ["rewardItems"] = { 29460 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 5922 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 111, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[11387] = { ["id"] = 11387, ["name"] = "WANTED: Tempest-Forge Destroyers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11387 }, ["description"] = "There are mechanical constructs within the Mechanar which Mah'duun has been told must be dismantled. Go to Tempest Keep, find the tempest-forge destroyers and destroy them. Then you may return to collect the bounty.", ["objectivesText"] = "Nether-Stalker Mah'duun wants you to destroy 5 Tempest-Forge Destroyers . Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", ["rewardGold"] = 619600, ["rewardXP"] = 2765, ["rewardItems"] = { 29460 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 5922 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 111, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[11389] = { ["id"] = 11389, ["name"] = "WANTED: Arcatraz Sentinels", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11389 }, ["description"] = "The sentinels within the Arcatraz have gone haywire. The prisoners run rampant and the guards attack those that would help. Mah'duun hears the speaker on the nether winds. The speaker says to destroy the sentinels. Accomplish this and today's bounty is yours.", ["objectivesText"] = "Nether-Stalker Mah'duun wants you to dismantle 5 Arcatraz Sentinels . Return to him in Shattrath's Lower City once that has been accomplished in order to collect the bounty.", ["rewardGold"] = 561800, ["rewardXP"] = 3440, ["rewardItems"] = { 29460 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 5922 }, ["db2PoiMapID"] = 552, ["db2PoiUiMapID"] = 270, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
