[11403] = { ["id"] = 11403, ["name"] = "Free at Last!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 11403 }, ["description"] = "Rage was my prison, <name>, and you have freed me. Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth. Thank you for leading me back to the Light. May I never again lose my way. Take this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.", ["objectivesText"] = "Take the Tome of Thomas Thomson to a Masked Orphan Matron in Durotar, Brill or Falconwing Square. Progress: <name>, it is good to see you again. I'm sure the children enjoy tales of your heroism.", ["rewardGold"] = 619600, ["rewardXP"] = 4300, ["rewardItems"] = { 20557, 33277, 39109, 39112, 39117, 39119, 39120 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.636667, ["y"] = 0.401333 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
