[11407] = { ["id"] = 11407, ["name"] = "Bark for Drohn's Distillery!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily", "timed" }, ["timerSeconds"] = 240, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 11407 }, ["description"] = "So, do you want to help bring strength and honor to Brewfest? We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits. We'll lend you a racing ram for 4 minutes. Be careful though, the cheap goblins didn't put any apple crates along the way.", ["objectivesText"] = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits. Progress: Have you finished spreading the word about Brewfest?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 24498, ["x"] = 0.5335, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 24498, ["x"] = 0.5335, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.5335, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[11408] = { ["id"] = 11408, ["name"] = "Bark for T'chali's Voodoo Brewery!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily", "timed" }, ["timerSeconds"] = 240, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 11408 }, ["description"] = "We need to spread the word about the trolls at Brewfest. Ya need to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits. But I'll make it easy for ya, I'll lend you a racing ram for 4 minutes. Be careful though, the goblins didn't put any apple crates along the way. They are cheap like that.", ["objectivesText"] = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits. Progress: Have you finished spreading the word about Brewfest? But more importantly, did you let people know about the amazing troll brew?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 24499, ["x"] = 0.574, ["y"] = 0.266667 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 24499, ["x"] = 0.574, ["y"] = 0.266667 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.574, ["y"] = 0.266667 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[11409] = { ["id"] = 11409, ["name"] = "Now This is Ram Racing... Almost.", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 11409 }, ["description"] = "So you want to check out the racing rams? The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be? Now before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures. So here's the deal: I'll lend you the use of a ram. You need to prove to me that you can handle using these rams. Keep the ram at a trot, canter and gallop for 8 seconds each.", ["objectivesText"] = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds. Progress: Have you got a handle on riding racing rams?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 24497, ["x"] = 0.549, ["y"] = 0.2485 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 24497, ["x"] = 0.549, ["y"] = 0.2485 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.2485 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[11431] = { ["id"] = 11431, ["name"] = "Catch the Wild Wolpertinger!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 11431 }, ["description"] = "On Draenor, many creatures posed a tough hunt. However, I've never encountered a creature such as the wild wolpertinger of Azeroth! These beasts are not to be found most of the year, but the sounds and smells of Brewfest seem to draw them out. If you look around, you still may not see them... which is where these goggles come in handy! Prove to me you are a worthy hunter and bring me five of these wolpertingers alive. If you need some goggles, I have some to spare.", ["objectivesText"] = "Snipehunter Goro has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net . You must be wearing Synthebrew Goggles to see them. Progress: Do you have something for me or are you just looking for some Synthebrew Goggles?", ["rewardGold"] = 30900, ["rewardXP"] = 25, ["rewardItems"] = { 32233, 32906, 32907 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 24657, ["x"] = 0.526667, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 24657, ["x"] = 0.526667, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.526667, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[11439] = { ["id"] = 11439, ["name"] = "Fire Brigade Practice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3524, ["mapID"] = 27, ["storyline"] = { 11439 }, ["description"] = "The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help? South of here, the mountaineers set up a small area to practice fighting fires. Go there and throw buckets onto the blazes. You can fill a bucket from the water barrel here. Good bye, <name>. When you're done with fire brigade practice, please visit us again!", ["objectivesText"] = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron .", ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[11440] = { ["id"] = 11440, ["name"] = "Fire Brigade Practice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3524, ["mapID"] = 27, ["storyline"] = { 11440 }, ["description"] = "With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help? West of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires. Go there and throw buckets onto the blazes. You can fill a bucket from the water barrel here. Good bye, <name>. When you're done with fire brigade practice, please visit us again!", ["objectivesText"] = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron .", ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 3524 } }, ["questType"] = "standard" },
[11441] = { ["id"] = 11441, ["name"] = "Brewfest!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 14771, ["mapID"] = 84, ["storyline"] = { 11441 }, ["description"] = "Have you heard? It's time for Brewfest! You should speak to the Brewfest organizer at the grounds just outside of Ironforge--he'll give you a free beer to kick things off!", ["objectivesText"] = "Speak to the Brewfest Organizer.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["rewardItems"] = { 33030, 33031, 33034, 34017, 34020, 37829 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 18927, ["x"] = 0.628143, ["y"] = 0.557571 }, { ["mapID"] = 87, ["npcID"] = 19148, ["x"] = 0.3115, ["y"] = 0.665625 }, { ["mapID"] = 103, ["npcID"] = 19171, ["x"] = 0.571375, ["y"] = 0.437 }, { ["mapID"] = 87, ["npcID"] = 19172, ["x"] = 0.575333, ["y"] = 0.489333 }, { ["mapID"] = 89, ["npcID"] = 19173, ["x"] = 0.445, ["y"] = 0.529 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 }, { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220865, ["x"] = 0.566667, ["y"] = 0.286 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 24710, ["x"] = 0.506, ["y"] = 0.491 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.628143, ["y"] = 0.557571 }, ["mapCandidates"] = { ["npc"] = { 10, 27, 84, 87, 89, 103, 2112, 2339 }, ["zone"] = { 14771 } }, ["questType"] = "standard" },
[11446] = { ["id"] = 11446, ["name"] = "Brewfest!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 1, ["zoneID"] = 1637, ["mapID"] = 94, ["storyline"] = { 11446 }, ["description"] = "Have you heard? It's time for Brewfest! You should speak to the Brewfest organizer at the grounds just outside of Orgrimmar--he'll give you a free beer to kick things off!", ["objectivesText"] = "Speak to the Brewfest Organizer.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["rewardItems"] = { 33030, 33031, 33034, 34017, 34020, 37829 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 19169, ["x"] = 0.542, ["y"] = 0.508 }, { ["mapID"] = 85, ["npcID"] = 19175, ["x"] = 0.545667, ["y"] = 0.709667 }, { ["mapID"] = 85, ["npcID"] = 19176, ["x"] = 0.402, ["y"] = 0.5615 }, { ["mapID"] = 85, ["npcID"] = 19177, ["x"] = 0.440857, ["y"] = 0.667714 }, { ["mapID"] = 90, ["npcID"] = 19178, ["x"] = 0.648923, ["y"] = 0.442154 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 }, { ["mapID"] = 2112, ["npcID"] = 199261, ["x"] = 0.390667, ["y"] = 0.61 }, { ["mapID"] = 2339, ["npcID"] = 220307, ["x"] = 0.46, ["y"] = 0.546 }, { ["mapID"] = 2339, ["npcID"] = 220865, ["x"] = 0.566667, ["y"] = 0.286 }, { ["mapID"] = 2339, ["npcID"] = 220870, ["x"] = 0.41, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 24711, ["x"] = 0.484, ["y"] = 0.182 }, { ["mapID"] = 1, ["npcID"] = 155194, ["x"] = 0.415, ["y"] = 0.183 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 1, 10, 85, 90, 94, 2112, 2339 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[11449] = { ["id"] = 11449, ["name"] = "Fire Training", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3430, ["mapID"] = 1, ["storyline"] = { 11449 }, ["description"] = "The deathstalkers have set up a fire training area outside the town. We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter. Head west past the graveyard, following the road. You'll find the training area there.", ["objectivesText"] = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.", ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.636667, ["y"] = 0.401333 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[11450] = { ["id"] = 11450, ["name"] = "Fire Training", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3430, ["mapID"] = 1, ["storyline"] = { 11450 }, ["description"] = "The guards have set up a fire training area outside the town. We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter. Head south through the gate to the crossroads. You'll find the training area there.", ["objectivesText"] = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Falconwing Square.", ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 23973, ["x"] = 0.636667, ["y"] = 0.401333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.636667, ["y"] = 0.401333 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[11451] = { ["id"] = 11451, ["name"] = "Alicia's Poem", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 11451 }, ["description"] = "Hi, I wrote a poem for my friend Caylee. She likes to hang out with the Aldor in Shattrath City . You know, in Outland? Could you take my poem to her? My mommy says I'm too young to go to Shattrath City !", ["objectivesText"] = "You have been asked to deliver Alicia's Poem to Caylee Dak in Shattrath City in Outland. Progress: Oh, is that a poem?", ["rewardXP"] = 1045, ["rewardItems"] = { 34089 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 24729, ["x"] = 0.8156, ["y"] = 0.2796 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24727, ["x"] = 0.315, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8156, ["y"] = 0.2796 }, ["mapCandidates"] = { ["npc"] = { 84, 111 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[11481] = { ["id"] = 11481, ["name"] = "Crisis at the Sunwell", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 109, ["storyline"] = { 11481 }, ["series"] = { 29682 }, ["description"] = "By the naaru, I thank you, <race>, for your efforts. Our work is far from finished, however, and I must request that you undertake a critical mission - one as important as any I've issued. Our forces are spread thinly. To compound the strain, we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell Plateau. You are needed there, <name>. Report to Larethor. Tell him that I wish we could spare more men.", ["objectivesText"] = "Adyen the Lightwarden on the Aldor Rise in Shattrath City has requested that you travel to Sunwell Plateau and speak with Larethor.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 109, ["npcID"] = 18537, ["x"] = 0.338667, ["y"] = 0.146333 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 24967, ["x"] = 0.474, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.338667, ["y"] = 0.146333 }, ["mapCandidates"] = { ["npc"] = { 109, 122 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11482] = { ["id"] = 11482, ["name"] = "Duty Calls", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11482 }, ["series"] = { 11490, 29684, 29685 }, ["description"] = "Hear me, <race>. Duty requires that you return to Azeroth. Every able person is to report to the Sunwell Plateau immediately. I'm afraid I have no more information to share, except this: You'll be joining forces with the Aldor for this mission. Speak with a draenei by the name of Larethor when you arrive. Apparently, the situation calls for us to set our differences aside and join forces. Prepare yourself, friend. This sounds serious.", ["objectivesText"] = "Dathris Sunstriker on Scryer's Tier in Shattrath City has insisted that you travel to Azeroth at once and report to Larethor at the Sunwell.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18594, ["x"] = 0.527, ["y"] = 0.787667 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 24967, ["x"] = 0.474, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.527, ["y"] = 0.787667 }, ["mapCandidates"] = { ["npc"] = { 111, 122 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11490] = { ["id"] = 11490, ["name"] = "The Scryer's Scryer", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4131, ["storyline"] = { 11490 }, ["series"] = { 11482, 29684, 29685 }, ["description"] = "Go to the terrace... use the orb. < Tyrith gasps for breath.> Hurry... they must be stopped... before they can.... < Tyrith dies.>", ["objectivesText"] = "Tyrith wants you to use the orb on the balcony in Magisters' Terrace .", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883, 185717, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4131 } }, ["questType"] = "dungeon" },
[11496] = { ["id"] = 11496, ["name"] = "The Sanctum Wards", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["storyline"] = { 11496 }, ["description"] = "Our first priority is to capture the Sun's Reach Sanctum. Once we've secured it, we'll be able to use its energy to open a portal from Shattrath. The sanctum is overrun with the Wretched - former blood elves who've devolved into mindless husks of their former selves. Its defenses would've normally prevented this intrusion, but the Wretched have stolen the power sources from the protective wards. Hunt down the Wretched and get the mana remnants they carry. Use them to energize the sanctum wards.", ["objectivesText"] = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the Sun's Reach Sanctum to the east.", ["rewardGold"] = 232300, ["rewardXP"] = 2580, ["rewardItems"] = { 34338 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11500] = { ["id"] = 11500, ["name"] = "WANTED: Sisters of Torment", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11500 }, ["description"] = "It has been whispered to Mah'duun that the sisters of torment are to be sent back to the hells from which they sprang. Mah'duun knows that these demons can be found at the Magisters' Terrace on the Isle of Quel'Danas. You will do this thing to earn the bounty, or you will not.", ["objectivesText"] = "Nether-Stalker Mah'duun wants you to slay 4 Sisters of Torment . Return to him in Shattrath's Lower City once you have done so in order to collect the bounty.", ["rewardGold"] = 561800, ["rewardXP"] = 3440, ["rewardItems"] = { 29460 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24370, ["x"] = 0.637, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "dungeon", ["db2LabelIDs"] = { 5922 }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 111, ["db2QuestInfoID"] = 81, ["db2QuestInfoName"] = "Dungeon" },
[11515] = { ["id"] = 11515, ["name"] = "Blood for Blood", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 11515 }, ["description"] = "When Kael's forces retreated through that portal, his most loyal lackeys were rewarded with an abominable gift. They stayed behind and gorged themselves on the blood of demons for days. The blood has changed them, given them new powers. It will also prove their undoing. Obtain blood samples from other demons. Use them to power this fel siphon and deprive these arrogant fools of their new powers. Slay them in their weakened state and return to me.", ["objectivesText"] = "Magistrix Seyla at the Throne of Kil'jaeden wants you to kill 4 Emaciated Felbloods by using the Fel Siphon on them. You will need Demonic Blood from nearby Wrath Heralds to power the Fel Siphon . Progress: These freaks are a disgrace to our race. You must destroy them, <name>.", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["rewardItems"] = { 21100, 21746, 23390, 23391, 23392, 23393, 24441, 25553, 26050, 26054, 27640, 29914, 29915, 29916, 29917, 29919, 30809, 30810, 32720, 34257, 34259, 38665, 46007, 59384, 59385, 59386, 59422, 59423, 59424, 59799, 59800, 59801, 61490, 61491, 61492, 61626, 61628, 61630, 61632, 97919, 102246, 119037, 128402, 131586, 133114, 133115, 133116, 133117, 133118, 133119, 133120, 133121, 133122, 133124, 137663, 141674, 141947, 170073, 211279, 237812 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 24937, ["x"] = 0.582, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 24937, ["x"] = 0.582, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "standard" },
[11516] = { ["id"] = 11516, ["name"] = "Blast the Gateway", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 11516 }, ["description"] = "We have to shut down this gateway to stop Legion reinforcements to the Isle of Quel'Danas. Take these embers, they contain one of my creations: a living flare. It is designed to act as a powerful destructive force - as long as it has been provided enough energy. Find the fel sparks that wander the area and slay them near the living flare. The flare will grow in power each time, until it becomes unstable. Once you've achieved this bring the flare to the gateway. It will know what to do.", ["objectivesText"] = "Magistrix Seyla at the Throne of Kil'jaeden wants you to use the Sizzling Embers to summon a Living Flare and slay Incandescent Fel Sparks near it until it becomes an Unstable Living Flare. Return to the Legion Gateway with the Unstable Living Flare to destroy it. Progress: Is it done, <name>? We must stop further Legion forces from reinforcing Kael'thas.", ["rewardGold"] = 309800, ["rewardXP"] = 2580, ["rewardItems"] = { 34253, 35232 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 24937, ["x"] = 0.582, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 24937, ["x"] = 0.582, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "standard" },
[11517] = { ["id"] = 11517, ["name"] = "Report to Nasuun", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["storyline"] = { 11517 }, ["description"] = "I am most glad that you are here, <class>! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland. My liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation. Please, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", ["objectivesText"] = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City .", ["rewardXP"] = 430, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[11523] = { ["id"] = 11523, ["name"] = "Arm the Wards!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11523 }, ["description"] = "We've succeeded in reactivating the crystal wards around the sanctum, but why stop there? We'll build defenses around the other structures, but the Wretched are stubborn and continue to steal power from the crystal wards. Hunt them down and get the mana remnants they carry. Use the remnants to energize the sanctum wards; the safety of our operation depends on it.", ["objectivesText"] = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the structures in Sun's Reach. Progress: Have you reactivated a crystal ward, <name>?", ["rewardGold"] = 210675, ["rewardXP"] = 2580, ["rewardItems"] = { 34338 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 24967, ["x"] = 0.474, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 24967, ["x"] = 0.474, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11524] = { ["id"] = 11524, ["name"] = "Erratic Behavior", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["storyline"] = { 11524 }, ["description"] = "We lack the numbers to capture the Sanctum at Sun's Reach, but I've a plan that will tip the scales in our favor. The loose energy from the Sunwell has caused the sentries that patrol this island to malfunction. The crystal cores that control their behavior are damaged beyond repair. I've crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries. We will need all the help we can get.", ["objectivesText"] = "Vindicator Xayanna at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", ["rewardGold"] = 232300, ["rewardXP"] = 2580, ["rewardItems"] = { 34368 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[11525] = { ["id"] = 11525, ["name"] = "Further Conversions", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11525 }, ["description"] = "My plan to replace the damaged crystals on the erratic sentries has been a success. We've managed to take the Sun's Reach Sanctum with their help. I've crafted new crystals that will bring more of them under our control; place them inside the hulls of defeated sentries. We'll deploy them to other locations once they're converted.", ["objectivesText"] = "Vindicator Xayann at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units. Progress: Have you converted the sentries, <name>?", ["rewardGold"] = 232300, ["rewardXP"] = 2580, ["rewardItems"] = { 34368 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 24965, ["x"] = 0.472, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 24965, ["x"] = 0.472, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11526] = { ["id"] = 11526, ["name"] = "The Missing Magistrix", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11526 }, ["description"] = "We sent one of our operatives to investigate the fel portal in the middle of Dawning Square, south of here. She never returned. Take this scroll we found on one of the enemy corpses. We believe it will grant you access through the portal. Once through, find Magistrix Seyla and aid her in any way you can.", ["objectivesText"] = "Use the Captured Legion Scroll near the portal at Dawning Square. Once you've gone through the portal, find Magistrix Seyla . Progress: Keep quiet, <class>. The Legion's forces watch the south of the gate.", ["rewardGold"] = 232300, ["rewardXP"] = 2580, ["rewardItems"] = { 34420 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 24967, ["x"] = 0.474, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 24937, ["x"] = 0.582, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 100, 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11528] = { ["id"] = 11528, ["name"] = "A Winter Veil Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Feast of Winter Veil", ["expansion"] = 2, ["zoneID"] = 1637, ["storyline"] = { 11528 }, ["rewardItems"] = { 34426, 43504, 46740, 67443, 70938, 90892, 104319, 116761, 128653, 139341, 151350, 162644, 172224, 178528, 187561, 192094, 209871, 218311, 244908 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[11531] = { ["id"] = 11531, ["name"] = "Strange Engine Part", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 3521, ["mapID"] = 102, ["storyline"] = { 11531 }, ["description"] = "This strange engine part doesn't look like it fits in a steam pump, much less anything else you've seen. Perhaps K. Lee Smallfry might know something about it.", ["objectivesText"] = "Take the Strange Engine Part to K. Lee Smallfry in Telredor. Progress: Oh goodness! What've you got there, <name>?", ["rewardGold"] = 52500, ["rewardXP"] = 1415, ["rewardItems"] = { 24283, 29960, 33036, 34469, 34474, 34476 }, ["ends"] = { { ["mapID"] = 102, ["npcID"] = 17634, ["x"] = 0.685, ["y"] = 0.501 } }, ["coords"] = { ["mapID"] = 102, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.501 }, ["mapCandidates"] = { ["npc"] = { 102 }, ["zone"] = { 3521 } }, ["questType"] = "standard", ["startItems"] = { 34469 } },
[11532] = { ["id"] = 11532, ["name"] = "Distraction at the Dead Scar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["storyline"] = { 11532 }, ["description"] = "The Legion will move against us as soon as their forces to the south are freed up. The Scourge at the Dead Scar are keeping their forces occupied at the moment. It won't last long, however. I want you to fly a dragonhawk over to the scar and put a dent in the demons' numbers with these arcane charges . If all goes well, they won't even notice us taking the armory from Kael's lackeys. Talk to Ayren, the dragonhawk master in the west part of the harbor, when you're ready to fly there.", ["objectivesText"] = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords , 3 Eredar Sorcerers and 12 Wrath Enforcers .", ["rewardGold"] = 210675, ["rewardXP"] = 2580, ["rewardItems"] = { 34475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11533] = { ["id"] = 11533, ["name"] = "The Air Strikes Must Continue", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11533 }, ["description"] = "We've taken the armory from the enemy thanks to our aerial attacks against the Legion's forces in the Dead Scar. As a matter of fact, it's gone so well that we're going to continue our air strikes against them. Take these arcane charges and use them against their forces. Talk to Ayren Cloudbreaker at the Sun's Reach Harbor when you're ready for flight.", ["objectivesText"] = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords , 3 Eredar Sorcerers and 12 Wrath Enforcers .", ["rewardGold"] = 232300, ["rewardXP"] = 2580, ["rewardItems"] = { 34475 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25057, ["x"] = 0.475, ["y"] = 0.351 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25057, ["x"] = 0.475, ["y"] = 0.351 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.351 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11534] = { ["id"] = 11534, ["name"] = "Report to Nasuun", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11534 }, ["description"] = "I am most glad that you are here, <class>! When we took this sanctum from the wretched, we hurried to create a magical portal that leads here from Shattrath City in the Outland. My liege lord, Exarch Nasuun , is heading up the Offensive's efforts to maintain that portal. He asked me to send along any promising candidates who have what it takes to help with acquiring more energy to fuel it. Please, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", ["objectivesText"] = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City .", ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25034, ["x"] = 0.472, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 24932, ["x"] = 0.459, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 111, 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11535] = { ["id"] = 11535, ["name"] = "Making Ready", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["storyline"] = { 11535 }, ["description"] = "Supplies are inbound, or so I'm told. Regardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have. As for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons. There are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....", ["objectivesText"] = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", ["rewardGold"] = 53500, ["rewardXP"] = 3440, ["rewardItems"] = { 29434, 34477, 34479 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11536] = { ["id"] = 11536, ["name"] = "Don't Stop Now....", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11536 }, ["description"] = "Now that we have an anvil, I can really get to work. No matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here. There are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....", ["objectivesText"] = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests. Progress: Have you gathered the ore I asked for?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 34477, 34479 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25046, ["x"] = 0.506, ["y"] = 0.408 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25046, ["x"] = 0.506, ["y"] = 0.408 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.408 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11537] = { ["id"] = 11537, ["name"] = "The Battle Must Go On", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11537 }, ["description"] = "We must continue to defeat and demoralize the armies of the Legion. The emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions. The enemy rallies around them for they fear them more than they fear us. Today we will change that. Take this banner and slay the demons of the Legion. When you meet the emissary, slay and impale him.", ["objectivesText"] = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse. Progress: Have you succeeded, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 2580, ["rewardItems"] = { 34414 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25061, ["x"] = 0.475, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25061, ["x"] = 0.475, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11538] = { ["id"] = 11538, ["name"] = "The Battle for the Sun's Reach Armory", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["storyline"] = { 11538 }, ["description"] = "The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation. As long as their morale remains high we will not wrest the building from their control. The emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions. The enemy rallies around them for they fear them more than they fear us. Today we will change that. Take this banner and slay the demons of the Legion. When you meet the emissary, slay and impale him.", ["objectivesText"] = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun's Reach Armory. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", ["rewardGold"] = 105000, ["rewardXP"] = 2580, ["rewardItems"] = { 34414 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11539] = { ["id"] = 11539, ["name"] = "Taking the Harbor", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["storyline"] = { 11539 }, ["description"] = "One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village. The harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help. Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.", ["objectivesText"] = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners , 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11540] = { ["id"] = 11540, ["name"] = "Crush the Dawnblade", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11540 }, ["description"] = "We've driven the Dawnblade army out of the Sun's Reach Harbor. Sun's Reach is ours in its entirety. Yet somehow... I'm not entirely satisfied. I want you to go to Dawnstar Village, west of here, and slay any surviving Dawnblade combatants. They sealed their fate when they followed Kael to this place.", ["objectivesText"] = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners , 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25069, ["x"] = 0.495, ["y"] = 0.402 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25069, ["x"] = 0.495, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11541] = { ["id"] = 11541, ["name"] = "Disrupt the Greengill Coast", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11541 }, ["description"] = "The naga have taken the Greengill Coast to the southeast. Their females, the Darkspine sirens, are using magic to enslave the indigenous murlocs. It's my responsibility to see to it that whatever the naga are up to over there is disrupted. That's where you come in. <class>, I want you to get the controlling orbs from the female naga and throw them near the Greengill slaves, breaking the orb and setting the murlocs free. My guess is that the murlocs will be incensed and turn on their masters.", ["objectivesText"] = "Captain Valindria wants you to free 10 Greengill Slaves. Return to her onboard the Silvermoon's Pride at Sun's Reach Harbor once you have done so.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 34483 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25088, ["x"] = 0.538, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25088, ["x"] = 0.538, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11542] = { ["id"] = 11542, ["name"] = "Intercept the Reinforcements", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["storyline"] = { 11542 }, ["description"] = "We're making a push to solidify our control of Sun's Reach by capturing the harbor next. Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael's forces there. Take this oil and secure a dragonhawk from Ayren Cloudbreaker. You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire. Land in one of the ships and attack the reservists. With their ship sails on fire they won't be able to mount much of a defense.", ["objectivesText"] = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists .", ["rewardXP"] = 3440, ["rewardItems"] = { 34489 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11543] = { ["id"] = 11543, ["name"] = "Keeping the Enemy at Bay", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11543 }, ["description"] = "We've managed to capture Sun's Reach in its entirety. Unfortunately a fleet of Dawnblade reservists is on its way to take back the harbor. Take this oil and secure a dragonhawk from Ayren Cloudbreaker. You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire. Land in one of the ships and attack the reservists. With their ship sails on fire they won't be able to mount much of a defense.", ["objectivesText"] = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists .", ["rewardXP"] = 3440, ["rewardItems"] = { 34489 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25108, ["x"] = 0.505, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25108, ["x"] = 0.505, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11545] = { ["id"] = 11545, ["name"] = "A Charitable Donation", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["storyline"] = { 11545 }, ["description"] = "We've taken Sun's Reach from the enemy and our final victory is at hand. The cost was high and many brave combatants gave their lives so we could achieve this. It is my goal to ensure that those who perished in combat are not forgotten. I ask that you take a moment to consider making a donation towards a memorial fund. Any leftover gold will go to the widows and orphans of the fallen.", ["objectivesText"] = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[11546] = { ["id"] = 11546, ["name"] = "Open for Business", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11546 }, ["description"] = "Welcome, <name>. There are a number of ways I can assist you in your efforts here. For example, I've recently discovered a recipe for a unique elixir. The bloodberry grows wild in many regions of Azeroth and has long been considered nothing more than a nuisance. I've learned though, that when exposed to the Sunwell's power this plant takes on special properties that can be distilled and imbibed to magnify one's abilites. Bring me a sample from the nearby bushes and I'll show you what I mean.", ["objectivesText"] = "Mar'nah at the Sun's Reach Harbor wants you to gather 5 Bloodberries from the bushes found on Quel'Danas. Progress: Have you gathered those berries yet?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 34502, 34537 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 24975, ["x"] = 0.514, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 24975, ["x"] = 0.514, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11547] = { ["id"] = 11547, ["name"] = "Know Your Ley Lines", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11547 }, ["description"] = "Freeloaders! You all want instant gratification - never giving thought to the effort required to create even the simplest of portals. Perhaps a little education will instill a bit of gratitude for my ceaseless efforts. Take this crystal. Attune it to the Bloodcrystal to the west, at the Dawning Square portal just south of here, and at the naga shrine at Greengill Coast to the southeast. Perhaps then you'll appreciate your precious translocations....", ["objectivesText"] = "Astromancer Darnarian in the Sun's Reach Sanctum wants you to use the Astromancer's Crystal at the Bloodcrystal, the Dawning Square portal, and the naga shrine at Greengill Coast. Progress: Have you attuned the crystal yet, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 34533, 35230 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25133, ["x"] = 0.475, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25133, ["x"] = 0.475, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11548] = { ["id"] = 11548, ["name"] = "Your Continued Support", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11548 }, ["description"] = "We've built a memorial to honor those slain in battle. It's but a small consolation to the families that lost their loved ones. I am taking up a collection to aid the orphans and spouses of our war heroes. If you can spare a small donation it would go a long way.", ["objectivesText"] = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold. Progress: Do you wish to make a donation?", ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25112, ["x"] = 0.485333, ["y"] = 0.37 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25112, ["x"] = 0.485333, ["y"] = 0.37 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.485333, ["y"] = 0.37 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11549] = { ["id"] = 11549, ["name"] = "A Magnanimous Benefactor", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11549 }, ["description"] = "You've done so much for us, <name>. We greatly appreciate your assistance. You might have noticed Anchorite Ayuri's efforts outside. She has a big heart and is very convincing, but the donations do not quite add up to what she had expected. If you were to make a large contribution to her cause, I will make sure that word of your deeds in this war spreads far and wide. What do you say?", ["objectivesText"] = "Anchorite Kairthos wants you to donate 1000 gold to aid in Anchorite Ayuri's efforts. You will be known as <name> of the Shattered Sun if you complete this quest. Progress: Are you ready to make the contribution?", ["starts"] = { { ["mapID"] = 122, ["npcID"] = 25163, ["x"] = 0.512, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25163, ["x"] = 0.512, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[11550] = { ["id"] = 11550, ["name"] = "Enter, the Deceiver...", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 11550 }, ["description"] = "Despite our best efforts, Kael'thas's sinister plans have been carried out. The Sunwell has been re-ignited in preparation for the Deceiver's arrival. The object that stands before me and below A'dal is a representation of the current status of the Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the inner chambers. If ever there were a time that our world needed assistance, it would be now. Report to Archmage Ne'thul at the Isle of Quel'Danas , north of Quel'Thalas.", ["objectivesText"] = "Report to Archmage Ne'thul on the Isle of Quel'Danas , north of Quel'Thalas. Flight masters in Ironforge and Silvermoon City will get you to your destination.", ["rewardXP"] = 1030, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 25169, ["x"] = 0.501, ["y"] = 0.284 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.501, ["y"] = 0.284 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
