[11657] = { ["id"] = 11657, ["name"] = "Torch Catching", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3557, ["mapID"] = 84, ["storyline"] = { 11657 }, ["series"] = { 11731, 82087 }, ["description"] = "Now that you can throw a torch, let's see if you can catch one! Take this stack of unlit torches . Go to the bonfire and throw a torch high into the air. Catch it before it hits the ground... then throw it back up! Catch four then come back to me. Careful! They're dangerous if they hit the ground! Good luck!", ["objectivesText"] = "Catch 4 torches then speak with the Master Fire Eater . Progress: Torch catching is a lot of fun, don't you think? But have care! You don't want to get singed!", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 2459, 23247, 34599, 34833, 41375, 63388, 64670, 79249 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.7205 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[11691] = { ["id"] = 11691, ["name"] = "Summon Ahune", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["storyline"] = { 11691 }, ["series"] = { 11696 }, ["description"] = "I and my Shamans have gathered our powers for the coming battle with the Lord of Frost. <name>, you will be the fist of the Earthmother. Take this magma totem. Use it against the Ice Stone, to the northeast. Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes. If fortune is with us, then, perhaps, we can defeat him. Prepare yourself, <name>. If Ahune comes to face us, then his fury will be great.", ["objectivesText"] = "Bring the Earthen Ring Magma Totem to the Ice Stone.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 34953, 35237, 35277, 35723, 49426, 54536, 54801, 54802, 54803, 54804, 54805, 54806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[11696] = { ["id"] = 11696, ["name"] = "Ahune is Here!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["storyline"] = { 11696 }, ["series"] = { 11691 }, ["description"] = "<name>, your presence is a blessing. Ahune lies within these caverns, gathering strength for his assault. Earthen Ring forces were sent ahead, but they alone cannot defeat him. Explore, <name>. Find our Earthen Ring Shamans and speak with their leader, Luma Skymother. Perhaps, with your added strength, we can beat Ahune before it's too late.", ["objectivesText"] = "Find Luma Skymother in the Slave Pens.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["rewardItems"] = { 35237, 35277, 35723, 49426, 54536, 54801, 54802, 54803, 54804, 54805, 54806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[11731] = { ["id"] = 11731, ["name"] = "Torch Tossing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster", "timed" }, ["timerSeconds"] = 45, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3557, ["mapID"] = 84, ["storyline"] = { 11731 }, ["series"] = { 11657, 82087 }, ["description"] = "So you want to be a fire juggler? Do you have what it takes? The dexterity? The reflexes? ...the courage? If you think so, then let's give you a little practice! Take these torches and run near the bonfire. You'll see braziers with markers flashing above them. Toss a torch at a marked brazier. Be quick! Do it before the mark fades if you want credit for the toss! Hit enough marked braziers before the time limit, then come back here... for your next lesson.", ["objectivesText"] = "Win the torch tossing game, then speak with the Master Fire Eater . Progress: Quick! There's no time to waste!", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 34599, 34862 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.7205 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
