[11875] = { ["id"] = 11875, ["name"] = "Gaining the Advantage", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 11875 }, ["description"] = "The troops of the Shattered Sun Offensive will need every advantage they can get to beat back the allies of Kil'Jaeden. My colleagues in Stormwind have created oils which will strengthen the blades and armor of our troops. The key ingredient, nether residue , pervades Outland -- if you know where to look. Any master herbalist, skinner, or miner who knows the signs can gather it while plying <his/her> trade. Those herbs, ores, and beasts native to Outland may all bear the residue.", ["objectivesText"] = "Bring 8 Nether Residue to Emissary Mordin in Shattrath City . Progress: Have you any residue for me?", ["rewardGold"] = 619600, ["rewardXP"] = 3440, ["rewardItems"] = { 18253, 35229 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 19202, ["x"] = 0.5645, ["y"] = 0.37825 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 19202, ["x"] = 0.5645, ["y"] = 0.37825 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.5645, ["y"] = 0.37825 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11882] = { ["id"] = 11882, ["name"] = "Playing with Fire", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 5287, ["mapID"] = 14, ["storyline"] = { 11882 }, ["description"] = "Are you interested in learning some hot new skills? I don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Fire Eater at any Alliance capital. They should be able to help you.", ["objectivesText"] = "Speak to a Master Fire Eater in any Alliance capital.", ["rewardGold"] = 202200, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 25962, ["x"] = 0.442, ["y"] = 0.452 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 14, 84 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[11886] = { ["id"] = 11886, ["name"] = "Unusual Activity", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 331, ["mapID"] = 18, ["storyline"] = { 11886 }, ["series"] = { 11891 }, ["description"] = "While celebration has its place, <class>, some of us must look to graver matters. When the festival began, we received reports from Zoram Strand about a sharp increase in Twilight Cult activity. The origins of this holiday are steeped in the very powers those madmen revere; this cannot be coincidence. Go to the camp just south of the Blackfathom Deeps entrance, in the ruins, and see if the cultists will part with information - forcefully if need be. Use this beacon to summon a guide when you find it.", ["objectivesText"] = "Go to the new Twilight Camp south of the Blackfathom Deeps entrance on the Zoram Strand of Ashenvale and retrieve Twilight Correspondence from the cultists, then call upon the Earthen Ring Guide using the Totemic Beacon . Progress: What have you uncovered?", ["rewardXP"] = 200, ["rewardItems"] = { 23247, 35237, 35277, 35723, 35828, 49426, 54536, 54801, 54802, 54803, 54804, 54805, 54806 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 25324, ["x"] = 0.133659, ["y"] = 0.17678 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 18, 63 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 111 },
[11891] = { ["id"] = 11891, ["name"] = "An Innocent Disguise", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 11891 }, ["series"] = { 11886 }, ["description"] = "According to this, it seems there is another encampment of the cultists to the northwest of the large gathering on the Zoram Strand, and they are speaking with... guests? Much could be learned from listening to these proceedings, <race>. Take this orb; it will allow you to appear as one of the native crawlers on the beach. Spy on the conversation with these \"guests\" of the cultists at the northwestern camp and report back to me when you are successful.", ["objectivesText"] = "Use the Orb of the Crawler to spy upon the new Twilight camp to the west of the Blackfathom Deeps entrance on the Zoram Strand in Ashenvale, then summon the Earthen Ring Guide using the Totemic Beacon. Progress: Have you learned their secrets?", ["rewardXP"] = 200, ["rewardItems"] = { 23247, 35237, 35277, 35723, 49426, 54536, 54801, 54802, 54803, 54804, 54805, 54806 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 25324, ["x"] = 0.133659, ["y"] = 0.17678 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 25324, ["x"] = 0.133659, ["y"] = 0.17678 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.133659, ["y"] = 0.17678 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[11905] = { ["id"] = 11905, ["name"] = "Postponing the Inevitable", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4265, ["mapID"] = 114, ["storyline"] = { 11905 }, ["description"] = "Azeroth's ley lines are being redirected to the Nexus. The influx of arcane energies is tearing a rift between dimensions. I cannot stop it, but I've discovered a way to slow it down. Take this and activate it near the forming rift.", ["objectivesText"] = "Image of Warmage Kaitlyn in the Nexus wants you to use the Interdimensional Refabricator near the rift. Progress: Have you been to the rift?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 35479, 42758, 42761, 42763, 42765 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 25314, ["x"] = 0.33, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 25314, ["x"] = 0.33, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 4265 } }, ["questType"] = "dungeon" },
[11911] = { ["id"] = 11911, ["name"] = "Quickening", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4265, ["mapID"] = 114, ["storyline"] = { 11911 }, ["description"] = "I've learned more in my short time here than in decades of studies. The ancients here are being exposed to incredible levels of arcane energy. It's literally transforming them into something... I'm confident that there's a final stage in their metamorphosis. Find me some evidence of their final state.", ["objectivesText"] = "Image of Warmage Kaitlyn in the Nexus wants you to collect 5 Arcane Splinters from Crystalline Protectors. Progress: The crystalline ancients... Do they exist?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 35490, 42760, 42762, 42766, 42767, 42768 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 25314, ["x"] = 0.33, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 25314, ["x"] = 0.33, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 4265 } }, ["questType"] = "dungeon" },
[11915] = { ["id"] = 11915, ["name"] = "Playing with Fire", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 85, ["mapID"] = 1, ["storyline"] = { 11915 }, ["description"] = "Are you interested in learning some hot new skills? I don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Flame Eater at any Horde capital. They should be able to help you.", ["objectivesText"] = "Speak to a Master Flame Eater in any Horde capital.", ["rewardGold"] = 202200, ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 25994, ["x"] = 0.524, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26113, ["x"] = 0.624, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1, 18 }, ["zone"] = { 85 } }, ["questType"] = "standard" },
[11917] = { ["id"] = 11917, ["name"] = "Striking Back", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3703, ["mapID"] = 18, ["storyline"] = { 11917 }, ["description"] = "We must act to preserve the balance! Time is against us. Return to the camp on the Zoram Strand with the large ice stones. They use them to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", ["objectivesText"] = "Slay the Frostwave Lieutenant summoned from the Ice Stone located on Zoram Strand in Ashenvale, then return to the Earthen Ring Elder in a capital city.", ["rewardGold"] = 65525, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 65360, 140192 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11921] = { ["id"] = 11921, ["name"] = "More Torch Tossing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily", "timed" }, ["timerSeconds"] = 90, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3557, ["mapID"] = 84, ["storyline"] = { 11921 }, ["description"] = "Hello, fire juggler! Are you having fun and making fiery mayhem? That's what I like to hear! Now, do you think you're an expert at torch tossing? Then I have a test for you... You know the rules: toss torches at the marked braziers. This time, however, you have a little more time and a LOT more braziers to hit. Ready?", ["objectivesText"] = "Win the torch tossing game, then speak with the Master Fire Eater .", ["rewardGold"] = 292100, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 34862 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.7205 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
[11922] = { ["id"] = 11922, ["name"] = "Torch Tossing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster", "timed" }, ["timerSeconds"] = 45, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3487, ["mapID"] = 18, ["storyline"] = { 11922 }, ["series"] = { 11923, 82105 }, ["description"] = "So you want to be a fire juggler? Do you have what it takes? The dexterity? The reflexes? ...the courage? If you think so, then let's give you a little practice! Take these torches and run near the bonfire. You'll see braziers with markers flashing above them. Toss a torch at a marked brazier. Be quick! Do it before the mark fades if you want credit for the toss! Hit enough marked braziers before the time limit, then come back here... for your next lesson.", ["objectivesText"] = "Win the torch tossing game, then speak with the Master Flame Eater . Progress: Quick! There's no time to waste!", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 34599, 34862 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26113, ["x"] = 0.624, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26113, ["x"] = 0.624, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3487 } }, ["questType"] = "standard" },
[11923] = { ["id"] = 11923, ["name"] = "Torch Catching", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3487, ["mapID"] = 18, ["storyline"] = { 11923 }, ["series"] = { 11922, 82105 }, ["description"] = "Now that you can throw a torch, let's see if you can catch one! Take this stack of unlit torches . Go to the bonfire and throw a torch high into the air. Catch it before it hits the ground... then throw it back up! Catch four then come back to me. Careful! They're dangerous if they hit the ground! Good luck!", ["objectivesText"] = "Catch 4 torches in a row, then speak with the Master Flame Eater . Progress: Torch catching is a lot of fun, don't you think? But have care! You don't want to get singed!", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 13000, 23247, 34599, 34833 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26113, ["x"] = 0.624, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26113, ["x"] = 0.624, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3487 } }, ["questType"] = "standard" },
[11924] = { ["id"] = 11924, ["name"] = "More Torch Catching", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3557, ["mapID"] = 84, ["storyline"] = { 11924 }, ["description"] = "Torch catching sure keeps you on your toes. Think you can keep it up for a long time? Let's see...", ["objectivesText"] = "Catch 10 torches then speak with the Master Fire Eater . Progress: Torch catching is a lot of fun, don't you think? But have care! You don't want to get singed!", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 2459, 23247, 34833, 41375 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 25975, ["x"] = 0.4985, ["y"] = 0.7205 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4985, ["y"] = 0.7205 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 3557 } }, ["questType"] = "standard" },
