[11933] = { ["id"] = 11933, ["name"] = "Stealing the Exodar's Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 11933 }, ["description"] = "This flame, stolen from the heart of the Exodar itself, floods you with warmth. This raw power is foreign to you, but the Talespinner might know more...", ["objectivesText"] = "Return the Flame of the Exodar to the Festival Talespinner . Progress: You're practically glowing, <race>. What do you have there?", ["rewardGold"] = 196575, ["rewardXP"] = 150, ["rewardItems"] = { 23211, 23246, 23247, 23326, 23327, 23435, 34684, 35569, 42898 }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 16818, ["x"] = 0.62, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["startItems"] = { 35569 } },
[11935] = { ["id"] = 11935, ["name"] = "Stealing Silvermoon's Flame", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 11935 }, ["description"] = "This flame, stolen from Silvermoon, floods you with warmth. This raw power is foreign to you, but the Loremaster might know more...", ["objectivesText"] = "Return the Flame of Silvermoon to the Festival Loremaster . Progress: You're practically glowing, <race>. What do you have there?", ["rewardGold"] = 216900, ["rewardXP"] = 150, ["rewardItems"] = { 23211, 23246, 23247, 23326, 23327, 23435, 34684, 35568, 104299, 119093 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 16817, ["x"] = 0.4948, ["y"] = 0.7188 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4948, ["y"] = 0.7188 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 35568 } },
[11947] = { ["id"] = 11947, ["name"] = "Striking Back", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3703, ["mapID"] = 18, ["storyline"] = { 11947 }, ["description"] = "We must act to preserve the balance! Time is against us. There is a camp located in the shadow of Ethel Rethor within northwestern Desolace. There, they use ice stones to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", ["objectivesText"] = "Slay the Hailstone Lieutenant summoned from the Ice Stone located at Ethel Rethor in Desolace, then return to the Earthen Ring Elder in a capital city.", ["rewardGold"] = 77400, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 140192 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11948] = { ["id"] = 11948, ["name"] = "Striking Back", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3703, ["mapID"] = 18, ["storyline"] = { 11948 }, ["description"] = "We must act to preserve the balance! Time is against us. Neptulon has long had a base of operations on an island in western Stranglethorn. There, the Twilight Cult has set up ice stones to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", ["objectivesText"] = "Slay the Chillwind Lieutenant summoned from the Ice Stone located on the water elemental's island in western Stranglethorn Vale, then return to the Earthen Ring Elder in a capital city.", ["rewardGold"] = 77400, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 140192 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11952] = { ["id"] = 11952, ["name"] = "Striking Back", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3703, ["mapID"] = 18, ["storyline"] = { 11952 }, ["description"] = "We must act to preserve the balance! Time is against us. Firewatch Ridge in Searing Gorge is an established bastion of Twilight Cult activity. Recently, they have been using ice stones in the cave to communicate with the Tidehunter's realm, much like they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", ["objectivesText"] = "Slay the Frigid Lieutenant summoned from the Ice Stone located in the cave underneath Firewatch Ridge in the northwest of Searing Gorge, then return to the Earthen Ring Elder in a capital city.", ["rewardGold"] = 77400, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 140192 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11953] = { ["id"] = 11953, ["name"] = "Striking Back", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3703, ["mapID"] = 18, ["storyline"] = { 11953 }, ["description"] = "We must act to preserve the balance! Time is against us. Silithus is the Azerothian base of the Twilight Cult. In the north, they have been using new ice stones to communicate with the Tidehunter's realm. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", ["objectivesText"] = "Slay the Glacial Lieutenant summoned from the Ice Stone located at Twilight's Run in northern Silithus, then return to the Earthen Ring Elder in a capital city.", ["rewardGold"] = 77400, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 140192 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11954] = { ["id"] = 11954, ["name"] = "Striking Back", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3703, ["mapID"] = 18, ["storyline"] = { 11954 }, ["description"] = "We must act to preserve the balance! Time is against us. In order to ensure Ahune's success, the cult has established a base near the Dark Portal itself in Draenor. They use ice stones to coordinate the frost lord's arrival. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's templar protectors and destroy it. Perhaps this forestalling action will be enough...", ["objectivesText"] = "Slay the Glacial Templar summoned from the Ice Stone located near the Dark Portal in Hellfire Peninsula, then return to the Earthen Ring Elder in a capital city. Progress: You have returned victorious?", ["rewardGold"] = 73700, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 63352, 140192 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[11955] = { ["id"] = 11955, ["name"] = "Ahune, the Frost Lord", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["storyline"] = { 11955 }, ["description"] = "I believe you are strong enough for the ultimate task set before us. We cannot allow the plot between the Twilight Cult and the naga heretics of Neptulon to come to fruition. For the sake of Azeroth and all life upon it, we must act. Our path is clear. You must journey to the Slave Pens deep within Coilfang Reservoir and meet with our shaman there. Go, and quickly!", ["objectivesText"] = "Travel to the Slave Pens in Coilfang Reservoir within Zangarmarsh and speak with Numa Cloudsister.", ["rewardXP"] = 100, ["rewardItems"] = { 35237, 35277, 35498, 35723, 49426, 53641, 54536, 54801, 54802, 54803, 54804, 54805, 54806, 95425, 95426, 95427, 95428, 95429, 95430, 117375 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[11964] = { ["id"] = 11964, ["name"] = "Incense for the Summer Scorchlings", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3703, ["mapID"] = 84, ["storyline"] = { 11964 }, ["description"] = "Did you know that our festival fires burn in every land with an Alliance settlement? Flame Wardens tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue. With each Flame Warden is a summer scorchling -- an emissary to the elemental spirits of fire. Would you like to honor a scorchling, <name>? Take this summer incense and bring it to any summer scorchling . Appease the little fire spirit, and it may reward you.", ["objectivesText"] = "The Festival Loremaster wants you to take Summer Incense to a Summer Scorchling outside any Alliance settlement. Progress: A fiery salutations to you, honored <class>. Welcome to this hallowed ground of the Midsummer Fire Festival.", ["rewardXP"] = 25, ["rewardItems"] = { 23247, 35725 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 16817, ["x"] = 0.4948, ["y"] = 0.7188 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 26401, ["x"] = 0.442, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.4948, ["y"] = 0.7188 }, ["mapCandidates"] = { ["npc"] = { 14, 84 }, ["zone"] = { 3703 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 111 },
[11966] = { ["id"] = 11966, ["name"] = "Incense for the Festival Scorchlings", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 11966 }, ["description"] = "Did you know that our festival fires burn in every land with a Horde settlement? Flame Keepers tend to them in camps outside of each town, ensuring the bonfires are bright and the celebrations continue. With each Flame Keeper is a festival scorchling -- an emissary to the elemental spirits of fire. Would you like to honor a scorchling, <name>? Take this summer incense and bring it to any festival scorchling . Appease the little fire spirit, and it may reward you.", ["objectivesText"] = "The Festival Talespinner wants you to take Summer Incense to a Festival Scorchling outside any Horde settlement. Progress: A fiery salutations to you, honored <class>. Welcome to this hallowed ground of the Midsummer Fire Festival.", ["rewardXP"] = 25, ["rewardItems"] = { 23247, 35725 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 16818, ["x"] = 0.62, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 26520, ["x"] = 0.522, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 1, 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 111 },
[11970] = { ["id"] = 11970, ["name"] = "The Master of Summer Lore", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 1537, ["mapID"] = 84, ["storyline"] = { 11970 }, ["description"] = "There should be no mistake, the festival is a time for fun and laughter! However it is important that you understand the origins of this holiday. Education should be sought out and savored! . The Festival Loremaster in the Alliance capitals can guide your way. Go now and learn!", ["objectivesText"] = "Speak to the Festival Loremaster in any Alliance capital.", ["rewardXP"] = 25, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 18927, ["x"] = 0.628143, ["y"] = 0.557571 }, { ["mapID"] = 87, ["npcID"] = 19148, ["x"] = 0.3115, ["y"] = 0.665625 }, { ["mapID"] = 103, ["npcID"] = 19171, ["x"] = 0.571375, ["y"] = 0.437 }, { ["mapID"] = 87, ["npcID"] = 19172, ["x"] = 0.575333, ["y"] = 0.489333 }, { ["mapID"] = 89, ["npcID"] = 19173, ["x"] = 0.445, ["y"] = 0.529 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 16817, ["x"] = 0.4948, ["y"] = 0.7188 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.628143, ["y"] = 0.557571 }, ["mapCandidates"] = { ["npc"] = { 10, 84, 87, 89, 103 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[11971] = { ["id"] = 11971, ["name"] = "The Spinner of Summer Tales", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 1, ["zoneID"] = 1637, ["mapID"] = 94, ["storyline"] = { 11971 }, ["description"] = "Let there be no mistake, the festival is a time for fun and laughter! However it's important that you understand the origins of this holiday. Education should be sought out and savored! . The Festival Talespinner in the Horde capitals can guide your way. Go now and learn.", ["objectivesText"] = "Speak to the Festival Talespinner in any Horde capital.", ["rewardXP"] = 25, ["rewardItems"] = { 23247 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 19169, ["x"] = 0.542, ["y"] = 0.508 }, { ["mapID"] = 85, ["npcID"] = 19175, ["x"] = 0.545667, ["y"] = 0.709667 }, { ["mapID"] = 85, ["npcID"] = 19176, ["x"] = 0.402, ["y"] = 0.5615 }, { ["mapID"] = 85, ["npcID"] = 19177, ["x"] = 0.440857, ["y"] = 0.667714 }, { ["mapID"] = 90, ["npcID"] = 19178, ["x"] = 0.648923, ["y"] = 0.442154 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 16818, ["x"] = 0.62, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 10, 18, 85, 90, 94 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[11972] = { ["id"] = 11972, ["name"] = "Shards of Ahune", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 3717, ["storyline"] = { 11972 }, ["description"] = "These shards pulse with foreboding. Do they hold the last essence of the Frost Lord?", ["objectivesText"] = "Bring the Ice Shards to Luma Skymother . Progress: Greetings, <name>. You look worried, but you shoud rejoice. The Frost Lord is defeated!", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 23247, 35279, 35280, 35723 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3717 } }, ["questType"] = "standard", ["startItems"] = { 35723 } },
[11973] = { ["id"] = 11973, ["name"] = "Prisoner of War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4265, ["mapID"] = 114, ["storyline"] = { 11973 }, ["description"] = "Malygos has taken Keristrasza to serve as his consort! We cannot allow this to come to pass. You must do whatever it takes to spare her such a fate, <race>.", ["objectivesText"] = "Warmage Kaitlyn wants you to free Keristrasza . Progress: Were you able to free her from her bonds?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 35648, 35668, 35669, 35671, 35685, 35690, 35709, 38221, 38222, 38223, 43665, 44950 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 26117, ["x"] = 0.332, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 26117, ["x"] = 0.332, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 4265 } }, ["questType"] = "dungeon" },
[11975] = { ["id"] = 11975, ["name"] = "Now, When I Grow Up...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["storyline"] = { 11975 }, ["description"] = "Maybe I already asked you this, but when you were my age did you know that you wanted to be a <class> when you grew up? I'm not sure what I want to be. Maybe a mage or a warlock or a Blood Knight, like I said before? Or maybe... A rock star!! Like Sig Nicious, the blood elf, in the Tauren Chieftains! I heard that when they aren't touring, they hang out in Silvermoon City! They just sit on a balcony in the Walk of Elders waiting for people to stop by. Please take me there. Please!", ["objectivesText"] = "Take your orphan, Salandria, to see the Tauren Chieftains in Silvermoon City's Walk of Elders. Make sure to call for her if she is not present when you arrive. Progress: Elite Tauren Chieftain are the coolest!", ["rewardXP"] = 1415, ["rewardItems"] = { 31880, 31951, 32616, 32617, 32622, 69648, 116202 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2VignetteID"] = 7546, ["db2VignetteName"] = "The Tauren Chieftains" },
[12012] = { ["id"] = 12012, ["name"] = "Inform the Elder", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Midsummer Fire Festival", ["expansion"] = 2, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 12012 }, ["description"] = "This information must be spread to the entirety of the Earthen Ring. I'm not certain how to proceed, but the elder who set you on this task in the first place may. Please, return to the elder and seek the next course of action - we must do something!", ["objectivesText"] = "Travel to a capital city and speak to the Earthen Ring Elder .", ["rewardXP"] = 100, ["rewardItems"] = { 35237, 35277, 35723, 35828, 49426, 54536, 54801, 54802, 54803, 54804, 54805, 54806 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 25324, ["x"] = 0.133659, ["y"] = 0.17678 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 26221, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.133659, ["y"] = 0.17678 }, ["mapCandidates"] = { ["npc"] = { 18, 63 }, ["zone"] = { 331 } }, ["questType"] = "standard" },
[12020] = { ["id"] = 12020, ["name"] = "This One Time, When I Was Drunk...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 12020 }, ["description"] = "The Dark Irons took a beating! As they rushed back to the Grim Guzzler, a portion of their transport fell off. More importantly, you managed to keep the camp safe... today. Head over to Boxey and explain your heroic triumph over the Dark Iron dwarves.", ["objectivesText"] = "Talk to Boxey Boltspinner in the Brewfest camp.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 27215, ["x"] = 0.502, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[12022] = { ["id"] = 12022, ["name"] = "Chug and Chuck!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 12022 }, ["description"] = "Hey there! You look like you can handle your brew. But can you handle your brew mug? We like to keep things lively around camp, and nothing says fun like a good old-fashioned mug toss! Think you've got the aim to hit S.T.O.U.T.? Just grab a sampler, take a sip, and see if you can land a hit. It's trickier than it looks, but that's half the fun. Step right up and give it a shot!", ["objectivesText"] = "Use the Alcohol-Free Brewfest Sampler to hit S.T.O.U.T. 5 times. Progress: Toss one back, then toss one forward. S.T.O.U.T. can take the abuse, it's why I built him.", ["rewardGold"] = 140450, ["rewardXP"] = 100, ["rewardItems"] = { 33096, 37829, 169219 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 27215, ["x"] = 0.502, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 27215, ["x"] = 0.502, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[12037] = { ["id"] = 12037, ["name"] = "Search and Rescue", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 394, ["mapID"] = 116, ["storyline"] = { 12037 }, ["series"] = { 12029, 13129 }, ["description"] = "Orcs... they just don't lissen <hic>. Know what I mean, <race>? Kurzel", ["objectivesText"] = "Mack at Granite Springs wants you to go into Drak'Tharon and find out what became of Kurzel .", ["rewardGold"] = 1123600, ["rewardXP"] = 4180, ["rewardItems"] = { 39648, 39649, 39650, 141940, 237812 }, ["starts"] = { { ["mapID"] = 116, ["npcID"] = 26604, ["x"] = 0.166, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.166, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 394 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Battle Pets" },
[12133] = { ["id"] = 12133, ["name"] = "Smash the Pumpkin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3524, ["mapID"] = 27, ["storyline"] = { 12133 }, ["description"] = "This large jack-o'-lantern rests in the middle of the village. It eyes those who look upon it, betraying a dark menace within. Smashing the pumpkin reveals an old, scorched holy symbol .", ["objectivesText"] = "Give the Scorched Holy Symbol to the Costumed Orphan Matron . Progress: Yes, <name>?", ["rewardXP"] = 1415, ["rewardItems"] = { 34077, 36876 }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
[12135] = { ["id"] = 12135, ["name"] = "\"Let the Fires Come!\"", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["event"] = "Hallow's End", ["expansion"] = 2, ["zoneID"] = 3524, ["mapID"] = 27, ["storyline"] = { 12135 }, ["description"] = "You must help us! The Headless Horseman will attack the village at any moment! Fires will be everywhere! The children aren't safe! Please, <name>, will you face the fires of the Headless Horseman? When he comes, you must join the fire brigade. Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze. If you put out all the fires then we may yet be saved!", ["objectivesText"] = "The Costumed Orphan Matron wants you to help put out all the village fires after the Headless Horseman lights them. When they are out, speak again to the Costumed Orphan Matron .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 33154, 33226, 34068, 34077 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 24519, ["x"] = 0.532, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 3524 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2764 } },
