[12172] = { ["id"] = 12172, ["name"] = "Attunement to Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 12172 }, ["description"] = "Welcome, mage. By now you must be wondering where Dalaran is and how to get there. I will help you. But before I can teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you risk destroying yourself in the process. Take this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the west. Then you will be ready to learn the spell.", ["objectivesText"] = "The Image of Archmage Modera at Stars' Rest has asked you to become Attuned to the Ley Lines of Northrend.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 37006 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 26673, ["x"] = 0.29, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26673, ["x"] = 0.29, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard" },
[12173] = { ["id"] = 12173, ["name"] = "Attunement to Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 8 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 12173 }, ["description"] = "Hello, mage. By now you must be wondering where Dalaran is and how to get there. I can help you with this if you can survive a simple test. Before I teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you will destroy yourself in the process! Take this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the southwest. Then you will be ready to learn what I have to teach.", ["objectivesText"] = "The Image of Archmage Aethas Sunreaver at Agmar's Hammer has asked you to become Attuned to the Ley Lines of Northrend.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 37006 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 26471, ["x"] = 0.38, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26471, ["x"] = 0.38, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard" },
[12189] = { ["id"] = 12189, ["name"] = "Imbeciles Abound!", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 12189 }, ["series"] = { 12181, 12182, 12188, 12200, 12218, 12221 }, ["description"] = "The shipment from New Agamand was to arrive at Venomspite last week and then be delivered to me after some simple field tests. It is a Horde imperative - the last piece of the \"victory puzzle.\" <Sintar sighs.> It is quite disheartening to know that you are surrounded by imbeciles and incompetent boobs! You must travel to Venomspite, near the eastern border of Dragonblight . Find that buffoon, Middleton, and let him know that I am waiting on the package.", ["objectivesText"] = "Travel to Venomspite in Dragonblight and speak with Chief Plaguebringer Middleton .", ["rewardXP"] = 525, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 26505, ["x"] = 0.36, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 27172, ["x"] = 0.776, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.36, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard" },
[12191] = { ["id"] = 12191, ["name"] = "Chug and Chuck!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 12191 }, ["description"] = "Hey, you look like you've got a good arm! We like to keep things lively around camp, and nothing says fun like a good old-fashioned mug toss! Think you've got the aim to hit S.T.O.U.T.? Just grab a sampler, take a sip, and see if you can land a hit. It's trickier than it looks, but that's half the fun. Step right up and give it a shot!", ["objectivesText"] = "Use the Alcohol-Free Brewfest Sampler to hit S.T.O.U.T. 5 times. Progress: Chug from the mug, then chuck the mug at S.T.O.U.T. I think he can withstand the pounding. I wouldn't have stol.. er... built him if he couldn't!", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 37829 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 27216, ["x"] = 0.499, ["y"] = 0.222333 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 27216, ["x"] = 0.499, ["y"] = 0.222333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.499, ["y"] = 0.222333 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[12192] = { ["id"] = 12192, ["name"] = "This One Time, When I Was Drunk...", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["event"] = "Brewfest", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 12192 }, ["description"] = "The Dark Irons took a beating! As they rushed back to the Grim Guzzler, a portion of their transport fell off. More importantly, you managed to keep the camp safe... today. Head over to Bizzle and explain your heroic triumph over the Dark Iron dwarves.", ["objectivesText"] = "Talk to Bizzle Quicklift in the Brewfest camp.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 37829, 62675 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 27216, ["x"] = 0.499, ["y"] = 0.222333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.499, ["y"] = 0.222333 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
