[12750] = { ["id"] = 12750, ["name"] = "A Special Surprise", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 6 }, ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13189, 28650 }, ["series"] = { 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12751, 28649, 28650 }, ["description"] = "We got here, tore the place apart, and headed toward the prison house. We weren't expecting what we found in there, <name>. Seems the Crusade's been real busy. That whole thing is full of Argent Dawn prisoners. Most of them were already dead by the time we arrived, but a few were still breathing. I was about to go in there and execute the rest of them, but I think you should have the honors. In particular, there's a real feisty Forsaken in there that I think you'll take great pleasure in executing.", ["objectivesText"] = "Knight Commander Plaguefist at the Chapel of the Crimson Flame has ordered you to execute Antoine Brack , an Argent Dawn prisoner inside the nearby prison house.", ["rewardGold"] = 105000, ["rewardXP"] = 1720, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 39, ["flags"] = 0 } } },
[12751] = { ["id"] = 12751, ["name"] = "A Sort Of Homecoming", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 28649, 28650 }, ["description"] = "Return to Thassarian at the Scarlet Tavern and let him know that Koltira's cry for vengeance has been answered. The Chapel of the Crimson Flame will be a pile of ashes in a matter of hours. You're one cold-blooded monster, <name>. I salute you, <brother/sister>.", ["objectivesText"] = "Return to Thassarian at the Scarlet Tavern in New Avalon with news of your victory.", ["rewardGold"] = 48350, ["rewardXP"] = 1720, ["rewardItems"] = { 38675 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 45, ["flags"] = 0 } } },
[12754] = { ["id"] = 12754, ["name"] = "Ambush At The Overlook", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12755, 12756, 12757 }, ["description"] = "While you were out burning churches and murdering vermin, I've been busy formulating a plan. The Scarlet courier is scheduled to pass by the Scarlet Overlook within the hour. The roads by the overlook are wide open and swarming with Crusaders. Use this makeshift cover to hide at the overlook and wait for the Scarlet Courier to pass. When he's close enough, strike with all your fury! Cut him down and take his belongings - including his clothes! The overlook is 200 paces east of here.", ["objectivesText"] = "Orbaz Bloodbane at the Scarlet Tavern in New Avalon has ordered you to kill the Scarlet Courier and retrieve the Scarlet Courier's Belongings and the Scarlet Courier's Message . Progress: You're going to miss the courier and then I'm going to be forced to kill you. By forced I mean I will take great pleasure in ending your life. HURRY UP!", ["rewardGold"] = 105000, ["rewardXP"] = 1720, ["rewardItems"] = { 39645, 39646, 39647 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 46, ["flags"] = 0 } } },
[12755] = { ["id"] = 12755, ["name"] = "A Meeting With Fate", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12754, 12756, 12757 }, ["description"] = "This message must reach Abbendis. We do not want to draw their suspicion. They must continue under the assumption that everything is going as they planned. You will don the Scarlet courier's clothes and with the help of some dark magic, take on the form of the courier. Abbendis is at King's Harbor, southeast of the Scarlet Overlook. Drop off the message and get as much information out of her as you can. She will tell us what we need to know about the \"Crimson Dawn.\"", ["objectivesText"] = "Orbaz Bloodbane has commanded you to deliver the Scarlet Courier's Message to High General Abbendis at King's Harbor. Progress: Where have you been? You are two hours late. We were about to send a courier out to the High Commander.", ["rewardXP"] = 1720, ["rewardItems"] = { 39647 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 47, ["flags"] = 0 } } },
[12756] = { ["id"] = 12756, ["name"] = "The Scarlet Onslaught Emerges", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12754, 12755, 12757 }, ["description"] = "Listen well, courier. The Scarlet lands are lost. New Avalon and Havenshire are overrun by Scourge. The specter of death looms overhead and threatens to overtake us at any moment. Return to Galvar with this message: \"Turn your armies around and prepare your ships for travel to the frozen wastes. When next we meet it will be in Northrend.\" Give this to Galvar. <Abbendis hands you a journal.> It will explain everything. The Scarlet Crusade is no more. Long live the Scarlet Onslaught!", ["objectivesText"] = "Deliver The Path of Redemption to Orbaz Bloodbane at the Scarlet Tavern in New Avalon. Progress: <Orbaz laughs.> What is this? Some child's coloring book?", ["rewardGold"] = 105000, ["rewardXP"] = 1720, ["rewardItems"] = { 39654 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 48, ["flags"] = 0 } } },
[12757] = { ["id"] = 12757, ["name"] = "Scarlet Armies Approach...", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12754, 12755, 12756 }, ["description"] = "We must prepare for the encroaching armies, <name>. You will take what you have discovered to Highlord Mograine at once! I will open a portal directly to Acherus. Step inside and it will transport you. Give Highlord Mograine Abbendis' journal as well. Perhaps he'll find it useful.", ["objectivesText"] = "Deliver The Path of Redemption to Highlord Darion Mograine at Acherus: The Ebon Hold. Progress: You did what?", ["rewardGold"] = 315000, ["rewardXP"] = 2290, ["rewardItems"] = { 38663, 39654 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 49, ["flags"] = 0 } } },
[12778] = { ["id"] = 12778, ["name"] = "The Scarlet Apocalypse", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12779, 12800 }, ["description"] = "The trap has been sprung, death knight. The armies of Hearthglen and Tirisfal have arrived, just in time to see their enclave in flames! If they turn back now, they fight us with their backs turned. <Mograine shakes his head.> No, they have only one option, which has only one outcome: APOCALYPSE! As we speak, they prepare to make one final stand. The Lich King awaits your return, champion. He stands watch below us, at Death's Breach.", ["objectivesText"] = "Seek out the Lich King at Death's Breach.", ["rewardXP"] = 145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 50, ["flags"] = 0 } } },
[12779] = { ["id"] = 12779, ["name"] = "An End To All Things...", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12778, 12800 }, ["description"] = "You have slaughtered legions beyond number and still your dark heart craves more. Your hunger knows no end, <name>. < The Lich King pauses.> There must come an end to all things, death knight. The Scarlet armies make their final stand against us. For them, there is no escape... no choice. And for this reason they will fight with a ferocity that you have yet to witness. Use this horn to call forth one of my wyrms. Climb upon its back and command it into battle. With it you will end the Scarlet Crusade.", ["objectivesText"] = "The Lich King has commanded you to eradicate the Scarlet Crusade. Use the Horn of the Frostbrood to call forth a Frostbrood Vanquisher and with it slay 150 Scarlet Soldiers and destroy 10 Scarlet Ballistas . Avoid incoming projectiles by moving out of their line of fire! Progress: Kill them all...", ["rewardGold"] = 315000, ["rewardXP"] = 2290, ["rewardItems"] = { 38661, 39700 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 51, ["flags"] = 0 } } },
[12790] = { ["id"] = 12790, ["name"] = "Learning to Leave and Return: the Magical Way", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 12790 }, ["series"] = { 12791, 12794, 12796, 39210 }, ["description"] = "Just in case you don't already know, you can use the crystal on the platform behind me to teleport to the Violet Stand in Crystalsong Forest beneath Dalaran . Correspondingly, you can use the crystal at the stand below to return to the chamber above me. I would like for you to do this now.", ["objectivesText"] = "Archmage Celindra at The Violet Gate in Dalaran wants you to use the Teleport to Violet Stand Crystal and the Teleport to Dalaran Crystal . Progress: I sense that you haven't yet tested out both of the teleport crystals. That's alright, take your time.", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[12791] = { ["id"] = 12791, ["name"] = "The Magical Kingdom of Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 12791 }, ["series"] = { 12790, 12794, 12796, 39210 }, ["description"] = "Hello, <name>. You may or may not be aware that we Kirin Tor moved our city here to Northrend. No longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest. We believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there. When you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", ["objectivesText"] = "Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran . Progress: Greetings, <class>.", ["rewardXP"] = 175, ["rewardItems"] = { 39740 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 26471, ["x"] = 0.38, ["y"] = 0.462 }, { ["mapID"] = 114, ["npcID"] = 29155, ["x"] = 0.415, ["y"] = 0.535 }, { ["mapID"] = 117, ["npcID"] = 29159, ["x"] = 0.794, ["y"] = 0.294 }, { ["mapID"] = 116, ["npcID"] = 29160, ["x"] = 0.206, ["y"] = 0.642 }, { ["mapID"] = 115, ["npcID"] = 29162, ["x"] = 0.768, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 114, 115, 116, 117 }, ["zone"] = { 65 } }, ["questType"] = "standard" },
[12794] = { ["id"] = 12794, ["name"] = "The Magical Kingdom of Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 65, ["mapID"] = 117, ["storyline"] = { 12794 }, ["series"] = { 12790, 12791, 12796, 39210 }, ["description"] = "Hello, <name>. You may or may not be aware that we Kirin Tor moved our city here to Northrend. No longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest. We believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there. When you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", ["objectivesText"] = "Deliver the Kirin Tor Signet to Archmage Celindra at the Violet Gate in Dalaran . Progress: Greetings, <class>.", ["rewardXP"] = 175, ["rewardItems"] = { 39740 }, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 23729, ["x"] = 0.586, ["y"] = 0.626 }, { ["mapID"] = 115, ["npcID"] = 26673, ["x"] = 0.29, ["y"] = 0.555 }, { ["mapID"] = 115, ["npcID"] = 27158, ["x"] = 0.788, ["y"] = 0.452 }, { ["mapID"] = 114, ["npcID"] = 29158, ["x"] = 0.585, ["y"] = 0.682 }, { ["mapID"] = 116, ["npcID"] = 29161, ["x"] = 0.32, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 114, 115, 116, 117 }, ["zone"] = { 65 } }, ["questType"] = "standard" },
[12796] = { ["id"] = 12796, ["name"] = "The Magical Kingdom of Dalaran", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 12796 }, ["series"] = { 12790, 12791, 12794, 39210 }, ["description"] = "Hello, <name>. You may or may not be aware that we Kirin Tor moved our city here to Northrend. No longer does Dalaran sit under its protective dome on the shores of Lordamere Lake. Now the city magically floats above the Crystalsong Forest. We believe you to be ready for your journey to the city. Speak with me again and I will cast a spell of teleportation to transport you there. When you arrive, seek out Archmage Celindra and give her my signet as proof that we spoke.", ["objectivesText"] = "Deliver the Kirin Tor Signet to Archmage Celindra at The Violet Gate in Dalaran . Progress: Greetings, <class>.", ["rewardXP"] = 175, ["rewardItems"] = { 39740 }, ["starts"] = { { ["mapID"] = 121, ["npcID"] = 29169, ["x"] = 0.405, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 121 }, ["zone"] = { 66 } }, ["questType"] = "standard" },
[12800] = { ["id"] = 12800, ["name"] = "The Lich King's Command", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12778, 12779 }, ["description"] = "The Scarlet Enclave is no more. What remains of the Crusade will be dealt with in Northrend. We now turn all of our efforts to Light's Hope Chapel. No longer will this affront to your master be allowed to exist! I have issued my final command. Scourge Commander Thalanor awaits your arrival at the edge of Browman Mill. Go northwest, through the cave, into the Noxious Glade and take the path leading out of the glade to the mill. Do not fail me, <name>.", ["objectivesText"] = "Report to Scourge Commander Thalanor at Browman Mill.", ["rewardXP"] = 145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 52, ["flags"] = 0 } } },
[12801] = { ["id"] = 12801, ["name"] = "The Light of Dawn", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 13165, 13166 }, ["description"] = "The Argent Dawn stands defiantly against us at Light's Hope Chapel. They dare oppose the Scourge and for that reason alone they must be destroyed! The mighty armies of the Lich King stand at the ready as the final battle for the Plaguelands approaches. Today we ascend into the immortal realm of Scourge heroes! When you are ready for battle, report to Highlord Darion Mograine . It is the highlord who will issue the final march orders and command our armies at Light's Hope Chapel.", ["objectivesText"] = "Defeat the forces of the Argent Dawn and uncover the Light of Dawn. Report to Highlord Darion Mograine should you survive. Progress: <Highlord Mograine nods.>", ["rewardGold"] = 420000, ["rewardXP"] = 2290, ["rewardItems"] = { 38632, 38633, 142321, 153130, 220107, 220111, 220113, 220114, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 53, ["flags"] = 0 } } },
[12842] = { ["id"] = 12842, ["name"] = "Runeforging: Preparation For Battle", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12848, 12850 }, ["description"] = "The mark of war is etched indelibly upon your soul, death knight. You have learned the dark art of runeforging and with it you will engrave runes of power upon your weaponry. Preparations for battle must be made. Return to one of the runeforges, here in the Heart of Acherus, and use the power of runeforging to emblazon your weapon with a rune of power! Return to me when your blade glows with dark energy!", ["objectivesText"] = "Instructor Razuvious in Ebon Hold has commanded you to use your Runeforging ability in your spellbook to engrave a rune upon your Runed Soulblade. You may freely replace the engraving upon your weapon at any time, so long as you are near a Runeforge. Progress: Do not waste time, <name>. We are on the brink of apocalypse!", ["rewardXP"] = 1720, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 2, ["flags"] = 0 } } },
[12848] = { ["id"] = 12848, ["name"] = "The Endless Hunger", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12842, 12850 }, ["description"] = "The endless hunger will soon take hold of you, <class>. When it does, you will feel pain immeasurable. There is only one remedy for the suffering: the hunger must be sated. I give you the key to your salvation. Chained to the Heart of Acherus are those deemed unworthy of the dark brotherhood. Use the key to free an unworthy initiate . Allow them to equip their gear and battle you for their freedom. Kill and the pain will cease. Fail and suffer for eternity. Live or die - the choice is yours to make.", ["objectivesText"] = "Instructor Razuvious in Ebon Hold has commanded you to free an Unworthy Initiate and then kill the Unworthy Initiate in cold blood! It's your life or theirs! Progress: Two lives, one key... Do not fail me, <name>.", ["rewardXP"] = 1720, ["rewardItems"] = { 40732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 3, ["flags"] = 0 } } },
[12849] = { ["id"] = 12849, ["name"] = "The Power Of Blood, Frost And Unholy", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["rewardXP"] = 1720, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 7, ["flags"] = 0 } } },
[12850] = { ["id"] = 12850, ["name"] = "Report To Scourge Commander Thalanor", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster", "class" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 124, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12842, 12848 }, ["description"] = "Scourge Commander Thalanor awaits your arrival at the overhang located directly southeast of our current position. Report to Thalanor and requisition a Scourge gryphon to deliver you to Death's Breach. Prince Valanar will be waiting for you down below. Suffer well, <brother/sister>!", ["objectivesText"] = "Report to Scourge Commander Thalanor at the balcony on the first floor of Ebon Hold.", ["rewardXP"] = 145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiMapID"] = 609, ["db2PoiUiMapID"] = 124, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 8, ["flags"] = 0 } } },
[12932] = { ["id"] = 12932, ["name"] = "The Amphitheater of Anguish: Yggdras!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 12504, 12505, 12506, 12507, 12508, 12510, 12512, 12514, 12516, 12552, 12553, 12554, 12555, 12557, 12583, 12584, 12596, 12597, 12598, 12599, 12606, 12623, 12627, 12628, 12629, 12630, 12631, 12632, 12633, 12637, 12638, 12642, 12643, 12646, 12647, 12648, 12649, 12653, 12661, 12663, 12664, 12665, 12666, 12667, 12668, 12669, 12672, 12674, 12675, 12676, 12677, 12684, 12685, 12712, 12713, 12721, 12729, 12730, 12740, 12859, 12861, 12883, 12884, 12894, 12901, 12902, 12903, 12904, 12912, 12914, 12916, 12919, 12932, 12933, 12934, 12935, 12936, 12948, 12954 }, ["series"] = { 12933, 12934, 12935, 12936, 12948, 12974 }, ["description"] = "I'll tell you what, buddy, this place is a far cry from the rolling plains of Nagrand. These trolls are dirtier than ogres; but hey, I go where the gold's at! So welcome to Zul'Drak , pal. You're new to this racket, so let me set you straight. I'm the fight promoter and this feisty troll next to me is Wodin, my bodyguard. You're the entertainment. When you wanna fight, let me know and I'll set up the match. If you're ready and got a group of friends with you, we can start! What do you say?", ["objectivesText"] = "Get in the arena at the Amphitheater of Anguish and defeat Yggdras! Return to Wodin the Troll-Servant to redeem your reward. Progress: No payout until the fight's over, man.", ["rewardGold"] = 842700, ["rewardXP"] = 4150, ["rewardItems"] = { 38699 }, ["starts"] = { { ["mapID"] = 121, ["npcID"] = 30007, ["x"] = 0.485, ["y"] = 0.563 }, { ["mapID"] = 71, ["npcID"] = 39034, ["x"] = 0.518, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 121, ["npcID"] = 30009, ["x"] = 0.485, ["y"] = 0.564 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.563 }, ["mapCandidates"] = { ["npc"] = { 71, 121 }, ["zone"] = { 66 } }, ["questType"] = "group", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 121, ["questLines"] = { { ["id"] = 536, ["name"] = "Zul'Drak", ["orderIndex"] = 58, ["flags"] = 0 } } },
