[13041] = { ["id"] = 13041, ["name"] = "Finish the Shipment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13041 }, ["description"] = "I'm glad you showed up! A shipment of Glowing Ivory Figurines needs to go out to Undermine right now, and I am still short a Chalcedony to complete an eye for the last one. Bring me one and a Dalaran Jeweler's token will be yours.", ["objectivesText"] = "Bring a Chalcedony to Timothy Jones in Dalaran. Progress: Do you have the Chalcedony yet?", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 36923 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
