[13087] = { ["id"] = 13087, ["name"] = "Northern Cooking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 495, ["mapID"] = 117, ["storyline"] = { 13087 }, ["description"] = "So what are ya doin' if you dinna have any stew for me. I got me a HUNGER! At least bring me some chilled meat so I kin cook me own stew! If ya do, I kin give ya the recipe so you kin make it for yourself. NOW GO GET ME SOME MEAT!", ["objectivesText"] = "Bring four chilled meat to Brom Brewbaster at Valgarde. chilled meat can be found on any Northrend beast. Progress: WHERE IS MY MEAT!", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 34747, 43013 }, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 26905, ["x"] = 0.582, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 26905, ["x"] = 0.582, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 495 } }, ["questType"] = "standard" },
[13088] = { ["id"] = 13088, ["name"] = "Northern Cooking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 13088 }, ["description"] = "We got a lot of new recruits here and these lads are hungry! If you could go out and get me some chilled meat for stew, I could teach you how to make it for yourself.", ["objectivesText"] = "Bring four chilled meat to Rollick Mackreel at Valiance Keep. chilled meat can be found on any Northrend beast. Progress: The lads need meat for their stew.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 34747, 43013 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 26989, ["x"] = 0.578, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 26989, ["x"] = 0.578, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "standard" },
[13089] = { ["id"] = 13089, ["name"] = "Northern Cooking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 495, ["mapID"] = 117, ["storyline"] = { 13089 }, ["description"] = "Nothing like a stew made from the living to warm your bones. Bring me some of the chilled meat that can be found on the wretched beasts of this place, and I shall teach you to make a warm stew.", ["objectivesText"] = "Bring four chilled meat to Thomas Kolichio at Vengeance Landing. chilled meat can be found on any Northrend beast. Progress: The stew awaits...", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 34747, 43013 }, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 26953, ["x"] = 0.786, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 26953, ["x"] = 0.786, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.786, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 495 } }, ["questType"] = "standard" },
[13090] = { ["id"] = 13090, ["name"] = "Northern Cooking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 13090 }, ["description"] = "The warriors of the Warsong Offensive need food in their bellies to keep their strength up. If you could bring some chilled meats from the Rhinos or other beasts, I could make them some stew. I would be willing to teach you the recipe if you were willing.", ["objectivesText"] = "Bring four chilled meat to Orn Tenderhoof at Warsong Hold. chilled meat can be found on any Northrend beast. Progress: When the meat is present, the stew will be prepared.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 34747, 43013 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 26972, ["x"] = 0.42, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 26972, ["x"] = 0.42, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "standard" },
[13094] = { ["id"] = 13094, ["name"] = "Have They No Shame?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4265, ["mapID"] = 114, ["storyline"] = { 13094 }, ["description"] = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble. I made the mistake of discussing it with a group of Horde adventurers and now it's gone! It must have been them. Please, recover the book.", ["objectivesText"] = "Image of Warmage Kaitlyn wants you to recover Berinand's Research . Progress: Please, <name>, tell me you've found the book...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 43095, 43181, 43182, 43183, 43184 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 26110, ["x"] = 0.334, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 26110, ["x"] = 0.334, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 4265 } }, ["questType"] = "dungeon" },
[13095] = { ["id"] = 13095, ["name"] = "Have They No Shame?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4265, ["mapID"] = 114, ["storyline"] = { 13095 }, ["description"] = "Archmage Berinand loaned me his research on the Arcanomicron, some sort of map that Malygos is trying to assemble. I made the mistake of discussing it with a group of Alliance adventurers and now it's gone! It must have been them. Please, recover the book.", ["objectivesText"] = "Image of Warmage Kaitlyn wants you to recover Berinand's Research . Progress: Please, <name>, tell me you've found the book...", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 43095, 43181, 43182, 43183, 43184 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 26110, ["x"] = 0.334, ["y"] = 0.344 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 26110, ["x"] = 0.334, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 4265 } }, ["questType"] = "dungeon" },
[13100] = { ["id"] = 13100, ["name"] = "Infused Mushroom Meatloaf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13100 }, ["description"] = "We have an important order that needs to go out! Orton Bennet in Curiosities & Moore needs a mushroom meatloaf. Get some infused mushrooms found in the Dalaran sewers, chilled meat, and cook them in this meatloaf pan . When you're done, deliver the cooked meatloaf to Orton.", ["objectivesText"] = "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran. Progress: Do you have any food for me? I never seem to be able to get away from the shop, even for a minute.", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 43099, 43100, 43101, 44113 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13101] = { ["id"] = 13101, ["name"] = "Convention at the Legerdemain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13101 }, ["description"] = "Arille Azuregaze at the Legerdemain Lounge has a convention coming in and needs a feast pronto! You need to provide some Northern Stew and a Jug of Wine from the cheese shop \"One More Glass\" in central Dalaran. The owner of the cheese shop owes me the wine and you should find it somewhere around the shop. Bring the wine and stews to Arille.", ["objectivesText"] = "Bring 4 Northern Stew that you use your cooking skill to make and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran. Progress: Where is my food, I will have conventioneers here any minute!", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 34747, 43128, 44113 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13102] = { ["id"] = 13102, ["name"] = "Sewer Stew", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13102 }, ["description"] = "Ajay Green the innkeeper in the Dalaran sewers needs a vegetable stew for his customers as they are running low on food down there. Collect 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat. You can get to the Crystalsong Forest from the portal chamber in the eastern corner of Runeweaver Square. Once the vegetable stew is ready, bring it to Ajay.", ["objectivesText"] = "Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot. Once it is ready bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green . Progress: I've got hungry people down here! We need some stew.", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 43013, 43147, 43148, 43149, 44113 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13103] = { ["id"] = 13103, ["name"] = "Cheese for Glowergold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13103 }, ["description"] = "Ranid Glowergold in the Leatherworkers shop in Dalaran has had a sudden craving for wine and cheese. Collect cheese which is on the shelf at \"One More Glass\" in central Dalaran and half full wine glasses found on tables all over the city. Pour the wine together into a bottle and serve it with the cheese to Ranid. We don't think he will know the difference.", ["objectivesText"] = "Combine the Empty Cheese Platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran. Bring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange. Progress: Have you seen a servant with my wine and cheese platter . I am quite peckish!", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 43136, 43137, 43138, 43139, 44113, 258145 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13107] = { ["id"] = 13107, ["name"] = "Mustard Dogs!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13107 }, ["description"] = "Archmage Pentarus likes to watch the occasional game of battle ball and is preparing to go, but needs food for the trip. You need to fill his picnic basket with 4 rhino dogs that you cook and then 4 wild mustard that are found in grassy areas of the city. Bring him his picnic basket so he can be ready to go see the big game.", ["objectivesText"] = "Fill the Empty Picnic Basket with 4 Rhino Dogs that you cook with your cooking skill and 4 Wild Mustard that you find in the grassy areas of Dalaran. Bring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran. Progress: I am almost ready to go, I just need the food and for my mates... er... my fellow mages to arrive.", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 43142, 43143, 43144, 44113 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13112] = { ["id"] = 13112, ["name"] = "Infused Mushroom Meatloaf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13112 }, ["description"] = "Orton Bennet in Curiosities & Moore be needin' a mushroom meatloaf. Get ya some infused mushrooms found in the Dalaran sewers, chilled meat, and cook 'em in the meatloaf pan . When ye be done, bring that meatloaf to Orton. If only de council would let me serve me gnome specialty, I would show dem a real treat!", ["objectivesText"] = "Use your Meatloaf Pan to cook 4 Infused Mushrooms and 2 Chilled Meats and bring the finished Mushroom Meatloaf to Orton Bennet in Curiosities & Moore, located in Runeweaver Square in Dalaran. Progress: Do you have something for me? I so rarely get away from my shop.", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 43099, 43100, 43101, 44113 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13113] = { ["id"] = 13113, ["name"] = "Convention at the Legerdemain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13113 }, ["description"] = "Can you believe da horde has outlawed cannibalism...it just ain't right I tell ya! I guess I should keep me mind on me work when we gots an order to fill. Arille Azuregaze at the Legerdemain Lounge has many a guest a'comin to his place, mon. You gots to be providin' some Northern Stew and a Jug of Wine from the cheese shop in central Dalaran. Bring the wine and stew to Arille.", ["objectivesText"] = "Bring 4 Northern Stews and a Jug of Wine from the cheese shop in Dalaran to Arille Azuregaze at the Legerdemain Lounge found in Runeweaver Square in Dalaran. Progress: Where is my food? My guests will be here soon!", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 34747, 43128, 44113 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13114] = { ["id"] = 13114, ["name"] = "Sewer Stew", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13114 }, ["description"] = "We be havin' another order to fill. Da innkeeper in da Dalaran sewers needs a vegetable stew as his customers dey don't have so much to eat, mon. He asked for a vegetable stew as he didn't appreciate da gnome that was in the last stew I sent. Get 4 Crystalsong Carrots from the Crystalsong Forest and cook them together with 4 Chilled Meat and bring it to Ajay. You can be gettin' to da Forest from da portal chamber in da eastern corner of Runeweaver Square.", ["objectivesText"] = "Cook 4 Crystalsong Carrots from Crystalsong Forest with 4 Chilled Meat in the Cookpot. Then bring the Vegetable Stew to the Dalaran sewers Innkeeper Ajay Green . Progress: Make sure there isn't any gnome in the stew this time!", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 43147, 43148, 43149, 44113 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13115] = { ["id"] = 13115, ["name"] = "Cheese for Glowergold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13115 }, ["description"] = "Ranid Glowergold in da Leatherworkers shop be havin' a need for wine and cheese. Why he don't want some tasty gnome is beyond me. Collect da cheese from da cheese shop in central Dalaran and da half full wine glasses found on tables around da city. Bring da wine and serve it with the cheese to Ranid. You can call da wine a Wine Medley, mon'.", ["objectivesText"] = "Combine the Empty Cheese Platter with Aged Dalaran Limburger from the cheese shop \"One More Glass\" and with 6 Half Full Dalaran Wine Glasses found on tables around Dalaran. Bring the Wine and Cheese platter to Ranid Glowergold at the Leatherworkers in the Magus Commerce Exchange. Progress: Have you seen a servant with my wine and cheese platter . I am quite peckish!", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 43136, 43137, 43138, 43139, 44113, 258145 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13116] = { ["id"] = 13116, ["name"] = "Mustard Dogs!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13116 }, ["description"] = "Da Archmage Pentarus likes to be watchin' his crazy battle ball game, but he be needin' some food for da game. You be needin' to fill his picnic basket with 4 cooked rhino dogs and then 4 wild mustard that are found in da grassy corners of de city. Fill up his basket with the mustard dog goodies, mon'.", ["objectivesText"] = "Fill the Empty Picnic Basket with 4 Rhino Dogs that you be cookin' with your skill and 4 Wild Mustard that you find in the grassy areas of Dalaran. Bring the Picnic Basket to Archmage Pentarus at Krasus' Landing in Dalaran. Progress: Make sure the wild mustard dogs are 100% rhino and have no Gnome in them!", ["rewardGold"] = 78750, ["rewardXP"] = 1060, ["rewardItems"] = { 34752, 43012, 43142, 43143, 43144, 44113, 44234 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13124] = { ["id"] = 13124, ["name"] = "The Struggle Persists", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 13124 }, ["series"] = { 13126, 13127, 13128 }, ["description"] = "Malygos and his underlings grow stronger in power with each passing day. And now, our latest assault team has been captured and is being held in the Oculus . We must attempt a rescue! Belgaristrasz and his companions are invaluable to our cause.", ["objectivesText"] = "Raelorasz wants you to rescue Belgaristrasz and his companions in the Oculus .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 44334, 44335, 44336, 44337 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 26117, ["x"] = 0.332, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "dungeon" },
[13126] = { ["id"] = 13126, ["name"] = "A Unified Front", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4228, ["storyline"] = { 13126 }, ["series"] = { 13124, 13127, 13128 }, ["description"] = "From here, it will take our combined efforts to proceed. Above us, Varos hides behind an impenetrable shield. To reach him, you must defeat the Centrifuge Constructs that power his shield. We can each provide you with drakes from our respective flights to help you reveal him.", ["objectivesText"] = "Belgaristrasz wants you to destroy 10 Centrifuge Constructs to bring down Varos' shield. You then must defeat Varos Cloudstrider .", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4228 } }, ["questType"] = "dungeon" },
[13127] = { ["id"] = 13127, ["name"] = "Mage-Lord Urom", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4228, ["storyline"] = { 13127 }, ["series"] = { 13124, 13126, 13128 }, ["description"] = "Only one obstacle stands between us and our ultimate goal here. His name is Urom. He guards the third ring above us. Beware his powerful conjurings, friend. Bring him down. Make him pay for his treacherous allegiance to the enemy!", ["objectivesText"] = "Belgaristrasz wants you to defeat Mage-Lord Urom in the Oculus . Progress: Has Mage-Lord Urom been dealt with?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4228 } }, ["questType"] = "dungeon" },
[13128] = { ["id"] = 13128, ["name"] = "A Wing and a Prayer", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4228, ["mapID"] = 114, ["storyline"] = { 13128 }, ["series"] = { 13124, 13126, 13127 }, ["description"] = "The time has come to face Eregos. He draws strength from the energies he is charged with defending - sipping from the well of the great aspect Malygos. However, defeating the Mage-Lord has allowed us to unlock the full power of our drakes. Use them wisely and Eregos shall surely fall.", ["objectivesText"] = "Belgaristrasz wants you to kill Eregos in the Oculus . Progress: You've done it, haven't you? You bested Eregos!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 44338, 44339, 44340, 44341, 57339, 57340, 57341 }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 26117, ["x"] = 0.332, ["y"] = 0.344 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.344 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 4228 } }, ["questType"] = "dungeon" },
[13129] = { ["id"] = 13129, ["name"] = "Head Games", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4196, ["mapID"] = 116, ["storyline"] = { 13129 }, ["series"] = { 12029, 12037 }, ["description"] = "< Kurzel rips a long strip of material from her blouse and hands it to you.> Here, <race>, take this. Dip it in the remains of Novos the Summoner. We're going to figure out what makes the Scourge leaders tick.", ["objectivesText"] = "Kurzel wants you to use Kurzel's Blouse Scrap at the corpse of Novos the Summoner, then take the Ichor-Stained Cloth to her inside Drak'Tharon Keep . Progress: Do you have the cloth?", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["rewardItems"] = { 43214, 43215, 44366, 44367, 44368, 44369 }, ["ends"] = { { ["mapID"] = 116, ["npcID"] = 26604, ["x"] = 0.166, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 116, ["source"] = "quest_giver", ["x"] = 0.166, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 116 }, ["zone"] = { 4196 } }, ["questType"] = "dungeon" },
[13131] = { ["id"] = 13131, ["name"] = "Junk in My Trunk", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 1196, ["storyline"] = { 13131 }, ["description"] = "Just look at it! Me trunk never been so empty. Me mates jumped at the sight o' all that booty, and now look at 'em! Rattlin' bones, they be! Say, thar be plenty o' loot farther in, an' not the cursed kind I'll wager. Fetch it fer me an' I'll be rewardin' ya handsomely, matey.", ["objectivesText"] = "Brigg in Utgarde Pinnacle wants you to find 5 Untarnished Silver Bars , 3 Shiny Baubles , 2 Golden Goblets , and a Jade Statue . Progress: How'd yeh fare in thar, matey?", ["rewardGold"] = 105000, ["rewardXP"] = 2765, ["rewardItems"] = { 43238, 43239, 43240, 43241, 44404, 44405, 44406, 44407 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1196 } }, ["questType"] = "dungeon" },
[13132] = { ["id"] = 13132, ["name"] = "Vengeance Be Mine!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 1196, ["storyline"] = { 13132 }, ["description"] = "Only luck spared me from the same fate as me mates. In the scurry I got knocked down - was a wee bit tipsy to begin with. Looked up ta see the first of 'em turn. There was a big ol' fella watchin' with a whole mess o' guards. They were chantin' Ymiron... maybe killin' him will free me mates?", ["objectivesText"] = "Brigg in Utgarde Pinnacle wants you to kill King Ymiron .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 44408, 44409, 44410, 44411, 44412 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1196 } }, ["questType"] = "dungeon" },
[13149] = { ["id"] = 13149, ["name"] = "Dispelling Illusions", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4100, ["storyline"] = { 13149 }, ["series"] = { 13151 }, ["description"] = "The infinite dragonflight seek to disrupt history by deceiving Prince Arthas. If they can convince him that none of the grain here carries the plague, then he'll never have to make the fateful decision to cull Stratholme. Use this arcane disruptor on any suspicious crates of grain you find.", ["objectivesText"] = "Chromie wants you to use the Arcane Disruptor on the suspicious crates in Stratholme Past, then speak to her near the entrance to Stratholme. Progress: It's good to see you again!", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 37888 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4100 } }, ["questType"] = "dungeon" },
[13151] = { ["id"] = 13151, ["name"] = "A Royal Escort", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4100, ["storyline"] = { 13151 }, ["series"] = { 13149 }, ["description"] = "Arthas will soon face a desperate dilemma, and make a momentous decision. I must call upon you to accompany the prince in his culling. Arthas must make it through Stratholme alive and you must see to it that he defeats Mal'Ganis!", ["objectivesText"] = "Chromie has asked you to accompany Arthas in the Culling of Stratholme . You are to speak with her again after Mal'Ganis is defeated.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44396, 44397, 44398, 44399 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4100 } }, ["questType"] = "dungeon" },
[13153] = { ["id"] = 13153, ["name"] = "Warding the Warriors", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13153 }, ["description"] = "<name>, good to see you. While the battle has subsided for now, we must hurry and replenish our stocks. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been seen collecting armor in the area. Head to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me. If you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", ["objectivesText"] = "Sorceress Kaylana at Wintergrasp Fortress wants you to retrieve 10 sets of Imbued Horde Armor from Horde players at the Glacial Falls. Progress: So, did you find the armor?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44808 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31051, ["x"] = 0.564, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31051, ["x"] = 0.564, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13154] = { ["id"] = 13154, ["name"] = "Bones and Arrows", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13154 }, ["description"] = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight. However, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over. Head to the Forest of Shadows and bring back any bone splinters you can find! The Horde have been seen collecting bone splinters in the area. Slay them!", ["objectivesText"] = "Bowyer Randolph at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows. Progress: How was the hunting? I've heard rumors the place is haunted, though I never venture out there myself.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 43323 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31052, ["x"] = 0.6275, ["y"] = 0.259 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31052, ["x"] = 0.6275, ["y"] = 0.259 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.6275, ["y"] = 0.259 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13156] = { ["id"] = 13156, ["name"] = "A Rare Herb", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13156 }, ["description"] = "My, it its quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold. Head to the Steppe of Life in southwestern Wintergrasp , and bring me back 10 of the Horde herb pouches you find. I will grind them into a medicine to help protect against the cold. The Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs!", ["objectivesText"] = "Anchorite Tessa in Wintergrasp Fortress wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life. Progress: I hope you didn't pull up any of the lashers by mistake! They gave Private Doane quite a whipping last week.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44809 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31054, ["x"] = 0.601429, ["y"] = 0.252286 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31054, ["x"] = 0.601429, ["y"] = 0.252286 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.601429, ["y"] = 0.252286 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13165] = { ["id"] = 13165, ["name"] = "Taking Back Acherus", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4298, ["mapID"] = 23, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12801, 13166 }, ["description"] = "The haze has been lifted. I can see as clearly now as the day that I plunged the Ashbringer into my own heart to free my father's cursed soul: my last memory as a free man. We must take back Acherus from the Scourge if our order is to survive in this new world. I have taught you how to call forth a death gate. The death gate will return you to Acherus when you call upon it, <name>. Use it now and meet me at Acherus. The first battle of the Knights of the Ebon Blade is underway! Death to the Scourge!", ["objectivesText"] = "Use your Death Gate spell to return to Acherus: The Ebon Hold. Report to Highlord Darion Mograine once you arrive.", ["rewardXP"] = 145, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 31084, ["x"] = 0.834, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.834, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 4298 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 23, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 54, ["flags"] = 0 } } },
[13166] = { ["id"] = 13166, ["name"] = "The Battle For The Ebon Hold", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12742, 12743, 12744, 12745, 12746, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 13189, 28649, 28650 }, ["series"] = { 12801, 13165 }, ["description"] = "The Hall of Command has been secured, but the Lich King has left us a little present in the Heart of Acherus. The stitched terror, Patchwerk , and a horde of abominations have taken over the second floor. Use the teleporter to get to the second floor and destroy the Scourge forces that remain. Do not engage Patchwerk alone! You must fight the monstrosity with other death knights of Acherus! Go, <name>. You have my strength to carry you!", ["objectivesText"] = "Slay 10 Scourge and help kill Patchwerk . Return to Highlord Darion Mograine should you succeed. Progress: Acherus will be ours!", ["rewardGold"] = 315000, ["rewardXP"] = 1720, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 31084, ["x"] = 0.834, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 31084, ["x"] = 0.834, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.834, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 23, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 55, ["flags"] = 0 } } },
[13177] = { ["id"] = 13177, ["name"] = "No Mercy for the Merciless", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13177 }, ["description"] = "Welcome to the Wintergrasp Fortress, <name>. Your mission is simple. Defeat ten of the Horde's finest. Now, go! Bring victory to the Alliance!", ["objectivesText"] = "Commander Zanneth in Wintergrasp Fortress wants you to slay 10 members of the Horde.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31036, ["x"] = 0.5555, ["y"] = 0.2145 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31036, ["x"] = 0.5555, ["y"] = 0.2145 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.5555, ["y"] = 0.2145 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13178] = { ["id"] = 13178, ["name"] = "Slay them all!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13178 }, ["description"] = "Welcome to the Wintergrasp Fortress, <name>. Warlord Garrosh demands one thing: Slay them all! Return to me when ten of the strongest members of the Alliance are dead.", ["objectivesText"] = "Commander Dardosh in Wintergrasp Fortress wants you to slay 10 members of the Alliance.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31091, ["x"] = 0.4412, ["y"] = 0.2048 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31091, ["x"] = 0.4412, ["y"] = 0.2048 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.4412, ["y"] = 0.2048 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
