[13180] = { ["id"] = 13180, ["name"] = "Slay them all!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13180 }, ["description"] = "Welcome to Wintergrasp , <name>. Warlord Garrosh demands one thing: Slay them all! Return to me when ten of the strongest members of the Alliance are dead.", ["objectivesText"] = "Commander Dardosh in Wintergrasp wants you to slay 10 members of the Alliance.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31091, ["x"] = 0.4412, ["y"] = 0.2048 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31091, ["x"] = 0.4412, ["y"] = 0.2048 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.4412, ["y"] = 0.2048 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13181] = { ["id"] = 13181, ["name"] = "Victory in Wintergrasp", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13181 }, ["description"] = "Commander Zanneth might be satisfied with a pile of Horde corpses at his feet, but controlling Wintergrasp is of the utmost importance to the Valiance Expedition. Make sure it remains in our control. However, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", ["objectivesText"] = "Win a Wintergrasp battleground match and return to Tactical Officer Abrahmis in Wintergrasp . You must have participated in the battle to be credited for the victory.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31153, ["x"] = 0.611, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31153, ["x"] = 0.611, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.611, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13183] = { ["id"] = 13183, ["name"] = "Victory in Wintergrasp", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13183 }, ["description"] = "While Dardosh might be content with slaying our foes, it is of the utmost importance that we control Wintergrasp Fortress. Do whatever it takes to ensure Wintergrasp is ours. However, don't think we'll just let you stand around while your allies do your dirty work for you. If you're not at least a second level recruit by the end of the battle, don't come back.", ["objectivesText"] = "Win a Wintergrasp battleground match and return to Tactical Officer Kilrath in Wintergrasp . You must have participated in the battle to gain credit for the victory.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31151, ["x"] = 0.406667, ["y"] = 0.231333 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31151, ["x"] = 0.406667, ["y"] = 0.231333 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.406667, ["y"] = 0.231333 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13185] = { ["id"] = 13185, ["name"] = "Stop the Siege", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13185 }, ["description"] = "I hears dem! The Alliance come soon. Destroy three Alliance siege devices and come back to Murp.", ["objectivesText"] = "Lieutenant Murp in Wintergrasp Fortress wants you to destroy 3 Alliance siege machines.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31107, ["x"] = 0.38925, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31107, ["x"] = 0.38925, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.38925, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13186] = { ["id"] = 13186, ["name"] = "Stop the Siege", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13186 }, ["description"] = "It is only a matter of time before this castle is besieged by the forces of the Horde. Destroy three of their siege devices and return to me.", ["objectivesText"] = "Senior Demolitionist Legoso in Wintergrasp Fortress wants you to destroy 3 Horde siege machines.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31109, ["x"] = 0.578667, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31109, ["x"] = 0.578667, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.578667, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13187] = { ["id"] = 13187, ["name"] = "The Faceless Ones", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4494, ["mapID"] = 115, ["storyline"] = { 13187 }, ["series"] = { 29825, 29826 }, ["description"] = "In my peoples' struggle against the forces of the undead, they dug deeper as they lost ground. They inadvertently exposed minions of the Old Gods known only as the Faceless. In the end, we could not fight a war on two fronts. With your aid, perhaps the Faceless will finally fall.", ["objectivesText"] = "Seer Ixit in Ahn'Kahet wants you to kill Herald Volazj and the three Forgotten Ones that accompany him. Progress: Have you overcome the faceless ones, <class>?", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 44350, 44351, 44352, 44353 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 26653, ["x"] = 0.262, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26653, ["x"] = 0.262, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 4494 } }, ["questType"] = "dungeon" },
[13188] = { ["id"] = 13188, ["name"] = "Where Kings Walk", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "alliance", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 1519, ["mapID"] = 23, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12742, 12743, 12744, 12745, 12746, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13188, 28649 }, ["description"] = "You are now, and forever will be, a Knight of the Ebon Blade, <name>, but know this: you were once a hero of the Alliance. <Darion stares at you.> This order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Alliance. On the platform, southeast of me, is a portal to Stormwind City. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to King Anduin Wrynn . Use the portal.", ["objectivesText"] = "Deliver the letter to King Anduin Wrynn of the Alliance at Stormwind Keep in Stormwind City. Progress: You have mere moments to live.", ["rewardXP"] = 1720, ["rewardItems"] = { 43440, 58487 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 31084, ["x"] = 0.834, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 29611, ["x"] = 0.855, ["y"] = 0.32 }, { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.834, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 23, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 37, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 56, ["flags"] = 0 } } },
[13189] = { ["id"] = 13189, ["name"] = "Saurfang's Blessing", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "horde", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 12593, 12619, 12636, 12641, 12657, 12670, 12678, 12679, 12680, 12687, 12697, 12698, 12700, 12701, 12706, 12711, 12714, 12715, 12716, 12717, 12719, 12720, 12722, 12723, 12724, 12725, 12727, 12733, 12738, 12739, 12747, 12748, 12749, 12750, 12751, 12754, 12755, 12756, 12757, 12778, 12779, 12800, 12801, 12842, 12848, 12849, 12850, 13165, 13166, 13189, 28650 }, ["description"] = "You are now, and forever will be, a Knight of the Ebon Blade, <name>, but know this: you were once a hero of the Horde. <Darion stares at you.> This order must establish allies for itself if it is to survive. You must represent the Knights of the Ebon Blade to the Horde. On the platform, southeast of me, is a portal to Orgrimmar. Take this letter, given to me on your behalf by Lord Fordring, and deliver it to High Overlord Saurfang . Use the portal.", ["objectivesText"] = "Deliver the letter to High Overlord Saurfang at Orgrimmar. Progress: An interesting turn of events.", ["rewardXP"] = 1720, ["rewardItems"] = { 9603, 43441 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 31084, ["x"] = 0.834, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 14720, ["x"] = 0.485, ["y"] = 0.71 }, { ["mapID"] = 85, ["npcID"] = 39605, ["x"] = 0.4745, ["y"] = 0.5395 }, { ["mapID"] = 85, ["npcID"] = 86832, ["x"] = 0.482, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.834, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 23, 85 }, ["zone"] = { 139 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 5453, ["name"] = "The Scarlet Enclave", ["orderIndex"] = 57, ["flags"] = 0 } } },
[13191] = { ["id"] = 13191, ["name"] = "Fueling the Demolishers", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13191 }, ["description"] = "Lok'tar, <name>! While the battle may be over, we must prepare for the Alliance's next assault! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers . The embers are mixed in with coal to fuel the Demolishers and Siege Engines. We've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", ["objectivesText"] = "Siegesmith Stronghoof at Wintergrasp Fortress wants you to retrieve 10 Eternal Embers from Alliance players in the Cauldron of Flames. Progress: Well? Did you manage to find the embers or did the Alliance beat you to it and leave you crying?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 37702, 39512, 43314 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31106, ["x"] = 0.303333, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31106, ["x"] = 0.303333, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.303333, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13192] = { ["id"] = 13192, ["name"] = "Warding the Walls", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13192 }, ["description"] = "Hey 'mon. This place be givin' me dah heebie jeebies, don't cha know? Way too many spirits haunting dis place. I want ta be placing hoodoo wards up, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job. The Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, mebbe they be havin' the stuff we need. Bring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", ["objectivesText"] = "Hoodoo Master Fu'jin at Wintergrasp Fortress wants you to retrieve 10 Enchanted Alliance Breastplates at the Glacial Falls. Progress: Did ya bring da armor, mon?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 43322 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31101, ["x"] = 0.416, ["y"] = 0.257333 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31101, ["x"] = 0.416, ["y"] = 0.257333 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.257333 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13193] = { ["id"] = 13193, ["name"] = "Bones and Arrows", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13193 }, ["description"] = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. <name>, I am in need of dragon bone for our arrowheads. Travel to the Forest of Shadows on the western side of Wintergrasp . Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones. If that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", ["objectivesText"] = "Lieutenant Vieron Blazefeather at Wintergrasp Fortress wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players in the Forest of Shadows. Progress: Back so soon? Drat, I was hoping to catch a moment's rest.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 43323 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31102, ["x"] = 0.3496, ["y"] = 0.2912 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31102, ["x"] = 0.3496, ["y"] = 0.2912 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.3496, ["y"] = 0.2912 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13194] = { ["id"] = 13194, ["name"] = "Healing with Roses", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13194 }, ["description"] = "Between the battles, one might almost believe that there was hope for peace in this land. Sadly, that is not to be our fate. Travel to the Steppe of Life in southwestern Wintergrasp . I have need of the roses that grow there for salve to treat the wounded. Sadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies. If that fails, perhaps a lasher or two might have one.", ["objectivesText"] = "Primalist Mulfort wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life. Progress: Were you able to recover the herbs? The sick and wounded increase by the hour.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 43324 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31053, ["x"] = 0.3295, ["y"] = 0.2565 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31053, ["x"] = 0.3295, ["y"] = 0.2565 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.3295, ["y"] = 0.2565 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13195] = { ["id"] = 13195, ["name"] = "A Rare Herb", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13195 }, ["description"] = "My, it is quite chilly up here! Reminds me of the stormy peaks of Kaarinos on Argus. However, with all of this snow and ice, our soldiers can easily catch cold. Head to the Steppe of Life in southwestern Wintergrasp , and bring me back 10 Horde Herb Pouches. I will grind the herbs into a medicine to protect against the cold. The Horde have been seen collecting them from the plant life in the area. Do not hesitate to slay them and retrieve the herbs! You may also find one on a lasher in the area.", ["objectivesText"] = "Anchorite Tessa in Wintergrasp wants you to retrieve 10 Horde Herb Pouches from Horde players in the Steppe of Life. Progress: I hope you didn't pull up any of the lashers by mistake! They gave Private Doane quite a whipping last week.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44809 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31054, ["x"] = 0.601429, ["y"] = 0.252286 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31054, ["x"] = 0.601429, ["y"] = 0.252286 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.601429, ["y"] = 0.252286 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13196] = { ["id"] = 13196, ["name"] = "Bones and Arrows", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13196 }, ["description"] = "Dragons are incredible! Well, their bones at least! I've been equipping our archers with arrowheads made of Dragonbone. Unfortunately, since the massacre at Angrathar, it has become almost impossible to get bone from Dragonblight. However, the Forest of Shadows on the western edge of Wintergrasp has enough bones to tide us over. Head to the Forest of Shadows and bring back any bone splinters you can find! The Horde have been seen collecting bone splinters in the area. Slay them!", ["objectivesText"] = "Bowyer Randolph in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Horde players at the Forest of Shadows. Progress: How was the hunting? I've heard rumors the place is haunted, though I never venture out there myself.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 43323 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31052, ["x"] = 0.6275, ["y"] = 0.259 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31052, ["x"] = 0.6275, ["y"] = 0.259 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.6275, ["y"] = 0.259 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13197] = { ["id"] = 13197, ["name"] = "Fueling the Demolishers", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13197 }, ["description"] = "<name>! About time you showed up. While we may have lost the last battle, we should prepare for the next! Travel to the Cauldron of Flames in southeastern Wintergrasp and retrieve several eternal embers . The embers are mixed in with coal to fuel the Demolisher and Siege Engines. Oh, and if you happen to see some of the Horde in the Cauldron, don't hesitate to slay them and take their embers. We must prevent them from holding the keep!", ["objectivesText"] = "Siegesmith Stouthandle in Wintergrasp wants you to retrieve 10 Eternal Embers from Horde players at the Cauldron of Flames. Progress: Well? Did you manage to find the embers or did the Horde beat you to it and leave you crying?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 37702, 39512, 43314 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31108, ["x"] = 0.595, ["y"] = 0.261 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31108, ["x"] = 0.595, ["y"] = 0.261 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.261 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13198] = { ["id"] = 13198, ["name"] = "Warding the Warriors", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13198 }, ["description"] = "<name>, good to see you. We must prepare for our next assault on the fortress. My research indicates that the armor of soldiers recently slain in the Glacial Falls becomes imbued with an incredible amount of energy. The Horde has been collecting armor in the area. Head to the Glacial Falls and slay any of the Horde you find there. Return their imbued armor to me. If you cannot find any of the Horde, you might find the armor of an adventurer slain by the elementals.", ["objectivesText"] = "Sorceress Kaylana in Wintergrasp wants you to retrieve 10 sets of Imbued Horde Armor at the Glacial Falls. Progress: So, did you find the armor?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44808 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31051, ["x"] = 0.564, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31051, ["x"] = 0.564, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13199] = { ["id"] = 13199, ["name"] = "Bones and Arrows", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13199 }, ["description"] = "Why would they set me to the task of arming our archers? I was a poet, not a ranger! Well, no use complaining. <name>, I am in need of dragon bone for our arrowheads. Travel to the Forest of Shadows on the western side of Wintergrasp . Ever since the last skirmish, the Alliance have been scavenging dragon bones in the area. Slay them and take the bones. If that fails, you might be lucky and get one from the spirits in the area. I hear they love to impale their living victims on the bones as they die.", ["objectivesText"] = "Lieutenant Vieron Blazefeather in Wintergrasp wants you to retrieve 10 Quivers of Dragonbone Arrows from Alliance players at the Forest of Shadows. Progress: Back so soon? Drat, I was hoping to catch a moment's rest.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 43323 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31102, ["x"] = 0.3496, ["y"] = 0.2912 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31102, ["x"] = 0.3496, ["y"] = 0.2912 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.3496, ["y"] = 0.2912 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13200] = { ["id"] = 13200, ["name"] = "Fueling the Demolishers", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13200 }, ["description"] = "Lok'tar, <name>! While the battle may have subsided, we must prepare to retake the fortress! Travel to the Cauldron of Flames in south eastern Wintergrasp and retrieve ten eternal embers . The embers are mixed in with coal to fuel the Demolishers and Siege Engines. We've heard reports of Alliance pigs collecting the embers all day. Slay them and take their embers! If they have already abandoned the area, then be prepared to fight the fire elementals there until you find some!", ["objectivesText"] = "Siegesmith Stronghoof in Wintergrasp wants you to retrieve 10 Eternal Embers from Alliance players at the Cauldron of Flames. Progress: Well? Did you manage to find the embers or did the Alliance beat you to it and leave you crying?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 37702, 39512, 43314 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31106, ["x"] = 0.303333, ["y"] = 0.3 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31106, ["x"] = 0.303333, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.303333, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13201] = { ["id"] = 13201, ["name"] = "Healing with Roses", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13201 }, ["description"] = "So many of our braves were lost during the battle, but even more shall die if left untreated. Travel to the Steppe of Life in southwestern Wintergrasp . I have need of the roses that grow there for salve to treat the wounded. Sadly, the rose has become scarce due to the Alliance harvesting it too rapidly. Slay them on the Steppe of Life and retrieve their herb pouches from the bodies. If that fails, perhaps a lasher or two might be in bloom.", ["objectivesText"] = "Primalist Mulfort in Wintergrasp wants you to retrieve 10 Alliance Herb Pouches from Alliance players at the Steppe of Life. Progress: Were you able to recover the herbs? The sick and wounded increase by the hour.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 43324 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31053, ["x"] = 0.3295, ["y"] = 0.2565 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31053, ["x"] = 0.3295, ["y"] = 0.2565 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.3295, ["y"] = 0.2565 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13202] = { ["id"] = 13202, ["name"] = "Jinxing the Walls", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13202 }, ["description"] = "Hey 'mon. See dem Alliance sitting comfy in their keep? I think they be a bit too comfy, ya? I want ta be jinxing the place, but I be needin' some souls, mon. Not any soul though, only da soul of a strong warrior could do da job. The Glacial Falls in east Wintergrasp be havin' dem special properties to extract da soul. Slay the Alliance there, they be havin' the stuff we need. Bring back da armor of the slain. If there be no Alliance maybe da elementals got 'em, mon.", ["objectivesText"] = "Hoodoo Master Fu'jin in Wintergrasp wants you to retrieve 10 Enchanted Alliance Breastplates from Alliance players at the Glacial Falls. Progress: Did ya bring da armor, mon?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 43322 }, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31101, ["x"] = 0.416, ["y"] = 0.257333 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31101, ["x"] = 0.416, ["y"] = 0.257333 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.257333 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13203] = { ["id"] = 13203, ["name"] = "A Winter Veil Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Feast of Winter Veil", ["expansion"] = 2, ["storyline"] = { 13203 }, ["rewardItems"] = { 34426, 43504, 46740, 67443, 70938, 90892, 104319, 116761, 128653, 139341, 151350, 162644, 172224, 178528, 187561, 192094, 209871, 218311, 244908 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[13207] = { ["id"] = 13207, ["name"] = "Halls of Stone", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4264, ["storyline"] = { 13207 }, ["description"] = "Well now, I'm surprised to see other adventurers in a place such as this. If my research on these halls is accurate, there be monumental discoveries to be made here! Assumin' I can count on ya to watch my back, you're welcome to tag along.", ["objectivesText"] = "Brann Bronzebeard wants you to accompany him as he uncovers the secrets that lie in the Halls of Stone . Progress: Well, now, it turned out ta be a good thing we ran into each other after all.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 44370, 44371, 44372, 44373 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4264 } }, ["questType"] = "dungeon" },
[13222] = { ["id"] = 13222, ["name"] = "Defend the Siege", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13222 }, ["description"] = "Front and center, <name>! We're beginning our assault on Wintergrasp Fortress. Those Horde animals think they can hide cowardly behind their walls? Well, I think not! We'll show them the power of Gnomish technology and smash their walls to bits! However, even the most powerful siege device is helpless without a crew. Pilot or protect one of our siege vehicles as it destroys three of the Horde structures.", ["objectivesText"] = "Senior Demolitionist Legoso in Wintergrasp wants you to pilot or protect a siege device as it destroys three structures. Players of private rank or higher can build siege devices at Goblin Workshops.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31109, ["x"] = 0.578667, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31109, ["x"] = 0.578667, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.578667, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13223] = { ["id"] = 13223, ["name"] = "Defend the Siege", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13223 }, ["description"] = "Dem Alliance won't be long to hold that keep. Murp would smash walls, but Murp has to stay in camp. Murp wish he could smash Alliance who want to hurt Horde demolishers. You, <name>! You go in Murp's place. Protect 3 siege vehicles while they smash Alliance buildings. Alliance not expect you to defend demolisher. Show Alliance how smart Murp is!", ["objectivesText"] = "Lieutenant Murp in Wintergrasp wants you to defend or pilot a siege vehicle while they destroy three Alliance structures. Siege devices can be built by ranked Horde players at the Goblin Workshops.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31107, ["x"] = 0.38925, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31107, ["x"] = 0.38925, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.38925, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13265] = { ["id"] = 13265, ["name"] = "Cloth Scavenging", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 13265 }, ["objectivesText"] = "Progress: The cut of your clothes suggests to me that you are a Tailor yourself and could easily learn the skill that I have to teach. Many of the northern humanoids wear clothes that can quickly be converted into cloth if you know the knack of doing it. For a small fee I can teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 27001, ["x"] = 0.575, ["y"] = 0.722 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 27001, ["x"] = 0.575, ["y"] = 0.722 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.575, ["y"] = 0.722 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "standard" },
[13268] = { ["id"] = 13268, ["name"] = "Cloth Scavenging", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 495, ["mapID"] = 117, ["storyline"] = { 13268 }, ["objectivesText"] = "Progress: You look like someone who knows their way around a needle and thread so maybe I can help you. The northern humanoids wear clothes that can quickly be converted into cloth if you know how. For a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional cloth from the humanoids of Northrend.", ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 26914, ["x"] = 0.585, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 26914, ["x"] = 0.585, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 495 } }, ["questType"] = "standard" },
[13269] = { ["id"] = 13269, ["name"] = "Cloth Scavenging", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 495, ["mapID"] = 117, ["storyline"] = { 13269 }, ["objectivesText"] = "Progress: The humanoids of the northern lands wear garments that can be converted into cloth if you know how. For a few gold I am willing to teach you the art of Cloth Scavenging that will give you additional frostweave cloth from the humanoids of Northrend that you slay.", ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 117, ["npcID"] = 26964, ["x"] = 0.794, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 117, ["npcID"] = 26964, ["x"] = 0.794, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 117, ["source"] = "quest_giver", ["x"] = 0.794, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 117 }, ["zone"] = { 495 } }, ["questType"] = "standard" },
[13324] = { ["id"] = 13324, ["name"] = "Darkmoon Prisms Deck", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 2, ["zoneID"] = 5861, ["storyline"] = { 13324 }, ["description"] = "Now that you have gathered all of the Prism cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight. On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\" You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", ["objectivesText"] = "Return the Prisms Deck to the Darkmoon Faire when it comes to town. Progress: I see that you have managed to complete a deck of Prisms! Congratulations!", ["rewardItems"] = { 42988, 44259 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard", ["startItems"] = { 44259 } },
