[13384] = { ["id"] = 13384, ["name"] = "Judgment at the Eye of Eternity", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 13384 }, ["description"] = "Now that you have access to the focusing iris it's time to put that key to use. As much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down. < Krasus says this last with a great deal of trepidation.> <name>, travel to the Eye of Eternity , confront Malygos and return with the Heart of Magic .", ["objectivesText"] = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic . This quest is for the Normal mode, 10-person version of The Eye of Eternity . Progress: Only Malygos carries the Heart of Magic . It is his most prized possession.", ["rewardGold"] = 509400, ["rewardXP"] = 6175, ["rewardItems"] = { 44569, 44650, 44657, 44658, 44659, 44660, 44661, 44662, 44664, 44665 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 27990, ["x"] = 0.598, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 27990, ["x"] = 0.598, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "raid" },
[13385] = { ["id"] = 13385, ["name"] = "Heroic Judgment at the Eye of Eternity", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4500, ["mapID"] = 115, ["storyline"] = { 13385 }, ["description"] = "Now that you have access to the focusing iris it's time to put that key to use. As much as I would like to see Malygos brought back into the fold, that's just not going to happen at this point. With everything that's at stake, it is the judgment of the other Dragon Aspects that the Spell-Weaver needs to be put down. < Krasus says this last with a great deal of trepidation.> <name>, travel to the Eye of Eternity , confront Malygos and return with the Heart of Magic .", ["objectivesText"] = "Krasus atop Wyrmrest Temple in the Dragonblight wants you to return with the Heart of Magic . This quest is for the Heroic mode, 25-person version of The Eye of Eternity . Progress: Only Malygos carries the Heart of Magic . It is his most prized possession.", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 44651, 44661, 44662, 44664, 44665 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 27990, ["x"] = 0.598, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 27990, ["x"] = 0.598, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 4500 } }, ["questType"] = "raid" },
[13410] = { ["id"] = 13410, ["name"] = "Hellfire Fortifications", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 13410 }, ["description"] = "The Hellfire Citadel wages constant battles with our forces. We are holding our own so far, but we can't yet launch a real offensive against them. To do that, we need forward staging areas. Our scouts identified three fortifications near Hellfire Citadel. We want you to help secure these forts. Capture each fort, and then report back to me. May fortune shine upon you in the conflicts ahead, <name>, for you will no doubt clash with Horde forces eager to gain these same fortifications.", ["objectivesText"] = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula .", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 24579, 24581 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 18266, ["x"] = 0.564, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 18266, ["x"] = 0.564, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "pvp" },
[13411] = { ["id"] = 13411, ["name"] = "Hellfire Fortifications", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3483, ["mapID"] = 100, ["storyline"] = { 13411 }, ["description"] = "The fel orcs of Hellfire Citadel must be scoured from our birthland! To attack them, we must first secure forward staging points near the Citadel. Our outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them! We want you to stop the Alliance and capture these forts. Aid in the capture of each fort and then return to me. For the Horde!", ["objectivesText"] = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 24579, 24581 }, ["starts"] = { { ["mapID"] = 100, ["npcID"] = 18267, ["x"] = 0.558, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 100, ["npcID"] = 18267, ["x"] = 0.558, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 100, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 100 }, ["zone"] = { 3483 } }, ["questType"] = "pvp" },
[13417] = { ["id"] = 13417, ["name"] = "The Brothers Bronzebeard", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["storyline"] = { 13417 }, ["description"] = "That does it! We finally have the keystone... It's beautiful! I've been around the world more than once, but this thing's got me all jittery with excitement again. I suppose now's not the time to stop and admire though, we need to get the heck out of here. Hop on my flying machine and help keep us covered from those iron dwarves on the way out!", ["objectivesText"] = "Accompany Brann Bronzebeard and his flying machine to Frosthold.", ["rewardGold"] = 222000, ["rewardXP"] = 300, ["rewardItems"] = { 43189, 43190, 43191, 43192 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[13430] = { ["id"] = 13430, ["name"] = "Trial of the Naaru: Magtheridon", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 1, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 13430 }, ["description"] = "Four trials you must pass before you are deemed worthy by the naaru. Only one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon , deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", ["objectivesText"] = "A'dal in Shattrath City wants you to slay Magtheridon .", ["rewardGold"] = 509400, ["rewardXP"] = 6175, ["rewardItems"] = { 31746 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 18481, ["x"] = 0.502667, ["y"] = 0.447778 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.502667, ["y"] = 0.447778 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "raid" },
[13432] = { ["id"] = 13432, ["name"] = "The Vials of Eternity", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 440, ["storyline"] = { 13432 }, ["description"] = "Seven vials were drawn from the Well of Eternity by Illidan. He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created. For years the rest were believed lost. With the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj. Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient. The outcome of the Battle of Mount Hyjal must be preserved.", ["objectivesText"] = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep. Progress: I've asked the impossible of you, yet I expect you to succeed. Much depends on it.", ["rewardGold"] = 929400, ["rewardXP"] = 6175, ["rewardItems"] = { 29905, 29906 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "raid", ["db2QuestSortName"] = "Nightborne" },
