[13479] = { ["id"] = 13479, ["name"] = "The Great Egg Hunt", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["event"] = "Noblegarden", ["expansion"] = 2, ["zoneID"] = 15969, ["mapID"] = 1, ["storyline"] = { 13479 }, ["series"] = { 13483 }, ["description"] = "Noblegarden, celebration of life and spring! I hope you've been enjoying the egg hunt, friend, because I could use the services of a capable individual like you. I'm not certain what form of magic was used in the creation of the eggs, and the druids aren't keen on explaining it to me. Perhaps you could collect some shell fragments for me during your egg collection. You can keep the contents of the eggs; all I require is a sufficient sample of the eggs themselves.", ["objectivesText"] = "Get 20 shell fragments. Progress: Do you have the fragments?", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 44792, 44806 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 32798, ["x"] = 0.52, ["y"] = 0.417 }, { ["mapID"] = 2112, ["npcID"] = 215033, ["x"] = 0.542, ["y"] = 0.6025 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 32798, ["x"] = 0.52, ["y"] = 0.417 }, { ["mapID"] = 2112, ["npcID"] = 215033, ["x"] = 0.542, ["y"] = 0.6025 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.417 }, ["mapCandidates"] = { ["npc"] = { 1, 2112 }, ["zone"] = { 15969 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 3250 } },
