[13502] = { ["id"] = 13502, ["name"] = "A Tisket, a Tasket, a Noblegarden Basket", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Noblegarden", ["expansion"] = 2, ["zoneID"] = 15969, ["mapID"] = 27, ["storyline"] = { 13502 }, ["description"] = "Here... take this egg basket and go hunting for brightly colored eggs. Return to me with the basket when you've found ten Noblegarden chocolates , please.", ["objectivesText"] = "Collect 10 Noblegarden Chocolates and return them along with the Borrowed Egg Basket . Progress: Do you have the ten Noblegarden Chocolates ?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 44791, 44802, 45067, 188698 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 32836, ["x"] = 0.54, ["y"] = 0.508 }, { ["mapID"] = 2112, ["npcID"] = 215033, ["x"] = 0.542, ["y"] = 0.6025 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 32836, ["x"] = 0.54, ["y"] = 0.508 }, { ["mapID"] = 2112, ["npcID"] = 215033, ["x"] = 0.542, ["y"] = 0.6025 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 27, 2112 }, ["zone"] = { 15969 } }, ["questType"] = "standard" },
