[13538] = { ["id"] = 13538, ["name"] = "Southern Sabotage", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13538 }, ["description"] = "The three towers south of the Wintergrasp river are draining power from the Fortress! Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower, then return to me. Remember, only siege vehicles can damage a tower, so make sure to protect them from the Horde!", ["objectivesText"] = "Destroy Shadowsight Tower, Flamewatch Tower or Winter's Edge Tower and return to Tactical Officer Ahbramis in Wintergrasp .", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31153, ["x"] = 0.611, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31153, ["x"] = 0.611, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.611, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
[13539] = { ["id"] = 13539, ["name"] = "Toppling the Towers", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "weekly" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4197, ["mapID"] = 123, ["storyline"] = { 13539 }, ["description"] = "While the Alliance may be pounding on our doors, a true tactician looks beyond the obvious. \"Attack him where he is unprepared, appear where you are not expected.\" <name>, I need you to travel across the Wintergrasp River and destroy one of the three towers to the south. Our Warlocks report that the towers are draining power we could use to bolster our own troops. Return to me once you've destroyed a tower.", ["objectivesText"] = "Destroy Shadowsight Tower, Flamewatch Tower, or Winter's Edge Tower and return to Tactical Officer Kilrath in Wintergrasp .", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 123, ["npcID"] = 31151, ["x"] = 0.406667, ["y"] = 0.231333 } }, ["ends"] = { { ["mapID"] = 123, ["npcID"] = 31151, ["x"] = 0.406667, ["y"] = 0.231333 } }, ["coords"] = { ["mapID"] = 123, ["source"] = "quest_giver", ["x"] = 0.406667, ["y"] = 0.231333 }, ["mapCandidates"] = { ["npc"] = { 123 }, ["zone"] = { 4197 } }, ["questType"] = "pvp" },
