[13592] = { ["id"] = 13592, ["name"] = "A Valiant's Field Training", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13592 }, ["description"] = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy. Travel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", ["objectivesText"] = "Sir Marcus Barlowe at the Argent Tournament Grounds wants you to kill 10 Converted Heroes . Progress: Have you tested yourself in combat against the Scourge?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44987 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33222, ["x"] = 0.765, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33222, ["x"] = 0.765, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13593] = { ["id"] = 13593, ["name"] = "Valiant Of Stormwind", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13593 }, ["description"] = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Stormwind's tournament delegation? You will train and rise through the ranks as you have before, but when you are named a champion of Stormwind, your squire will have the option of carrying our banner into battle.", ["objectivesText"] = "Speak with Marshal Jacob Alerius again if you wish to become a valiant of Stormwind.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13600] = { ["id"] = 13600, ["name"] = "A Worthy Weapon", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13600 }, ["description"] = "Of all the times to have such rotten luck! My tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", ["objectivesText"] = "Bring the Blade of Drak'Mar to Marshal Jacob Alerius at the Argent Tournament Grounds. Progress: Were the wandering bard's tales true? Have you brought a blade?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44978, 44987, 45000, 45192, 98134 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13603] = { ["id"] = 13603, ["name"] = "A Blade Fit For A Champion", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13603 }, ["description"] = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, <name>. Otherwise, you'll catch warts.", ["objectivesText"] = "Retrieve the Ashwood Brand and bring it to Marshal Jacob Alerius at the Argent Tournament Grounds. Progress: Were you able to recover the blade?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44981, 44986, 44987, 45192, 46874 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13604] = { ["id"] = 13604, ["name"] = "Archivum Data Disc", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13604 }, ["description"] = "This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections. Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\" There must be a device inside Ulduar capable of reading the disc.", ["objectivesText"] = "Bring the Archivum Data Disc to the Archivum Console in Ulduar . Progress: The console whirrs with energy as the round receptacle opens.", ["rewardGold"] = 315000, ["rewardXP"] = 6175, ["rewardItems"] = { 45506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid", ["startItems"] = { 45506 } },
[13606] = { ["id"] = 13606, ["name"] = "Freya's Sigil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13606 }, ["description"] = "Freya's Sigil is going to be one of the tougher ones, I reckon. According to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark. Should any of the elders be harmed, the Sigil's integrity will be compromised. Sparing the elders, however, means that Freya will be more powerful when you face her. What can I say, <name>. We're stuck between a rock and hard place.", ["objectivesText"] = "Prospector Doren at the Archivum in Ulduar wants you to obtain Freya's Sigil . For more information on obtaining Freya's Sigil consult the Archivum Console. Progress: Freya's sigil , <name>? Do ye have it?", ["rewardGold"] = 1123600, ["rewardXP"] = 8230, ["rewardItems"] = { 45788 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13607] = { ["id"] = 13607, ["name"] = "The Celestial Planetarium", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13607 }, ["description"] = "Listen, <lad/lass>! Azeroth's fate is at stake here. Our only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters. Locate the Celestial Planetarium and come back with any information you get. We might still have some time to prepare for Algalon's arrival.", ["objectivesText"] = "Prospector Doren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium.", ["rewardGold"] = 210000, ["rewardXP"] = 5145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13609] = { ["id"] = 13609, ["name"] = "Hodir's Sigil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13609 }, ["description"] = "Hodir's Sigil won't be easy to obtain. Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it! Check the Archivum console if you need more information. That thing contains more knowledge than all of the world's libraries put together!", ["objectivesText"] = "Prospector Doren at the Archivum in Ulduar wants you to obtain Hodir's Sigil . For more information on obtaining Hodir's Sigil , consult the Archivum Console. Progress: Did ye obtain the sigil, <name>?", ["rewardGold"] = 1123600, ["rewardXP"] = 8230, ["rewardItems"] = { 45786 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13610] = { ["id"] = 13610, ["name"] = "Thorim's Sigil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13610 }, ["description"] = "Thorim's not himself, <name>. He's come under a dark influence. An evil presence under the guise of an illusion pretends to be his lost wife, Sif. Ye can't let him be overcome by this impostor's spell. If he does, the location of his sigil might forever be lost! Yer going to have to beat some sense into him and yer going to have to do it quick. As always, the Archivum Console will give ye all the gory details... even the ones ye don't like.", ["objectivesText"] = "Prospector Doren at the Archivum in Ulduar wants you to obtain Thorim's Sigil . For more information on obtaining Thorim's Sigil consult the Archivum Console. Progress: Well, <name>? Do ye have it?", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 45784 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13611] = { ["id"] = 13611, ["name"] = "Mimiron's Sigil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13611 }, ["description"] = "Mimiron's a clever one. His entire abode is rigged with some sort of self-destruction mechanism. Unfortunately yer gonna have to race against it if ye want to get his sigil. Check the Archivum Console for more details if ye need them.", ["objectivesText"] = "Prospector Doren at the Ulduar Archivum wants you to obtain Mimiron's Sigil . For more information on obtaining Mimiron's Sigil consult the Archivum Console. Progress: Were you able to obtain the sigil, <name>?", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 45787 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13614] = { ["id"] = 13614, ["name"] = "Algalon", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13614 }, ["description"] = "You really did it, <name>. Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium. You best hurry, <lad/lass>. Time is of the essence.", ["objectivesText"] = "Bring the Sigils of the Watchers to the Archivum Console in Ulduar . Progress: The console's bright lights scan the glass surface repeatedly, as if awaiting some form of input.", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 45791, 45798, 45875, 45878 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13616] = { ["id"] = 13616, ["name"] = "The Edge Of Winter", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13616 }, ["description"] = "Curse that death knight for breaking my sword! In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, <name>.", ["objectivesText"] = "Marshal Jacob Alerius at the Argent Tournament Grounds wants you to bring him Winter's Edge . Progress: Did you win the blade I seek?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45003, 45005, 45192 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13622] = { ["id"] = 13622, ["name"] = "Ancient History", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13622 }, ["series"] = { 13629 }, ["description"] = "The pieces fit together to form an elegant hammer. Its construction appears to be at least partially Titan in nature. The console inside the Archivum might have some information regarding this artifact.", ["objectivesText"] = "Bring the Shattered Fragments of Val'anyr to the Archivum Console in the Archivum in Ulduar . Progress: Awaiting input.", ["rewardItems"] = { 40684, 45038, 45039 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid", ["startItems"] = { 45039 } },
[13625] = { ["id"] = 13625, ["name"] = "Learning The Reins", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13625 }, ["description"] = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds. Visit the stables outside the pavilion, equip your lance, and mount up on the Quel'dorei steed. Familiarize yourself with the tactics available to you and use them to defeat the three different kinds of training dummies.", ["objectivesText"] = "Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets and then return to Scout Shalyndria at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or the Silver Covenant Pavilion. Progress: How goes the mounted combat practice?", ["rewardGold"] = 232300, ["rewardXP"] = 3440, ["rewardItems"] = { 45192 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33647, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33647, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13627] = { ["id"] = 13627, ["name"] = "Jack Me Some Lumber", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["storyline"] = { 13627 }, ["description"] = "Come closer. No, not too close. Don't want any unnecessary suspicion now, do we? This coliseum requires more lumber than we've stockpiled and there's no way I'm going to pay to have it shipped in from Grizzly Hills. At the western end of Crystalsong Forest, by the Great Tree, grow a number of young Crystalsong oaks. They'd provide just the kind of planking we need for building and scaffolding. Take this axe, use it to fell the trees and then hew them into planks, but don't let anyone see you!", ["objectivesText"] = "Bring 12 Rough Hewn Planks to Bezzle Blastbolt at the Argent Tournament Grounds.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44703, 45045, 45046 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[13629] = { ["id"] = 13629, ["name"] = "Val'anyr, Hammer of Ancient Kings", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13629 }, ["series"] = { 13622 }, ["description"] = "The Archivum Console has hinted at a possible way to rebind the fragments of Val'anyr: you must get the fragments inside the physical form of the being known as Yogg-Saron. It sounds like a long shot, but for an artifact of such power you think the risk might just be worth it.", ["objectivesText"] = "Throw the Shattered Pieces of Val'anyr into Yogg-Saron's maw while he's casting Deafening Roar and defeat Yogg-Saron and recover the Reforged Hammer of Ancient Kings . This can only be completed in Heroic mode and only if at least one Ulduar Watcher is not assisting you. Progress: Awaiting input.", ["rewardGold"] = 315000, ["rewardXP"] = 6175, ["rewardItems"] = { 45896, 45897, 46017 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13631] = { ["id"] = 13631, ["name"] = "All Is Well That Ends Well", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13631 }, ["description"] = "We'd best hurry now, <name>. We're going to have to transmit the reply-code from Dalaran. Take it to Rhonin , I will meet you there.", ["objectivesText"] = "Take the Reply-Code Alpha to Rhonin in Dalaran. Progress: You're ready, <name>?", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 45588, 45608, 45614, 45618, 46052, 46320, 46321, 46322, 46323 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid", ["startItems"] = { 46052 } },
[13633] = { ["id"] = 13633, ["name"] = "The Black Knight of Westfall?", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13633 }, ["series"] = { 13634, 13641, 13643, 13654, 13663 }, ["description"] = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end. Of course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background. He claims to be descended from the Cooper family of Westfall. Would you visit their residence in the western part of Moonbrook in Westfall? See if you can find any proof of his story.", ["objectivesText"] = "Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings. Progress: Have you found anything related to the Black Knight's story?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 45058 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13634] = { ["id"] = 13634, ["name"] = "The Black Knight of Silverpine?", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13634 }, ["series"] = { 13633, 13641, 13643, 13654, 13663 }, ["description"] = "No doubt you've heard the disturbing rumors about the contestant the others are calling the Black Knight. It's said that any rider who was scheduled to face him in combat has met an untimely end. Of course, we have no definitive proof of anything, but it wouldn't hurt to look into this knight's background. He claims to hail from Valgan's Field in Silverpine Forest. It's a small farm on the western shore of Lordamere Lake. Would you visit the farm and let me know if there's any truth to his story?", ["objectivesText"] = "Investigate the Black Knight's claims and return to Crusader Rhydalla at the Argent Tournament Grounds with your findings. Progress: Have you found anything related to the Black Knight's story?", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["rewardItems"] = { 45062 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13641] = { ["id"] = 13641, ["name"] = "The Seer's Crystal", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13641 }, ["series"] = { 13633, 13634, 13643, 13654, 13663 }, ["description"] = "Now that we know there's no truth to the Black Knight's stories, we must find a way to connect him to the murdered knights. I know a way to reveal the truth about how they died, but it requires a rare material. We must gain a seer's crystal , found only among the unbound seers who congregate near night elf ruins in the Forlorn Woods in the central part of Crystalsong Forest. Find one of these seers, <name>, and bring me the crystal it holds.", ["objectivesText"] = "Bring a Seer's Crystal to Crusader Rhydalla at the Argent Tournament Grounds. Progress: Have you located a seer's crystal ?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 45064 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13643] = { ["id"] = 13643, ["name"] = "The Stories Dead Men Tell", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13643 }, ["series"] = { 13633, 13634, 13641, 13654, 13663 }, ["description"] = "The crystal will reveal the truth about how three of the tournament's combatants died. Take it with you to the graveyard east of the Tournament Grounds and use it before the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip. If indeed these men were murdered, then we must find a way to tie it to the Black Knight before he strikes again. Look closely at what the crystal tells you, <name>, for we must be certain these deaths were not accidental.", ["objectivesText"] = "Use the Seer's Crystal at the graves of Sir Wendell Balfour, Lorien Sunblaze, and Conall Irongrip to determine how they died, then return to Crusader Rhydalla . Progress: Have you visisted the graves of the slain combatants?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 45070 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13654] = { ["id"] = 13654, ["name"] = "There's Something About the Squire", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13654 }, ["series"] = { 13633, 13634, 13641, 13643, 13663 }, ["description"] = "Every day, the Black Knight's squire, Maloric, makes a big show of heading to Crystalsong Forest with his axe over his shoulder. He wants us to believe he's chopping wood, but he never returns with more than a few twigs. He usually goes toward the ruins southwest of the Mirror of Twilight. He spends a lot of time out there, even for a squire with responsibilities to his knight. Find a way to distract or incapacitate him and search him. If he's up to something, we'll know it.", ["objectivesText"] = "Obtain a Large Femur from a Skeletal Woodcutter and use it to incapacitate Maloric. Search Maloric for evidence, then report back to Crusader Rhydalla at the Argent Tournament Grounds. Progress: Did the squire's behavior yield any clues?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 45080, 45082, 47541, 69777 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13663] = { ["id"] = 13663, ["name"] = "The Black Knight's Orders", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13663 }, ["series"] = { 13664, 14016, 14017 }, ["description"] = "We must discover who sent the Black Knight to the tournament and what his master hopes to gain by killing the competitors. The Kirin Tor has offered to help in this matter and provided us with something to help our search. Take this enchanted bridle to the Black Knight's camp on the eastern edge of the tournament grounds and use it to gain control over the Black Knight's gryphon . The bridle's magic will force the gryphon to take you to his master's home. Search it and return with anything you find.", ["objectivesText"] = "Use the Enchanted Bridle to gain control of the Black Knight's Gryphon and ride it to its destination. Once you have arrived, recover the Stolen Tournament Invitation and the Black Knight's Orders and bring them to Crusader Rhydalla at the Argent Tournament Grounds. Progress: What did you discover?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 45083, 45121, 45122 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13664] = { ["id"] = 13664, ["name"] = "The Black Knight's Fall", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13664 }, ["series"] = { 13663, 14016, 14017 }, ["description"] = "We must put an end to the Black Knight 's scheming, and show those who oppose us that we will not stand by and allow our champions to be murdered. By now, he will suspect that someone is on his trail. Challenge him in the light of day, where he cannot refuse or murder in the dark, <name>. Use my argent charger for the battle. It's housed in the stables. Speak to Squire Cavin at the Ring of Champions. The squire will call the Black Knight to battle, but you will make him answer for his crimes.", ["objectivesText"] = "Defeat the Black Knight and then speak to Crusader Rhydalla at the Argent Tournament Grounds.", ["rewardGold"] = 619600, ["rewardXP"] = 4300, ["rewardItems"] = { 45568 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13665] = { ["id"] = 13665, ["name"] = "The Grand Melee", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13665 }, ["description"] = "The grand melee is the most important of the tournament's competitions. The people of Stormwind adore their knights and are looking forward to seeing us win the melee. To that end, they've been honing their skills against the other valiants. I suggest you do the same. Go to the stables outside the pavilion, equip your lance, mount the stabled Elwynn steed, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.", ["objectivesText"] = "Bring 3 Marks of the Valiant to Captain Joseph Holley at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you completed your training for the grand melee?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45127 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33223, ["x"] = 0.765, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33223, ["x"] = 0.765, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13666] = { ["id"] = 13666, ["name"] = "A Blade Fit For A Champion", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13666 }, ["description"] = "Some of the champions believe an ancient weapon born of Northrend will bring them luck in the tourney. I have agreed to help them search for these weapons. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, <name>. Otherwise, you'll catch warts.", ["objectivesText"] = "Retrieve the Ashwood Brand and bring it to Arcanist Taelis at the Argent Tournament Grounds. Progress: Were you able to recover the blade?", ["rewardGold"] = 210675, ["rewardXP"] = 3440, ["rewardItems"] = { 44981, 44986, 44987, 45192, 46874 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13667] = { ["id"] = 13667, ["name"] = "The Argent Tournament", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13667 }, ["series"] = { 13828 }, ["description"] = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy. Arcanist Taelis is the Silver Covenant's representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Alliance tent in the northeastern part of the grounds.", ["objectivesText"] = "Speak with Arcanist Taelis at the Argent Tournament grounds to enroll in the tournament.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33817, ["x"] = 0.696, ["y"] = 0.228 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.228 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13668] = { ["id"] = 13668, ["name"] = "The Argent Tournament", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13668 }, ["series"] = { 13829 }, ["description"] = "We have invited you here to test your skill and valor against others who have bravely opposed the Scourge. Many have been our divisions, but the time has come for heroes fighting under all banners to test their blades against one another in preparation for facing our mutual enemy. Magister Edien Sunhollow is the Sunreaver representative to the tournament and he'll enter your name into the rolls and begin your training. Seek him out inside the large Horde tent in the southeastern part of the grounds.", ["objectivesText"] = "Speak with Magister Edien Sunhollow at the Argent Tournament grounds to enroll in the tournament.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33817, ["x"] = 0.696, ["y"] = 0.228 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.228 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13669] = { ["id"] = 13669, ["name"] = "A Worthy Weapon", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13669 }, ["description"] = "Our champions have taken a liking to ancient weapons produced here in Northrend. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", ["objectivesText"] = "Bring the Blade of Drak'Mar to Arcanist Taelis at the Argent Tournament Grounds. Progress: Were the wandering bard's tales true? Have you brought a blade?", ["rewardGold"] = 78750, ["rewardXP"] = 3440, ["rewardItems"] = { 44978, 44987, 45000, 45192, 98134 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13670] = { ["id"] = 13670, ["name"] = "The Edge Of Winter", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13670 }, ["description"] = "The Ironforge grand champion's squire told me an intriguing story. In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, <name>.", ["objectivesText"] = "Arcanist Taelis at the Argent Tournament Grounds wants you to bring him Winter's Edge . Progress: Did you win the blade?", ["rewardGold"] = 78750, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45003, 45005, 45192 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13671] = { ["id"] = 13671, ["name"] = "Training In The Field", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13671 }, ["description"] = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament. Travel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", ["objectivesText"] = "Avareth Swiftstrike at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment. Progress: Have you tested yourself in combat against the Scourge?", ["rewardGold"] = 78750, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45192, 182482, 182491, 182500, 182509, 183744, 184843 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33646, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33646, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13672] = { ["id"] = 13672, ["name"] = "Up To The Challenge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13672 }, ["series"] = { 13679 }, ["description"] = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant. When you are ready to begin the challenge, return to me.", ["objectivesText"] = "Present Arcanist Taelis at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge. Progress: Do you wish to take the aspirant's challenge?", ["rewardGold"] = 10500, ["rewardXP"] = 430, ["rewardItems"] = { 33231, 33256, 40483, 44382, 44383, 44384, 44385, 45192, 57828, 57846, 57847, 57850, 93724, 98134, 114700, 114701, 114702, 114703, 114704, 114705, 114706, 114707, 116062, 131675, 141175, 143488, 156999, 181179, 181181, 181186, 181187, 181192, 181195, 181202, 181203, 181211, 181217, 181469, 181476, 181545, 181546, 181547, 181548, 181550, 181557, 181733, 181741, 181866, 182127, 182667, 182724, 183132, 184147, 184150, 184777, 185854, 199197, 211279, 237812 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
