[13675] = { ["id"] = 13675, ["name"] = "The Edge Of Winter", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13675 }, ["description"] = "I heard an interesting story from one of the Orgrimmar valiants. In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, <name>.", ["objectivesText"] = "Magister Edien Sunhollow at the Argent Tournament Grounds wants you to bring him Winter's Edge . Progress: Did you win the blade?", ["rewardGold"] = 210675, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45003, 45005, 45192 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13676] = { ["id"] = 13676, ["name"] = "Training In The Field", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13676 }, ["description"] = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you learn to master mounted combat, do not forget to practice the skills that have served you well all these years. Show us that you can face the Scourge with honor and bravery, and you will earn your right to compete in this tournament. Travel to Icecrown and slay any Scourge you see there, but stay clear of the Bombardment, where you would be overwhelmed.", ["objectivesText"] = "Amariel Sunsworn at the Argent Tournament Grounds wants you to kill 8 Icecrown Scourge. You may kill Scourge in any part of Icecrown except the Bombardment. Progress: Have you tested yourself in combat against the Scourge?", ["rewardGold"] = 232300, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45192, 182482, 182491, 182500, 182509, 183744, 184843 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33658, ["x"] = 0.762, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33658, ["x"] = 0.762, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13677] = { ["id"] = 13677, ["name"] = "Learning The Reins", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13677 }, ["description"] = "Most of the tournament's competitions require competitors to master the command of a mount in battle. In order to familiarize you with mounted combat, we've put up training dummies all over the northern part of the tournament grounds. Visit the stables outside the pavilion, equip your lance, and mount up on the Sunreaver hawkstrider. Familiarize yourself with the mount and use its abilities to defeat the three different kinds of training dummies.", ["objectivesText"] = "Strike a Melee Target with Thrust 5 times, use Shield-Breaker on 2 vulnerable Ranged Targets, use Charge on 2 vulnerable Charge Targets, and then return to Galathia Brightdawn at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or the Sunreaver Pavilion. Progress: How goes the mounted combat practice?", ["rewardGold"] = 232300, ["rewardXP"] = 3440, ["rewardItems"] = { 45192 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33659, ["x"] = 0.762, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33659, ["x"] = 0.762, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13678] = { ["id"] = 13678, ["name"] = "Up To The Challenge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13678 }, ["series"] = { 13680 }, ["description"] = "When you have mastered the skills of the aspirant, you may choose to take the aspirant's challenge. The challenge will test your mounted combat skills and assess whether or not you're prepared to become a valiant. Should you pass, you will be able to join your capital city's delegation as a valiant. When you are ready to begin the challenge, return to me.", ["objectivesText"] = "Present Magister Edien Sunhollow at the Argent Tournament with 15 Aspirant's Seals to signify you're ready to undergo the aspirant's challenge. Progress: Do you wish to take the aspirant's challenge?", ["rewardGold"] = 10500, ["rewardXP"] = 430, ["rewardItems"] = { 33231, 33256, 40483, 44382, 44383, 44384, 44385, 45192, 57828, 57846, 57847, 57850, 93724, 98134, 114700, 114701, 114702, 114703, 114704, 114705, 114706, 114707, 116062, 131675, 141175, 143488, 156999, 181179, 181181, 181186, 181187, 181192, 181195, 181202, 181203, 181211, 181217, 181469, 181476, 181545, 181546, 181547, 181548, 181550, 181557, 181733, 181741, 181866, 182127, 182667, 182724, 183132, 184147, 184150, 184777, 185854, 199197, 211279, 237812 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13679] = { ["id"] = 13679, ["name"] = "The Aspirant's Challenge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13679 }, ["series"] = { 13672 }, ["description"] = "You have trained hard as an aspirant, <name>, and now the time has come to test your mounted combat skills against a skilled opponent. Equip your lance, then go to the stables outside the pavilion and mount up on the stabled Quel'dorei steed. At the Aspirants' Ring on the northern side of the tournament grounds, you'll find Squire David. He'll make certain that you're ready for the fight and call out your opponent. Good luck, <name>. May your horse be steady and your aim true.", ["objectivesText"] = "Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Arcanist Taelis at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 43154 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13680] = { ["id"] = 13680, ["name"] = "The Aspirant's Challenge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13680 }, ["series"] = { 13678 }, ["description"] = "You have trained hard as an aspirant, <name>, and now the time has come to test your mounted combat skills against an experienced opponent. Equip your lance, then go to the stables outside the pavilion and mount the Sunreaver hawkstrider. At the Aspirants' Ring on the northern side of the tournament grounds, you'll find a human child called Squire David. He'll ask if you're ready for the fight and call out your opponent. Good luck, <name>. May your mount be steady and your aim true.", ["objectivesText"] = "Speak with Squire David to summon your opponent. Once you have defeated the Argent Valiant, return to Magister Edien Sunhollow at the Argent Tournament Grounds.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13681] = { ["id"] = 13681, ["name"] = "A Chip Off the Ulduar Block", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["storyline"] = { 13681 }, ["description"] = "Getting stone for this job has been a nightmare, I tell ya! There are tons of stone available from ruins in safe places, but those holier-than-thou paladins won't go for it. Something about 'priceless artifacts.' Anyway, whining about that isn't going to get this place built. There are tons of crumbling titan ruins in the Foot Steppes and at the Inventor's Library in Storm Peaks. Take my, uh, 'chisel' with you and see if you can break those huge blocks into useful pieces.", ["objectivesText"] = "Bring 15 Small Stone Blocks to Bozzle Blastbolt at the Argent Tournament Grounds.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 45278, 45281 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[13682] = { ["id"] = 13682, ["name"] = "Threat From Above", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13682 }, ["description"] = "Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated. Our skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", ["objectivesText"] = "Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers .", ["rewardXP"] = 3440, ["rewardItems"] = { 45724, 46114, 50415 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33759, ["x"] = 0.698, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33759, ["x"] = 0.698, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "group" },
[13684] = { ["id"] = 13684, ["name"] = "A Valiant Of Stormwind", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13684 }, ["description"] = "You've proven yourself worthy of competing under the banner of Stormwind, <name>. Now, you should introduce yourself to Marshal Jacob Alerius , who leads the Stormwind delegation. As Stormwind's grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, <name>, and I wish you luck in the competition ahead.", ["objectivesText"] = "Speak with Marshal Jacob Alerius at the Argent Tournament Grounds to become a valiant of Stormwind.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13685] = { ["id"] = 13685, ["name"] = "A Valiant Of Ironforge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["requiredRaces"] = { 3, 34 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13685 }, ["description"] = "You've proven yourself worthy of competing under the banner of Ironforge, <name>. Now, you should introduce yourself to Lana Stouthammer , who leads the Ironforge delegation. As Ironforge's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, <name>, and I wish you luck in the competition ahead.", ["objectivesText"] = "Speak with Lana Stouthammer at the Argent Tournament Grounds to become a valiant of Ironforge.", ["rewardGold"] = 22130, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
