[13695] = { ["id"] = 13695, ["name"] = "A Valiant Of Undercity", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13695 }, ["description"] = "You've proven yourself worthy of competing under the banner of the Undercity, <name>. Now, you should speak with Deathstalker Visceri , who leads the Undercity delegation. As grand champion, he will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, <name>, and I wish you luck in the competition ahead.", ["objectivesText"] = "Speak with Deathstalker Visceri at the Argent Tournament Grounds to become a valiant of the Undercity.", ["rewardGold"] = 30900, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33373, ["x"] = 0.764, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13696] = { ["id"] = 13696, ["name"] = "A Valiant Of Silvermoon", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13696 }, ["description"] = "You've proven yourself worthy of competing under the banner of Silvermoon, <name>. Now, you should speak with Eressea Dawnsinger , who leads the Silvermoon delegation. As Silvermoon's grand champion, she will enter you into the tournament on behalf of the city and oversee your training and testing as valiant. It has been an honor working with you, <name>, and I wish you luck in the competition ahead.", ["objectivesText"] = "Speak with Eressea Dawnsinger at the Argent Tournament Grounds to become a valiant of Silvermoon.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33379, ["x"] = 0.764, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13697] = { ["id"] = 13697, ["name"] = "The Valiant's Charge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13697 }, ["series"] = { 13726 }, ["description"] = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents. The valiants are a spirited lot, competing amongst themselves for honor and notoriety. Train as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", ["objectivesText"] = "Bring 25 Valiant's Seals to Mokra the Skullcrusher at the Argent Tournament Grounds. Progress: Are you ready to demonstrate your mastery of the valiant's skills?", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["rewardItems"] = { 44987 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33361, ["x"] = 0.764, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33361, ["x"] = 0.764, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13699] = { ["id"] = 13699, ["name"] = "The Valiant's Challenge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13699 }, ["series"] = { 13718 }, ["description"] = "You are nearly ready to compete on behalf of Stormwind in the grand melee. To prove yourself worthy to enter the lists on behalf of our city, you must defeat a champion of the Argent Crusade. Go to the stables outside the pavilion, equip your lance, and mount up. Speak to Squire Danny at the Argent Valiants' Ring on the western edge of the grounds. The squire will call out your opponent when you're ready. After the battle is concluded, we will speak of the outcome.", ["objectivesText"] = "Speak with Squire Danny to summon your opponent. Once you have defeated the Argent Champion, return to Marshal Jacob Alerius at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you overcome the Argent champion?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13702] = { ["id"] = 13702, ["name"] = "A Champion Rises", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13702 }, ["description"] = "Congratulations, <name>. You have mastered many kinds of combat and overcome all the challenges you've faced. There can be no doubt that you are ready to compete with the best warriors who have gathered at the tournament, against the champions of the capital cities. Justicar Mariel Trueheart has asked to speak with you, <name>, and to formally enter you in the champions' grand melee.", ["objectivesText"] = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", ["rewardGold"] = 561800, ["rewardXP"] = 4300, ["rewardItems"] = { 44998 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33225, ["x"] = 0.765, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33817, ["x"] = 0.696, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13703] = { ["id"] = 13703, ["name"] = "Valiant Of Ironforge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13703 }, ["description"] = "Welcome, champion. Word of your combat prowess has already reached my ears. Do you seek to join Ironforge's tournament delegation? You will train and rise through the ranks as you have before, but when you are named a champion of Ironforge, your squire will have the option of carrying our banner into battle.", ["objectivesText"] = "Speak with Lana Stouthammer again if you wish to become a valiant of Ironforge.", ["rewardGold"] = 22130, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13704] = { ["id"] = 13704, ["name"] = "Valiant Of Gnomeregan", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13704 }, ["description"] = "Welcome, champion. Word of your combat prowess has already reached my ears. Gnomeregan's delegation could really benefit from a <class> like you. You will train and rise through the ranks as you have before, but when you are named a champion of Gnomeregan, your squire will have the option of carrying our banner into battle.", ["objectivesText"] = "Speak with Ambrose Boltspark again if you wish to become a valiant of Gnomeregan.", ["rewardGold"] = 20855, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33335, ["x"] = 0.765, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33335, ["x"] = 0.765, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
