[13706] = { ["id"] = 13706, ["name"] = "Valiant Of Darnassus", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13706 }, ["description"] = "Welcome, champion. I have heard of your accomplishments and we would be honored if you would join the delegation from Darnassus. You will train and rise through the ranks as you have before, but when you are named a champion of Darnassus, your squire will have the option of carrying our banner into battle.", ["objectivesText"] = "Speak with Jaelyne Eveonsong again if you wish to become a valiant of Darnassus.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33592, ["x"] = 0.762, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33592, ["x"] = 0.762, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13707] = { ["id"] = 13707, ["name"] = "Valiant Of Orgrimmar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13707 }, ["description"] = "So, you have become a champion? Then, you have proven yourself a worthy combatant and I would proudly welcome you into Orgrimmar's delegation. You will train and rise through the ranks as you have before, but when you are named a champion of Orgrimmar, your gruntling will have the option of carrying our banner into battle.", ["objectivesText"] = "Speak with Mokra the Skullcrusher again if you wish to become a valiant of Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33361, ["x"] = 0.764, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33361, ["x"] = 0.764, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
