[13714] = { ["id"] = 13714, ["name"] = "The Valiant's Charge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13714 }, ["series"] = { 13713 }, ["description"] = "In your training as a valiant, you'll have the chance to test your skills against valiants representing other cities. Although a valiant's battles are not a formal part of the competition, you will learn valuable lessons about the fighting styles and weaknesses of your opponents. The valiants are a spirited lot, competing amongst themselves for honor and notoriety. Train as a valiant until you are confident of your ability to best all who face you, then bring me the seals you have earned.", ["objectivesText"] = "Bring 25 Valiant's Seals to Lana Stouthammer at the Argent Tournament Grounds. Progress: Are you ready to demonstrate your mastery of the valiant's skills?", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["rewardItems"] = { 44987 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
