[13739] = { ["id"] = 13739, ["name"] = "A Champion Rises", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13739 }, ["description"] = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of the Forsaken! Justicar Mariel Trueheart has asked to speak with you, <name>, and to formally enter you in the champions' grand melee.", ["objectivesText"] = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", ["rewardGold"] = 561800, ["rewardXP"] = 4300, ["rewardItems"] = { 44998, 45022 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33373, ["x"] = 0.764, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33817, ["x"] = 0.696, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13740] = { ["id"] = 13740, ["name"] = "A Champion Rises", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13740 }, ["description"] = "You have earned my respect and the respect of your peers. You defeated all who challenged you and mastered the ways of tournament combat. I have no doubt that you are ready to face down the champions of other cities for the glory of Silvermoon! Justicar Mariel Trueheart has asked to speak with you, <name>, and to formally enter you in the champions' grand melee.", ["objectivesText"] = "Speak with Justicar Mariel Trueheart at the Argent Tournament Grounds.", ["rewardGold"] = 561800, ["rewardXP"] = 4300, ["rewardItems"] = { 44998, 45022 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33379, ["x"] = 0.764, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33817, ["x"] = 0.696, ["y"] = 0.228 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13741] = { ["id"] = 13741, ["name"] = "A Blade Fit For A Champion", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13741 }, ["description"] = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, <name>. Otherwise, you'll catch warts.", ["objectivesText"] = "Retrieve the Ashwood Brand and bring it to Lana Stouthammer at the Argent Tournament Grounds. Progress: Were you able to recover the blade?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44981, 44986, 44987, 45192, 46874 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13742] = { ["id"] = 13742, ["name"] = "A Worthy Weapon", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13742 }, ["description"] = "Of all the times to have such rotten luck! My tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", ["objectivesText"] = "Bring the Blade of Drak'Mar to Lana Stouthammer at the Argent Tournament Grounds. Progress: Were the wandering bard's tales true? Have you brought a blade?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44978, 44987, 45000, 45192, 98134 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13743] = { ["id"] = 13743, ["name"] = "The Edge Of Winter", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13743 }, ["description"] = "Curse that death knight for breaking my sword! In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, <name>.", ["objectivesText"] = "Lana Stouthammer at the Argent Tournament Grounds wants you to bring her Winter's Edge . Progress: Did you win the blade I seek?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45003, 45005, 45192 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33312, ["x"] = 0.765, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13744] = { ["id"] = 13744, ["name"] = "A Valiant's Field Training", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13744 }, ["description"] = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy. Travel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", ["objectivesText"] = "Rollo Sureshot at the Argent Tournament Grounds wants you to kill 10 Converted Heroes . Progress: Have you tested yourself in combat against the Scourge?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44987 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33315, ["x"] = 0.766, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33315, ["x"] = 0.766, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13745] = { ["id"] = 13745, ["name"] = "The Grand Melee", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13745 }, ["description"] = "The grand melee is the most important of the tournament's competitions. The people of Ironforge are looking forward to hearing of our success. To that end, they've been honing their skills against the valiants representing the other Alliance capitals. I suggest you do the same. The valiants practice in the ring just outside our tent. Equip your lance, go to the stables outside the pavilion and mount the stabled Ironforge ram, then challenge other Alliance valiants.", ["objectivesText"] = "Bring 3 Marks of the Valiant to Clara Tumblebrew at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you completed your training for the grand melee?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45127 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33309, ["x"] = 0.766, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33309, ["x"] = 0.766, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
