[13754] = { ["id"] = 13754, ["name"] = "The Edge Of Winter", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13754 }, ["description"] = "That's the last time I ever spar with a death knight. In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, <name>.", ["objectivesText"] = "Colosos at the Argent Tournament Grounds wants you to bring him Winter's Edge . Progress: Did you win the blade I seek?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45003, 45005, 45192 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33593, ["x"] = 0.76, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33593, ["x"] = 0.76, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13755] = { ["id"] = 13755, ["name"] = "A Valiant's Field Training", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13755 }, ["description"] = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy. Travel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", ["objectivesText"] = "Saandos at the Argent Tournament Grounds wants you to kill 10 Converted Heroes .", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["rewardItems"] = { 44987 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33655, ["x"] = 0.76, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33655, ["x"] = 0.76, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13756] = { ["id"] = 13756, ["name"] = "The Grand Melee", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13756 }, ["description"] = "The grand melee is the most important of the tournament's competitions. The people of the Exodar are looking forward to seeing us win the melee. To that end, they've been honing their skills against the valiants representing the other Alliance capitals. I suggest you do the same. Go to the stables outside the pavilion, equip your lance, mount the stabled Azuremyst elekk, and challenge the valiants. They wait in the Alliance Valiants' Ring just outside our tent.", ["objectivesText"] = "Bring 3 Marks of the Valiant to Ranii at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you completed your training for the grand melee?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45127 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33656, ["x"] = 0.500667, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33656, ["x"] = 0.500667, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.500667, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13757] = { ["id"] = 13757, ["name"] = "A Blade Fit For A Champion", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13757 }, ["description"] = "Good, honest, honed steel may not carry the day. The other combatants are using enchanted blades and I find myself at a disadvantage, but all is not lost. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, <name>. Otherwise, you'll catch warts.", ["objectivesText"] = "Retrieve the Ashwood Brand and bring it to Jaelyne Evensong at the Argent Tournament Grounds. Progress: Were you able to recover the blade?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44981, 44986, 44987, 45192, 46874, 71076 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33592, ["x"] = 0.762, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33592, ["x"] = 0.762, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13758] = { ["id"] = 13758, ["name"] = "A Worthy Weapon", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13758 }, ["description"] = "Of all the times to have such rotten luck! My blade is missing! I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", ["objectivesText"] = "Bring the Blade of Drak'Mar to Jaelyne Evensong at the Argent Tournament Grounds. Progress: Were the wandering bard's tales true? Have you brought a blade?", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["rewardItems"] = { 44978, 44987, 45000, 45192, 98134 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33592, ["x"] = 0.762, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33592, ["x"] = 0.762, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
