[13764] = { ["id"] = 13764, ["name"] = "The Edge Of Winter", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13764 }, ["description"] = "Curse that death knight for breaking my sword! In southern Crystalsong Forest, overlooking the Crystal Vice's exit, you will find Lord Everblaze. Kill him and take the everburning ember from his corpse. Bring it to the center of Winter's Breath Lake in northern Howling Fjord, and use it to free the maiden encased in ice. She is the guardian of an ancient sword and will award it to whoever frees her. Prove your worth and earn the weapon that she has guarded for so long, <name>.", ["objectivesText"] = "Mokra the Skullcrusher at the Argent Tournament Grounds wants you to bring him Winter's Edge . Progress: Did you win the blade?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45003, 45005, 45192 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33361, ["x"] = 0.764, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33361, ["x"] = 0.764, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
