[13771] = { ["id"] = 13771, ["name"] = "A Valiant's Field Training", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13771 }, ["description"] = "The tournament is a time for testing your skills against your peers, but we must not forget that the real enemy, the Scourge, will not wait. As you hone your skills against others, so should you maintain your edge in combat against the enemy. Travel to the area southwest of the Valley of Fallen Heroes and north of Corp'rethar. There, the Scourge raises dead heroes and turns them against us. Defeat these minions of the Scourge, do honor to our allies, and keep yourself prepared for combat.", ["objectivesText"] = "Shadow Hunter Mezil-kree at the Argent Tournament Grounds wants you to kill 10 Converted Heroes .", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 44987 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33540, ["x"] = 0.76, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33540, ["x"] = 0.76, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13772] = { ["id"] = 13772, ["name"] = "The Grand Melee", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13772 }, ["description"] = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one. It will help prepare you for the rigors of tournament combat. Go to the stables outside the pavilion, equip your lance, mount the stabled Darkspear raptor, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", ["objectivesText"] = "Bring 3 Marks of the Valiant to Gahju at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion. Progress: Have you completed your training for the grand melee?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45127 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33545, ["x"] = 0.76, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33545, ["x"] = 0.76, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13773] = { ["id"] = 13773, ["name"] = "A Blade Fit For A Champion", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13773 }, ["description"] = "I've heard that the Alliance champions are seeking after ancient blades for their warriors. We can't afford to let them have that kind of advantage. There's an old legend from Grizzly Hills about a maiden cursed with a frog's form to protect the blade she has long guarded. She lives among the lake frogs on the shore of Ashwood Lake, just east of Ashwood Post. The only thing said to break the curse is a kiss, freely given. Apply this balm before kissing anything, <name>. Otherwise, you'll catch warts.", ["objectivesText"] = "Retrieve the Ashwood Brand and bring it to Runok Wildmane at the Argent Tournament Grounds. Progress: Were you able to recover the blade?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44981, 44986, 44987, 45192, 46874 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33403, ["x"] = 0.762, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33403, ["x"] = 0.762, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13774] = { ["id"] = 13774, ["name"] = "A Worthy Weapon", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13774 }, ["description"] = "Of all the times to have such rotten luck! My tournament blade has gone missing. I've heard the bards telling tales of travelers offering winter hyacinths to a lonely maiden in return for gifts. Those hyacinths grow only on the ice flowing from the Ironwall Dam, on Crystalsong Forest's northwestern border with Icecrown. Gather the flowers and take them to the circle of lamps in Drak'Mar Lake in northeastern Dragonblight, near Zul'Drak and Grizzly Hills. Ask the lonely maiden for a worthy blade.", ["objectivesText"] = "Bring the Blade of Drak'Mar to Runok Wildmane at the Argent Tournament Grounds. Progress: Were the wandering bard's tales true? Have you brought a blade?", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["rewardItems"] = { 44978, 44987, 45000, 45192, 98134 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33403, ["x"] = 0.762, ["y"] = 0.245 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33403, ["x"] = 0.762, ["y"] = 0.245 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.245 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
