[13787] = { ["id"] = 13787, ["name"] = "The Grand Melee", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13787 }, ["description"] = "The grand melee is the most important of the tournament's competitions. Victory will not be easy, but I am confident that we will win. You must practice with your mount until the two of you work as one. It will help prepare you for the rigors of tournament combat. Go to the stables outside the pavilion, equip your lance, mount the stabled Silvermoon hawkstrider, and challenge the valiants. They wait in the Horde Valiants' Ring just outside our tent.", ["objectivesText"] = "Bring 3 Marks of the Valiant to Aneera Thuron at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you completed your training for the grand melee?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44987, 45127 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33548, ["x"] = 0.764, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33548, ["x"] = 0.764, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13788] = { ["id"] = 13788, ["name"] = "Threat From Above", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13788 }, ["description"] = "The Argent Crusade has doubled the guard since your exposure of the Cult of the Damned's infiltrator. They know the cultists won't stop until they've destroyed this area and thwarted the tournament. The Argent Crusade's scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. You must intercept and destroy them before they attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", ["objectivesText"] = "Crok Scourgebane at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers .", ["rewardXP"] = 3440, ["rewardItems"] = { 45724, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33762, ["x"] = 0.738, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33762, ["x"] = 0.738, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "group" },
[13789] = { ["id"] = 13789, ["name"] = "Taking Battle To The Enemy", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13789 }, ["description"] = "The coliseum is perched in the most dangerous part of the world, <name>. The territory we've taken from the Scourge has been paid for in blood and misery, yet the enemy continues to strike back with a seemingly limitless army. To make matters worse, this undead army is supported and assisted by mortal sympathizers, the Cult of the Damned. Go forth into Icecrown and slay any cultists you encounter.", ["objectivesText"] = "Cellian Daybreak at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill Cult of the Damned members in any part of Icecrown.", ["rewardXP"] = 3440, ["rewardItems"] = { 45724, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33763, ["x"] = 0.698, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33763, ["x"] = 0.698, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13790] = { ["id"] = 13790, ["name"] = "Among the Champions", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13790 }, ["description"] = "As a champion, you have mastered the art of mounted combat, besting challengers of all levels. When the tournament begins, those you have defeated will have redoubled their efforts and will seek to avenge their losses to you. It would be wise to continue practicing your skills against the combatants waiting in the Ring of Champions. Equip your lance, go to the stables on the southern side of the grounds. then mount up on any mount you're permitted to use, and face the champions.", ["objectivesText"] = "Bring 4 Marks of the Champion to Luuri at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you finished training with the other champions?", ["rewardXP"] = 3440, ["rewardItems"] = { 45500, 45724, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33771, ["x"] = 0.698, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33771, ["x"] = 0.698, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13791] = { ["id"] = 13791, ["name"] = "Taking Battle To The Enemy", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13791 }, ["description"] = "While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let's show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament. Go forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur'thar and Deathspeaker's Watch.", ["objectivesText"] = "Zor'be the Bloodletter at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.", ["rewardXP"] = 3440, ["rewardItems"] = { 45724, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33769, ["x"] = 0.738, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33769, ["x"] = 0.738, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13793] = { ["id"] = 13793, ["name"] = "Among the Champions", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13793 }, ["description"] = "As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins. You should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, and pick any mount you're permitted to ride, then face the champions.", ["objectivesText"] = "Bring 4 Marks of the Champion to Illyrie Nightfall at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Silver Covenant Pavilion. Progress: Have you finished training with the other champions?", ["rewardXP"] = 3440, ["rewardItems"] = { 45500, 45724, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33770, ["x"] = 0.735, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33770, ["x"] = 0.735, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13794] = { ["id"] = 13794, ["name"] = "Eadric the Pure", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13794 }, ["description"] = "I have asked my brothers of the Argent Crusade to work closely with those who rise to the rank of champion. Eadric the Pure , our brotherhood's grand champion, helps oversee training exercises for champions from all cities and helps them make their final preparations for tournament competition. Please go and introduce yourself to him. I know he'll be eager to meet you and work with you on your way to competing against Azeroth's greatest champions.", ["objectivesText"] = "Speak with Eadric the Pure at the Argent Tournament Grounds.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33817, ["x"] = 0.696, ["y"] = 0.228 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33759, ["x"] = 0.698, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.228 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13795] = { ["id"] = 13795, ["name"] = "The Scourgebane", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13795 }, ["description"] = "The leader of the Knights of the Ebon Blade delegation has asked to speak you, <class>. Crok Scourgebane is as fearsome a combatant as they come and I have no doubt he'll have much to ask of you. The Knights of the Ebon Blade have made camp on the north side of the tournament grounds, west of the tent housing the Alliance delegations.", ["objectivesText"] = "Speak with Crok Scourgebane at the Argent Tournament Grounds.", ["rewardGold"] = 28090, ["rewardXP"] = 430, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33817, ["x"] = 0.696, ["y"] = 0.228 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33762, ["x"] = 0.738, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.228 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13809] = { ["id"] = 13809, ["name"] = "Threat From Above", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13809 }, ["description"] = "Highlord Tirion Fordring has doubled the guard since your exposure of the Cult of the Damned's infiltrator. He doesn't believe that they will stop just because their Black Knight has been defeated. Our skytalon scouts have reported sighting a frost wyrm named Chillmaw leading a cult raiding party. If we don't intercept them, the tournament will come under attack. The scouts reporting seeing Chillmaw to the southwest, flying over the area between the Ironwall Rampart and Aldur'thar.", ["objectivesText"] = "Eadric the Pure at the Argent Tournament wants you to defeat Chillmaw and 3 Cultist Bombardiers . Progress: Have you defeated the Cult of the Damned raiding party?", ["rewardXP"] = 3440, ["rewardItems"] = { 36892, 36895, 41174, 42470, 42779, 45724, 45783, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33759, ["x"] = 0.698, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33759, ["x"] = 0.698, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "group" },
