[13813] = { ["id"] = 13813, ["name"] = "Taking Battle To The Enemy", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13813 }, ["description"] = "While we all play at mock combat, it will do us good to remember that the real enemy surrounds us. The Argent Crusade wants to use competition to find the best fighters, but we can tell that by who returns from battle. Let's show the paladins that we are willing to take battle to the Cult of the Damned, even while making preparations for the tournament. Go forth into Icecrown and slay any of the cultists you encounter. They have a strong presence around Aldur'thar and Deathspeaker's Watch.", ["objectivesText"] = "Zor'be the Bloodletter at the Argent Tournament Grounds wants you to kill 15 members of the Cult of the Damned. You may kill cultists in any part of Icecrown.", ["rewardXP"] = 3440, ["rewardItems"] = { 45724, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33769, ["x"] = 0.738, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33769, ["x"] = 0.738, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13814] = { ["id"] = 13814, ["name"] = "Among the Champions", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13814 }, ["description"] = "As a champion, you have mastered the art of mounted combat, overcoming challengers of all levels. You must make certain that you can defeat anyone you face when the tournament begins. You should continue honing your own skills and learning more about the weaknesses of your opponents. Champions representing all cities practice in the Ring of Champions near the stables. Go to the stables, equip your lance, pick any mount you can ride, then face the champions in practice bouts.", ["objectivesText"] = "Bring 4 Marks of the Champion to Illyrie Nightfall at the Argent Tournament Grounds. If you lose your lance, you can get another from any of the Lance Racks near the stables or in the Sunreaver Pavilion. Progress: Have you finished training with the other champions?", ["rewardXP"] = 3440, ["rewardItems"] = { 45500, 45724, 46114, 231118 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33770, ["x"] = 0.735, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33770, ["x"] = 0.735, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13816] = { ["id"] = 13816, ["name"] = "Heroic: The Celestial Planetarium", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13816 }, ["description"] = "Listen, <lad/lass>! Azeroth's fate is at stake here. Our only chance is to get to the Celestial Planetarium in time to find this Algalon and stop him from beaming back any messages to his Titan masters. Locate the Celestial Planetarium and come back with any information you get. We might still have some time to prepare for Algalon's arrival.", ["objectivesText"] = "Prospector Loren at the Archivum in Ulduar wants you to locate the entrance to the Celestial Planetarium. Progress: Did you find it, <name>?", ["rewardGold"] = 210000, ["rewardXP"] = 5145, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13817] = { ["id"] = 13817, ["name"] = "Heroic: Archivum Data Disc", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13817 }, ["description"] = "This platinum disc is surprisingly symmetrical and devoid of any scratches or imperfections. Engraved along its edge, bold runes spell out the word \"ARCHIVUM.\" There must be a device inside Ulduar capable of reading the disc.", ["objectivesText"] = "Bring the Archivum Data Disc to the Archivum Console in Ulduar . Progress: The console whirrs with energy as the round receptacle opens.", ["rewardGold"] = 315000, ["rewardXP"] = 6175, ["rewardItems"] = { 45857 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid", ["startItems"] = { 45857 } },
[13818] = { ["id"] = 13818, ["name"] = "Heroic: Algalon", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13818 }, ["description"] = "You really did it, <name>. Take the sigils to the Archivum Console and see if you can gain access to the Celestial Planetarium. You best hurry, <lad/lass>. Time is of the essence.", ["objectivesText"] = "Bring the Sigils of the Watchers to the Archivum Console in Ulduar . Progress: The console's bright lights scan the glass surface repeatedly, as if awaiting some form of input.", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 45798, 45855, 45878 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13819] = { ["id"] = 13819, ["name"] = "Heroic: All Is Well That Ends Well", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13819 }, ["description"] = "We'd best hurry now, <name>. We're going to have to transmit the reply-code from Dalaran. Take it to Rhonin , I will meet you there.", ["objectivesText"] = "Take the Reply-Code Alpha to Rhonin in Dalaran. Progress: You're ready, <name>?", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 45588, 45608, 45614, 45618, 46053 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid", ["startItems"] = { 46053 } },
[13821] = { ["id"] = 13821, ["name"] = "Heroic: Freya's Sigil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13821 }, ["description"] = "Freya's Sigil is going to be one of the tougher ones, I reckon. According to the Archivum, the essence of the Sigil is tied to her three elder servants, Brightleaf, Ironbranch and Stonebark. Should any of the elders be harmed, the Sigil's integrity will be compromised. Sparing the elders, however, means that Freya will be more powerful when you face her. What can I say, <name>. We're stuck between a rock and hard place.", ["objectivesText"] = "Prospector Loren at the Archivum in Ulduar wants you to obtain Freya's Sigil . For more information on obtaining Freya's Sigil consult the Archivum Console. Progress: Freya's sigil , <name>? Do ye have it?", ["rewardGold"] = 1123600, ["rewardXP"] = 8230, ["rewardItems"] = { 45814 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13822] = { ["id"] = 13822, ["name"] = "Heroic: Hodir's Sigil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13822 }, ["description"] = "Hodir's Sigil won't be easy to obtain. Not only are ye going to have to defeat Hodir himself, but yer going to have to do it before he destroys the chest that contains it! Check the Archivum console if you need more information. That thing contains more knowledge than all of the world's libraries put together!", ["objectivesText"] = "Prospector Loren at the Archivum in Ulduar wants you to obtain Hodir's Sigil . For more information on obtaining Hodir's Sigil , consult the Archivum Console. Progress: Did ye obtain the sigil, <name>?", ["rewardGold"] = 1239200, ["rewardXP"] = 8230, ["rewardItems"] = { 45815 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13823] = { ["id"] = 13823, ["name"] = "Heroic: Thorim's Sigil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13823 }, ["description"] = "Thorim's not himself, <name>. He's come under a dark influence. An evil presence under the guise of an illusion pretends to be his lost wife, Sif. Ye can't let him be overcome by this impostor's spell. If he does, the location of his sigil might forever be lost! Yer going to have to beat some sense into him and yer going to have to do it quick. As always, the Archivum Console will give ye all the gory details... even the ones ye don't like.", ["objectivesText"] = "Prospector Loren at the Archivum in Ulduar wants you to obtain Thorim's Sigil . For more information on obtaining Thorim's Sigil consult the Archivum Console. Progress: Well, <name>? Do ye have it?", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 45817 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
[13824] = { ["id"] = 13824, ["name"] = "Heroic: Mimiron's Sigil", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4273, ["storyline"] = { 13824 }, ["description"] = "Mimiron's a clever one. His entire abode is rigged with some sort of self-destruction mechanism. Unfortunately yer gonna have to race against it if ye want to get his sigil. Check the Archivum Console for more details if ye need them.", ["objectivesText"] = "Prospector Loren at the Ulduar Archivum wants you to obtain Mimiron's Sigil . For more information on obtaining Mimiron's Sigil consult the Archivum Console. Progress: Were you able to obtain the sigil, <name>?", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 45816 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4273 } }, ["questType"] = "raid" },
