[13828] = { ["id"] = 13828, ["name"] = "Mastery Of Melee", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13828 }, ["series"] = { 13667 }, ["description"] = "The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion. Once you're mounted, seek out Jeran Lockwood . He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.", ["objectivesText"] = "Equip your lance, then mount the Stabled Quel'dorei Steed outside the pavilion. Speak to Jeran Lockwood and use Thrust 5 times on a Melee Target, then return to Arcanist Taelis at the Argent Tournament Grounds.", ["rewardGold"] = 154900, ["rewardXP"] = 1720, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33625, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13829] = { ["id"] = 13829, ["name"] = "Mastery Of Melee", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13829 }, ["series"] = { 13668 }, ["description"] = "The heart of tournament competition is mounted melee combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion. Once you're mounted, seek out Jeran Lockwood . He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Jeran will instruct you on how to use your defenses to keep you safe while attacking a melee target at close range.", ["objectivesText"] = "Equip your lance, then mount the Stabled Sunreaver Hawkstrider outside the pavilion. Speak to Jeran Lockwood and use Thrust 5 times on a Melee Target, then return to Magister Edien Sunhollow at the Argent Tournament Grounds.", ["rewardGold"] = 154900, ["rewardXP"] = 1720, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33542, ["x"] = 0.762, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13830] = { ["id"] = 13830, ["name"] = "The Ghostfish", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13830 }, ["description"] = "Any Northrend angler worth <his/her> salt knows about the pygmy suckerfish. It's not edible, but sometimes useful to alchemists. There is, however, a stealthy fish that hides among the suckerfish in the River's Heart of Sholazar Basin. The phantom ghostfish . When out of water, they become increasingly translucent until they fade away completely. Some hypothesize they return to Sholazar, and others are more... superstitious. I want you to catch this fish and discover its secret by any means!", ["objectivesText"] = "Marcia Chase in Dalaran City wants you to discover the mystery of the Phantom Ghostfish .", ["rewardXP"] = 1415, ["rewardItems"] = { 45902, 46007 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13832] = { ["id"] = 13832, ["name"] = "Jewel Of The Sewers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13832 }, ["description"] = "Hard to believe that most people fish in the Dalaran Sewers for giant rats and mutated fish. Especially when those waters are filled with priceless jewelry - discarded by broken hearted fools, thieves, and careless drunks. The trick is to let your hook drag the bottom and don't pull up too hard when you get something. Try it out, <name>. I'd be willing to trade whatever you find for a few trinkets of my own.", ["objectivesText"] = "Marcia Chase in Dalaran City wants you to bring her a piece of Corroded Jewelry . Progress: Any luck?", ["rewardXP"] = 1415, ["rewardItems"] = { 43698, 45903, 46007 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13833] = { ["id"] = 13833, ["name"] = "Blood Is Thicker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13833 }, ["description"] = "The bloodtooth is a feisty little fish used in a recipe to cure infected wounds. We could use some of them, if you're up to it. As the name suggests, they've a hunger for blood. The only way I know how to catch the little devils is by creating a blood pool and fishing in it. Get yourself covered in blood - just slaughter a beast in the Borean Tundra - and then jump in the water. It'll wash right off and create the perfect fishing spot.", ["objectivesText"] = "Marcia Chase in Dalaran City wants you to bring her 5 Bloodtooth Frenzies . Progress: Any luck with the bloodtooth? Don't forget what I told you about making blood pools.", ["rewardXP"] = 1415, ["rewardItems"] = { 45905, 45977, 46007 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13834] = { ["id"] = 13834, ["name"] = "Dangerously Delicious", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13834 }, ["description"] = "The best fishing is often the most dangerous. Wintergrasp boasts a bountiful catch for the brazen. In fact, it's the only place to catch the fabled Terrorfish - a fish both lethal and delicious. Bring me some, and we'll have something to discuss.", ["objectivesText"] = "Marcia Chase in Dalaran City wants you to bring her 10 Terrorfish . Progress: Be on your guard when you're after the Terrorfish .", ["rewardXP"] = 1415, ["rewardItems"] = { 25978, 45904, 46007 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13835] = { ["id"] = 13835, ["name"] = "Mastery Of The Shield-Breaker", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13835 }, ["description"] = "You'll need to learn how to break through an opponent's defenses to succeed in mounted combat. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion. Once you're mounted, seek out Valis Windchaser . He'll be on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.", ["objectivesText"] = "Equip your lance and mount the Stabled Quel'dorei Steed outside the pavilion. Speak to Valis Windchaser and use Shield-Breaker on 2 vulnerable Ranged Targets, then return to Scout Shalyndria at the Argent Tournament Grounds.", ["rewardGold"] = 154900, ["rewardXP"] = 1720, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33647, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33647, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13836] = { ["id"] = 13836, ["name"] = "Disarmed!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13836 }, ["description"] = "I've received word of an unfortunate accident at the Dalaran prison; a guard had his arm severed and thrown into the water by a particularly vicious inmate. Our first aid clinic promises they can reattach the arm if we bring it back. You fish long enough in the water outside the prison, and I'd bet my favorite fishing pole that arm will surface. Find that arm, and bring it to Olisarra the Kind here in Dalaran. She'll know what to do.", ["objectivesText"] = "Olisarra the Kind in Dalaran City wants you to return the Severed Arm to her. Progress: Hi there. Do you have something for me?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 33820, 45323, 45328, 46007 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13837] = { ["id"] = 13837, ["name"] = "Mastery Of The Charge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13837 }, ["description"] = "Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Quel'dorei steed just outside the pavilion. Once you're mounted, speak with Rugan Steelbelly . He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.", ["objectivesText"] = "Equip your lance and mount the Stabled Quel'dorei Steed outside the pavilion. Speak to Rugan Steelbelly and Charge 2 vulnerable Charge Targets, then return to Avareth Swiftstrike at the Argent Tournament Grounds. Progress: Have you mastered the use of the charge?", ["rewardGold"] = 154900, ["rewardXP"] = 1720, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33646, ["x"] = 0.764, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33646, ["x"] = 0.764, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13838] = { ["id"] = 13838, ["name"] = "Mastery Of The Shield-Breaker", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13838 }, ["description"] = "You'll need to learn how to break through an opponent's defenses to succeed in mounted combat. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion. Once you're mounted, seek out Valis Windchaser . He'll be on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Valis will teach you the basics of using a ranged shield breaker attack to make a ranged target vulnerable.", ["objectivesText"] = "Equip your lance and mount the Stabled Sunreaver Hawkstrider. Speak to Valis Windchaser and use Shield-Breaker on 2 vulnerable Ranged Targets, then return to Galathia Brightdawn at the Argent Tournament Grounds.", ["rewardGold"] = 154900, ["rewardXP"] = 1720, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33659, ["x"] = 0.762, ["y"] = 0.244 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33659, ["x"] = 0.762, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13839] = { ["id"] = 13839, ["name"] = "Mastery Of The Charge", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13839 }, ["description"] = "Your strongest attack in mounted combat is undoubtedly the charge. Take this lance and mount the stabled Sunreaver hawkstrider just outside the pavilion. Once you're mounted, speak with Rugan Steelbelly . He's on the northern edge of the tournament grounds at the training area east of the Aspirants' Ring. Rugan will tell you how to use this powerful ability and teach you some basic strategies.", ["objectivesText"] = "Equip your lance and mount the Stabled Sunreaver Hawkstrider outside the pavilion. Speak to Rugan Steelbelly and Charge 2 vulnerable Charge Targets, then return to Amariel Sunsworn at the Argent Tournament Grounds. Progress: Have you mastered the use of the charge?", ["rewardGold"] = 154900, ["rewardXP"] = 1720, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33658, ["x"] = 0.762, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33658, ["x"] = 0.762, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13846] = { ["id"] = 13846, ["name"] = "Contributin' To The Cause", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13846 }, ["description"] = "The bestest of the champions come to the chapel to hear the argent confessor speak every day. You should see how much she inspires them, <name>. Not only do they fight for the Argent Crusade, but they put a lot of money into the collection basket when I take it around. Maybe you'd like to contribute too?", ["objectivesText"] = "Speak with Squire Artie to contribute 10 gold to the Argent Crusade's cause. Progress: Do you want to contribute?", ["rewardItems"] = { 45724 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34210, ["x"] = 0.695333, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34210, ["x"] = 0.695333, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.695333, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13847] = { ["id"] = 13847, ["name"] = "At The Enemy's Gates", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13847 }, ["description"] = "Even as we ready for the tournament, Argent Crusade forces prepare the way for an assault on the enemy's stronghold of Icecrown Citadel. In the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's minions. Do not fear the masses of boneguard footmen, <name>, for they can easily be trampled under your horse's hooves.", ["objectivesText"] = "Captain Joseph Holley at the Argent Tournament Grounds wants you to kill 15 Boneguard Footmen, 10 Boneguard Scouts , and 3 Boneguard Lieutenants .", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 44987 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33223, ["x"] = 0.765, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33223, ["x"] = 0.765, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
