[13862] = { ["id"] = 13862, ["name"] = "Battle Before The Citadel", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13862 }, ["description"] = "Even as some of us labor on the tournament, our brothers prepare the way for an assault on the enemy's stronghold of Icecrown Citadel. In the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled argent charger at the camp, then destroy the Lich King's commanders. Do not fear the masses of boneguard footmen, <name>, for they can easily be trampled under your horse's hooves.", ["objectivesText"] = "Eadric the Pure at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders .", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 45724, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33759, ["x"] = 0.698, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33759, ["x"] = 0.698, ["y"] = 0.234 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13863] = { ["id"] = 13863, ["name"] = "Battle Before The Citadel", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13863 }, ["description"] = "As some crusaders prepare for the tournament, they have sent others to make an assault on the enemy's stronghold of Icecrown Citadel. In the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders. Do not fear the masses of boneguard footmen, <name>, for they can easily be trampled under your horse's hooves.", ["objectivesText"] = "Crok Scourgebane at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders .", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 45724, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33762, ["x"] = 0.738, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33762, ["x"] = 0.738, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13864] = { ["id"] = 13864, ["name"] = "Battle Before The Citadel", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 13864 }, ["description"] = "As some crusaders prepare for the tournament, they have sent others to make an assault on the enemy's stronghold of Icecrown Citadel. In the Court of Bones in southwestern Icecrown, a few brave crusaders have set up a forward camp on the southern side of Corp'rethar. Equip your lance and mount the stabled campaign charger at the camp, then destroy the Lich King's commanders. Do not fear the masses of boneguard footmen, <name>, for they can easily be trampled under your horse's hooves.", ["objectivesText"] = "Crok Scourgebane at the Argent Tournament Grounds wants you to kill 3 Boneguard Commanders . Progress: Have you fought against the enemy in the Court of Bones?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 45724, 46114 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33762, ["x"] = 0.738, ["y"] = 0.2 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33762, ["x"] = 0.738, ["y"] = 0.2 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.2 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[13926] = { ["id"] = 13926, ["name"] = "Little Orphan Roo Of The Oracles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13926 }, ["description"] = "The orphans have been looking forward to the opportunity to meet friends like you, <name>. It's wonderful that you've agreed to take one into your care. Take this whistle. With it, you will be able to call for the orphan you have agreed to sponsor. It will only last for a limited time - not much longer than Children's Week itself, in fact. Please, <name>, call upon your orphan. He will be excited to meet you and see the sights of Northrend with you.", ["objectivesText"] = "Speak to Orphan Matron Aria , then use the Oracle Orphan Whistle to call the orphan you will be taking care of during Children's Week. Progress: You taking care of us?", ["rewardXP"] = 175, ["rewardItems"] = { 46397, 46544, 46545 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13927] = { ["id"] = 13927, ["name"] = "Little Orphan Kekek Of The Wolvar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13927 }, ["description"] = "The orphans have been looking forward to the opportunity to meet friends like you, <name>. It's wonderful that you've agreed to take one into your care. Take this whistle. With it, you will be able to call for the orphan you have agreed to sponsor. It will only last for a limited time - not much longer than Children's Week itself, in fact. Please, <name>, call upon your orphan. He will be excited to meet you and see the sights of Northrend with you.", ["objectivesText"] = "Speak to Orphan Matron Aria , then use the Wolvar Orphan Whistle to call the orphan you will be taking care of during Children's Week. Progress: Orphan lady say Kekek go with you.", ["rewardXP"] = 175, ["rewardItems"] = { 23002, 32617, 37460, 46396, 46544, 46545 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13929] = { ["id"] = 13929, ["name"] = "The Biggest Tree Ever!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 394, ["storyline"] = { 13929 }, ["description"] = "Before there was a big war and we left the village, we remember Soo-say telling us all about the biggest tree ever! Soo-say call it Grizzlemaw or something. Soo-say tell us it in the middle Grizzle Hills. No, wait, that not what Soo-say say. Soo-say say Grizzly Hills. Now we remember! Tree is big and right in middle of Grizzly Hills. Can't miss! You take us there, oki? We see inside of giant tree? Soo-say tell us big bear men live in tree too. Maybe we see them.", ["objectivesText"] = "Take your orphan, Roo, to visit Grizzlemaw. Make sure to call for him if he is not present when you enter the trunk of the great tree. Progress: Can we see the big tree? Can we?", ["rewardXP"] = 1415, ["rewardItems"] = { 46397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Battle Pets" },
[13930] = { ["id"] = 13930, ["name"] = "Home Of The Bear-Men", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 394, ["storyline"] = { 13930 }, ["description"] = "High Shaman Rakjak always tell stories of mighty warriors, even ones far away. Sometimes he tell stories about giant bear-men fighting great battle for tree-city. Maybe you take Kekek there, see tree, see battle! High Shaman Rakjak tell Kekek that giant tree-city Grizzlemaw stand in the middle of Grizzly Hills. Kekek never see a city before meeting orphan lady, but this city have no warriors, only men in purple dresses. Kekek want to see real warriors fight for real city.", ["objectivesText"] = "Take your orphan, Kekek, to visit Grizzlemaw. Make sure to call for him if he is not present when you enter the trunk of the great tree. Progress: Kekek want to visit bear-men tree. We go.", ["rewardXP"] = 1415, ["rewardItems"] = { 34498, 44012, 46396, 46693 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 394 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Battle Pets" },
[13933] = { ["id"] = 13933, ["name"] = "The Bronze Dragonshrine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 65, ["storyline"] = { 13933 }, ["description"] = "Sometimes High-Oracle Soo-say tell stories about a shrine to dragon-things, not like great rain stone, but different. Soo-say tell us maybe we see ourselves there, but not like in a shiny. Soo-say mean we could see what we are like many years from now. You take us there? We remember shrine to bronze dragon-things in place called Dragonblight. Soo-say say great rain stone show him shrine to northeast of Wyrmrest Temple, or northwest of place dryskins call Wintergarde Keep. We go?", ["objectivesText"] = "Take your orphan, Roo, to visit the Bronze Dragonshrine. Make sure to call for him if he is not present when you get there.", ["rewardXP"] = 1415, ["rewardItems"] = { 46397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard" },
[13934] = { ["id"] = 13934, ["name"] = "The Bronze Dragonshrine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 65, ["storyline"] = { 13934 }, ["description"] = "When Kekek was a pup, he sometimes heard elders talking about a far-off shrine. Sometimes they say that bronze dragon-things there know all about future. Kekek tell you he be great warrior, now we go see. Bronze dragon-thing shrine somewhere in Dragonblight, northeast of dragon-thing temple called Wyrmrest, also northwest of man-town called Wintergarde. We go there, see future. Prove orphan-lady wrong about Kekek. Kekek warrior, not bully.", ["objectivesText"] = "Take your orphan, Kekek, to visit the Bronze Dragonshrine. Make sure to call for him if he is not present when you get there.", ["rewardXP"] = 1415, ["rewardItems"] = { 34498, 46396, 46693 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard" },
[13937] = { ["id"] = 13937, ["name"] = "A Trip To The Wonderworks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["storyline"] = { 13937 }, ["description"] = "We have time for one more stop? We heard Dalaran has toy store, but we never get to go there. Orphan mistress says too many orphans would crowd the store. Maybe we can go, just us? We can have a small paper zeppelin? We think they have those at Wonderworks in Dalaran. We always wanted to play with one. Maybe you throw one to us?", ["objectivesText"] = "Purchase a Small Paper Zeppelin at the Wonderworks and then throw it to your orphan, Roo. Progress: We go to the Wonderworks?", ["rewardXP"] = 1415, ["rewardItems"] = { 34498, 46397, 46693 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[13938] = { ["id"] = 13938, ["name"] = "A Visit To The Wonderworks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["storyline"] = { 13938 }, ["description"] = "You take Kekek one more place? Orphan lady say Dalaran have toy store called Wonderworks, but Kekek never seen it. She say that if one orphan go, she have to take everyone. Maybe you take Kekek? Kekek seen other children playing with small paper zeppelin? Kekek hear those come from Wonderworks. Maybe you get one and throw it around with Kekek?", ["objectivesText"] = "Purchase a Small Paper Zeppelin at The Wonderworks and then throw it to your orphan, Kekek. Progress: This toy store yet?", ["rewardXP"] = 1415, ["rewardItems"] = { 34498, 46396, 46693 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[13950] = { ["id"] = 13950, ["name"] = "Playmates!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 3537, ["storyline"] = { 13950 }, ["description"] = "Orphanage gets real lonely, you know? Sometimes we want to go places, meet new friends. Maybe you can take us somewheres with other hatchlings? We heard about a place called Winterfin Retreat, in the big Borean Tundra. We think it's way in the northwest, near the edge of the Coldarra-island. The orphan lady say someone brave save a bunch of hatchlings there. We think they lonely, too. We think they need friends. You take us there?", ["objectivesText"] = "Take your orphan, Roo, to visit Winterfin Retreat. Make sure to call for him if he is not present when you get there. Progress: You take us to Winterfin Retreat? Meet new friends maybe?", ["rewardXP"] = 1415, ["rewardItems"] = { 46397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3537 } }, ["questType"] = "standard" },
[13951] = { ["id"] = 13951, ["name"] = "Playmates!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 65, ["storyline"] = { 13951 }, ["description"] = "Kekek think there not enough other pups living with orphan-lady. Maybe we go visit some others? Kekek know a tribe that lives in Dragonblight, at place called Snowfall Glade. You know? Snowfall Glade north of walrus-men town of Mo'aki Harbor and south of Ruby Dragonshrine. <Kekek scowls at the mention of the tuskarr.> You take Kekek there, to some of the villages there. Maybe we meet new wolvar, show them how fierce Frenzyheart are!", ["objectivesText"] = "Take your orphan, Kekek, to visit Snowfall Glade. Make sure to call for him if he is not present when you get there. Progress: You take Kekek to Snowfall Glade now?", ["rewardXP"] = 1415, ["rewardItems"] = { 34498, 46396, 46693 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard" },
[13952] = { ["id"] = 13952, ["name"] = "The Grateful Dead", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 1, 32 }, ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Day of the Dead", ["expansion"] = 2, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 13952 }, ["description"] = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me! Might I trouble you for some more of that delicious Bread of the Dead ? I'd be most grateful... Chapman there sells the recipe, I think.", ["objectivesText"] = "Acquire some Bread of the Dead and give it to the Cheerful Human Spirit in Stormwind's graveyard. Use an Orange Marigold to see the otherwise invisible spirit. Progress: You don't have any Bread of the Dead , do you?", ["rewardXP"] = 200, ["rewardItems"] = { 1179, 30817, 46691, 46718, 46831 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 34435, ["x"] = 0.475333, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 34435, ["x"] = 0.475333, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.475333, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2801 } },
[13954] = { ["id"] = 13954, ["name"] = "The Dragon Queen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 65, ["storyline"] = { 13954 }, ["description"] = "One of High-Oracle Soo-say's stories says Great Ones made all the dragons and a queen for the dragons, too. We want to see her! Would you take us to the top of Wyrmrest Temple? We remember Soo-say telling us the temple-thing was in the middle of Dragonblight. We really want to meet dragon queen. She must be so big and pretty. Maybe she help us find new parents. You take us?", ["objectivesText"] = "Take your orphan, Roo, to visit Alexstrasza the Life-Binder at the top of Wyrmrest Temple. Make sure to call for him if he is not present when you get there. Progress: We go see dragon queen now?", ["rewardGold"] = 140450, ["rewardXP"] = 1415, ["rewardItems"] = { 46397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard" },
[13955] = { ["id"] = 13955, ["name"] = "The Dragon Queen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 65, ["storyline"] = { 13955 }, ["description"] = "Kekek always liked dragons. Always wanted to be one, but orphan-lady said no. But she did say maybe you take Kekek to meet dragon queen. Kekek think orphan-lady have good idea for once. You take Kekek to Wyrmrest Temple in the middle of Dragonblight? Fly all the way to top to meet dragon queen. She must be really big, to be queen of all dragons. Kekek can't wait to see!", ["objectivesText"] = "Take your orphan, Kekek, to visit Alexstrasza the Life-Binder at the top of Wyrmrest Temple. Make sure to call for him if he is not present when you get there. Progress: We go see dragon queen now?", ["rewardGold"] = 140450, ["rewardXP"] = 1415, ["rewardItems"] = { 34498, 46396, 46693 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 65 } }, ["questType"] = "standard" },
[13956] = { ["id"] = 13956, ["name"] = "Meeting a Great One", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 490, ["storyline"] = { 13956 }, ["description"] = "High-Oracle Soo-say always tell us about how Great Ones built shrines and we give them shinies, but he never see Great Ones. No one see Great Ones, but maybe you know how to find one? Soo-say told us the Great Ones made a waygate and put it in the center of the southern part of Sholazar. Soo-say not say where it goes, but maybe it take us to a Great One! Take us through that waygate and let's find out, <name>.", ["objectivesText"] = "Take your orphan, Roo, to visit the Etymidian at the Shaper's Terrace. Make sure to call for him if he is not present when you get there. Progress: Do you know how to find a Great One? We've never seen one before.", ["rewardXP"] = 1415, ["rewardItems"] = { 46397 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 490 } }, ["questType"] = "standard" },
[13957] = { ["id"] = 13957, ["name"] = "The Mighty Hemet Nesingwary", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 3711, ["storyline"] = { 13957 }, ["description"] = "Know who Kekek always wanted to meet? Hemet Nesingwary. Maybe you take Kekek to see him? Elder Harkek tell us all about him. He come to Sholazar to hunt biggest creatures anywhere! Even Frenzyheart elders respect Hemet Nesingwary as great hunter. Elder Harkek tell Kekek that Nesingwary Base Camp in the middle of west side of Sholazar, right on river called Seabreach Flow. We go visit and learn how to hunt like Hemet?", ["objectivesText"] = "Take your orphan, Kekek, to visit Hemet Nesingwary at the Nesingwary Base Camp. Make sure to call for him if he is not present when you get there. Progress: Can't wait to meet Hemet Nesingwary.", ["rewardXP"] = 1415, ["rewardItems"] = { 34498, 46396, 46693 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3711 } }, ["questType"] = "standard" },
[13959] = { ["id"] = 13959, ["name"] = "Back To The Orphanage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13959 }, ["description"] = "We had the best time with you, <name>. We wish you could be our <daddy/mama> now, but you have to take us back to Orphan Matron Aria in Dalaran. Maybe you could come visit us again sometime? We loved meeting Winterfin hatchlings and getting to see the dragon queen. No one will believe us when we say we met a Great One! We going to miss you, <name>. We promise to write letter sometime, oki?", ["objectivesText"] = "Return your ward to the Dalaran orphanage by handing in the Oracle Orphan Whistle to Orphan Matron Aria in Dalaran.", ["rewardXP"] = 710, ["rewardItems"] = { 23022, 32616, 32617, 32622, 46544, 46545, 69648, 71153, 116202, 241215 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13960] = { ["id"] = 13960, ["name"] = "Back To The Orphanage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 13960 }, ["description"] = "Know what? You not so bad after all, <name>. You take Kekek a lot of fun places. Kekek meet a lot of new friends and do things no other pup get to do. You, and Hemet Nesingwary, and Snowfall Glade pups all new best friends. Maybe sometime you bring Kekek that green hills book? Kekek promise to write sometimes, too, tell you how things go. Maybe even be nice to big-tongue kids sometimes. Kekek gotta go back to orphan-lady Aria now, back in purple human city.", ["objectivesText"] = "Return your ward to the Dalaran orphanage by handing in the Wolvar Orphan Whistle to Orphan Matron Aria in Dalaran.", ["rewardXP"] = 710, ["rewardItems"] = { 23022, 32616, 32617, 32622, 46544, 46545, 69648, 116202, 241215 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[13966] = { ["id"] = 13966, ["name"] = "A Winter Veil Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Feast of Winter Veil", ["expansion"] = 2, ["storyline"] = { 13966 }, ["rewardItems"] = { 34426, 43504, 46740, 67443, 70938, 90892, 104319, 116761, 128653, 139341, 151350, 162644, 172224, 178528, 187561, 192094, 209871, 218311, 244908 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[14016] = { ["id"] = 14016, ["name"] = "The Black Knight's Curse", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14016 }, ["series"] = { 13663, 13664, 14017 }, ["description"] = "I wanted to remove the Black Knight's remains from the tournament grounds after your victory, but Confessor Paletress insisted that he receive a decent burial. Ever since, a dark presence has lingered in the cemetery and people are afraid to go there to visit the fallen. Would you visit the cemetery just past the eastern end of the tournament grounds and see if you can discover what's happening?", ["objectivesText"] = "Crusader Rhydalla at the Argent Tournament Grounds wants you to investigate the Black Knight's Grave. Progress: Have you investigated the Black Knight's gravesite?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14017] = { ["id"] = 14017, ["name"] = "The Black Knight's Fate", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14017 }, ["series"] = { 13663, 13664, 14016 }, ["description"] = "You said the body was taken by cultists? I can only think of one place they would have gone, Deathspeaker's Watch, the encampment on the rise west of the tournament grounds. Whatever the cultists are doing must be stopped. The rumors I've heard can only be true, then. The infamous Doctor Kohler must be among the cultists, practicing his arts. Look for a rise or an altar overlooking the cultist camp, slay the doctor, and look for proof of his plans. Slow down his work in any other way you can.", ["objectivesText"] = "Capture Doctor Kolher's Orders at Deathspeaker's Watch, then return to Crusader Rhydalla at the Argent Tournament Grounds. Progress: Did you find out what they're doing with the Black Knight's remains?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 47048 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 33417, ["x"] = 0.694, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14022] = { ["id"] = 14022, ["name"] = "Pilgrim's Bounty", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1537, ["mapID"] = 84, ["storyline"] = { 14022 }, ["description"] = "Won't you celebrate Pilgrim's Bounty with us, <name>? It's a time for reflecting on your journeys and your good fortune, sharing plentiful food and stories with friends. You can partake of wonderful Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there. If you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Gregory Tabor . You will find him just outside Stormwind's gates.", ["objectivesText"] = "Speak with Gregory Tabor just outside the city gates of Stormwind.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 18927, ["x"] = 0.628143, ["y"] = 0.557571 }, { ["mapID"] = 87, ["npcID"] = 19148, ["x"] = 0.3115, ["y"] = 0.665625 }, { ["mapID"] = 103, ["npcID"] = 19171, ["x"] = 0.571375, ["y"] = 0.437 }, { ["mapID"] = 87, ["npcID"] = 19172, ["x"] = 0.575333, ["y"] = 0.489333 }, { ["mapID"] = 89, ["npcID"] = 19173, ["x"] = 0.445, ["y"] = 0.529 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 34675, ["x"] = 0.489333, ["y"] = 0.669333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.628143, ["y"] = 0.557571 }, ["mapCandidates"] = { ["npc"] = { 10, 37, 84, 87, 89, 103 }, ["zone"] = { 1537 } }, ["questType"] = "standard" },
[14023] = { ["id"] = 14023, ["name"] = "Spice Bread Stuffing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 14023 }, ["series"] = { 14024, 14028, 14030, 14033, 14035 }, ["description"] = "Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe has always been a favorite in Stormwind and now it has taken its place in the bountiful cookbook. If you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start! Once you've made the stuffing, bring it to Jasper Moore over near the tables.", ["objectivesText"] = "Cook 5 servings of Spice Bread Stuffing and then bring them to Jasper Moore at the feasting area just outside Stormwind's gates. Progress: We can always use more of that delicious spice bread stuffing . It's very popular.", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44837, 44838, 44839, 44840, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 34675, ["x"] = 0.489333, ["y"] = 0.669333 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 34744, ["x"] = 0.561, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.489333, ["y"] = 0.669333 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14024] = { ["id"] = 14024, ["name"] = "Pumpkin Pie", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 14024 }, ["series"] = { 14023, 14028, 14030, 14033, 14035 }, ["description"] = "That spice bread stuffing you made smells delicious, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie . It's another one of our favorite dishes here in Stormwind, since it uses ripe Elwynn pumpkins that only grow here. If you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook. Would you mind cooking up a few slices and bringing them to Edward Winslow outside Ironforge? He's bound to be running low by now.", ["objectivesText"] = "Make 5 slices of Pumpkin Pie and bring them to Edward Winslow at the feasting area right outside Ironforge. Progress: More pumpkin pie ? Just in time.", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 34744, ["x"] = 0.561, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 34644, ["x"] = 0.598, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 27, 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14028] = { ["id"] = 14028, ["name"] = "Cranberry Chutney", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 14028 }, ["series"] = { 14023, 14024, 14030, 14033, 14035 }, ["description"] = "If you haven't tried the cranberry chutney yet, you're in for a treat. It's made with the freshest tangy Wetlands cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney. The recipe should be in your bountiful cookbook. If you've got some extra time on your hands, would you mind making some of the chutney and bringing it down to Jasper Moore outside Stormwind? I promised him I'd trade some for the pie you brought.", ["objectivesText"] = "Make 5 servings of Cranberry Chutney and bring them to Jasper Moore at the feasting area outside Stormwind. Progress: Is that cranberry chutney I smell?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 34644, ["x"] = 0.598, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 34744, ["x"] = 0.561, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 27, 37 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 }, ["db2QuestSortName"] = "Epic" },
[14030] = { ["id"] = 14030, ["name"] = "They're Ravenous In Darnassus", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 14030 }, ["series"] = { 14023, 14024, 14028, 14033, 14035 }, ["description"] = "Thanks for bringing the cranberry chutney. There's so much cooking to do, I hardly have time to think of anything else. And on top of my responsibilities here, Isaac Allerton in Darnassus is out of almost everything. I don't suppose you'd be willing to step in and whip up some more spice bread stuffing and pumpkin pie ? The vendor should have all the ingredients you need You should be able to find him near the feasting tables near the entrance to Darnassus just beyond the Warrior's Terrace.", ["objectivesText"] = "Bring 5 servings of Spice Bread Stuffing and 5 Pumpkin Pies to Isaac Allerton near the entrance to Darnassus. Progress: Have you come to partake of the Pilgrim's Bounty feast?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44837, 44838, 44839, 44840, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 34744, ["x"] = 0.561, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 34676, ["x"] = 0.575429, ["y"] = 0.489429 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 37, 89 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14033] = { ["id"] = 14033, ["name"] = "Candied Sweet Potatoes", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 14033 }, ["series"] = { 14023, 14024, 14028, 14030, 14035 }, ["description"] = "While you're here, you might want to stock up on Teldrassil sweet potatoes. They're used to make the most delicious candied sweet potatoes you've ever tasted. If you don't believe me, look up the recipe in your bountiful cookbook and give it a try. And if there are any extras, you might want to share them with Gregory Tabor at the feasting area just outside Stormwind. They're one of his favorites, but to hear him tell it, everything's his favorite!", ["objectivesText"] = "Make 5 servings of Candied Sweet Potatoes and bring them to Gregory Tabor just outside the gates of Stormwind. Progress: <name>, it's good to see you again.", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 34676, ["x"] = 0.575429, ["y"] = 0.489429 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 34675, ["x"] = 0.489333, ["y"] = 0.669333 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.575429, ["y"] = 0.489429 }, ["mapCandidates"] = { ["npc"] = { 37, 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14035] = { ["id"] = 14035, ["name"] = "Slow-roasted Turkey", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 14035 }, ["series"] = { 14023, 14024, 14028, 14030, 14033 }, ["description"] = "Every Pilgrim's Bounty feast requires a magnificent centerpiece, and I'm not talking about a decorative horn of plenty, either. No, the focus of the meal is a magnificent roast turkey. There's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Elwynn Forest, so you shouldn't have a problem finding one. Once you're done roasting them, will you bring them to Isaac Allerton near the gates of Darnassus?", ["objectivesText"] = "Make 5 Slow-Roasted Turkeys and bring them to Isaac Allerton near the gates of Darnassus. Progress: What brings you back to Darnassus, <name>?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44838, 44839, 44840, 44844, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 34675, ["x"] = 0.489333, ["y"] = 0.669333 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 34676, ["x"] = 0.575429, ["y"] = 0.489429 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.489333, ["y"] = 0.669333 }, ["mapCandidates"] = { ["npc"] = { 37, 89 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14036] = { ["id"] = 14036, ["name"] = "Pilgrim's Bounty", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 1, ["zoneID"] = 1637, ["mapID"] = 94, ["storyline"] = { 14036 }, ["description"] = "Are you here to celebrate Pilgrim's Bounty with us? It was once a time for reflecting on your journeys and your good fortune while sharing a meal with friends. Many still mark the occasion. You can partake of Pilgrim's Bounty feasts near major towns by sitting at a bountiful table and serving the foods you find there. If you're interested in learning how to cook the traditional Pilgrim's Bounty foods, seek out Miles Standish . You will find him in the courtyard above Undercity.", ["objectivesText"] = "Speak with Miles Standish in the courtyard above Undercity.", ["rewardXP"] = 25, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 19169, ["x"] = 0.542, ["y"] = 0.508 }, { ["mapID"] = 85, ["npcID"] = 19175, ["x"] = 0.545667, ["y"] = 0.709667 }, { ["mapID"] = 85, ["npcID"] = 19176, ["x"] = 0.402, ["y"] = 0.5615 }, { ["mapID"] = 85, ["npcID"] = 19177, ["x"] = 0.440857, ["y"] = 0.667714 }, { ["mapID"] = 90, ["npcID"] = 19178, ["x"] = 0.648923, ["y"] = 0.442154 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 34677, ["x"] = 0.614, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 10, 18, 85, 90, 94 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[14037] = { ["id"] = 14037, ["name"] = "Spice Bread Stuffing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 14037 }, ["series"] = { 14040, 14041, 14043, 14044, 14047 }, ["description"] = "Our spice bread stuffing is the cornerstone of the Pilgrim's Bounty table. The recipe dates from better times in Lordaeron and now it has taken its place in the traditional meal. If you are already a cook, pay a visit to the Pilgrim's Bounty vendor to get your copy of the bountiful cookbook and all the local ingredients you'll need to prepare holiday fare. And if you're not yet a cook, there's no better time to start! Once you've made the stuffing, bring it to William Mullins over near the tables.", ["objectivesText"] = "Cook 5 servings of Spice Bread Stuffing and then bring them to William Mullins at the feasting area in the courtyard above the Undercity. Progress: The tables could really use more of that spice bread stuffing .", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44837, 44838, 44839, 44840, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 34677, ["x"] = 0.614, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 34768, ["x"] = 0.616, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14040] = { ["id"] = 14040, ["name"] = "Pumpkin Pie", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 14040 }, ["series"] = { 14037, 14041, 14043, 14044, 14047 }, ["description"] = "That spice bread stuffing you made is a hit, but no Pilgrim's Bounty feast is complete without a slice of pumpkin pie . It's another traditional local dish, since it uses ripe Tirisfal pumpkins that only grow around here. If you don't know how to make pumpkin pie already, there's a recipe in your bountiful cookbook. Would you mind cooking up a few slices and bringing them to Francis Eaton outside Orgrimmar? He's bound to be running low by now.", ["objectivesText"] = "Make 5 slices of Pumpkin Pie and bring them to Francis Eaton at the feasting area right outside Orgrimmar. Progress: We can always use more pumpkin pie .", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 34768, ["x"] = 0.616, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 34679, ["x"] = 0.465, ["y"] = 0.138 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 1, 18 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14041] = { ["id"] = 14041, ["name"] = "Cranberry Chutney", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 14041 }, ["series"] = { 14037, 14040, 14043, 14044, 14047 }, ["description"] = "Have you tried the cranberry chutney yet? It's made with fresh tangy Southfury cranberries. Just pick some up from the Pilgrim's Bounty vendor if you want to try your hand at making chutney. The recipe should be in your bountiful cookbook. If you've got some extra time on your hands, would you mind making some of the chutney and bringing it to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff?", ["objectivesText"] = "Make 5 servings of Cranberry Chutney and bring them to Dokin Farplain at the base of the elevator on the western side of Thunder Bluff. Progress: How are you enjoying Pilgrim's Bounty, <class>?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 34679, ["x"] = 0.465, ["y"] = 0.138 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 34678, ["x"] = 0.3056, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.138 }, ["mapCandidates"] = { ["npc"] = { 1, 88 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14043] = { ["id"] = 14043, ["name"] = "Candied Sweet Potatoes", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 14043 }, ["series"] = { 14037, 14040, 14041, 14044, 14047 }, ["description"] = "While you're here, you might want to stock up on Mulgore sweet potatoes. They're used to make delicious candied sweet potatoes, my favorite part of the Pilgrim's Bounty meal. If you don't believe me, look up the recipe in your bountiful cookbook and give it a try. If you're headed back to Orgrimmar, bring them to Francis Eaton at the feasting area just outside the city. I've been trying to keep him supplied, but everything goes so fast over there.", ["objectivesText"] = "Make 5 servings of Candied Sweet Potatoes and bring them to Francis Eaton just outside of Orgrimmar. Progress: Welcome back, <name>.", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 34678, ["x"] = 0.3056, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 34679, ["x"] = 0.465, ["y"] = 0.138 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.3056, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1, 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14044] = { ["id"] = 14044, ["name"] = "Undersupplied in the Undercity", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 14044 }, ["series"] = { 14037, 14040, 14041, 14043, 14047 }, ["description"] = "Thanks for bringing the candied sweet potatoes. There's so much cooking to do, I can hardly keep up. And then, Miles sends me a note saying he's on the verge of running out of stuffing and cranberry chutney . I don't suppose you'd be willing to step in and whip up some more of each? The vendor should have all the ingredients you need. You should be able to find Miles Standish near the feasting tables in the courtyard in the ruins above Undercity.", ["objectivesText"] = "Bring 5 servings of Spice Bread Stuffing and 5 servings of Cranberry Chutney to Miles Standish near the entrance to Undercity. Progress: It's good to see you again. <name>.", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44837, 44838, 44839, 44840, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 34679, ["x"] = 0.465, ["y"] = 0.138 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 34677, ["x"] = 0.614, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.138 }, ["mapCandidates"] = { ["npc"] = { 1, 18 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14047] = { ["id"] = 14047, ["name"] = "Slow-roasted Turkey", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 14047 }, ["series"] = { 14037, 14040, 14041, 14043, 14044 }, ["description"] = "Every Pilgrim's Bounty feast requires a centerpiece, and for us, that's a slow-roasted wild turkey. I can't think of anything better to bring the meal together. There's a good recipe for it in your bountiful cookbook. Why not hunt some wild turkeys and prepare a few? The turkeys wander all over Tirisfal Glades, so you shouldn't have a problem finding any. Once you're done roasting them, will you bring them to Francis Eaton outside Orgrimmar?", ["objectivesText"] = "Make 5 Slow-Roasted Turkeys and bring them to Francis Eaton near the gates of Orgrimmar. Progress: What brings you back to Orgrimmar, <name>?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44834, 44835, 44836, 44838, 44839, 44840, 44844, 44853, 44854, 44855, 46784, 46793, 46796, 46797, 46809, 46810, 116404 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 34677, ["x"] = 0.614, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 34679, ["x"] = 0.465, ["y"] = 0.138 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 1, 18 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14048] = { ["id"] = 14048, ["name"] = "Can't Get Enough Turkey", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 14048 }, ["description"] = "I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I? Turkey is hard to come by here, so if you could supply some slow-roasted turkeys , it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in Elwynn Forest. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.", ["objectivesText"] = "Bring 20 Slow-Roasted Turkeys to Caitrin Ironkettle outside Ironforge. Progress: Did you manage to find those turkeys?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404, 134020 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 34708, ["x"] = 0.6, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 34708, ["x"] = 0.6, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 }, ["db2QuestSortName"] = "Epic" },
[14051] = { ["id"] = 14051, ["name"] = "Don't Forget The Stuffing!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 14051 }, ["description"] = "Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn. I think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.", ["objectivesText"] = "Bring 20 Spice Bread Stuffing to Caitrin Ironkettle at the feasting area outside Ironforge. Progress: Were you able to get that stuffing?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44837, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 34708, ["x"] = 0.6, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 34708, ["x"] = 0.6, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 }, ["db2QuestSortName"] = "Epic" },
[14053] = { ["id"] = 14053, ["name"] = "We're Out of Cranberry Chutney Again?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 14053 }, ["description"] = "My husband, Jasper, was going to make more cranberry chutney , but it looks like he's busy trying to make sure there's enough candied sweet potatoes for all the guests. Would you be willing to help? If you're a cook, you can get the tangy Wetlands cranberries you'll need from the Pilgrim's Bounty vendor outside Ironforge. If you don't feel up to cooking, you could always ask someone else to make the chutney, too.", ["objectivesText"] = "Bring 20 servings of Cranberry Chutney to Ellen Moore at the feasting area outside Stormwind. Progress: Were you able to get your hands on any cranberry chutney ?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 34710, ["x"] = 0.5136, ["y"] = 0.6892 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 34710, ["x"] = 0.5136, ["y"] = 0.6892 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.5136, ["y"] = 0.6892 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14054] = { ["id"] = 14054, ["name"] = "Easy As Pie", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1657, ["mapID"] = 89, ["storyline"] = { 14054 }, ["description"] = "Isaac's been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running out of one of Isaac's favorites, pumpkin pie . Would you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Elwynn pumpkins from the Pilgrim's Bounty vendor outside Stormwind.", ["objectivesText"] = "Bring 20 pieces of Pumpkin Pie to Mary Allerton at the feasting area near the gates of Darnassus. Progress: How are those pies coming along?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404, 134020 }, ["starts"] = { { ["mapID"] = 89, ["npcID"] = 34711, ["x"] = 0.5612, ["y"] = 0.4656 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 34711, ["x"] = 0.5612, ["y"] = 0.4656 } }, ["coords"] = { ["mapID"] = 89, ["source"] = "quest_giver", ["x"] = 0.5612, ["y"] = 0.4656 }, ["mapCandidates"] = { ["npc"] = { 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14055] = { ["id"] = 14055, ["name"] = "She Says Potato", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 14055 }, ["description"] = "My wife Ellen has enlisted my help in keeping the tables stocked, but she can't make up her mind. First I was making pumpkin pie, but now she's changed her mind and she wants candied sweet potatoes. Well, I've already started on the pie, so maybe you can help me whip up those sweet potatoes. She'll be pleasantly surprised if we can get everything she's asked for. If you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Darnassus. Thanks, <name>.", ["objectivesText"] = "Bring 20 Candied Sweet Potatoes to Jasper Moore at the feasting area outside of Stormwind. Progress: Do you have those candied sweet potatoes?", ["rewardXP"] = 150, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404, 134020 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 34744, ["x"] = 0.561, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 34744, ["x"] = 0.561, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14058] = { ["id"] = 14058, ["name"] = "She Says Potato", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 14058 }, ["description"] = "Roberta Carter has recruited me to help prepare one of the feast dishes, candied sweet potatoes. Normally, I'd love to help, but I've promised the hostess that I'd help her watch the tables. I'd really appreciate it if you would help me come up with those candied sweet potatoes. Roberta would never forgive me if I let her down. If you're going to cook the sweet potatoes yourself, you'll have to buy them from the Pilgrim's Bounty merchant in Thunder Bluff. Thanks, <name>.", ["objectivesText"] = "Bring 20 Candied Sweet Potatoes to William Mullins at the feasting area above Undercity. Progress: Do you have those candied sweet potatoes?", ["rewardXP"] = 150, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 34768, ["x"] = 0.616, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 34768, ["x"] = 0.616, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14059] = { ["id"] = 14059, ["name"] = "We're Out of Cranberry Chutney Again?", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1497, ["mapID"] = 18, ["storyline"] = { 14059 }, ["description"] = "I wish I knew why we're going through cranberry chutney so fast. Sometimes, I think they're feeding it to the abominations when I'm not looking. Would you be willing to help me make up a new batch? If you're a cook, you can get the tangy Southfury cranberries you'll need from the Pilgrim's Bounty vendor outside Orgrimmar. If you don't feel up to cooking, you could always ask someone else to make the chutney, too.", ["objectivesText"] = "Bring 20 servings of Cranberry Chutney to Roberta Carter at the feasting area in the courtyard above Undercity. Progress: Were you able to get your hands on any cranberry chutney ?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 34712, ["x"] = 0.612, ["y"] = 0.67 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 34712, ["x"] = 0.612, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.67 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14060] = { ["id"] = 14060, ["name"] = "Easy As Pie", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 14060 }, ["description"] = "Dokin and Laha have been hard at work helping celebrants learn about the traditional Pilgrim's Bounty feast and how to make dishes out of all the ingredients we harvest at this time of year. I've been trying to keep the tables stocked with as many of the dishes as I can, but we're running low on pumpkin pie . Would you be able to get some for us? If you want to make the pies yourself, you'll need to buy ripe Tirisfal pumpkins from the Pilgrim's Bounty vendor outside the Undercity.", ["objectivesText"] = "Bring 20 pieces of Pumpkin Pie to Marhara Goldwheat at the feasting area outside Thunder Bluff. Progress: How are those pies coming along?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 34714, ["x"] = 0.308667, ["y"] = 0.693333 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 34714, ["x"] = 0.308667, ["y"] = 0.693333 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.308667, ["y"] = 0.693333 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14061] = { ["id"] = 14061, ["name"] = "Can't Get Enough Turkey", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 14061 }, ["description"] = "I've been cooking nonstop since before the start of the holiday, and I still can't keep up with the demand. I don't suppose I could persuade you to help with one of the dishes, could I? Turkey is hard to come by here, so if you could supply some slow-roasted turkeys , it would be a big help. If you intend to prepare them yourself, you can hunt fresh wild turkeys anywhere in the Tirisfal Glades. You should be able to buy everything else you need from any of the Pilgrim's Bounty vendors.", ["objectivesText"] = "Bring 20 Slow-Roasted Turkeys to Ondani Greatmill outside Orgrimmar. Progress: How's your turkey hunt going?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 34713, ["x"] = 0.464, ["y"] = 0.138 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 34713, ["x"] = 0.464, ["y"] = 0.138 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.138 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14062] = { ["id"] = 14062, ["name"] = "Don't Forget The Stuffing!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 14062 }, ["description"] = "Keeping these tables stocked can be overwhelming! I've got to make the cranberry chutney while keeping my eye on the sweet potatoes, and making sure the pies don't burn. I think I've got everything covered. No, wait, I'm forgetting something. The stuffing! Oh, no. There won't be time to get another batch of stuffing started before everything else is done. Would you be willing to help me out? It shouldn't take long to buy or make some stuffing and you can buy the ingredients right here.", ["objectivesText"] = "Bring 20 Spice Bread Stuffing to Ondani Greatmill outside Orgrimmar. Progress: Were you able to get that stuffing?", ["rewardXP"] = 100, ["rewardItems"] = { 2678, 30816, 30817, 44785, 44788, 44834, 44835, 44836, 44837, 44838, 44839, 44840, 44853, 44854, 44855, 46723, 46784, 46793, 46796, 46797, 46800, 46809, 46810, 46824, 116404 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 34713, ["x"] = 0.464, ["y"] = 0.138 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 34713, ["x"] = 0.464, ["y"] = 0.138 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.138 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14064] = { ["id"] = 14064, ["name"] = "Sharing a Bountiful Feast", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 14771, ["mapID"] = 27, ["storyline"] = { 14064 }, ["description"] = "You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table. Please, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food. Once you eat enough of every dish, you'll be infused with the Spirit of Sharing.", ["objectivesText"] = "Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing. Bountiful Tables can be found in most major cities and towns. Progress: Did you eat enough at a Bountiful Table?", ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 34653, ["x"] = 0.576667, ["y"] = 0.401333 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 34653, ["x"] = 0.576667, ["y"] = 0.401333 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.576667, ["y"] = 0.401333 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14065] = { ["id"] = 14065, ["name"] = "Sharing a Bountiful Feast", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["event"] = "Pilgrim's Bounty", ["expansion"] = 2, ["zoneID"] = 14771, ["mapID"] = 1, ["storyline"] = { 14065 }, ["description"] = "You've not celebrated Pilgrim's Bounty properly until you've eaten your fill at a Bountiful Table. Please, sit down, feast, and try everything! You can move from chair to chair yourself, or ask others at the table to pass you some of their food. Once you eat enough of every dish, you'll be infused with the Spirit of Sharing.", ["objectivesText"] = "Eat five helpings of every food at a Bountiful Table until you gain the Spirit of Sharing. Bountiful Tables can be found in most major cities and towns. Progress: Did you eat enough at a Bountiful Table?", ["rewardXP"] = 100, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 34654, ["x"] = 0.495, ["y"] = 0.291 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 34654, ["x"] = 0.495, ["y"] = 0.291 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.291 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14771 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2802 } },
[14074] = { ["id"] = 14074, ["name"] = "A Leg Up", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4742, ["mapID"] = 118, ["storyline"] = { 14074 }, ["description"] = "The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the Kvaldir, fearsome vrykul raiders who roam the seas. They've slain the crew and taken the cargo to an island called Hrothgar's Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we'll soon be out of food.", ["objectivesText"] = "Recover 10 Stolen Tallstrider Legs for Narasi Snowdawn at the Argent Tournament Grounds. Progress: Were you able to recover any of the missing supplies?", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["rewardItems"] = { 17903, 17908, 21332, 21346, 21362, 21390, 30368, 30369, 30370, 30371, 30860, 44113, 46859, 67168, 67185, 67202, 67218, 67225, 67271, 80749, 80750, 80751, 80752, 80753, 80754, 80755, 80756, 80757, 115506, 126910, 126911, 126912, 126913, 126914, 126915, 126916, 132172, 135546, 137642, 142054, 211279, 237812 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 4742 } }, ["questType"] = "standard" },
[14076] = { ["id"] = 14076, ["name"] = "Breakfast Of Champions", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14076 }, ["description"] = "Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting. The giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar. Take this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there. Rouse the deep jormungar, kill them, and gather their egg sacs.", ["objectivesText"] = "Acquire 4 Jormungar Egg Sacs and bring them to Savinia Loresong at the Argent Tournament Grounds. Progress: Were you able to get those eggs? Those worms will start eating their handlers if they're not fed soon.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 46889, 46893 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34912, ["x"] = 0.762, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34912, ["x"] = 0.762, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14077] = { ["id"] = 14077, ["name"] = "The Light's Mercy", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14077 }, ["description"] = "I've been listening to Confessor Paletress speak, and I must tell you, her words have given me much to consider. It is not enough to fight beside the crusaders; we must take up their mission. Off the north coast is Hrothgar's Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.", ["objectivesText"] = "Use the Confessor's Prayer Book to perform last rites for 8 Slain Tualiq Villagers and then return to Narasi Snowdawn at the Argent Tournament Grounds. Progress: Have you seen to the spirits of the slain Tualiq villagers ?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 46870 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14079] = { ["id"] = 14079, ["name"] = "Learn to Ride in Elwynn Forest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 1, 32 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 14079 }, ["description"] = "This pamphlet advertising riding training and mount purchases was sent from Randal Hunter . Randal can be found at Elwynn Forest's Eastvale Logging Camp, along the road east out of Stormwind.", ["objectivesText"] = "Return the pamphlet to Randal Hunter at Eastvale Logging Camp in Elwynn Forest. Progress: Ah, you received my letter? Good.", ["rewardXP"] = 175, ["rewardItems"] = { 46875, 86570 }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 4732, ["x"] = 0.842, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.842, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["startItems"] = { 46875 } },
[14080] = { ["id"] = 14080, ["name"] = "Stop The Aggressors", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4742, ["mapID"] = 118, ["storyline"] = { 14080 }, ["description"] = "The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar's Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target. The crusade's forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.", ["objectivesText"] = "Narasi Snowdawn at the Argent Tournament Grounds wants you to kill 10 Kvaldir. Progress: Have you shown the Kvaldir that we will not let them threaten us?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 4742 } }, ["questType"] = "standard" },
