[14088] = { ["id"] = 14088, ["name"] = "Learn to Ride in Durotar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 8, 31 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 14088 }, ["description"] = "This pamphlet advertising riding training and mount purchases was sent from Xar'Ti . Xar'Ti can be found at Sen'jin Village in southern Durotar .", ["objectivesText"] = "Return the pamphlet to Xar'Ti at Sen'jin Village in southern Durotar . Progress: Ah, you received my letter? Good.", ["rewardXP"] = 175, ["rewardItems"] = { 46883 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 7953, ["x"] = 0.552, ["y"] = 0.755 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.755 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["startItems"] = { 46883 } },
[14089] = { ["id"] = 14089, ["name"] = "Learn to Ride in Tirisfal Glades", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 85, ["mapID"] = 18, ["storyline"] = { 14089 }, ["description"] = "This pamphlet advertising riding training and mount purchases was sent from Velma Warnam . Velma can be found at Brill in Tirisfal Glades.", ["objectivesText"] = "Return the pamphlet to Velma Warnam at Brill in Tirisfal Glades. Progress: Ah, you received my letter? Good.", ["rewardXP"] = 175, ["rewardItems"] = { 46881 }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 4773, ["x"] = 0.618, ["y"] = 0.518 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.518 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 85 } }, ["questType"] = "standard", ["startItems"] = { 46881 } },
[14090] = { ["id"] = 14090, ["name"] = "Gormok Wants His Snobolds", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14090 }, ["description"] = "Two of my men have already been killed trying to confine the magnataur called Gormok the Impaler, yet the creature still rages. It howls for hours about being without its favorite snobold. If the Argent Crusade didn't wish to use this monster in the coliseum, I'd slay it myself. Perhaps it's time to bring the beast its playthings. Take this net and travel to Garm's Bane in southeast Storm Peaks. It's just northeast of K3. Capture some of those snobolds and pray to the Light you've found the right one.", ["objectivesText"] = "Use the Weighted Net to capture 8 Snowblind Followers and bring them to Savinia Loresong at the Argent Tournament Grounds. Progress: Have you managed to round up those snobolds yet? Gormok's anger shows no signs of lessening.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 46885 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34912, ["x"] = 0.762, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34912, ["x"] = 0.762, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14092] = { ["id"] = 14092, ["name"] = "Breakfast Of Champions", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14092 }, ["description"] = "Now that the coliseum is complete, the Argent Crusade has asked us to help look after the creatures that champions will be fighting. The giant jormungar have perhaps the strangest diet; they grow strong by eating the eggs of their own kind and the best eggs come from deep jormungar. Take this drum to the Foot Steppes in central Storm Peaks and play them near the snow mounds you see there. The sound will rouse the deep jormungar. Kill them, collect their egg sacs, and return to the tournament grounds.", ["objectivesText"] = "Acquire 4 Jormungar Egg Sacs and bring them to Tylos Dawnrunner at the Argent Tournament Grounds. Progress: Were you able to get those eggs? The jormungar are going to get nasty if they don't get fed.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 46889, 46893 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34914, ["x"] = 0.76, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34914, ["x"] = 0.76, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14095] = { ["id"] = 14095, ["name"] = "Identifying the Remains", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14095 }, ["description"] = "A whole tooth from a dead Kraken is a rare find indeed. Crusader Silverdawn will want to see this.", ["objectivesText"] = "Take the Kraken Tooth to Crusader Silverdawn as proof of your victory. Progress: What have you found, Champion?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 46954, 46955, 69777 }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 35094, ["x"] = 0.695, ["y"] = 0.231 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["startItems"] = { 46955 } },
[14096] = { ["id"] = 14096, ["name"] = "You've Really Done It This Time, Kul", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14096 }, ["description"] = "Crusader Kul has gone and gotten himself into trouble again, only this time he's not alone. When he saw the cultists making camp at Deathspeaker's Watch, west of the tournament grounds, Kul gathered the aspirants for an assault. Without reinforcements, Kul and his followers were easily captured. I have no doubt that the cult will sacrifice the prisoners unless we can mount a rescue. Any of those cultists could carry keys to the black cages. Find the keys and free Kul and the captive aspirants .", ["objectivesText"] = "Rescue Kul the Reckless and 4 Captive Aspirants from Deathspeaker's Watch and return to Narasi Snowdawn at the Argent Tournament Grounds.", ["rewardGold"] = 169800, ["rewardXP"] = 3440, ["rewardItems"] = { 46895 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14101] = { ["id"] = 14101, ["name"] = "Drottinn Hrothgar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14101 }, ["description"] = "The Kvaldir, seafaring vrykul who raid ships and coastal settlements, have overrun a tuskarr island across the strait to the north. Their leader is a veteran raider, Drottinn Hrothgar , who seeks to control these seas. With him in power, our shipments and troop transports will never be safe. We will be stranded here at the Lich King's mercy. Take this captured Kvaldir war horn to the circle of tuskarr statues on the northeastern part of Hrothgar's Landing and use it to challenge the Kvaldir leader.", ["objectivesText"] = "High Crusader Adelard at the Argent Tournament Grounds wants you to defeat Drottinn Hrothgar . Progress: We cannot allow Drottinn Hrothgar 's men to continue their assault on our ships and our men.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 47006 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34882, ["x"] = 0.695, ["y"] = 0.231 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34882, ["x"] = 0.695, ["y"] = 0.231 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14102] = { ["id"] = 14102, ["name"] = "Mistcaller Yngvar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14102 }, ["description"] = "The Kvaldir have returned to the coasts of Northrend and if left unchecked, they will prevent our supplies and reinforcements from arriving. One of them, known as Mistcaller Yngvar , has taken up residence in a cave on the western side of Hrothgar's Landing. There, he manipulates the mists to conceal the Kvaldir and the sea beasts they command. Take this charm and travel across the strait north of the tournament grounds, to Hrothgar's Landing. Find the mistcaller's cave and use the charm to reveal him.", ["objectivesText"] = "High Crusader Adelard at the Argent Tournament Grounds wants you to kill Mistcaller Yngvar . Progress: Have you defeated Mistcaller Yngvar and disrupted his rituals?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 47009 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34882, ["x"] = 0.695, ["y"] = 0.231 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34882, ["x"] = 0.695, ["y"] = 0.231 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14103] = { ["id"] = 14103, ["name"] = "Titanium Powder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 14103 }, ["objectivesText"] = "Progress: Hello <name>! Do you have anything to trade?", ["rewardGold"] = 10500, ["rewardXP"] = 175, ["rewardItems"] = { 46849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[14104] = { ["id"] = 14104, ["name"] = "Ornolf The Scarred", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14104 }, ["description"] = "Ornolf the Scarred is a fearsome raider renowned among his Kvaldir brethren for raiding and capturing ships. From aboard Bor's Fury, he and his crew attack our ships and steal our goods. Ornolf and his men are among those who slaughtered the inhabitants of a tuskarr island to the north and renamed it Hrothgar's Landing. His ship sits at anchor at the eastern end of the island's harbor. Take this captured banner and display it on his ship to provoke him into facing you in battle.", ["objectivesText"] = "High Crusader Adelard at the Argent Tournament Grounds wants you to kill Ornolf the Scarred . Progress: Have you dealt with Ornolf the Scarred ?", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 47029 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34882, ["x"] = 0.695, ["y"] = 0.231 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34882, ["x"] = 0.695, ["y"] = 0.231 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14105] = { ["id"] = 14105, ["name"] = "Deathspeaker Kharos", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14105 }, ["description"] = "The Cult of the Damned has redoubled its efforts to see us destroyed. They have grown bold and are massing their strength at Deathspeaker's Watch on the ridge west of the tournament grounds. The ruthless Deathspeaker Kharos has his men fortifying their positions, preparing to unleash all of the cult's weapons. My men are preparing themselves and the valiants to defend the grounds, but I want champions like you, <name>, to lead our efforts to blunt the attack. Find Deathspeaker Kharos and slay him.", ["objectivesText"] = "High Crusader Adelard at the Argent Tournament Grounds wants to you kill Deathspeaker Kharos . Progress: Have you defeated the leader of the cult's attack?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34882, ["x"] = 0.695, ["y"] = 0.231 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34882, ["x"] = 0.695, ["y"] = 0.231 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14107] = { ["id"] = 14107, ["name"] = "The Fate Of The Fallen", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14107 }, ["description"] = "The Argent Crusade is hardly the first force to challenge the Lich King. Our enemy turns spirits of the fallen against us. Their spirits wander the Valley of Fallen Heroes, southwest of the grounds and between Aldur'thar and the Ironwall Rampart. The area is littered with discarded soul crystals , used by the Scourge to control the spirits. Gather those soul crystals and use them with this Light-blessed relic to bestow the blessing of peace upon the spirits. They have more than earned their rest.", ["objectivesText"] = "Crusader Silverdawn wants you to bring peace to 6 Fallen Hero's Spirits. Progress: Have you brought peace to the spirits of the fallen heroes?", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["rewardItems"] = { 47033, 47035, 119037 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 35094, ["x"] = 0.695, ["y"] = 0.231 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 35094, ["x"] = 0.695, ["y"] = 0.231 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14108] = { ["id"] = 14108, ["name"] = "Get Kraken!", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14108 }, ["description"] = "The Sunreavers and Silver Covenant sent ships north to engage the Kvaldir at Hrothgar's Landing, but were intercepted and detained by a Kvaldir Raiding vessel. To make matters worse, the Kvaldir have found a way to call forth the dreaded Kraken that lives beneath the North Sea. If anyone on board is to get out alive, that Kraken must be driven away and the Kvaldir's summoning ritual ... disrupted. Crusader, take these spears and an Argent Hippogryph will take you to the battle.", ["objectivesText"] = "Crusader Silverdawn wants you to mount an Argent Hippogryph, throw 8 Flaming Spears at the North Sea Kraken and take out 6 Vrykul Deepcallers. You can find the Argent Hippogryphs right outside the Argent Crusade tent at the Tournament Grounds. Progress: Have you driven away the Kraken yet? Hurry, Crusader! There isn't much time.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 46954, 46955 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 35094, ["x"] = 0.695, ["y"] = 0.231 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 35094, ["x"] = 0.695, ["y"] = 0.231 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.231 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14112] = { ["id"] = 14112, ["name"] = "What Do You Feed a Yeti, Anyway?", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14112 }, ["description"] = "The crusaders have captured a yeti that they're calling Icehowl. He's to be a participant in the coliseum battles and we've been asked to help with his training and upkeep. The crusaders weren't fond of my suggestion that we feed the beast surplus Sunreavers. The creature has a predilection for shark meat, so I want you to fly down to the Silver Blade, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.", ["objectivesText"] = "Savinia Loresong at the Argent Tournament Grounds wants you to bring her 3 pieces of North Sea Shark Meat . Progress: I hope you have something to feed Icehowl, otherwise I really will start bringing Sunreavers down to his cage.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 47036, 47037 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34912, ["x"] = 0.762, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34912, ["x"] = 0.762, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14136] = { ["id"] = 14136, ["name"] = "Rescue at Sea", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4742, ["mapID"] = 118, ["storyline"] = { 14136 }, ["description"] = "The Kvaldir have set up camp at Hrothgar's Landing, the small island to the North. We sent Captain Aerthas Firehawk to the area, but they ran into a Kvaldir Raiding party heading to the Tournament Grounds! The Firehawk is now under attack by the raiders and is vastly outnumbered. Get out there and show those Kvaldir why attacking the Sunreavers is a poor plan indeed. The Firehawk is between Hrothgar's Landing to the north and the Tournament Grounds, on the western side of The Sea Reaver's Run.", ["objectivesText"] = "Girana the Blooded at the Argent Tournament Grounds would like you to kill 8 Kvaldir Berserkers and 3 Kvaldir Harpooners aboard The Firehawk. Progress: Have you defended The Firehawk?", ["rewardGold"] = 232300, ["rewardXP"] = 2580, ["rewardItems"] = { 39648, 39649, 39650, 141940, 237812 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 4742 } }, ["questType"] = "standard" },
[14140] = { ["id"] = 14140, ["name"] = "Stop The Aggressors", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4742, ["mapID"] = 118, ["storyline"] = { 14140 }, ["description"] = "The Kvaldir, fearsome vrykul raiders, have disrupted our shipments and murdered the tuskarr inhabitants of an island to the north, renaming it Hrothgar's Landing. If they are allowed to get a foothold there, there is no doubt that we will be their next target. The crusade's forces have their hands full dealing with the Scourge, and we must defend the tournament grounds. Fly north from the grounds until you reach the island and take on the Kvaldir before they can destroy anything else.", ["objectivesText"] = "Giranan the Blooded at the Argent Tournament Grounds wants you to kill 10 Kvaldir.", ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 4742 } }, ["questType"] = "standard" },
[14141] = { ["id"] = 14141, ["name"] = "Gormok Wants His Snobolds", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14141 }, ["description"] = "Two of my men have already been killed trying to confine the magnataur called Gormok the Impaler, yet the creature still rages. It howls for hours about being without its favorite snobold. If the Argent Crusade didn't wish to use this monster in the coliseum, I'd slay it myself. Perhaps it's time to bring the beast its playthings. Take this net and travel to Garm's Bane in southeast Storm Peaks. It's just northeast of K3. Capture some of those snobolds and pray to the Light you've found the right one.", ["objectivesText"] = "Use the Weighted Net to capture 8 Snowblind Followers and bring them to Tylos Dawnrunner at the Argent Tournament Grounds. Progress: Have you managed to round up those snobolds yet? Gormok's anger shows no signs of lessening.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 46885 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34914, ["x"] = 0.76, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34914, ["x"] = 0.76, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14142] = { ["id"] = 14142, ["name"] = "You've Really Done It This Time, Kul", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14142 }, ["description"] = "Crusader Kul has gone and gotten himself into trouble again, only this time he's not alone. When he saw the cultists making camp at Deathspeaker's Watch, west of the tourney grounds, Kul gathered the aspirants for an attack. They were easily captured, and now Kul languishes in a cage on the platform in the camp. I am sure that the cult will sacrifice the prisoners unless we can rescue them. Any of those cultists could carry keys to the black cages. Find the keys and free Kul and the captive aspirants .", ["objectivesText"] = "Rescue Kul the Reckless and 4 Captive Aspirants from Deathspeaker's Watch and return to Girana the Blooded at the Argent Tournament Grounds.", ["rewardGold"] = 169800, ["rewardXP"] = 3440, ["rewardItems"] = { 46895 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14143] = { ["id"] = 14143, ["name"] = "A Leg Up", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4742, ["mapID"] = 118, ["storyline"] = { 14143 }, ["description"] = "The Argent Crusade dispatched a fast ship carrying tallstrider meat and other supplies for us here at the tournament grounds, but it never arrived. Scouts reported seeing it attacked by the Kvaldir, fearsome vrykul raiders who roam the seas. They've slain the crew and taken the cargo to an island called Hrothgar's Landing. If you look to the north, you can see it shrouded in the mist. Would you help us in recovering the stolen supplies? Without those tallstrider legs, we'll soon be out of food.", ["objectivesText"] = "Recover 10 Stolen Tallstrider Legs for Girana the Blooded at the Argent Tournament Grounds. Progress: Were you able to recover any of the missing supplies?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 17903, 17908, 21332, 21346, 21362, 21390, 30368, 30369, 30370, 30371, 30860, 44113, 46859, 67168, 67185, 67202, 67218, 67225, 67271, 80749, 80750, 80751, 80752, 80753, 80754, 80755, 80756, 80757, 115506, 126910, 126911, 126912, 126913, 126914, 126915, 126916, 132172, 135546, 137642, 142054, 211279, 237812 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 4742 } }, ["questType"] = "standard" },
[14144] = { ["id"] = 14144, ["name"] = "The Light's Mercy", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14144 }, ["description"] = "I've been listening to Confessor Paletress speak, and I must tell you, her words have made me think. We fight beside the crusaders, but we can learn from them, too. Off the north coast is Hrothgar's Landing, where the seagoing Kvaldir have overrun an old tuskarr settlement and slain the villagers. Take this book and read the rites for the dead near the corpses of the villagers. It will allow their spirits to escape the mists engulfing the island and find peace.", ["objectivesText"] = "Use the Confessor's Prayer Book to perform last rites for 8 Slain Tualiq Villagers and then return to Girana the Blooded at the Argent Tournament Grounds. Progress: Have you seen to the spirits of the slain Tualiq villagers ?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 46870 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34771, ["x"] = 0.76, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14145] = { ["id"] = 14145, ["name"] = "What Do You Feed a Yeti, Anyway?", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 14145 }, ["description"] = "The crusaders have captured a yeti that they're calling Icehowl. He's to be a participant in the coliseum battles and we've been asked to help with his training and upkeep. The crusaders weren't fond of my suggestion that we feed some Silver Covenant members to the beast. The creature prefers shark meat, so I want you to fly down to the Crimson Dawn, floating in the strait to the north. Get some fresh chum from one of the buckets on the boat, then spread it in the water to attract sharks.", ["objectivesText"] = "Tylos Dawnrunner at the Argent Tournament Grounds wants you to bring him 3 pieces of North Sea Shark Meat . Progress: I hope you have something to feed Icehowl, otherwise I really will start bringing Silver Covenant members down to his cage.", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 47036, 47037 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34914, ["x"] = 0.76, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34914, ["x"] = 0.76, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[14151] = { ["id"] = 14151, ["name"] = "Cardinal Ruby", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 14151 }, ["description"] = "The Cardinal Ruby is said to be the finest gem in all of Northrend. It sparkles like a crystal rose under the sun. Before I teach you this recipe, I ask that you perform five epic gem transmutes to prepare your mind. You can do any you like, and even do the same transmute many times. Return to me when you are truly ready.", ["objectivesText"] = "Linzy Blackbolt in Dalaran wants you to successfully transmute 5 epic gems with your alchemy skill. Acceptable transmutes include Ametrine, Eye of Zul, Dreadstone, King's Amber, and Majestic Zircon.", ["rewardXP"] = 1415, ["rewardItems"] = { 36934 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
[14152] = { ["id"] = 14152, ["name"] = "Rescue at Sea", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable", "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4742, ["mapID"] = 118, ["storyline"] = { 14152 }, ["description"] = "Champion, Captain Wavecrest and her ship were sent north to disrupt the Kvaldir in Hrothgar's Landing when they were intercepted by a Kvaldir raiding party headed to the Tournament Grounds. Unfortunately, the Kvaldir far outnumber the crew on board and are slowly taking over the ship. We need you to go north to The Wavecrest in The Sea Reaver's Run, between the Tournament Grounds and Hrothgar's Landing and help the crew fend off the attack. You should see the ship on the east side of the pass.", ["objectivesText"] = "Head out to The North Sea and kill 8 Vrykul Berserkers and 3 Vrykul Harpooners attacking The Wavecrest. Progress: Have you helped fend off the Kvaldir attack?", ["rewardGold"] = 232300, ["rewardXP"] = 2580, ["rewardItems"] = { 39648, 39649, 39650, 141940, 237812 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 34880, ["x"] = 0.762, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.762, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 4742 } }, ["questType"] = "standard" },
[14166] = { ["id"] = 14166, ["name"] = "The Grateful Dead", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["event"] = "Day of the Dead", ["expansion"] = 2, ["zoneID"] = 7502, ["storyline"] = { 14166 }, ["description"] = "It's good to visit with friends and family again, though I may have overdone it... I've already eaten everything they made for me! Might I trouble you for some more of that delicious Bread of the Dead ? I'd be most grateful... Chapman there sells the recipe, I think.", ["objectivesText"] = "Acquire some Bread of the Dead and give it to the Cheerful Dalaran Spirit in Dalaran's graveyard. Use an Orange Marigold to see the otherwise invisible spirit. Progress: You don't have any Bread of the Dead , do you?", ["rewardXP"] = 200, ["rewardItems"] = { 1179, 46691, 46831 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2801 } },
