[14203] = { ["id"] = 14203, ["name"] = "Waterlogged Recipe", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 14203 }, ["description"] = "This appears to be the remains of a mixture for potent wine. Perhaps the proprietor of One More Glass in Dalaran would be interested in it....", ["objectivesText"] = "Bring the Waterlogged Recipe to Christi Stockton in the Dalaran city. Progress: Wine is only as fine as the person drinking it, I always say.", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 48681 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard", ["startItems"] = { 48679 } },
[14438] = { ["id"] = 14438, ["name"] = "Sharing the Land", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 215, ["mapID"] = 7, ["storyline"] = { 743, 744, 749, 751, 761, 773, 833, 11129, 14438, 14491, 20440, 20441, 24440, 24441, 24456, 24523, 24524, 24540, 24550, 26179, 26180, 26188, 26397, 26398 }, ["series"] = { 14491 }, ["description"] = "<name>, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as our elders have. Yet there is one that I would ask you to seek. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land. Palemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled. Words are no longer the answer.", ["objectivesText"] = "Kill 15 Palemane Gnolls then return to Ahmo Thunderhorn in Bloodhoof Village. Progress: If the Palemanes had respected the land and its inhabitants more, this conflict would have never occurred.", ["rewardGold"] = 105000, ["rewardXP"] = 200, ["rewardItems"] = { 57204 }, ["starts"] = { { ["mapID"] = 7, ["npcID"] = 36644, ["x"] = 0.476, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 7, ["npcID"] = 36644, ["x"] = 0.476, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 7, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 7 }, ["zone"] = { 215 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 7, ["questLines"] = { { ["id"] = 564, ["name"] = "Mulgore", ["orderIndex"] = 0, ["flags"] = 0 } } },
[14488] = { ["id"] = 14488, ["name"] = "You've Been Served", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 2, ["storyline"] = { 14488 }, ["description"] = "You made it, huh? Good. I've been waiting for help. No time like the present to act, right? Take this kit and head deeper inside to serve papers to the leader of that scumbag chemical company, Hummel. The paper's inside. So's a little something to protect you from any chemical tricks they might pull. Use one of the neutralizers when the time comes, all right?", ["objectivesText"] = "Serve the Court Subpoena to Apothecary Hummel in Shadowfang Keep.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 49631, 49635 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[24428] = { ["id"] = 24428, ["name"] = "A Most Puzzling Circumstance", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 2159, ["mapID"] = 84, ["storyline"] = { 24428 }, ["description"] = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Zardeth of the Black Claw .", ["objectivesText"] = "Take the Head of Onyxia to Zardeth of the Black Claw in the basement of the Slaughtered Lamb. Progress: By Nozdormu's teeth!", ["rewardXP"] = 6175, ["rewardItems"] = { 49485, 49486, 49487, 49644 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 1435, ["x"] = 0.401, ["y"] = 0.847 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.401, ["y"] = 0.847 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 2159 } }, ["questType"] = "standard", ["startItems"] = { 49644 } },
[24429] = { ["id"] = 24429, ["name"] = "A Most Puzzling Circumstance", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 2159, ["storyline"] = { 24429 }, ["description"] = "You have accomplished the truly impossible. The brood mother of the Black Dragonflight lies dead at your feet. Seize her head and deliver it to Arnak Fireblade .", ["objectivesText"] = "Take the Head of Onyxia to Arnak Fireblade in the Cleft of Shadow. Progress: What is the meaning of this?!", ["rewardXP"] = 6175, ["rewardItems"] = { 15138, 49485, 49486, 49487, 49643 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2159 } }, ["questType"] = "standard", ["startItems"] = { 49643 } },
[24461] = { ["id"] = 24461, ["name"] = "Reforging The Sword", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4812, ["mapID"] = 118, ["storyline"] = { 24461 }, ["series"] = { 24476, 24480, 24522, 24535 }, ["description"] = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel. In the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar. You must gather bars of infused saronite and capture the forgemaster's hammer , then bring them to the forgemaster's anvil and reforge the sword.", ["objectivesText"] = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer and use them to make the Reforged Quel'Delar . Progress: Were you able to reconstruct Quel'Delar?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 49718, 49723, 49739, 49740 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 36624, ["x"] = 0.637, ["y"] = 0.607 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 36624, ["x"] = 0.637, ["y"] = 0.607 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.607 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 4812 } }, ["questType"] = "dungeon" },
[24498] = { ["id"] = 24498, ["name"] = "The Path to the Citadel", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4813, ["storyline"] = { 24498 }, ["series"] = { 24499, 24506, 24510, 24511, 24682, 24683, 24710, 24711 }, ["description"] = "They've put my captured soldiers to work in the quarry! Kill their captors and set them free, hero. We will need their aid when we confront Scourgelord Tyrannus.", ["objectivesText"] = "Free 6 quarry camps and kill Forgemaster Garfrost . Progress: My men and I appreciate your help, <class>. More than we could possibly express in these trying times.", ["rewardGold"] = 420000, ["rewardXP"] = 6880, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4813 } }, ["questType"] = "dungeon" },
[24499] = { ["id"] = 24499, ["name"] = "Echoes of Tortured Souls", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4809, ["storyline"] = { 24499 }, ["series"] = { 24498, 24506, 24510, 24511, 24682, 24683, 24710, 24711 }, ["description"] = "We're severely undermanned to be risking a venture into the citadel, but opportunities like this are too rare to pass up. Clear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the citadel.", ["objectivesText"] = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4809 } }, ["questType"] = "dungeon" },
[24500] = { ["id"] = 24500, ["name"] = "Wrath of the Lich King", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4820, ["storyline"] = { 24500 }, ["description"] = "It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that? Many questions remain. but you need to find Jaina and escape the Lich King while there's still time.", ["objectivesText"] = "Find Lady Jaina Proudmoore and escape the Halls of Reflection .", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4820 } }, ["questType"] = "dungeon" },
[24506] = { ["id"] = 24506, ["name"] = "Inside the Frozen Citadel", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 6611, ["storyline"] = { 24506 }, ["series"] = { 24498, 24499, 24510, 24511, 24682, 24683, 24710, 24711 }, ["description"] = "<class>! Come close quickly, I must have a word! My queen, the Lady Sylvanas Windrunner , has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \" The Forge of Souls .\" She sent word before she left for me to find fierce fighters to send her way. I think you'll do. Go to her within the entrance to the forge, <class>.", ["objectivesText"] = "Enter The Forge of Souls from the side of Icecrown Citadel and locate Lady Sylvanas Windrunner .", ["rewardGold"] = 70225, ["rewardXP"] = 860, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6611 } }, ["questType"] = "dungeon" },
[24507] = { ["id"] = 24507, ["name"] = "The Path to the Citadel", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4813, ["storyline"] = { 24507 }, ["series"] = { 24712, 24713 }, ["description"] = "They've put our captured soldiers to work in the quarry. Kill their captors and set them free, <class>. We will need their aid when we confront Scourgelord Tyrannus.", ["objectivesText"] = "Free 5 quarry camps and kill Forgemaster Garfrost .", ["rewardGold"] = 1239200, ["rewardXP"] = 6880, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4813 } }, ["questType"] = "dungeon" },
[24510] = { ["id"] = 24510, ["name"] = "Inside the Frozen Citadel", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 6611, ["mapID"] = 504, ["storyline"] = { 24510 }, ["series"] = { 24498, 24499, 24506, 24511, 24682, 24683, 24710, 24711 }, ["description"] = "<class>! Come close quickly, I must have a word! My patron, the Lady Jaina Proudmoore , has uncovered a hole in the defenses of Icecrown Citadel into a place she referred to as \" The Forge of Souls .\" She sent word before she left for me to find any help that I could... and, well, I was hoping that might be you. Please, find her there as soon as you can.", ["objectivesText"] = "Enter The Forge of Souls from the side of Icecrown Citadel and find Lady Jaina Proudmoore .", ["rewardGold"] = 70225, ["rewardXP"] = 860, ["starts"] = { { ["mapID"] = 504, ["npcID"] = 37776, ["x"] = 0.632, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 504, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 504 }, ["zone"] = { 6611 } }, ["questType"] = "dungeon" },
[24511] = { ["id"] = 24511, ["name"] = "Echoes of Tortured Souls", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4809, ["storyline"] = { 24511 }, ["series"] = { 24498, 24499, 24506, 24510, 24682, 24683, 24710, 24711 }, ["description"] = "Delving into the citadel with so few is risky at best, but opportunities like this are too rare to pass up. Clear the way to the far side and secure the passage to the Pit of Saron. We will need to hold it to move our men further into the Citadel.", ["objectivesText"] = "Kill Bronjahm and the Devourer of Souls to secure access to the Pit of Saron.", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4809 } }, ["questType"] = "dungeon" },
[24522] = { ["id"] = 24522, ["name"] = "Journey To The Sunwell", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4812, ["mapID"] = 118, ["storyline"] = { 24522 }, ["series"] = { 24461, 24476, 24480, 24535 }, ["description"] = "Take Quel'Delar to the Sunwell as quickly as possible, <name>. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas , and there, seek entry to the Sunwell itself, where you can cleanse the sword. The guardians of the Sunwell will not simply allow you to walk in, so you must find Halduron Brightwing , who will be inspecting the guards there.", ["objectivesText"] = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas . Progress: What brings you here?", ["rewardGold"] = 30900, ["rewardXP"] = 430, ["rewardItems"] = { 49870 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 36624, ["x"] = 0.637, ["y"] = 0.607 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.637, ["y"] = 0.607 }, ["mapCandidates"] = { ["npc"] = { 118, 122 }, ["zone"] = { 4812 } }, ["questType"] = "standard" },
[24535] = { ["id"] = 24535, ["name"] = "Thalorien Dawnseeker", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 24535 }, ["series"] = { 24461, 24476, 24480, 24522 }, ["description"] = "If you truly bear Quel'Delar, <name>, I might be able to admit you to the Sunwell. If you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", ["objectivesText"] = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar. Progress: Did you visit the ground where Thalorien fell defending the Sunwell?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 49870 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[24545] = { ["id"] = 24545, ["name"] = "The Sacred and the Corrupt", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4812, ["storyline"] = { 24545 }, ["series"] = { 24547, 24548, 24549, 24743, 24748, 24749, 24756, 24757 }, ["description"] = "It is against my judgment that I present you this errand, <race>, as it will likely end in your undoing. Ignore my counsel and embark on the endeavor, and I shall provide you with the knowledge and resources to see it through. You must return to Frostmourne Cavern and recover Light's Vengeance , Arthas' discarded hammer. Reforged with saronite and etched with the acidic blood of the Lich King's abominations, it will provide the foundation for our work.", ["objectivesText"] = "Place Light's Vengeance , 25 Primordial Saronite , Rotface's Acidic Blood , and Festergut's Acidic Blood in Highlord Mograine's runeforge in Icecrown Citadel. Rotface's Acidic Blood and Festergut's Acidic Blood may only be obtained in the 25 person difficulty setting of Icecrown Citadel. Progress: As you draw near, the forge's flame seems to burn even more ravenously...", ["rewardGold"] = 210000, ["rewardXP"] = 5145, ["rewardItems"] = { 49426, 49623, 49869, 49888, 49908, 50226, 50231, 50274, 51315, 51317, 51318, 51319, 51320, 51321, 52200, 52201, 52251, 52252, 52253, 69777 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4812 } }, ["questType"] = "raid" },
[24547] = { ["id"] = 24547, ["name"] = "A Feast of Souls", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4812, ["storyline"] = { 24547 }, ["series"] = { 24545, 24548, 24549, 24743, 24748, 24749, 24756, 24757 }, ["description"] = "Shadow's Edge is among the greatest weapons a <class> could hope to obtain. Is your lust for power sated, <race>? <You feel Mograine's penetrating gaze.> I thought not. A final warning then... You now embark on the most treacherous leg of your quest. Bridle your aspirations, for if your aims are impure then your life, your very soul, is forfeit. The weapon you hold is but an empty husk, a mere shadow of what it may become.", ["objectivesText"] = "Highlord Darion Mograine wants you to use Shadow's Edge to slay 50 of the Lich King's minions in Icecrown Citadel. Souls can be obtained in 10 or 25 person difficulty. Progress: Has the weapon's hunger been sated, <class>?", ["rewardGold"] = 210000, ["rewardXP"] = 5145, ["rewardItems"] = { 4358, 6714, 18588, 49623, 49888, 49908, 50274, 51315, 52200, 52201, 52251, 52252, 52253, 69777, 97919, 128636 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4812 } }, ["questType"] = "raid" },
[24548] = { ["id"] = 24548, ["name"] = "The Splintered Throne", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4812, ["storyline"] = { 24548 }, ["series"] = { 24545, 24547, 24549, 24743, 24748, 24749, 24756, 24757 }, ["description"] = "The Lich King's throne once served as his prison. Kil'jaeden himself crafted the vessel of icy crystals from the twisting nether, its sole purpose to hold Ner'zhul's vengeful spirit. When Arthas struck the crystal with Frostmourne, he released Ner'zhul's soul, allowing it to merge with his own. Splinters from that impact are now scattered throughout the citadel. I shall require those shards, held only by the Lich King's most powerful servants, to seal the power contained in your blade.", ["objectivesText"] = "Highlord Darion Mograine wants you to collect 50 Shadowfrost Shards . Shadowfrost Shards may only be obtained in the 25 person difficulty setting. Progress: Have you obtained the shards of the frozen throne, <class>?", ["rewardGold"] = 210000, ["rewardXP"] = 5145, ["rewardItems"] = { 49888, 50274, 132511 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4812 } }, ["questType"] = "raid" },
[24549] = { ["id"] = 24549, ["name"] = "Shadowmourne...", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4812, ["storyline"] = { 24549 }, ["series"] = { 24545, 24547, 24548, 24743, 24748, 24749, 24756, 24757 }, ["objectivesText"] = "Highlord Darion Mograine wants you to bring him Shadow's Edge.", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 49623 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4812 } }, ["questType"] = "raid" },
[24553] = { ["id"] = 24553, ["name"] = "The Purification of Quel'Delar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 24553 }, ["series"] = { 24796 }, ["description"] = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to me and to the rest of my people that Quel'Delar has been recovered. As promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. The blade will bond to you. When that happens, carry it to Caladis Brightspear at Quel'Delar's Rest.", ["objectivesText"] = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau . Progress: What happened during your time in the Sunwell?", ["rewardItems"] = { 49871, 49879 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 36624, ["x"] = 0.637, ["y"] = 0.607 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 118, 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[24559] = { ["id"] = 24559, ["name"] = "Reforging The Sword", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4812, ["mapID"] = 118, ["storyline"] = { 24559 }, ["series"] = { 24560, 24561, 24562, 24563 }, ["description"] = "We cannot allow Quel'Delar to remain broken and disgraced. Take the remnants of the sword, along with the battered hilt you discovered, and venture into the Pit of Saron within Icecrown Citadel. In the pit, the Lich King uses slaves to mine, process, and transform saronite ore. This infused saronite is what we will use to rebuild Quel'Delar. You must gather bars of infused saronite and capture the forgemaster's hammer , then bring them to the forgemaster's anvil and reforge the sword.", ["objectivesText"] = "Obtain 5 Infused Saronite Bars and the Forgemaster's Hammer , then combine them with the Remnants of Quel'Delar to create the Reforged Quel'Delar . Progress: Were you able to reconstruct Quel'Delar?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["rewardItems"] = { 49718, 49723, 49739, 49740 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 36642, ["x"] = 0.64, ["y"] = 0.6095 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 36642, ["x"] = 0.64, ["y"] = 0.6095 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.6095 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 4812 } }, ["questType"] = "dungeon" },
[24562] = { ["id"] = 24562, ["name"] = "Journey To The Sunwell", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4812, ["mapID"] = 118, ["storyline"] = { 24562 }, ["series"] = { 24559, 24560, 24561, 24563 }, ["description"] = "Take Quel'Delar to the Sunwell as quickly as possible, <name>. Trust in Uther's words when he says that you will not always be able to control the blade while it is subject to the evil of the Lich King's influence. You must travel to the Isle of Quel'Danas , and there, seek entry to the Sunwell itself, where you can cleanse the sword. The guardians will try to stop you from entering the Sunwell Plateau, but make yourself known to Halduron Brightwing , who will be inspecting the guards there.", ["objectivesText"] = "Speak with Halduron Brightwing at the entrance to the Sunwell Plateau on the Isle of Quel'Danas . Progress: What brings you here?", ["rewardGold"] = 30900, ["rewardXP"] = 430, ["rewardItems"] = { 49870 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 36642, ["x"] = 0.64, ["y"] = 0.6095 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.6095 }, ["mapCandidates"] = { ["npc"] = { 118, 122 }, ["zone"] = { 4812 } }, ["questType"] = "standard" },
[24563] = { ["id"] = 24563, ["name"] = "Thalorien Dawnseeker", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 24563 }, ["series"] = { 24559, 24560, 24561, 24562 }, ["description"] = "You are the one working with Myralion Sunblaze, arent you? I know of a way we can test the sword. If you know the blade's history, you recall that it was borne by Thalorien Dawnseeker in defense of the Sunwell against the Scourge. He fell in what is now the Dead Scar, buying time for his men to make their own preparations. You will find his remains near the southern end of the Dead Scar on this isle. Visit them, and if his spirit gives you its blessing, I will allow you to enter the Sunwell.", ["objectivesText"] = "Visit Thalorien Dawnseeker's Remains and obtain his blessing to wield Quel'Delar. Progress: Did you visit the ground where Thalorien fell defending the Sunwell?", ["rewardGold"] = 309800, ["rewardXP"] = 3440, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[24564] = { ["id"] = 24564, ["name"] = "The Purification of Quel'Delar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 24564 }, ["series"] = { 24801 }, ["description"] = "The Sunwell and the end of Quel'Delar's exile await, <name>. You will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary and do not allow them to entrap you in their political scheming. Instead, remain focused on your task here. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Afterward, show the blade to Myralion Sunblaze at Quel'Delar's Rest.", ["objectivesText"] = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau . Progress: What happened inside the Sunwell?", ["rewardItems"] = { 49871, 49879 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 36642, ["x"] = 0.64, ["y"] = 0.6095 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 118, 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[24579] = { ["id"] = 24579, ["name"] = "Sartharion Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24579 }, ["description"] = "Sartharion , the Onyx Guardian, watches over the eggs of the Twilight Dragonflight. He rests within the Obsidian Sanctum in the Chamber of the Aspects underneath Wyrmrest Temple. The Council of Six has decreed that Sartharion must die!", ["objectivesText"] = "Kill Sartharion . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24580] = { ["id"] = 24580, ["name"] = "Anub'Rekhan Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24580 }, ["description"] = "Anub'Rekhan , once-mighty Spider Lord of the nerubian empire, has been taken by the Lich King and corrupted into a state of undeath. Now a crypt lord, he sits in his parlor in the Arachnid Quarter of Naxxramas , spinning strategies for Kel'Thuzad. The Council of Six has decreed that Anub'Rekhan must die!", ["objectivesText"] = "Kill Anub'Rekhan . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24581] = { ["id"] = 24581, ["name"] = "Noth the Plaguebringer Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24581 }, ["description"] = "Noth the Plaguebringer , traitor and coward! Second only to the Lich King himself for the number of souls that have been Scourged! Make haste to Naxxramas . You will find him within the Plague Quarter hiding behind his undead minions. Destroy him! The Council of Six has decreed that Noth must die!", ["objectivesText"] = "Kill Noth the Plaguebringer . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24582] = { ["id"] = 24582, ["name"] = "Instructor Razuvious Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24582 }, ["description"] = "Instructor Razuvious smugly struts about the Military Quarter of Naxxramas . It is said that only a death knight personally trained by him could possibly even withstand the prowess of his blade. You and your group are going to prove everyone wrong. The Council of Six has decreed that Razuvious must die!", ["objectivesText"] = "Kill Instructor Razuvious . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24583] = { ["id"] = 24583, ["name"] = "Patchwerk Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24583 }, ["description"] = "The so-called \"avatar of war\", Patchwerk is the ultimate abomination. It is also taking a heavy toll upon on our forces in the Dragonblight. I want you to assemble your companions and enter the Construct Quarter of Naxxramas . Disassemble the construct. The Council of Six has decreed that Patchwerk must die!", ["objectivesText"] = "Kill Patchwerk . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24584] = { ["id"] = 24584, ["name"] = "Malygos Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24584 }, ["description"] = "Our resources are strained. Malygos , the Spell-Weaver, is draining all of the magic out of the world, consolidating it in the Eye of Eternity . Without magic, we are doomed. <class>, the Nexus War must be brought to an end. The Council of Six has decreed that Malygos must die!", ["objectivesText"] = "Kill Malygos . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24585] = { ["id"] = 24585, ["name"] = "Flame Leviathan Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24585 }, ["description"] = "Within the Formation Grounds sits Ulduar 's first line of defense: Flame Leviathan . The Kirin Tor have been provided with information suggesting that this Keeper-created machine is soon to be transported to an undisclosed location and let loose to wreak havoc upon the mortals of Azeroth. This must not come to pass. The Council of Six has decreed that Flame Leviathan must die!", ["objectivesText"] = "Kill Flame Leviathan . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24586] = { ["id"] = 24586, ["name"] = "Razorscale Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24586 }, ["description"] = "Razorscale normally keeps to her aerie near the Colossal Forge in Ulduar . Of late, however, she has been spotted raining fire down upon lands outside of the titan complex. Though the broodmother's is a sad tale, she poses an imminent threat to all of Northrend. The Council of Six has decreed that Razorscale must die!", ["objectivesText"] = "Kill Razorscale . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24587] = { ["id"] = 24587, ["name"] = "Ignis the Furnace Master Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24587 }, ["description"] = "The great fire giant, Ignis the Furnace Master toils away inside of Ulduar 's Colossal Forge. Under orders from Loken, Ignis creates weapons that are terrifying in their power. The Council of Six has decreed that Ignis must die!", ["objectivesText"] = "Kill Ignis the Furnace Master . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24588] = { ["id"] = 24588, ["name"] = "XT-002 Deconstructor Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24588 }, ["description"] = "Yet another strange construct of Mimiron, the XT-002 Deconstructor actually thinks that it is the keeper's son. Do not be fooled by its feigned innocence. It is a deadly machine! You will find the Deconstructor within Ulduar 's Scrapyard. The Council of Six has decreed that XT-002 Deconstructor must die!", ["objectivesText"] = "Kill XT-002 Deconstructor . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24589] = { ["id"] = 24589, ["name"] = "Lord Jaraxxus Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24589 }, ["description"] = "Archmage Timear has foreseen a horrible event, which is about to transpire. A foolish gnome warlock is about to accidentally summon an Eredar lord of the Burning Legion into the middle of the Trial of the Crusader . You must be there when it happens, <class>. If Lord Jaraxxus escapes, he will open a portal and the Burning Legion will spill forth into our world once more. The Council of Six has decreed that Lord Jaraxxus must die!", ["objectivesText"] = "Kill Lord Jaraxxus . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24590] = { ["id"] = 24590, ["name"] = "Lord Marrowgar Must Die!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["storyline"] = { 24590 }, ["description"] = "Lord Marrowgar is the guardian of the Frozen Throne within the Spire Chamber. Pieced together by the Lich King from the bones of a thousand vanquished adventurers, Marrowgar wields the power of the throne itself. Without the destruction of this bone wraith, there is no hope of taking Icecrown Citadel . The Council of Six has decreed that Lord Marrowgar must die!", ["objectivesText"] = "Kill Lord Marrowgar . This quest can be completed with any difficulty or size raid.", ["rewardGold"] = 1239200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[24595] = { ["id"] = 24595, ["name"] = "The Purification of Quel'Delar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["requiredClasses"] = { 5, 7, 11 }, ["requiredRaces"] = { 4, 11, 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 24595 }, ["series"] = { 24795 }, ["description"] = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to my people that Quel'Delar has been recovered. As promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. Once the blade is restored, return with it to Caladis Brightspear at Quel'Delar's Rest.", ["objectivesText"] = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau . Progress: Tell me of what happened in the Sunwell, <name>.", ["rewardItems"] = { 49871, 49879 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 36624, ["x"] = 0.637, ["y"] = 0.607 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 118, 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[24596] = { ["id"] = 24596, ["name"] = "The Purification of Quel'Delar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 24596 }, ["series"] = { 24798 }, ["description"] = "The Sunwell and the end of Quel'Delar's exile await, <name>. You will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming. Instead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete the its restoration, then speak with Myralion Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau .", ["objectivesText"] = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau . Progress: What happened during your visit to the Sunwell?", ["rewardItems"] = { 49871, 49889 }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 36642, ["x"] = 0.64, ["y"] = 0.6095 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.6095 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard" },
[24598] = { ["id"] = 24598, ["name"] = "The Purification of Quel'Delar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 1, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 24598 }, ["series"] = { 24799 }, ["description"] = "The Sunwell and the end of Quel'Delar's exile await, <name>. You will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming. Instead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete its restoration, then show it to Myralio Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau .", ["objectivesText"] = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau . Progress: What news do you bring from the Sunwell?", ["rewardItems"] = { 49871, 49879 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 36642, ["x"] = 0.64, ["y"] = 0.6095 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 118, 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[24638] = { ["id"] = 24638, ["name"] = "Crushing the Crown", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "loremaster", "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Love is in the Air", ["expansion"] = 2, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 24638 }, ["description"] = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough. Here's an entry I want you to check out: it's right outside Orgrimmar's gates, to the west! That can't be good. Get out there and rough 'em up. Oh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", ["objectivesText"] = "Kill 5 Crown Lackeys and use Snagglebolt's Khorium Bomb to damage one Chemical Wagon just west of Orgrimmar's gates in Durotar, then return to Detective Snap Snagglebolt in Orgrimmar.", ["rewardGold"] = 74100, ["rewardXP"] = 200, ["rewardItems"] = { 49927, 50130 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 37172, ["x"] = 0.5, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[24682] = { ["id"] = 24682, ["name"] = "The Pit of Saron", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4809, ["storyline"] = { 24682 }, ["series"] = { 24498, 24499, 24506, 24510, 24511, 24683, 24710, 24711 }, ["description"] = "Quickly, through the portal! I'll find you on the other side.", ["objectivesText"] = "Meet Lady Sylvanas Windrunner inside the entrance to the Pit of Saron .", ["rewardGold"] = 70225, ["rewardXP"] = 860, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4809 } }, ["questType"] = "dungeon" },
[24683] = { ["id"] = 24683, ["name"] = "The Pit of Saron", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4809, ["storyline"] = { 24683 }, ["series"] = { 24498, 24499, 24506, 24510, 24511, 24682, 24710, 24711 }, ["description"] = "Quickly, through the portal! I'll meet you on the other side.", ["objectivesText"] = "Meet Lady Jaina Proudmoore just inside the Pit of Saron .", ["rewardGold"] = 70225, ["rewardXP"] = 860, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4809 } }, ["questType"] = "dungeon" },
[24710] = { ["id"] = 24710, ["name"] = "Deliverance from the Pit", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4813, ["storyline"] = { 24710 }, ["series"] = { 24498, 24499, 24506, 24510, 24511, 24682, 24683, 24711 }, ["description"] = "We need to make our way up the main path and through the cave to Tyrannus' rise. He will be forced to confront us there lest we make our way into the citadel proper. Go now, <class>. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", ["objectivesText"] = "Kill Scourgelord Tyrannus .", ["rewardGold"] = 420000, ["rewardXP"] = 6880, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4813 } }, ["questType"] = "dungeon" },
[24711] = { ["id"] = 24711, ["name"] = "Frostmourne", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4813, ["storyline"] = { 24711 }, ["series"] = { 24498, 24499, 24506, 24510, 24511, 24682, 24683, 24710 }, ["description"] = "We've come so far... we're so close to our goal. I'm uncertain how we're going to escape with so many men lost and so few to keep our path secure, but we must press on.", ["objectivesText"] = "Meet Lady Jaina Proudmoore within the Halls of Reflection .", ["rewardGold"] = 70225, ["rewardXP"] = 860, ["rewardItems"] = { 38530, 38531, 38532, 38533 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4813 } }, ["questType"] = "dungeon" },
[24712] = { ["id"] = 24712, ["name"] = "Deliverance from the Pit", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4813, ["storyline"] = { 24712 }, ["series"] = { 24507, 24713 }, ["description"] = "We need to make our way up the main path and through the cave to Tyrannus' rise. There, he will be forced to confront us there lest we make our way into the citadel proper. Go now, <class>. My men and I will be there to stand by you when the confrontation with Tyrannus comes.", ["objectivesText"] = "Kill Scourgelord Tyrannus .", ["rewardGold"] = 420000, ["rewardXP"] = 6880, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4813 } }, ["questType"] = "dungeon" },
[24713] = { ["id"] = 24713, ["name"] = "Frostmourne", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4813, ["storyline"] = { 24713 }, ["series"] = { 24507, 24712 }, ["description"] = "You must press on, hero. We've come so far... we're so close to our goal. For now, I must stay here and secure a path for your exit. Find Sylvanas and continue the mission.", ["objectivesText"] = "Meet Lady Sylvanas Windrunner within the Halls of Reflection .", ["rewardGold"] = 70225, ["rewardXP"] = 860, ["rewardItems"] = { 38530, 38531, 38532, 38533 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4813 } }, ["questType"] = "dungeon" },
[24743] = { ["id"] = 24743, ["name"] = "Shadow's Edge", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4812, ["storyline"] = { 24743 }, ["series"] = { 24545, 24547, 24548, 24549, 24748, 24749, 24756, 24757 }, ["rewardItems"] = { 49888 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4812 } }, ["questType"] = "standard" },
[24748] = { ["id"] = 24748, ["name"] = "The Lich King's Last Stand", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4812, ["storyline"] = { 24748 }, ["series"] = { 24545, 24547, 24548, 24549, 24743, 24749, 24756, 24757 }, ["description"] = "Shadowmourne; a newly forged weapon already steeped in this world's history, reborn into an unrivaled destiny. With this weapon you bear a solemn responsibility, and the time to carry out that charge is at hand. Take this weapon of myth and legend and march on the enemy. Avenge the countless heroes lost in his merciless campaign. Bring rest to their tortured souls. Steel yourself, <class>, and guide Shadowmourne to fulfill the purpose of its creation.", ["objectivesText"] = "Highlord Darion Mograine in Icecrown Citadel wants you to kill the Lich King.", ["rewardGold"] = 420000, ["rewardXP"] = 8230, ["rewardItems"] = { 49623, 50235, 51315, 51316 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4812 } }, ["questType"] = "raid" },
[24749] = { ["id"] = 24749, ["name"] = "Unholy Infusion", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4812, ["storyline"] = { 24749 }, ["series"] = { 24545, 24547, 24548, 24549, 24743, 24748, 24756, 24757 }, ["description"] = "Before your weapon can reach its full potential it must be endowed with its signature powers. First among them is unholiness. You must seek out and defeat the one called Professor Putricide, but his death is not your only goal. You must use his resources against him. Find a way to absorb his mutated slime. Use the foul substance to infuse your weapon with the power of the unholy. Only when this has been done shall I reveal your next task.", ["objectivesText"] = "Highlord Darion Mograine wants you to infuse Shadow's Edge with Unholy power and slay Professor Putricide. This quest may only be completed in 25 person difficulty of Icecrown Citadel. Progress: Is it done, <race>?", ["rewardGold"] = 683200, ["rewardXP"] = 5145, ["rewardItems"] = { 13382, 14023, 49623, 49888, 49908, 50274, 51315, 52200, 52201, 52251, 52252, 52253, 86570, 86572, 95566, 116154, 118682, 140192 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4812 } }, ["questType"] = "raid" },
[24756] = { ["id"] = 24756, ["name"] = "Blood Infusion", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4812, ["storyline"] = { 24756 }, ["series"] = { 24545, 24547, 24548, 24549, 24743, 24748, 24749, 24757 }, ["description"] = "Your weapon is ready to be endowed with the power of blood. You must face Queen Lana'thel in battle and subject yourself to her Blood Mirror. This will cause Shadow's Edge to drink the blood of the nearest living being. That being would be you, <race>. Once the blade has been thus awakened, allow the Queen's Frenzied Bloodthirst to take hold of you, feed the blade thrice to sate it, and then give the queen an ignominious death. May her screams pierce the ears of the Lich King as he awaits his fate.", ["objectivesText"] = "Highlord Darion Mograine wants you to infuse Shadow's Edge with blood and defeat Queen Lana'thel. This quest may only be completed in 25 person difficulty of Icecrown Citadel.", ["rewardGold"] = 468000, ["rewardXP"] = 5145, ["rewardItems"] = { 19290, 49623, 49888, 49908, 50274, 51315, 52200, 52201, 52251, 52252, 52253 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4812 } }, ["questType"] = "raid" },
[24757] = { ["id"] = 24757, ["name"] = "Frost Infusion", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4812, ["storyline"] = { 24757 }, ["series"] = { 24545, 24547, 24548, 24549, 24743, 24748, 24749, 24756 }, ["description"] = "Shadow's Edge is prepared to receive its final infusion of power. Sindragosa, the enemy's own mount, must fall. But before she is brought down, you must sustain four of her frozen breath attacks without tasting death. Without his dragon, nothing shall stand between you and the Lich King.", ["objectivesText"] = "Highlord Darion Mograine has instructed you to slay Sindragosa after subjecting yourself to 4 of her breath attacks while wielding Shadow's Edge. This quest may only be completed in 25 person difficulty of Icecrown Citadel.", ["rewardGold"] = 210000, ["rewardXP"] = 5145, ["rewardItems"] = { 41099, 43582, 43586, 43587, 43588, 45747, 49118, 49888, 50356 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4812 } }, ["questType"] = "raid" },
