[24802] = { ["id"] = 24802, ["name"] = "Wrath of the Lich King", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 2, ["zoneID"] = 4820, ["storyline"] = { 24802 }, ["description"] = "It's hard to believe that there is much hope of defeating Arthas upon the steps of his own throne. And who will take up the crown of Lich King if it comes to that? Many questions remain, but you need to find Sylvanas and escape the Lich King while there's still time.", ["objectivesText"] = "Find Lady Sylvanas Windrunner and escape the Halls of Reflection .", ["rewardGold"] = 105000, ["rewardXP"] = 3440, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4820 } }, ["questType"] = "dungeon" },
