[26012] = { ["id"] = 26012, ["name"] = "Trouble at Wyrmrest", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4395, ["mapID"] = 115, ["storyline"] = { 26012 }, ["series"] = { 26013, 26034 }, ["description"] = "My old friend Krasus sends word of dire happenings at Wyrmrest, in Dragonblight. His missive was brief, but it seems that there has been some sort of attack on the Ruby Sanctum beneath the Temple. Pressing business here in Dalaran keeps me from attending to the matter personally, but I have heard word of your exploits in the Lich King's Citadel and you are doubtless up to the task -- perhaps you could assist Krasus in my stead?", ["objectivesText"] = "Speak with Krasus at Wyrmrest Temple in Dragonblight.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 27990, ["x"] = 0.598, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 4395 } }, ["questType"] = "raid" },
[26013] = { ["id"] = 26013, ["name"] = "Assault on the Sanctum", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 26013 }, ["series"] = { 26012, 26034 }, ["description"] = "<race>, something terrible has transpired within the Ruby Sanctum beneath the Temple. The entry to the Sanctum is in ruins, and its guardians violently slain. We sent scouts to investigate, but they have not returned. I cannot help but fear the worst. Enter the Ruby Sanctum and discover what has befallen the home of my flight. Once we have more information, we can plan our next steps accordingly.", ["objectivesText"] = "Investigate the Ruby Sanctum beneath Wyrmrest Temple.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 27990, ["x"] = 0.598, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "raid" },
[26034] = { ["id"] = 26034, ["name"] = "The Twilight Destroyer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 2, ["zoneID"] = 4987, ["mapID"] = 115, ["storyline"] = { 26034 }, ["series"] = { 26012, 26013 }, ["description"] = "This was no reckless attack, but rather a carefully orchestrated strike against the heart of the Red Dragonflight. Zarithrian, on the bluff over there, is overseeing the assault, but the true leader of this force is a brash and powerful Twilight dragon named Halion . Not since Dargonax has a full-grown spawn of Sinestra's twisted experiments been seen. Slay him, <name>, and then when the invasion has been fully repelled, report to Krasus regarding all you have seen here.", ["objectivesText"] = "Defeat Halion and repel the invasion of the Ruby Sanctum .", ["rewardGold"] = 929400, ["rewardXP"] = 6175, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 27990, ["x"] = 0.598, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 4987 } }, ["questType"] = "raid" },
})
